/****** Object:  UserDefinedFunction [dbo].[FngetMCNo]    Script Date: 10/25/2026 4:57:09 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE FUNCTION [dbo].[FngetMCNo](
    @Process VARCHAR(20),
    @MCNo VARCHAR(50)
)
RETURNS @ResultTable TABLE
(
    MCNO VARCHAR(50)
)
AS
BEGIN
    IF @Process = 'ATC'
    BEGIN
        INSERT INTO @ResultTable
        SELECT DISTINCT MCNo 
        FROM ATCBMMaintenance;
    END
    ELSE IF @Process = 'SING'
    BEGIN
        INSERT INTO @ResultTable
        SELECT DISTINCT MCNo 
        FROM SINGBMMaintenance;
    END
    ELSE IF @Process = 'WB'
    BEGIN
        INSERT INTO @ResultTable
        SELECT DISTINCT MCNo 
        FROM WBBMMaintenance;
    END

    RETURN;
END;
GO
