CREATE FUNCTION [dbo].[FnGetReOccurrence]
(
    @timeframe INT,
    @Process VARCHAR(20),
	@MCNo VARCHAR(50),
	@RequestItem VARCHAR(50)
   
)
RETURNS @ResultTable TABLE
(

    ReOccurrence INT
)
AS
BEGIN
    DECLARE @datefrom DATE = DATEADD(DAY, -@timeframe, GETDATE());

    IF @Process = 'ATC'
    BEGIN
        INSERT INTO @ResultTable
       SELECT 
    ISNULL(
        (SELECT    
            CASE 
                WHEN COUNT(*) > 1 THEN COUNT(*) - 1  
                ELSE 0 
            END AS Reoccurrence
        FROM ATCBMMaintenance a
        WHERE a.MCNo = @MCNo
          AND a.TimeOfRequest >= @datefrom
          AND a.TimeOfRequest <= GETDATE()
          AND a.RequestItem = @RequestItem
        GROUP BY a.MCNo, a.RequestItem), 0) AS Reoccurrence;

  
    END
    ELSE IF @Process = 'SING'
    BEGIN
        INSERT INTO @ResultTable
		SELECT 
    ISNULL(
        (SELECT    
            CASE 
                WHEN COUNT(*) > 1 THEN COUNT(*) - 1  
                ELSE 0 
            END AS Reoccurrence
        FROM SINGBMMaintenance a
        WHERE a.MCNo = @MCNo
          AND a.TimeOfRequest >= @datefrom
          AND a.TimeOfRequest <= GETDATE()
          AND a.RequestItem = @RequestItem
        GROUP BY a.MCNo, a.RequestItem), 0) AS Reoccurrence;
  
    END
    ELSE IF @Process = 'WB'
    BEGIN
        INSERT INTO @ResultTable
			SELECT 
    ISNULL(
        (SELECT    
            CASE 
                WHEN COUNT(*) > 1 THEN COUNT(*) - 1  
                ELSE 0 
            END AS Reoccurrence
        FROM WBBMMaintenance a
        WHERE a.MCNo = @MCNo
          AND a.TimeOfRequest >= @datefrom
          AND a.TimeOfRequest <= GETDATE()
          AND a.RequestItem = @RequestItem
        GROUP BY a.MCNo, a.RequestItem), 0) AS Reoccurrence;
    END

