CREATE FUNCTION [dbo].[FngetRequestItem](
    @Process VARCHAR(20),
    @RequestItem VARCHAR(100)
)
RETURNS @ResultTable TABLE
(
    RequestItem VARCHAR(100)
)
AS
BEGIN
    IF @Process = 'ATC'
    BEGIN
        INSERT INTO @ResultTable
        SELECT DISTINCT RequestItem
        FROM ATCBMMaintenance;
    END
    ELSE IF @Process = 'SING'
    BEGIN
        INSERT INTO @ResultTable
        SELECT DISTINCT RequestItem 
        FROM SINGBMMaintenance;
    END
    ELSE IF @Process = 'WB'
    BEGIN
        INSERT INTO @ResultTable
        SELECT DISTINCT RequestItem
        FROM WBBMMaintenance;
    END

    RETURN;
END;

