CREATE   VIEW [dbo].[gridSINGEEEData]
AS
SELECT
    e.bm_id AS bmID,
    e.BMStatusID,
    s.SubProcessID, -- From SINGBMMaintenance
    s. PMCategoryID,
    s.MCNo, -- From SINGBMMaintenance
    s.MCStatus, -- From SINGBMMaintenance
    s.MCType, -- From SINGBMMaintenance
    s.LOTNo,
    s.DeviceName, -- From SINGBMMaintenance
    s.PkgName, -- From SINGBMMaintenance
    s.RequestItem, -- From SINGBMMaintenance
    s.OccurrenceDate, -- From SINGBMMaintenance
	s.NGDetectionCircumtances,
	s.RequestContent,
	s.OccurrenceFreq,
