	s.GLAndon,
	s.GLConfirmOPReq,
	s.GLConfirmOPReqReason,
	s.GLConfirmOPReqBy,
	CAST(NULL AS datetime2) AS GLConfirmOPReqDate,
	s.TimeOfRequest,
	s.RequestedBy,
	e.Situation,
	e.Why1,
	e.Why2,
    e.Why3,
    e.Why4, 
    
    s. Action1,
