    s. ActionAft2,
    s. ActionAft3,
    s. ActionAft4,
    s. ActionAft5,
    s. ActionAft6,
    s. ActionAft7,
    s. ActionAft8,
    s. ActionAft9,
    s. ActionAft10,
    s. ActionAft11,
    s. ActionAft12,
    s. ActionAft13,
	s.DataSetP1XAxisBef,
	s.DataSetP1ZAxisBef,
	s.DataSetP1XAxisAft,
	s.DataSetP1ZAxisAft,
	s.DataSetP2XAxisBef,
	s.DataSetP2ZAxisBef,
	s.DataSetP2XAxisAft,
	s.DataSetP2ZAxisAft,
	s. ReplacedPartsBefore1,
	s. ReplacedPartsBefore2,
	s. ReplacedPartsBefore3,
	s. ReplacedPartsBefore4,
	s.ReplacedPartsAfter1,
	s.ReplacedPartsAfter2,
	s.ReplacedPartsAfter3,
	s.ReplacedPartsAfter4,
	s. Parts1,
    s.Parts2,
    s.Parts3,
    s.Parts4,
	s.PartsType1,
    s. PartsType2,
    s. PartsType3,
    s. PartsType4,
    s. PartsQty1,
    s. PartsQty2,
    s. PartsQty3,
    s. PartsQty4,
	s. Picture,
	s.GoodPcsBef,
	s.NGPcsBef,
	s. TotalPcsBef,
	s.GoodPcsAft,
	s.NGPcsAft,
	s.TotalPcsAft,
	s.PMChkLOTNo,
	s.PMChkDevice,
	s.PMChkRecipe,
	s.REELChk,
	s.REELChkGoodNG,
	s.OccurrenceFreqAfterPM,
	s.RPMAfterPM,
	s.NeedInsp,
	s.InspItem,
	s.UseDummy,
	s.Chk4SAfterPM,
	s.ChkItemBef,
	s.ChkSafetyCoverBef,
	s.ChkSafetyCoverAft,
	s.QCTapingBef1,
	s.QCTapingBef2,
	s.QCTapingBef3,
