                         dbo.FTBMMaintenance.Process, dbo.FTBMMaintenance.Location, dbo.FTBMMaintenance.ConBeforeAfterAdjValue6, dbo.FTBMMaintenance.ConBeforeAfterAdjValue5, dbo.FTBMMaintenance.ConBeforeAfterAdjValue4, 
                         dbo.FTBMMaintenance.ConBeforeAfterAdjValue3, dbo.FTBMMaintenance.ConBeforeAfterAdjValue2, dbo.FTBMMaintenance.ConBeforeAfterAdjValue1, dbo.FTBMMaintenance.ConBeforeAfterAdjItem6, 
                         dbo.FTBMMaintenance.ConBeforeAfterAdjItem5, dbo.FTBMMaintenance.ConBeforeAfterAdjItem4, dbo.FTBMMaintenance.ConBeforeAfterAdjItem3, dbo.FTBMMaintenance.ConBeforeAfterAdjItem2, 
                         dbo.FTBMMaintenance.ConBeforeAfterAdjItem1, dbo.FTBMMaintenance.RPMRelAdj, dbo.FTBMMaintenance.RPMStandard, dbo.FTBMMaintenance.RPMBefore, dbo.FTBMMaintenance.RPMAfter, dbo.FTBMMaintenance.CPData, 
                         dbo.FTBMMaintenance.QCData, dbo.FTBMMaintenance.BMINSPN, dbo.FTBMMaintenance.LeaderChk, dbo.FTBMMaintenance.LineLoc, dbo.FTBMMaintenance.ProdQtyData, dbo.FTBMMaintenance.LastActBeforeProb, 
                         dbo.FTBMMaintenance.PMSafetyData, dbo.FTBMMaintenance.PMRPMData, dbo.FTBMMaintenance.ProdTreatDummyOut, dbo.FTBMMaintenance.ProdTreatDummyIn, dbo.FTBMMaintenance.ProdTreatUsageOfDummy, 
                         dbo.FTBMMaintenance.ProdTreatTRC, dbo.FTBMMaintenance.ProdTreatLotTreat, dbo.FTBMMaintenance.ProdTreatInspResult, dbo.FTBMMaintenance.ProdTreatOccStatus, dbo.FTBMMaintenance.ProdTreatDevice, 
                         dbo.FTBMMaintenance.ProdTreatLotNo, dbo.FTBMMaintenance.ProdTreatPackage, dbo.FTBMMaintenance.PMProdQtyData, dbo.FTBMMaintenance.isNotQuality3, dbo.FTBMMaintenance.isNotQuality2, 
                         dbo.FTBMMaintenance.isNotQuality1, dbo.FTBMMaintenance.BMCategoryID, dbo.FTBMMaintenance.LeaderCheck, dbo.FTBMMaintenance.ProdQtyGood, dbo.FTBMMaintenance.ProdQtyNG, dbo.FTBMMaintenance.ProdQtyTotal, 
                         dbo.FTBMMaintenance.ProdQtyVNG, dbo.FTBMMaintenance.LastActionDoneBeforeProb, dbo.FTBMMaintenance.UsageOfProdLot, dbo.FTBMMaintenance.C5SConBefore, dbo.FTBMMaintenance.C5SConAfter, 
                         dbo.FTBMMaintenance.C5SConAction, dbo.FTBMMaintenance.UsageOfProdLotYN, dbo.FTBMMaintenance.AlarmNo, dbo.FTBMMaintenance.PMMiss, dbo.FTBMMaintenance.LastBMStop, dbo.FTBMMaintenance.LastBMContinue,
                          DATEDIFF(MINUTE, dbo.FTBMMaintenance.TimeTurnover, dbo.FTBMMaintenance.CCStartOfRepair) AS PEWaitingTime, DATEDIFF(MINUTE, dbo.FTBMMaintenance.CCStartOfRepair, dbo.FTBMMaintenance.EndOfRepair) 
                         AS PERepairTime, YEAR(dbo.FTBMMaintenance.PMTurnOvertoPEDate) AS BMYear, MONTH(dbo.FTBMMaintenance.PMTurnOvertoPEDate) AS BMMonth, DAY(dbo.FTBMMaintenance.PMTurnOvertoPEDate) AS BMDay
FROM            dbo.FTBMMaintenance LEFT OUTER JOIN
                         dbo.SubProcess ON dbo.FTBMMaintenance.SubProcessID = dbo.SubProcess.SubProcessID LEFT OUTER JOIN
                         dbo.BMStatus ON dbo.FTBMMaintenance.BMStatusID = dbo.BMStatus.BMStatusID LEFT OUTER JOIN
                         dbo.PMCategory ON dbo.FTBMMaintenance.PMCategoryID = dbo.PMCategory.PMCategoryID LEFT OUTER JOIN
                         dbo.BMCase ON dbo.FTBMMaintenance.BMCaseID = dbo.BMCase.BMCaseID INNER JOIN
                         dbo.MCList ON dbo.FTBMMaintenance.MCNo = dbo.MCList.MCNo LEFT OUTER JOIN
                         dbo.I4M ON dbo.FTBMMaintenance.I4MID = dbo.I4M.I4MID LEFT OUTER JOIN
                         dbo.pm_EquipInsData ON dbo.FTBMMaintenance.bmID = dbo.pm_EquipInsData.bmID
WHERE        (dbo.FTBMMaintenance.Turnover = 'CC') AND (dbo.FTBMMaintenance.BMStatusID <> 30) AND (dbo.FTBMMaintenance.PMCategoryID = 1)
GO
