CREATE VIEW [dbo].[gridMEMSMachineHistory]
AS
SELECT        dbo.MEMSBMMaintenance.bmID, dbo.MEMSBMMaintenance.BMStatusID, dbo.MEMSBMMaintenance.SubProcessID, dbo.MEMSBMMaintenance.PMCategoryID, 
                         dbo.MEMSBMMaintenance.MCNo, dbo.MEMSBMMaintenance.MCStatus, dbo.MEMSBMMaintenance.MCType, dbo.MEMSBMMaintenance.LOTNo, 
                         dbo.MEMSBMMaintenance.DeviceName, dbo.MEMSBMMaintenance.PkgName, dbo.MEMSBMMaintenance.RequestItem, dbo.MEMSBMMaintenance.OccurrenceDate, 
                         dbo.SubProcess.SubProcess, dbo.BMWhy.BMWhy, dbo.MEMSBMMaintenance.Treatment1, dbo.MEMSBMMaintenance.Treatment2, dbo.MEMSBMMaintenance.Treatment3, 
                         dbo.MEMSBMMaintenance.Treatment4, dbo.MEMSBMMaintenance.Treatment5, dbo.MEMSBMMaintenance.Treatment6, dbo.MEMSBMMaintenance.Treatment7, 
                         dbo.MEMSBMMaintenance.Treatment8, dbo.MEMSBMMaintenance.Treatment9, dbo.MEMSBMMaintenance.Treatment10, dbo.MEMSBMMaintenance.Treatment11, 
                         dbo.MEMSBMMaintenance.Treatment12, dbo.MEMSBMMaintenance.Treatment13, dbo.MEMSBMMaintenance.Treatment14, dbo.PMCategory.PMCategory, 
                         dbo.MEMSBMMaintenance.TimeOfRequest, dbo.MEMSBMMaintenance.RequestedBy, dbo.MEMSBMMaintenance.Why1, dbo.MEMSBMMaintenance.Why2, 
                         dbo.MEMSBMMaintenance.Why3
FROM            dbo.BMStatus INNER JOIN
                         dbo.MEMSBMMaintenance ON dbo.BMStatus.BMStatusID = dbo.MEMSBMMaintenance.BMStatusID INNER JOIN
                         dbo.PMCategory ON dbo.MEMSBMMaintenance.PMCategoryID = dbo.PMCategory.PMCategoryID LEFT OUTER JOIN
                         dbo.BMWhy ON dbo.MEMSBMMaintenance.Why4 = dbo.BMWhy.BMWhyID LEFT OUTER JOIN
                         dbo.SubProcess ON dbo.MEMSBMMaintenance.SubProcessID = dbo.SubProcess.SubProcessID
GO
/****** Object:  View [dbo].[viewEDSBMPerMachineWW]    Script Date: 10/25/2026 4:57:09 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[viewEDSBMPerMachineWW]
AS
SELECT DISTINCT { fn WEEK(EndOfRepair) } AS myWW, YEAR(EndOfRepair) AS myYear,
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.EDSBMMaintenance AS b
                               WHERE        ({ fn WEEK(EndOfRepair) } = { fn WEEK(a.EndOfRepair) }) AND (YEAR(EndOfRepair) = YEAR(a.EndOfRepair)) AND (BMStatusID > 10 OR
                                                         BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30) AND (Location = 'LSI2-1F')) AS LSI21FBM,
                             (SELECT        ISNULL(macCount, 0) AS Expr1
                               FROM            dbo.viewBMRateCalcWW AS c
                               WHERE        (myWW = { fn WEEK(a.EndOfRepair) }) AND (myYear = YEAR(a.EndOfRepair)) AND (ProcessMatch = 'EDS') AND (Shift = '1ST') AND (LocationMatch = 'LSI2-1F')) AS LSI21FMC,
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.EDSBMMaintenance AS b
                               WHERE        ({ fn WEEK(EndOfRepair) } = { fn WEEK(a.EndOfRepair) }) AND (YEAR(EndOfRepair) = YEAR(a.EndOfRepair)) AND (BMStatusID > 10 OR
                                                         BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30) AND (Location = 'LSI2-2F')) AS LSI22FBM,
                             (SELECT        ISNULL(macCount, 0) AS Expr1
                               FROM            dbo.viewBMRateCalcWW AS c
                               WHERE        (myWW = { fn WEEK(a.EndOfRepair) }) AND (myYear = YEAR(a.EndOfRepair)) AND (ProcessMatch = 'EDS') AND (Shift = '1ST') AND (LocationMatch = 'LSI2-2F')) AS LSI22FMC,
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.EDSBMMaintenance AS b
                               WHERE        ({ fn WEEK(EndOfRepair) } = { fn WEEK(a.EndOfRepair) }) AND (YEAR(EndOfRepair) = YEAR(a.EndOfRepair)) AND (BMStatusID > 10 OR
                                                         BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30) AND (Location = 'LSI2-3F')) AS LSI23FBM,
                             (SELECT        ISNULL(macCount, 0) AS Expr1
                               FROM            dbo.viewBMRateCalcWW AS c
                               WHERE        (myWW = { fn WEEK(a.EndOfRepair) }) AND (myYear = YEAR(a.EndOfRepair)) AND (ProcessMatch = 'EDS') AND (Shift = '1ST') AND (LocationMatch = 'LSI2-3F')) AS LSI23FMC,
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.EDSBMMaintenance AS b
                               WHERE        ({ fn WEEK(EndOfRepair) } = { fn WEEK(a.EndOfRepair) }) AND (YEAR(EndOfRepair) = YEAR(a.EndOfRepair)) AND (BMStatusID > 10 OR
                                                         BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30) AND (Location = 'LSI1-1F')) AS LSI11FBM,
                             (SELECT        ISNULL(macCount, 0) AS Expr1
                               FROM            dbo.viewBMRateCalcWW AS c
                               WHERE        (myWW = { fn WEEK(a.EndOfRepair) }) AND (myYear = YEAR(a.EndOfRepair)) AND (ProcessMatch = 'EDS') AND (Shift = '1ST') AND (LocationMatch = 'LSI1-1F')) AS LSI11FMC,
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.EDSBMMaintenance AS b
                               WHERE        ({ fn WEEK(EndOfRepair) } = { fn WEEK(a.EndOfRepair) }) AND (YEAR(EndOfRepair) = YEAR(a.EndOfRepair)) AND (BMStatusID > 10 OR
                                                         BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30) AND (Location = 'LSI1-2F')) AS LSI12FBM,
                             (SELECT        ISNULL(macCount, 0) AS Expr1
                               FROM            dbo.viewBMRateCalcWW AS c
                               WHERE        (myWW = { fn WEEK(a.EndOfRepair) }) AND (myYear = YEAR(a.EndOfRepair)) AND (ProcessMatch = 'EDS') AND (Shift = '1ST') AND (LocationMatch = 'LSI1-2F')) AS LSI12FMC,
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.EDSBMMaintenance AS b
                               WHERE        ({ fn WEEK(EndOfRepair) } = { fn WEEK(a.EndOfRepair) }) AND (YEAR(EndOfRepair) = YEAR(a.EndOfRepair)) AND (BMStatusID > 10 OR
                                                         BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30) AND (Location = 'LSI3-2F')) AS LSI32FBM,
                             (SELECT        ISNULL(macCount, 0) AS Expr1
                               FROM            dbo.viewBMRateCalcWW AS c
                               WHERE        (myWW = { fn WEEK(a.EndOfRepair) }) AND (myYear = YEAR(a.EndOfRepair)) AND (ProcessMatch = 'EDS') AND (Shift = '1ST') AND (LocationMatch = 'LSI3-2F')) AS LSI32FMC
FROM            dbo.EDSBMMaintenance AS a
WHERE        (BMStatusID > 10 OR
                         BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30) AND (EndOfRepair IS NOT NULL)
GROUP BY { fn WEEK(EndOfRepair) }, EndOfRepair
GO
