/****** Object:  View [dbo].[viewTPBMPerMachineWW]    Script Date: 10/25/2026 4:57:09 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[viewTPBMPerMachineWW]
AS
SELECT DISTINCT { fn WEEK(EndOfRepair) } AS myWW, YEAR(EndOfRepair) AS myYear,
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.TPBMMaintenance AS b
                               WHERE        ({ fn WEEK(EndOfRepair) } = { fn WEEK(a.EndOfRepair) }) AND (YEAR(EndOfRepair) = YEAR(a.EndOfRepair)) AND (BMStatusID > 10 OR
                                                         BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30) AND (Location = 'LSI2-1F')) AS LSI21FBM,
                             (SELECT        ISNULL(macCount, 0) AS Expr1
                               FROM            dbo.viewBMRateCalcWW AS c
                               WHERE        (myWW = { fn WEEK(a.EndOfRepair) }) AND (myYear = YEAR(a.EndOfRepair)) AND (ProcessMatch = 'TP') AND (Shift = '1ST') AND (LocationMatch = 'LSI2-1F')) AS LSI21FMC,
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.TPBMMaintenance AS b
                               WHERE        ({ fn WEEK(EndOfRepair) } = { fn WEEK(a.EndOfRepair) }) AND (YEAR(EndOfRepair) = YEAR(a.EndOfRepair)) AND (BMStatusID > 10 OR
                                                         BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30) AND (Location = 'LSI2-2F')) AS LSI22FBM,
                             (SELECT        ISNULL(macCount, 0) AS Expr1
                               FROM            dbo.viewBMRateCalcWW AS c
                               WHERE        (myWW = { fn WEEK(a.EndOfRepair) }) AND (myYear = YEAR(a.EndOfRepair)) AND (ProcessMatch = 'TP') AND (Shift = '1ST') AND (LocationMatch = 'LSI2-2F')) AS LSI22FMC,
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.TPBMMaintenance AS b
                               WHERE        ({ fn WEEK(EndOfRepair) } = { fn WEEK(a.EndOfRepair) }) AND (YEAR(EndOfRepair) = YEAR(a.EndOfRepair)) AND (BMStatusID > 10 OR
                                                         BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30) AND (Location = 'LSI2-3F')) AS LSI23FBM,
                             (SELECT        ISNULL(macCount, 0) AS Expr1
                               FROM            dbo.viewBMRateCalcWW AS c
                               WHERE        (myWW = { fn WEEK(a.EndOfRepair) }) AND (myYear = YEAR(a.EndOfRepair)) AND (ProcessMatch = 'TP') AND (Shift = '1ST') AND (LocationMatch = 'LSI2-3F')) AS LSI23FMC,
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.TPBMMaintenance AS b
                               WHERE        ({ fn WEEK(EndOfRepair) } = { fn WEEK(a.EndOfRepair) }) AND (YEAR(EndOfRepair) = YEAR(a.EndOfRepair)) AND (BMStatusID > 10 OR
                                                         BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30) AND (Location = 'LSI1-1F')) AS LSI11FBM,
                             (SELECT        ISNULL(macCount, 0) AS Expr1
                               FROM            dbo.viewBMRateCalcWW AS c
                               WHERE        (myWW = { fn WEEK(a.EndOfRepair) }) AND (myYear = YEAR(a.EndOfRepair)) AND (ProcessMatch = 'TP') AND (Shift = '1ST') AND (LocationMatch = 'LSI1-1F')) AS LSI11FMC,
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.TPBMMaintenance AS b
                               WHERE        ({ fn WEEK(EndOfRepair) } = { fn WEEK(a.EndOfRepair) }) AND (YEAR(EndOfRepair) = YEAR(a.EndOfRepair)) AND (BMStatusID > 10 OR
                                                         BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30) AND (Location = 'LSI1-2F')) AS LSI12FBM,
                             (SELECT        ISNULL(macCount, 0) AS Expr1
                               FROM            dbo.viewBMRateCalcWW AS c
                               WHERE        (myWW = { fn WEEK(a.EndOfRepair) }) AND (myYear = YEAR(a.EndOfRepair)) AND (ProcessMatch = 'TP') AND (Shift = '1ST') AND (LocationMatch = 'LSI1-2F')) AS LSI12FMC,
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.TPBMMaintenance AS b
                               WHERE        ({ fn WEEK(EndOfRepair) } = { fn WEEK(a.EndOfRepair) }) AND (YEAR(EndOfRepair) = YEAR(a.EndOfRepair)) AND (BMStatusID > 10 OR
                                                         BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30) AND (Location = 'LSI3-2F')) AS LSI32FBM,
                             (SELECT        ISNULL(macCount, 0) AS Expr1
                               FROM            dbo.viewBMRateCalcWW AS c
                               WHERE        (myWW = { fn WEEK(a.EndOfRepair) }) AND (myYear = YEAR(a.EndOfRepair)) AND (ProcessMatch = 'TP') AND (Shift = '1ST') AND (LocationMatch = 'LSI3-2F')) AS LSI32FMC
FROM            dbo.TPBMMaintenance AS a
WHERE        (BMStatusID > 10 OR
                         BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30) AND (EndOfRepair IS NOT NULL)
GROUP BY { fn WEEK(EndOfRepair) }, EndOfRepair
GO
