/****** Object:  View [dbo].[viewWBBMPerMachineWW]    Script Date: 10/25/2026 4:57:09 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[viewWBBMPerMachineWW]
AS
SELECT DISTINCT { fn WEEK(EndOfRepair) } AS myWW, YEAR(EndOfRepair) AS myYear,
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.WBBMMaintenance AS b
                               WHERE        ({ fn WEEK(EndOfRepair) } = { fn WEEK(a.EndOfRepair) }) AND (YEAR(EndOfRepair) = YEAR(a.EndOfRepair)) AND (BMStatusID > 10 OR
                                                         BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30) AND (Location = 'LSI2-1F')) AS LSI21FBM,
                             (SELECT        ISNULL(macCount, 0) AS Expr1
                               FROM            dbo.viewBMRateCalcWW AS c
                               WHERE        (myWW = { fn WEEK(a.EndOfRepair) }) AND (myYear = YEAR(a.EndOfRepair)) AND (ProcessMatch = 'WB') AND (Shift = '1ST') AND (LocationMatch = 'LSI2-1F')) AS LSI21FMC,
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.WBBMMaintenance AS b
                               WHERE        ({ fn WEEK(EndOfRepair) } = { fn WEEK(a.EndOfRepair) }) AND (YEAR(EndOfRepair) = YEAR(a.EndOfRepair)) AND (BMStatusID > 10 OR
                                                         BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30) AND (Location = 'LSI2-2F')) AS LSI22FBM,
                             (SELECT        ISNULL(macCount, 0) AS Expr1
                               FROM            dbo.viewBMRateCalcWW AS c
                               WHERE        (myWW = { fn WEEK(a.EndOfRepair) }) AND (myYear = YEAR(a.EndOfRepair)) AND (ProcessMatch = 'WB') AND (Shift = '1ST') AND (LocationMatch = 'LSI2-2F')) AS LSI22FMC,
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.WBBMMaintenance AS b
                               WHERE        ({ fn WEEK(EndOfRepair) } = { fn WEEK(a.EndOfRepair) }) AND (YEAR(EndOfRepair) = YEAR(a.EndOfRepair)) AND (BMStatusID > 10 OR
                                                         BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30) AND (Location = 'LSI2-3F')) AS LSI23FBM,
                             (SELECT        ISNULL(macCount, 0) AS Expr1
                               FROM            dbo.viewBMRateCalcWW AS c
                               WHERE        (myWW = { fn WEEK(a.EndOfRepair) }) AND (myYear = YEAR(a.EndOfRepair)) AND (ProcessMatch = 'WB') AND (Shift = '1ST') AND (LocationMatch = 'LSI2-3F')) AS LSI23FMC,
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.WBBMMaintenance AS b
                               WHERE        ({ fn WEEK(EndOfRepair) } = { fn WEEK(a.EndOfRepair) }) AND (YEAR(EndOfRepair) = YEAR(a.EndOfRepair)) AND (BMStatusID > 10 OR
                                                         BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30) AND (Location = 'LSI1-1F')) AS LSI11FBM,
                             (SELECT        ISNULL(macCount, 0) AS Expr1
                               FROM            dbo.viewBMRateCalcWW AS c
                               WHERE        (myWW = { fn WEEK(a.EndOfRepair) }) AND (myYear = YEAR(a.EndOfRepair)) AND (ProcessMatch = 'WB') AND (Shift = '1ST') AND (LocationMatch = 'LSI1-1F')) AS LSI11FMC,
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.WBBMMaintenance AS b
                               WHERE        ({ fn WEEK(EndOfRepair) } = { fn WEEK(a.EndOfRepair) }) AND (YEAR(EndOfRepair) = YEAR(a.EndOfRepair)) AND (BMStatusID > 10 OR
                                                         BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30) AND (Location = 'LSI1-2F')) AS LSI12FBM,
                             (SELECT        ISNULL(macCount, 0) AS Expr1
                               FROM            dbo.viewBMRateCalcWW AS c
                               WHERE        (myWW = { fn WEEK(a.EndOfRepair) }) AND (myYear = YEAR(a.EndOfRepair)) AND (ProcessMatch = 'WB') AND (Shift = '1ST') AND (LocationMatch = 'LSI1-2F')) AS LSI12FMC,
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.WBBMMaintenance AS b
                               WHERE        ({ fn WEEK(EndOfRepair) } = { fn WEEK(a.EndOfRepair) }) AND (YEAR(EndOfRepair) = YEAR(a.EndOfRepair)) AND (BMStatusID > 10 OR
                                                         BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30) AND (Location = 'LSI3-2F')) AS LSI32FBM,
                             (SELECT        ISNULL(macCount, 0) AS Expr1
                               FROM            dbo.viewBMRateCalcWW AS c
                               WHERE        (myWW = { fn WEEK(a.EndOfRepair) }) AND (myYear = YEAR(a.EndOfRepair)) AND (ProcessMatch = 'WB') AND (Shift = '1ST') AND (LocationMatch = 'LSI3-2F')) AS LSI32FMC
FROM            dbo.WBBMMaintenance AS a
WHERE        (BMStatusID > 10 OR
                         BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30) AND (EndOfRepair IS NOT NULL)
GROUP BY { fn WEEK(EndOfRepair) }, EndOfRepair
GO
/****** Object:  View [dbo].[ViewDBBM_OEE]    Script Date: 10/25/2026 4:57:09 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[ViewDBBM_OEE]
AS
SELECT DISTINCT MCNo, { fn IFNULL
                             ((SELECT        TOP (1) CellCon_MCNo
                                 FROM            dbo.MachineNameCompare_OEE
                                 WHERE        (Emaint_MCNo = dbo.DBBMMaintenance.MCNo)), MCNo) } AS MCNoCellCon, MCType, LOTNo, StartOfRepair, EndOfRepair, TimeOfRequest, PEConfirmPMTurnoverDate, GLConfirmOPReqDate, 
                         MONTH(StartOfRepair) AS Month1, DAY(StartOfRepair) AS Day1, YEAR(StartOfRepair) AS Year1, CAST(DATEPART(Hour, TimeOfRequest) AS varchar) + ':' + CAST(DATEPART(Minute, TimeOfRequest) AS varchar) AS timeofrequest1, 
                         MONTH(OccurrenceDate) AS MonthEnd_Emt, DAY(OccurrenceDate) AS DayEnd_Emt, YEAR(OccurrenceDate) AS YearEnd_Emt, CAST(DATEPART(Hour, EndOfRepair) AS varchar) + ':' + CAST(DATEPART(Minute, EndOfRepair) 
                         AS varchar) AS Endofrepair1, { fn WEEK(TimeOfRequest) } AS Week1, Location, { fn WEEK(OccurrenceDate) } AS WeekEnd_Emt, PkgName AS Package, Situation, OccurrenceFreq, OccurrenceFreqQuantity, 
                         OccurrenceFreqLotFrame, RequestedBy, OccurrenceDate, RepairedByEnd, GLConfirmOPReq,
                             (SELECT        BMCase
                               FROM            dbo.BMCase
                               WHERE        (BMCaseID = dbo.DBBMMaintenance.BMCaseID)) AS CaseName, RequestContent, GLConfirmOPReqDate AS GLConfirmDate, StartOfRepair AS StartTime, EndOfRepair AS EndTime, 
                         PEConfirmPMTurnoverDate AS PEStartTime, EndOfRepair AS PEEndTime,
                             (SELECT        PMCategory
                               FROM            dbo.PMCategory
                               WHERE        (PMCategoryID = dbo.DBBMMaintenance.PMCategoryID)) AS Classification, KanagataNo, DeviceName, NGDetectionCircumtances, AQI, RequestedBy AS Issuer, GLConfirmOPReq AS GL, PMConfirmGLOPReq, 
                         PEConfirmPMTurnoverBy, PEConfirmPMTurnoverDate AS Expr1, Why1,
                             (SELECT        CASE WHEN dbo.DBBMMaintenance.Turnover = 'PE' OR
                                                         dbo.DBBMMaintenance.Turnover = 'CC' OR
                                                         dbo.DBBMMaintenance.Turnover = 'VIS' THEN dbo.DBBMMaintenance.PMTurnOvertoPEDate ELSE dbo.DBBMMaintenance.EndOfRepair END AS PMTurnOvertoPEDate) AS PMTurnOvertoPEDate,
                             (SELECT        CASE WHEN dbo.DBBMMaintenance.Turnover = 'PE' OR
                                                         dbo.DBBMMaintenance.Turnover = 'CC' OR
                                                         dbo.DBBMMaintenance.Turnover = 'VIS' THEN dbo.DBBMMaintenance.EndOfRepair ELSE NULL END AS Expr1) AS Endofrepair3
FROM            dbo.DBBMMaintenance
GO
