                         dbo.PLBMMaintenance.isNotQuality2, dbo.PLBMMaintenance.isNotQuality3, dbo.PLBMMaintenance.KanagataNo, dbo.PLBMMaintenance.TypeofRequest, dbo.PLBMMaintenance.LotNo1, dbo.PLBMMaintenance.LotNo2, 
                         dbo.PLBMMaintenance.LotNo3, dbo.PLBMMaintenance.LotNo4, dbo.PLBMMaintenance.WhatCN, dbo.PLBMMaintenance.HowCN, dbo.PLBMMaintenance.WhyCN, dbo.PLBMMaintenance.Prioritization, 
                         dbo.PLBMMaintenance.TRC, dbo.PLBMMaintenance.AQIYN, dbo.PLBMMaintenance.Illustration, dbo.PLBMMaintenance.OtherQuality, dbo.PLBMMaintenance.OccurenceRatePM, dbo.PLBMMaintenance.OccurenceRatePM1, 
                         dbo.PLBMMaintenance.OccurenceRatePM2, dbo.PLBMMaintenance.OPConfAfterWork, dbo.PLBMMaintenance.PMConfAfterWork, dbo.PLBMMaintenance.WorkCheck, dbo.PLBMMaintenance.WorkCheckBefore, 
                         dbo.PLBMMaintenance.WorkCheckAfter, dbo.PLBMMaintenance.ReOccurenceMode, dbo.PLBMMaintenance.RoBMTimes, dbo.PLBMMaintenance.PMReqInsp, dbo.PLBMMaintenance.FiveSMaintenance, 
                         dbo.PLBMMaintenance.SafetyCheck, dbo.PLBMMaintenance.ReqToOtherSec, dbo.PLBMMaintenance.IfYes, dbo.PLBMMaintenance.ShiftLeader, dbo.PLBMMaintenance.VeteranPM, dbo.PLBMMaintenance.InCharge, 
                         dbo.PLBMMaintenance.Manager, dbo.PLBMMaintenance.OtherUnitCheck, dbo.PLBMMaintenance.MCStatGood, dbo.PLBMMaintenance.MCStatNG, dbo.PLBMMaintenance.MCStatTotal, dbo.PLBMMaintenance.PMMiss, 
                         dbo.PLBMMaintenance.GLResolvedRemarks, dbo.PLBMMaintenance.GLResolvedRemarksDate, dbo.PLBMMaintenance.GLResolvedRemarksBy, dbo.PLBMMaintenance.LastBMStop, 
						 dbo.PLBMMaintenance.LastBMContinue, datediff(MINUTE, dbo.PLBMMaintenance.PEConfirmPMTurnoverDate,dbo.PLBMMaintenance.TimeTurnover ) as PEWaitingTime, datediff(MINUTE,dbo.PLBMMaintenance.timeturnover,dbo.PLBMMaintenance.EndofRepair) as PERepairTime, year(dbo.PLBMMaintenance.pmturnovertopedate) as BMYear, month(dbo.PLBMMaintenance.pmturnovertopedate) as BMMonth, day(dbo.PLBMMaintenance.pmturnovertopedate) as BMDay
FROM            dbo.PLBMMaintenance LEFT OUTER JOIN
                         dbo.SubProcess ON dbo.PLBMMaintenance.SubProcessID = dbo.SubProcess.SubProcessID LEFT OUTER JOIN
                         dbo.BMStatus ON dbo.PLBMMaintenance.BMStatusID = dbo.BMStatus.BMStatusID LEFT OUTER JOIN
                         dbo.PMCategory ON dbo.PLBMMaintenance.PMCategoryID = dbo.PMCategory.PMCategoryID LEFT OUTER JOIN
                         dbo.BMCase ON dbo.PLBMMaintenance.BMCaseID = dbo.BMCase.BMCaseID INNER JOIN
                         dbo.MCList ON dbo.PLBMMaintenance.MCNo = dbo.MCList.MCNo LEFT OUTER JOIN
                         dbo.I4M ON dbo.PLBMMaintenance.I4MID = dbo.I4M.I4MID LEFT OUTER JOIN
                         dbo.pm_EquipInsData ON dbo.PLBMMaintenance.bmID = dbo.pm_EquipInsData.bmID

WHERE dbo.PLBMMaintenance.turnover='CC' and dbo.plbmmaintenance.bmstatusid<>30 AND dbo.PLBMMaintenance.PMCategoryID=1


GO
/****** Object:  View [dbo].[viewBMRateCalc]    Script Date: 10/25/2026 4:57:09 PM ******/
