CREATE VIEW [dbo].[ViewMPBM_OEE]
AS
SELECT DISTINCT MCNo, { fn IFNULL
                             ((SELECT        TOP (1) CellCon_MCNo
                                 FROM            dbo.MachineNameCompare_OEE
                                 WHERE        (Emaint_MCNo = dbo.MPBMMaintenance.MCNo)), MCNo) } AS MCNoCellCon, MCType, LOTNo, StartOfRepair, EndOfRepair, TimeOfRequest, PEConfirmPMTurnoverDate, GLConfirmOPReqDate, 
                         MONTH(StartOfRepair) AS Month1, DAY(StartOfRepair) AS Day1, YEAR(StartOfRepair) AS Year1, CAST(DATEPART(Hour, TimeOfRequest) AS varchar) + ':' + CAST(DATEPART(Minute, TimeOfRequest) AS varchar) AS timeofrequest1, 
                         MONTH(OccurrenceDate) AS MonthEnd_Emt, DAY(OccurrenceDate) AS DayEnd_Emt, YEAR(OccurrenceDate) AS YearEnd_Emt, CAST(DATEPART(Hour, EndOfRepair) AS varchar) + ':' + CAST(DATEPART(Minute, EndOfRepair) 
                         AS varchar) AS Endofrepair1, { fn WEEK(OccurrenceDate) } AS WeekEnd_Emt, Location, PkgName AS Package, Situation, OccurrenceFreq, OccurrenceFreqQuantity, OccurrenceFreqLotFrame, RequestedBy, OccurrenceDate, 
                         RepairedByEnd, GLConfirmOPReq,
                             (SELECT        BMCase
                               FROM            dbo.BMCase
                               WHERE        (BMCaseID = dbo.MPBMMaintenance.BMCaseID)) AS CaseName, RequestContent, GLConfirmOPReqDate AS GLConfirmDate, StartOfRepair AS StartTime, EndOfRepair AS EndTime, 
                         PEConfirmPMTurnoverDate AS PEStartTime, EndOfRepair AS PEEndTime,
                             (SELECT        PMCategory
                               FROM            dbo.PMCategory
                               WHERE        (PMCategoryID = dbo.MPBMMaintenance.PMCategoryID)) AS Classification, KanagataNo, DeviceName, NGDetectionCircumtances, AQI, RequestedBy AS Issuer, GLConfirmOPReqBy AS GL, PMConfirmGLOPReq, 
                         PEConfirmPMTurnoverBy, PEConfirmPMTurnoverDate AS Expr1, Why1,
                             (SELECT        CASE WHEN dbo.MPBMMaintenance.Turnover = 'PE' OR
                                                         dbo.MPBMMaintenance.Turnover = 'CC' OR
                                                         dbo.MPBMMaintenance.Turnover = 'VIS' THEN dbo.MPBMMaintenance.PMTurnOvertoPEDate ELSE dbo.MPBMMaintenance.EndOfRepair END AS PMTurnOvertoPEDate) AS PMTurnOvertoPEDate,
                             (SELECT        CASE WHEN dbo.MPBMMaintenance.Turnover = 'PE' OR
                                                         dbo.MPBMMaintenance.Turnover = 'CC' OR
                                                         dbo.MPBMMaintenance.Turnover = 'VIS' THEN dbo.MPBMMaintenance.EndOfRepair ELSE NULL END AS Expr1) AS Endofrepair3
FROM            dbo.MPBMMaintenance
GO
