                         dbo.WBBMMaintenance.ColletAdherePadUsed, dbo.WBBMMaintenance.ColletAdherePadReplaced, dbo.WBBMMaintenance.ChuckTJigTReplaced, dbo.WBBMMaintenance.ChuckTJigTUsed, 
                         dbo.WBBMMaintenance.PkgDevFixed, dbo.WBBMMaintenance.PartsRepCommon, dbo.WBBMMaintenance.SetSTDCommon, dbo.WBBMMaintenance.PKGDev1A, dbo.WBBMMaintenance.PKGDev1B, 
                         dbo.WBBMMaintenance.PKGDev2A, dbo.WBBMMaintenance.PKGDev2B, dbo.WBBMMaintenance.PKGDev3A, dbo.WBBMMaintenance.PKGDev3B, dbo.WBBMMaintenance.PKGDev4A, dbo.WBBMMaintenance.PKGDev4B, 
                         dbo.WBBMMaintenance.PKGDev5A, dbo.WBBMMaintenance.PKGDev5B, dbo.WBBMMaintenance.GLRepairConfirmationBy, dbo.WBBMMaintenance.AcredINSPN, dbo.WBBMMaintenance.MajorTreatment, 
                         dbo.WBBMMaintenance.AccreditorReturnToPMBy, dbo.WBBMMaintenance.AccreditorRetunToPMDate, dbo.WBBMMaintenance.PMTurnOvertoPEBy, dbo.WBBMMaintenance.PMTurnOvertoPEDate, 
                         dbo.WBBMMaintenance.PEConfirmPMTurnoverReq, dbo.WBBMMaintenance.PEConfirmPMTurnoverReason, dbo.WBBMMaintenance.PEConfirmPMTurnoverDate, dbo.WBBMMaintenance.PETurnOverPMBy, 
                         dbo.WBBMMaintenance.PETurnOverPMDate, dbo.WBBMMaintenance.GLResolvedOPReq, dbo.WBBMMaintenance.GLResolvedOPReqBy, dbo.WBBMMaintenance.GLResolvedOPReqDate, 
                         dbo.WBBMMaintenance.PMReturnToAccreditorBy, dbo.WBBMMaintenance.PMReturnToAccreditorDate, dbo.WBBMMaintenance.CheckItem1, dbo.WBBMMaintenance.CheckItem2, dbo.WBBMMaintenance.CheckItem3, 
                         dbo.WBBMMaintenance.OPBMUnitID, dbo.WBBMMaintenance.Process, dbo.WBBMMaintenance.Location, dbo.WBBMMaintenance.ConBeforeAfterAdjValue6, dbo.WBBMMaintenance.ConBeforeAfterAdjValue5, 
                         dbo.WBBMMaintenance.ConBeforeAfterAdjValue4, dbo.WBBMMaintenance.ConBeforeAfterAdjValue3, dbo.WBBMMaintenance.ConBeforeAfterAdjValue2, dbo.WBBMMaintenance.ConBeforeAfterAdjValue1, 
                         dbo.WBBMMaintenance.ConBeforeAfterAdjItem6, dbo.WBBMMaintenance.ConBeforeAfterAdjItem5, dbo.WBBMMaintenance.ConBeforeAfterAdjItem4, dbo.WBBMMaintenance.ConBeforeAfterAdjItem3, 
                         dbo.WBBMMaintenance.ConBeforeAfterAdjItem2, dbo.WBBMMaintenance.ConBeforeAfterAdjItem1, dbo.WBBMMaintenance.RPMRelAdj, dbo.WBBMMaintenance.RPMStandard, dbo.WBBMMaintenance.RPMBefore, 
                         dbo.WBBMMaintenance.RPMAfter, dbo.WBBMMaintenance.CPData, dbo.WBBMMaintenance.QCData, dbo.WBBMMaintenance.BMINSPN, dbo.WBBMMaintenance.BMCategoryID, dbo.WBBMMaintenance.isNotQuality1, 
                         dbo.WBBMMaintenance.isNotQuality2, dbo.WBBMMaintenance.isNotQuality3, dbo.WBBMMaintenance.KanagataNo, dbo.WBBMMaintenance.TypeofRequest, dbo.WBBMMaintenance.SubChuckUsed, 
                         dbo.WBBMMaintenance.SubChuckReplaced, dbo.WBBMMaintenance.PincettePadUsed, dbo.WBBMMaintenance.PincettePadReplaced, dbo.WBBMMaintenance.ChuckTopUsed, dbo.WBBMMaintenance.ChuckTopReplaced, 
                         dbo.WBBMMaintenance.WaferNo, dbo.WBBMMaintenance.DefectiveUnit, dbo.WBBMMaintenance.DefectivePoint, dbo.WBBMMaintenance.LineLoc, dbo.WBBMMaintenance.CC1, dbo.WBBMMaintenance.CC2, 
                         dbo.WBBMMaintenance.CC3, dbo.WBBMMaintenance.CC4, dbo.WBBMMaintenance.CheckCondition, dbo.WBBMMaintenance.CC5, dbo.WBBMMaintenance.PrepofDummyFrames, dbo.WBBMMaintenance.PcsUsed, 
                         dbo.WBBMMaintenance.PcsScrapped, dbo.WBBMMaintenance.Freq1, dbo.WBBMMaintenance.Freq2, dbo.WBBMMaintenance.AbnormalityTreatment, dbo.WBBMMaintenance.BacksideAdj, dbo.WBBMMaintenance.MCInspRel, 
                         dbo.WBBMMaintenance.OccMode, dbo.WBBMMaintenance.ReqTo, dbo.WBBMMaintenance.GLConf, dbo.WBBMMaintenance.Result, dbo.WBBMMaintenance.Rate, dbo.WBBMMaintenance.FourSConfAfterPM, 
                         dbo.WBBMMaintenance.StartPM1, dbo.WBBMMaintenance.StartPM2, dbo.WBBMMaintenance.EndPM1, dbo.WBBMMaintenance.EndPM2, dbo.WBBMMaintenance.Judgement1, dbo.WBBMMaintenance.Judgement2, 
                         dbo.WBBMMaintenance.Judgement3, dbo.WBBMMaintenance.Judgement4, dbo.WBBMMaintenance.Judgement5, dbo.WBBMMaintenance.Judgement6, dbo.WBBMMaintenance.Judgement7, 
                         dbo.WBBMMaintenance.Judgement8, dbo.WBBMMaintenance.Judgement9, dbo.WBBMMaintenance.Judgement10, dbo.WBBMMaintenance.Judgement11, dbo.WBBMMaintenance.Judgement12, 
                         dbo.WBBMMaintenance.Judgement13, dbo.WBBMMaintenance.Judgement14, dbo.WBBMMaintenance.ReporttoGL, dbo.WBBMMaintenance.WiringData, dbo.WBBMMaintenance.ChipNo, dbo.WBBMMaintenance.RowNo, 
                         dbo.WBBMMaintenance.OperationLine, dbo.WBBMMaintenance.CapillaryNo, dbo.WBBMMaintenance.WBCon, dbo.WBBMMaintenance.AdditionalTightening, dbo.WBBMMaintenance.ConSafety, 
                         dbo.WBBMMaintenance.PMMiss, dbo.WBBMMaintenance.LastBMStop, dbo.WBBMMaintenance.LastBMContinue, datediff(MINUTE, dbo.wbBMMaintenance.PEConfirmPMTurnoverDate,dbo.wbBMMaintenance.TimeTurnover ) as PEWaitingTime, datediff(MINUTE,dbo.wbBMMaintenance.timeturnover,dbo.wbBMMaintenance.EndofRepair) as PERepairTime, year(dbo.WBBMMaintenance.pmturnovertopedate) as BMYear, month(dbo.WBBMMaintenance.pmturnovertopedate) as BMMonth, day(dbo.WBBMMaintenance.pmturnovertopedate) as BMDay
FROM            dbo.WBBMMaintenance LEFT OUTER JOIN
                         dbo.SubProcess ON dbo.WBBMMaintenance.SubProcessID = dbo.SubProcess.SubProcessID LEFT OUTER JOIN
                         dbo.BMStatus ON dbo.WBBMMaintenance.BMStatusID = dbo.BMStatus.BMStatusID LEFT OUTER JOIN
                         dbo.PMCategory ON dbo.WBBMMaintenance.PMCategoryID = dbo.PMCategory.PMCategoryID LEFT OUTER JOIN
                         dbo.BMCase ON dbo.WBBMMaintenance.BMCaseID = dbo.BMCase.BMCaseID INNER JOIN
                         dbo.MCList ON dbo.WBBMMaintenance.MCNo = dbo.MCList.MCNo LEFT OUTER JOIN
                         dbo.I4M ON dbo.WBBMMaintenance.I4MID = dbo.I4M.I4MID LEFT OUTER JOIN
                         dbo.pm_EquipInsData ON dbo.WBBMMaintenance.bmID = dbo.pm_EquipInsData.bmID

WHERE DBO.WBBMMAINTENANCE.TURNOVER='CC' AND DBO.WBBMMAINTENANCE.BMSTATUSID<>30 AND dbo.WBBMMaintenance.PMCategoryID=1


GO
/****** Object:  View [dbo].[viewTEWaitingForApproval]    Script Date: 10/25/2026 4:57:09 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[viewTEWaitingForApproval]
AS
SELECT        COUNT(bmID) AS TotalBM, Location, Process,
                             (SELECT        COUNT(BMStatusID) AS GLTotal
                               FROM            dbo.TEBMMaintenance AS b
                               WHERE        (BMStatusID = 1) AND (Location = a.Location)) AS WaitingForGLApprovalTotal,
                             (SELECT        COUNT(BMStatusID) AS PMTotal
                               FROM            dbo.TEBMMaintenance AS c
                               WHERE        (BMStatusID IN (2, 3, 21)) AND (Location = a.Location)) AS WaitingForPMApprovalTotal,
                             (SELECT        COUNT(BMStatusID) AS OnGoingPMTotal
                               FROM            dbo.TEBMMaintenance AS d
                               WHERE        (BMStatusID = 3) AND (Location = a.Location)) AS OnGoingPMTotal,
                             (SELECT        COUNT(BMStatusID) AS PMRepairDoneTotal
                               FROM            dbo.TEBMMaintenance AS e
                               WHERE        (BMStatusID = 4) AND (Location = a.Location)) AS PMRepairDoneTotal,
                             (SELECT        COUNT(BMStatusID) AS GLReturnedToPMTotal
                               FROM            dbo.TEBMMaintenance AS f
                               WHERE        (BMStatusID = 5) AND (Location = a.Location)) AS GLReturnedToPMTotal,
                             (SELECT        COUNT(BMStatusID) AS EETotal
                               FROM            dbo.TEBMMaintenance AS g
                               WHERE        (BMStatusID = 6) AND (Location = a.Location)) AS WaitingForEEApprovalTotal,
                             (SELECT        COUNT(BMStatusID) AS OngoingPERepairTotal
                               FROM            dbo.TEBMMaintenance AS h
                               WHERE        (BMStatusID = 7) AND (Location = a.Location)) AS OngoingPERepairTotal,
                             (SELECT        COUNT(BMStatusID) AS PERepairDoneTotal
                               FROM            dbo.TEBMMaintenance AS i
                               WHERE        (BMStatusID = 8) AND (Location = a.Location)) AS PERepairDoneTotal,
                             (SELECT        COUNT(BMStatusID) AS ReturnedToPETotal
                               FROM            dbo.TEBMMaintenance AS j
                               WHERE        (BMStatusID = 9) AND (Location = a.Location)) AS ReturnedToPETotal,
                             (SELECT        COUNT(BMStatusID) AS PMTurnoverApprovalTotal
                               FROM            dbo.TEBMMaintenance AS k
                               WHERE        (BMStatusID = 10) AND (Location = a.Location)) AS PMTurnoverApprovalTotal,
                             (SELECT        COUNT(BMStatusID) AS AccApprovalTotal
                               FROM            dbo.TEBMMaintenance AS l
                               WHERE        (BMStatusID = 11) AND (Location = a.Location)) AS AccApprovalTotal,
                             (SELECT        COUNT(BMStatusID) AS AccReturnedtoPM
                               FROM            dbo.TEBMMaintenance AS m
                               WHERE        (BMStatusID = 12) AND (Location = a.Location)) AS AccReturnedtoPM,
                             (SELECT        COUNT(BMStatusID) AS PMReturnedtoPM
                               FROM            dbo.TEBMMaintenance AS n
                               WHERE        (BMStatusID = 13) AND (Location = a.Location)) AS PMReturnedtoPM,
                             (SELECT        COUNT(BMStatusID) AS BMClosed
                               FROM            dbo.TEBMMaintenance AS o
                               WHERE        (BMStatusID = 14) AND (Location = a.Location)) AS BMClosed,
                             (SELECT        COUNT(BMStatusID) AS BMInvalid
                               FROM            dbo.TEBMMaintenance AS p
                               WHERE        (BMStatusID = 15) AND (Location = a.Location)) AS BMOcapResolved,
                             (SELECT        COUNT(BMStatusID) AS BMInvalid
                               FROM            dbo.TEBMMaintenance AS q
                               WHERE        (BMStatusID = 30) AND (Location = a.Location)) AS BMInvalid,
                             (SELECT        COUNT(BMStatusID) AS BMVoid
                               FROM            dbo.TEBMMaintenance AS r
                               WHERE        (BMStatusID = 31) AND (Location = a.Location)) AS BMVoid
FROM            dbo.TEBMMaintenance AS a
GROUP BY Location, Process
GO
