/****** Object:  View [dbo].[TPFinalBMRawData]    Script Date: 10/25/2026 4:57:09 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[TPFinalBMRawData]
AS
SELECT        dbo.TPBMMaintenance.MCNo AS [MC No], dbo.TPBMMaintenance.MCType AS [MC Type], dbo.TPBMMaintenance.PkgName AS Package, dbo.TPBMMaintenance.KanagataNo AS [Kanagata Number], 
                         dbo.TPBMMaintenance.LOTNo AS [Lot Number], dbo.TPBMMaintenance.DeviceName AS [Device Name],
                             (SELECT        CASE WHEN dbo.TPBMMaintenance.BMStatusID = 14 THEN PMCategory.PMCategory ELSE PMCategory_1.PMCategory END AS PMCategory) AS Classification, 
                         dbo.TPBMMaintenance.NGDetectionCircumtances AS [NG Detection Circumstance], dbo.TPBMMaintenance.RequestItem AS [Case Name], dbo.TPBMMaintenance.RequestContent AS [Request Content], 
                         dbo.TPBMMaintenance.Situation AS Condition, dbo.TPBMMaintenance.OccurrenceFreq AS [Occurrence Rate Before Condition], dbo.TPBMMaintenance.OccurrenceFreqQuantity AS Quantity1, 
                         dbo.TPBMMaintenance.OccurrenceFreqLotFrame AS Quantity2, dbo.TPBMMaintenance.AQI, dbo.TPBMMaintenance.OccurrenceDate AS [Request Date and Time], dbo.TPBMMaintenance.RequestedBy AS Issuer, 
                         dbo.TPBMMaintenance.GLConfirmOPReqBy AS GL, dbo.TPBMMaintenance.GLConfirmOPReqDate AS [GL Confirmed Date], dbo.TPBMMaintenance.PMConfirmGLOPReqBy AS [PM Confirmed Request],
                             (SELECT        CASE WHEN dbo.TPBMMaintenance.Turnover = 'PE' OR
                                                         dbo.TPBMMaintenance.Turnover = 'CC' OR
                                                         dbo.TPBMMaintenance.Turnover = 'VIS' THEN '' ELSE dbo.TPBMMaintenance.RepairedByEnd END AS Expr1) AS [PM Done Request], dbo.TPBMMaintenance.PMConfirmGLOPReqDate AS [START DATE AND TIME],
                             (SELECT        CASE WHEN dbo.TPBMMaintenance.Turnover = 'PE' OR
                                                         dbo.TPBMMaintenance.Turnover = 'CC' OR
                                                         dbo.TPBMMaintenance.Turnover = 'VIS' THEN dbo.TPBMMaintenance.PMTurnOvertoPEDate ELSE dbo.TPBMMaintenance.EndOfRepair END AS Expr1) AS [END DATE AND TIME], 
                         dbo.TPBMMaintenance.PEConfirmPMTurnoverBy AS [PE Confirmed Request],
                             (SELECT        CASE WHEN dbo.TPBMMaintenance.Turnover = 'PE' OR
                                                         dbo.TPBMMaintenance.Turnover = 'CC' OR
                                                         dbo.TPBMMaintenance.Turnover = 'VIS' THEN dbo.TPBMMaintenance.RepairedByEnd ELSE '' END AS Expr1) AS [PE Done Request], 
                         dbo.TPBMMaintenance.PEConfirmPMTurnoverDate AS [PE START DATE AND TIME],
                             (SELECT        CASE WHEN dbo.TPBMMaintenance.Turnover = 'PE' OR
                                                         dbo.TPBMMaintenance.Turnover = 'CC' OR
                                                         dbo.TPBMMaintenance.Turnover = 'VIS' THEN dbo.TPBMMaintenance.EndOfRepair ELSE NULL END AS Expr1) AS [PE END DATE AND TIME], dbo.TPBMMaintenance.Why1, dbo.TPBMMaintenance.Why2, 
                         dbo.TPBMMaintenance.Why3, dbo.BMWhy.BMWhy AS Why4, dbo.TPBMMaintenance.Treatment1, dbo.TPBMMaintenance.Treatment2, dbo.TPBMMaintenance.Treatment3, dbo.TPBMMaintenance.Treatment4, 
                         dbo.TPBMMaintenance.Treatment5, dbo.TPBMMaintenance.Treatment6, dbo.TPBMMaintenance.Treatment7, dbo.TPBMMaintenance.Treatment8, dbo.TPBMMaintenance.Treatment9, dbo.TPBMMaintenance.Treatment10, 
                         dbo.TPBMMaintenance.Treatment11, dbo.TPBMMaintenance.Treatment12, dbo.TPBMMaintenance.Treatment13, dbo.TPBMMaintenance.Treatment14, dbo.TPBMMaintenance.MajorTreatment AS COUNTERMEASURE1, 
                         dbo.TPBMMaintenance.ConditionAfterAdj AS [AFTER CONDITION], dbo.TPBMMaintenance.ConditionAfterAdjMin AS [AFTER CONDITION QUANTITY1], 
                         dbo.TPBMMaintenance.ConditionAfterAdjMax AS [AFTER CONDITION QUANTITY2], dbo.TPBMMaintenance.UseDummyFrames AS [USING DUMMY PRODUCT], dbo.TPBMMaintenance.DummyIn AS [DUMMY IN], 
                         dbo.TPBMMaintenance.DummyOut AS [DUMMY OUT], dbo.TPBMMaintenance.DroppedWork AS [CHECKING DROPPED WORK], dbo.TPBMMaintenance.DroppedWorkBeforePM AS [DROPPED WORK BEFORE], 
                         dbo.TPBMMaintenance.DroppeWorkAfterPM AS [DROPPED WORK AFTER], dbo.TPBMMaintenance.ItemValueChecked AS [ITEM/VALUE CHECKED], dbo.TPBMMaintenance.ChangedValueChecked AS [CHANGED/CHECKED VALUE], 
                         dbo.TPBMMaintenance.ReqSATInsp AS [REQUEST FOR SAT INSPECTION], dbo.TPBMMaintenance.SATInspResult AS [SAT INSPECTION RESULT], dbo.TPBMMaintenance.SATInspResultStatus AS [SAT INSPECTION], 
                         dbo.TPBMMaintenance.CheckSensorColorNo AS [CHECK SENSOR COLOR AND NO.], dbo.TPBMMaintenance.CheckSensorReaction AS [CHECK SENSOR REACTION], 
                         dbo.TPBMMaintenance.MotionSafetyCoverSwitch AS [MOTION OF SAFETY COVER SWITCH], dbo.TPBMMaintenance.Check5SAfterPMWork AS [5S AFTER PM WORK], 
                         dbo.TPBMMaintenance.SelconReg AS [SELCON REGISTRATION], dbo.TPBMMaintenance.SelconRegValue AS [PREVIOUS ADJUSTMENT], dbo.TPBMMaintenance.InspectionReq AS [INSPECTION REQUEST], 
                         dbo.TPBMMaintenance.InspQtyNeeded AS [INSPECTION QTY NEEDED], dbo.TPBMMaintenance.CheckItem AS [CHECK ITEM1], dbo.TPBMMaintenance.CheckItem1 AS [CHECK ITEM2], 
                         dbo.TPBMMaintenance.CheckItem2 AS [CHECK ITEM3], dbo.TPBMMaintenance.CheckItem3 AS [CHECK ITEM4], dbo.TPBMMaintenance.RequesttoPD AS [REQUEST TO], 
                         dbo.TPBMMaintenance.PDConfirmation AS [PD CONFIRMATION], dbo.TPBMMaintenance.InspectionResults AS [INSPECTION RESULTS], dbo.TPBMMaintenance.PDTreatmentIncharge AS [PD TREATMENT/ INCHARGE], 
                         dbo.TPBMMaintenance.ChangePartsName1 AS [PARTS NAME1], dbo.TPBMMaintenance.ChangePartsType1 AS TYPE1, dbo.TPBMMaintenance.ChangePartsQty1 AS QTY1, 
                         dbo.TPBMMaintenance.ChangePartsNewReworked1 AS [PARTS REPLACED1], dbo.TPBMMaintenance.ChangePartsDate1 AS [CHANGE PARTS DATE1], dbo.TPBMMaintenance.ChangePartsMonthDay1 AS [REMARKS/LIFE1], 
                         dbo.TPBMMaintenance.ChangePartsInsNewReworked1 AS [PARTS INSTALLED1], dbo.TPBMMaintenance.ChangePartsName2 AS [PARTS NAME2], dbo.TPBMMaintenance.ChangePartsType2 AS TYPE2, 
                         dbo.TPBMMaintenance.ChangePartsQty2 AS QTY2, dbo.TPBMMaintenance.ChangePartsNewReworked2 AS [PARTS REPLACED2], dbo.TPBMMaintenance.ChangePartsDate2 AS [CHANGE PARTS DATE2], 
                         dbo.TPBMMaintenance.ChangePartsMonthDay2 AS [REMARKS/LIFE2], dbo.TPBMMaintenance.ChangePartsInsNewReworked2 AS [PARTS INSTALLED2], dbo.TPBMMaintenance.ChangePartsName3 AS [PARTS NAME3], 
                         dbo.TPBMMaintenance.ChangePartsType3 AS TYPE3, dbo.TPBMMaintenance.ChangePartsQty3 AS QTY3, dbo.TPBMMaintenance.ChangePartsNewReworked3 AS [PARTS REPLACED3], 
                         dbo.TPBMMaintenance.ChangePartsDate3 AS [CHANGE PARTS DATE3], dbo.TPBMMaintenance.ChangePartsMonthDay3 AS [REMARKS/LIFE3], dbo.TPBMMaintenance.ChangePartsInsNewReworked3 AS [PARTS INSTALLED3], 
                         dbo.TPBMMaintenance.ChangePartsName4 AS [PARTS NAME4], dbo.TPBMMaintenance.ChangePartsType4 AS TYPE4, dbo.TPBMMaintenance.ChangePartsQty4 AS QTY4, 
                         dbo.TPBMMaintenance.ChangePartsNewReworked4 AS [PARTS REPLACED4], dbo.TPBMMaintenance.ChangePartsDate4 AS [CHANGE PARTS DATE4], dbo.TPBMMaintenance.ChangePartsMonthDay4 AS [REMARKS/LIFE4], 
                         dbo.TPBMMaintenance.ChangePartsInsNewReworked4 AS [PARTS INSTALLED4], dbo.TPBMMaintenance.ChangePartsName5 AS [PARTS NAME5], dbo.TPBMMaintenance.ChangePartsType5 AS TYPE5, 
                         dbo.TPBMMaintenance.ChangePartsQty5 AS QTY5, dbo.TPBMMaintenance.ChangePartsNewReworked5 AS [PARTS REPLACED5], dbo.TPBMMaintenance.ChangePartsDate5 AS [CHANGE PARTS DATE5], 
                         dbo.TPBMMaintenance.ChangePartsMonthDay5 AS [REMARKS/LIFE5], dbo.TPBMMaintenance.ChangePartsInsNewReworked5 AS [PARTS INSTALLED5], dbo.TPBMMaintenance.TypeofRequest AS [TYPE OF REQUEST], 
                         dbo.TPBMMaintenance.PMConfirmGLOPReason AS [INVALID REQUEST REASON], PMCategory_1.PMCategory AS [PM CATEGORY], BMContent_1.BMContent AS [BM CONTENT], BMCase_1.BMCase AS [CASE], 
                         BMMCUnit_1.BMMCUnit AS [MACHINE UNIT], BMPoint_1.BMPoint AS POSITION, BMWorkContent_1.BMWorkContent AS [WORK CONTENT], dbo.TPBMMaintenance.RequestItem AS [BM CAUSE], 
                         dbo.PREVMeasure.PREVMeasure AS [PREVENTIVE MEASURE], dbo.TPBMMaintenance.AccreditorRemarks AS [IN-CHARGE REMARKS], dbo.TPBMMaintenance.AccreditorPMReply AS [PM REMARKS], 
                         BMWhy_1.BM4M AS [4M ANALYSIS TYPE], BMWhy_1.BMWhy AS [4M ANALYSIS], dbo.PMCategory.PMCategory AS [IN-CHARGE PM CATEGORY], dbo.BMContent.BMContent AS [IN-CHARGE-CONTENT], 
                         dbo.BMCase.BMCase AS [IN-CHARGE CASE], dbo.BMMCUnit.BMMCUnit AS [IN-CHARGE MACHINE UNIT], dbo.BMPoint.BMPoint AS [IN-CHARGE POSITION], 
                         dbo.BMWorkContent.BMWorkContent AS [IN-CHARGE WORK CONTENT], BMWhy_2.BMWhy AS [IN-CHARGE CAUSE], dbo.PREVMeasure.PREVMeasure AS [IN-CHARGE PREVENTIVE MEASURE], 
                         dbo.TPBMMaintenance.AcredINSPN AS [PERIODIC RELATED BM], dbo.TPBMMaintenance.bmID, dbo.TPBMMaintenance.OccurrenceDate, dbo.TPBMMaintenance.BMStatusID, dbo.TPBMMaintenance.Process, 
                         dbo.TPBMMaintenance.Location,
                             (SELECT        CASE WHEN dbo.TPBMMaintenance.BMStatusID = '14' OR
                                                         dbo.TPBMMaintenance.BMStatusID = '11' OR
                                                         dbo.TPBMMaintenance.BMStatusID = '13' THEN CASE WHEN dbo.TPBMMaintenance.isnotquality2 = 'No' AND 
                                                         dbo.TPBMMaintenance.isnotquality3 = 'No' THEN 'Yes' ELSE 'No' END ELSE 'No' END AS IsQualityBM) AS IsQualityBM, dbo.TPBMMaintenance.EndBM AS AccreditorTimeStamp
FROM            dbo.TPBMMaintenance LEFT OUTER JOIN
                         dbo.BMWhy ON dbo.TPBMMaintenance.Why4 = dbo.BMWhy.BMWhyID LEFT OUTER JOIN
                         dbo.BMWhy AS BMWhy_2 ON dbo.TPBMMaintenance.AcredBMCauseID = BMWhy_2.BMWhyID LEFT OUTER JOIN
                         dbo.BMWorkContent ON dbo.TPBMMaintenance.AcredBMWorkContentID = dbo.BMWorkContent.BMWorkContentID LEFT OUTER JOIN
                         dbo.BMPoint ON dbo.TPBMMaintenance.AcredBMPointID = dbo.BMPoint.BMPointID LEFT OUTER JOIN
                         dbo.BMMCUnit ON dbo.TPBMMaintenance.AcredBMMCUnitID = dbo.BMMCUnit.BMMCUnitID LEFT OUTER JOIN
                         dbo.BMCase ON dbo.TPBMMaintenance.AcredBMCaseID = dbo.BMCase.BMCaseID LEFT OUTER JOIN
                         dbo.PMCategory ON dbo.TPBMMaintenance.AcredPMCategoryID = dbo.PMCategory.PMCategoryID LEFT OUTER JOIN
                         dbo.BMWhy AS BMWhy_1 ON dbo.TPBMMaintenance.AcredBMCauseID = BMWhy_1.BMWhyID LEFT OUTER JOIN
                         dbo.PREVMeasure ON dbo.TPBMMaintenance.AcredPREVMeasureID = dbo.PREVMeasure.PREVMeasureID LEFT OUTER JOIN
                         dbo.BMWorkContent AS BMWorkContent_1 ON dbo.TPBMMaintenance.BMWorkContentID = BMWorkContent_1.BMWorkContentID LEFT OUTER JOIN
                         dbo.BMPoint AS BMPoint_1 ON dbo.TPBMMaintenance.BMPointID = BMPoint_1.BMPointID LEFT OUTER JOIN
                         dbo.BMCase AS BMCase_1 ON dbo.TPBMMaintenance.BMCaseID = BMCase_1.BMCaseID LEFT OUTER JOIN
                         dbo.BMMCUnit AS BMMCUnit_1 ON dbo.TPBMMaintenance.BMUnitID = BMMCUnit_1.BMMCUnitID LEFT OUTER JOIN
                         dbo.BMContent AS BMContent_1 ON dbo.TPBMMaintenance.BMContentID = BMContent_1.BMContentID LEFT OUTER JOIN
                         dbo.PMCategory AS PMCategory_1 ON dbo.TPBMMaintenance.PMCategoryID = PMCategory_1.PMCategoryID LEFT OUTER JOIN
                         dbo.BMContent ON dbo.TPBMMaintenance.AcredBMContentID = dbo.BMContent.BMContentID
GO
