                  dbo.FLBMMaintenance.BMCategoryID, dbo.FLBMMaintenance.isNotQuality1, dbo.FLBMMaintenance.isNotQuality2, dbo.FLBMMaintenance.isNotQuality3, dbo.FLBMMaintenance.KanagataNo, dbo.FLBMMaintenance.TypeofRequest, 
                  dbo.FLBMMaintenance.LastBMStop, dbo.FLBMMaintenance.LastBMContinue, dbo.FLBMMaintenance.DateWhen, dbo.FLBMMaintenance.LotRetrieval, dbo.FLBMMaintenance.Remarks, dbo.FLBMMaintenance.TurnOverTo, 
                  dbo.FLBMMaintenance.BMVersionNo, dbo.FLBMMaintenance.BMRouteNo, dbo.FLBMMaintenance.LotRetrievalConfirm, dbo.FLBMMaintenance.LotRetrievalDate, dbo.BMWhy.BMWhy AS BMWhy4, 
                  dbo.FLBMMaintenance.disassembleBefore1, dbo.FLBMMaintenance.disassembleBefore2, dbo.FLBMMaintenance.disassembleBefore3, dbo.FLBMMaintenance.disassembleAfter1, dbo.FLBMMaintenance.disassembleAfter2, 
                  dbo.FLBMMaintenance.disassembleAfter3, dbo.FLBMMaintenance.Akapen1, dbo.FLBMMaintenance.Akapen2, dbo.FLBMMaintenance.Akapen3, dbo.FLBMMaintenance.Aopen1, dbo.FLBMMaintenance.Aopen2, 
                  dbo.FLBMMaintenance.Aopen3, dbo.FLBMMaintenance.AssyUnit1, dbo.FLBMMaintenance.AssyUnit2, dbo.FLBMMaintenance.AssyUnit3, dbo.FLBMMaintenance.AssyUnit4, dbo.FLBMMaintenance.AssyUnit5, 
                  dbo.FLBMMaintenance.AssyUnit6, dbo.FLBMMaintenance.AssyUnit7, dbo.FLBMMaintenance.AssyUnit8, dbo.FLBMMaintenance.AssyUnit9, dbo.FLBMMaintenance.AssyUnit10, dbo.FLBMMaintenance.AssyUnit11, 
