SELECT 'FT' AS Process, BMID, McNo, RequestItem, OccurrenceDate, EndOfRepair  FROM dbo.FTBMMaintenance
UNION ALL					 	    
SELECT 'TP' AS Process, BMID, McNo, RequestItem, OccurrenceDate, EndOfRepair  FROM dbo.TPBMMaintenance 
UNION ALL					  	    
SELECT 'TE' AS Process, BMID, McNo, RequestItem, OccurrenceDate, EndOfRepair  FROM dbo.TEBMMaintenance 

WHERE YEAR(OccurrenceDate) > 2021


