CREATE VIEW [dbo].[DBFinalBMRawData]
AS
SELECT        dbo.DBBMMaintenance.MCNo AS [MC No], dbo.DBBMMaintenance.MCType AS [MC Type], dbo.DBBMMaintenance.PkgName AS Package, dbo.DBBMMaintenance.KanagataNo AS [Kanagata Number], 
                         dbo.DBBMMaintenance.LOTNo AS [Lot Number], dbo.DBBMMaintenance.DeviceName AS [Device Name],
                             (SELECT        CASE WHEN dbo.DBBMMaintenance.BMStatusID = 14 THEN PMCategory.PMCategory ELSE PMCategory_1.PMCategory END AS PMCategory) AS Classification, 
                         dbo.DBBMMaintenance.NGDetectionCircumtances AS [NG Detection Circumstance], dbo.DBBMMaintenance.RequestItem AS [Case Name], dbo.DBBMMaintenance.RequestContent AS [Request Content], 
                         dbo.DBBMMaintenance.Situation AS Condition, dbo.DBBMMaintenance.OccurrenceFreq AS [Occurrence Rate Before Condition], dbo.DBBMMaintenance.OccurrenceFreqQuantity AS Quantity1, 
                         dbo.DBBMMaintenance.OccurrenceFreqLotFrame AS Quantity2, dbo.DBBMMaintenance.AQI, dbo.DBBMMaintenance.OccurrenceDate AS [Request Date and Time], dbo.DBBMMaintenance.RequestedBy AS Issuer, 
                         dbo.DBBMMaintenance.GLConfirmOPReqBy AS GL, dbo.DBBMMaintenance.GLConfirmOPReqDate AS [GL Confirmed Date], dbo.DBBMMaintenance.PMConfirmGLOPReqBy AS [PM Confirmed Request],
                             (SELECT        CASE WHEN dbo.DBBMMaintenance.Turnover = 'PE' OR
                                                         dbo.DBBMMaintenance.Turnover = 'CC' OR
                                                         dbo.DBBMMaintenance.Turnover = 'VIS' THEN '' ELSE dbo.DBBMMaintenance.RepairedByEnd END AS Expr1) AS [PM Done Request], 
                         dbo.DBBMMaintenance.PMConfirmGLOPReqDate AS [START DATE AND TIME],
                             (SELECT        CASE WHEN dbo.DBBMMaintenance.Turnover = 'PE' OR
                                                         dbo.DBBMMaintenance.Turnover = 'CC' OR
                                                         dbo.DBBMMaintenance.Turnover = 'VIS' THEN dbo.DBBMMaintenance.PMTurnOvertoPEDate ELSE dbo.DBBMMaintenance.EndOfRepair END AS Expr1) AS [END DATE AND TIME], 
                         dbo.DBBMMaintenance.PEConfirmPMTurnoverBy AS [PE Confirmed Request],
                             (SELECT        CASE WHEN dbo.DBBMMaintenance.Turnover = 'PE' OR
                                                         dbo.DBBMMaintenance.Turnover = 'CC' OR
                                                         dbo.DBBMMaintenance.Turnover = 'VIS' THEN dbo.DBBMMaintenance.RepairedByEnd ELSE '' END AS Expr1) AS [PE Done Request], 
                         dbo.DBBMMaintenance.PEConfirmPMTurnoverDate AS [PE START DATE AND TIME],
                             (SELECT        CASE WHEN dbo.DBBMMaintenance.Turnover = 'PE' OR
                                                         dbo.DBBMMaintenance.Turnover = 'CC' OR
                                                         dbo.DBBMMaintenance.Turnover = 'VIS' THEN dbo.DBBMMaintenance.EndOfRepair ELSE NULL END AS Expr1) AS [PE END DATE AND TIME], dbo.DBBMMaintenance.Why1, dbo.DBBMMaintenance.Why2, 
                         dbo.DBBMMaintenance.Why3, dbo.BMWhy.BMWhy AS Why4, dbo.DBBMMaintenance.Treatment1, dbo.DBBMMaintenance.Treatment2, dbo.DBBMMaintenance.Treatment3, dbo.DBBMMaintenance.Treatment4, 
                         dbo.DBBMMaintenance.Treatment5, dbo.DBBMMaintenance.Treatment6, dbo.DBBMMaintenance.Treatment7, dbo.DBBMMaintenance.Treatment8, dbo.DBBMMaintenance.Treatment9, dbo.DBBMMaintenance.Treatment10, 
                         dbo.DBBMMaintenance.Treatment11, dbo.DBBMMaintenance.Treatment12, dbo.DBBMMaintenance.Treatment13, dbo.DBBMMaintenance.Treatment14, dbo.DBBMMaintenance.MajorTreatment AS COUNTERMEASURE1, 
                         dbo.DBBMMaintenance.ConditionAfterAdj AS [AFTER CONDITION], dbo.DBBMMaintenance.ConditionAfterAdjMin AS [AFTER CONDITION QUANTITY1], 
                         dbo.DBBMMaintenance.ConditionAfterAdjMax AS [AFTER CONDITION QUANTITY2], dbo.DBBMMaintenance.UseDummyFrames AS [USING DUMMY PRODUCT], dbo.DBBMMaintenance.DummyIn AS [DUMMY IN], 
                         dbo.DBBMMaintenance.DummyOut AS [DUMMY OUT], dbo.DBBMMaintenance.DroppedWork AS [CHECKING DROPPED WORK], dbo.DBBMMaintenance.DroppedWorkBeforePM AS [DROPPED WORK BEFORE], 
                         dbo.DBBMMaintenance.DroppeWorkAfterPM AS [DROPPED WORK AFTER], dbo.DBBMMaintenance.ItemValueChecked AS [ITEM/VALUE CHECKED], 
                         dbo.DBBMMaintenance.ChangedValueChecked AS [CHANGED/CHECKED VALUE], dbo.DBBMMaintenance.ReqSATInsp AS [REQUEST FOR SAT INSPECTION], 
                         dbo.DBBMMaintenance.SATInspResult AS [SAT INSPECTION RESULT], dbo.DBBMMaintenance.SATInspResultStatus AS [SAT INSPECTION], dbo.DBBMMaintenance.CheckSensorColorNo AS [CHECK SENSOR COLOR AND NO.], 
                         dbo.DBBMMaintenance.CheckSensorReaction AS [CHECK SENSOR REACTION], dbo.DBBMMaintenance.MotionSafetyCoverSwitch AS [MOTION OF SAFETY COVER SWITCH], 
                         dbo.DBBMMaintenance.Check5SAfterPMWork AS [5S AFTER PM WORK], dbo.DBBMMaintenance.SelconReg AS [SELCON REGISTRATION], dbo.DBBMMaintenance.SelconRegValue AS [PREVIOUS ADJUSTMENT], 
                         dbo.DBBMMaintenance.InspectionReq AS [INSPECTION REQUEST], dbo.DBBMMaintenance.InspQtyNeeded AS [INSPECTION QTY NEEDED], dbo.DBBMMaintenance.CheckItem AS [CHECK ITEM1], 
                         dbo.DBBMMaintenance.CheckItem1 AS [CHECK ITEM2], dbo.DBBMMaintenance.CheckItem2 AS [CHECK ITEM3], dbo.DBBMMaintenance.CheckItem3 AS [CHECK ITEM4], dbo.DBBMMaintenance.RequesttoPD AS [REQUEST TO], 
                         dbo.DBBMMaintenance.PDConfirmation AS [PD CONFIRMATION], dbo.DBBMMaintenance.InspectionResults AS [INSPECTION RESULTS], dbo.DBBMMaintenance.PDTreatmentIncharge AS [PD TREATMENT/ INCHARGE], 
                         dbo.DBBMMaintenance.ChangePartsName1 AS [PARTS NAME1], dbo.DBBMMaintenance.ChangePartsType1 AS TYPE1, dbo.DBBMMaintenance.ChangePartsQty1 AS QTY1, 
                         dbo.DBBMMaintenance.ChangePartsNewReworked1 AS [PARTS REPLACED1], dbo.DBBMMaintenance.ChangePartsDate1 AS [CHANGE PARTS DATE1], dbo.DBBMMaintenance.ChangePartsMonthDay1 AS [REMARKS/LIFE1], 
                         dbo.DBBMMaintenance.ChangePartsInsNewReworked1 AS [PARTS INSTALLED1], dbo.DBBMMaintenance.ChangePartsName2 AS [PARTS NAME2], dbo.DBBMMaintenance.ChangePartsType2 AS TYPE2, 
                         dbo.DBBMMaintenance.ChangePartsQty2 AS QTY2, dbo.DBBMMaintenance.ChangePartsNewReworked2 AS [PARTS REPLACED2], dbo.DBBMMaintenance.ChangePartsDate2 AS [CHANGE PARTS DATE2], 
                         dbo.DBBMMaintenance.ChangePartsMonthDay2 AS [REMARKS/LIFE2], dbo.DBBMMaintenance.ChangePartsInsNewReworked2 AS [PARTS INSTALLED2], dbo.DBBMMaintenance.ChangePartsName3 AS [PARTS NAME3], 
                         dbo.DBBMMaintenance.ChangePartsType3 AS TYPE3, dbo.DBBMMaintenance.ChangePartsQty3 AS QTY3, dbo.DBBMMaintenance.ChangePartsNewReworked3 AS [PARTS REPLACED3], 
                         dbo.DBBMMaintenance.ChangePartsDate3 AS [CHANGE PARTS DATE3], dbo.DBBMMaintenance.ChangePartsMonthDay3 AS [REMARKS/LIFE3], dbo.DBBMMaintenance.ChangePartsInsNewReworked3 AS [PARTS INSTALLED3], 
                         dbo.DBBMMaintenance.ChangePartsName4 AS [PARTS NAME4], dbo.DBBMMaintenance.ChangePartsType4 AS TYPE4, dbo.DBBMMaintenance.ChangePartsQty4 AS QTY4, 
                         dbo.DBBMMaintenance.ChangePartsNewReworked4 AS [PARTS REPLACED4], dbo.DBBMMaintenance.ChangePartsDate4 AS [CHANGE PARTS DATE4], dbo.DBBMMaintenance.ChangePartsMonthDay4 AS [REMARKS/LIFE4], 
                         dbo.DBBMMaintenance.ChangePartsInsNewReworked4 AS [PARTS INSTALLED4], dbo.DBBMMaintenance.ChangePartsName5 AS [PARTS NAME5], dbo.DBBMMaintenance.ChangePartsType5 AS TYPE5, 
                         dbo.DBBMMaintenance.ChangePartsQty5 AS QTY5, dbo.DBBMMaintenance.ChangePartsNewReworked5 AS [PARTS REPLACED5], dbo.DBBMMaintenance.ChangePartsDate5 AS [CHANGE PARTS DATE5], 
                         dbo.DBBMMaintenance.ChangePartsMonthDay5 AS [REMARKS/LIFE5], dbo.DBBMMaintenance.ChangePartsInsNewReworked5 AS [PARTS INSTALLED5], dbo.DBBMMaintenance.TypeofRequest AS [TYPE OF REQUEST], 
                         dbo.DBBMMaintenance.PMConfirmGLOPReason AS [INVALID REQUEST REASON], PMCategory_1.PMCategory AS [PM CATEGORY], BMContent_1.BMContent AS [BM CONTENT], BMCase_1.BMCase AS [CASE], 
                         BMMCUnit_1.BMMCUnit AS [MACHINE UNIT], BMPoint_1.BMPoint AS POSITION, BMWorkContent_1.BMWorkContent AS [WORK CONTENT], dbo.DBBMMaintenance.RequestItem AS [BM CAUSE], 
                         dbo.PREVMeasure.PREVMeasure AS [PREVENTIVE MEASURE], dbo.DBBMMaintenance.AccreditorRemarks AS [IN-CHARGE REMARKS], dbo.DBBMMaintenance.AccreditorPMReply AS [PM REMARKS], 
                         BMWhy_1.BM4M AS [4M ANALYSIS TYPE], BMWhy_1.BMWhy AS [4M ANALYSIS], dbo.PMCategory.PMCategory AS [IN-CHARGE PM CATEGORY], dbo.BMContent.BMContent AS [IN-CHARGE-CONTENT], 
                         dbo.BMCase.BMCase AS [IN-CHARGE CASE], dbo.BMMCUnit.BMMCUnit AS [IN-CHARGE MACHINE UNIT], dbo.BMPoint.BMPoint AS [IN-CHARGE POSITION], 
                         dbo.BMWorkContent.BMWorkContent AS [IN-CHARGE WORK CONTENT], BMWhy_2.BMWhy AS [IN-CHARGE CAUSE], dbo.PREVMeasure.PREVMeasure AS [IN-CHARGE PREVENTIVE MEASURE], 
                         dbo.DBBMMaintenance.AcredINSPN AS [PERIODIC RELATED BM], dbo.DBBMMaintenance.OccurrenceDate, dbo.DBBMMaintenance.BMStatusID, dbo.DBBMMaintenance.bmID, dbo.DBBMMaintenance.Process, 
                         dbo.DBBMMaintenance.Location, dbo.DBBMMaintenance.LineLoc, dbo.DBBMMaintenance.WaferNo,
                             (SELECT        CASE WHEN dbo.DBBMMaintenance.BMStatusID = '14' OR
                                                         dbo.DBBMMaintenance.BMStatusID = '11' OR
                                                         dbo.DBBMMaintenance.BMStatusID = '13' THEN CASE WHEN dbo.DBBMMaintenance.isnotquality2 = 'No' AND 
                                                         dbo.DBBMMaintenance.isnotquality3 = 'No' THEN 'Yes' ELSE 'No' END ELSE 'No' END AS IsQualityBM) AS IsQualityBM, dbo.DBBMMaintenance.EndBM AS AccreditorTimeStamp
FROM            dbo.DBBMMaintenance LEFT OUTER JOIN
                         dbo.BMWhy ON dbo.DBBMMaintenance.Why4 = dbo.BMWhy.BMWhyID LEFT OUTER JOIN
                         dbo.BMWhy AS BMWhy_2 ON dbo.DBBMMaintenance.AcredBMCauseID = BMWhy_2.BMWhyID LEFT OUTER JOIN
                         dbo.BMWorkContent ON dbo.DBBMMaintenance.AcredBMWorkContentID = dbo.BMWorkContent.BMWorkContentID LEFT OUTER JOIN
                         dbo.BMPoint ON dbo.DBBMMaintenance.AcredBMPointID = dbo.BMPoint.BMPointID LEFT OUTER JOIN
                         dbo.BMMCUnit ON dbo.DBBMMaintenance.AcredBMMCUnitID = dbo.BMMCUnit.BMMCUnitID LEFT OUTER JOIN
                         dbo.BMCase ON dbo.DBBMMaintenance.AcredBMCaseID = dbo.BMCase.BMCaseID LEFT OUTER JOIN
                         dbo.PMCategory ON dbo.DBBMMaintenance.AcredPMCategoryID = dbo.PMCategory.PMCategoryID LEFT OUTER JOIN
                         dbo.BMWhy AS BMWhy_1 ON dbo.DBBMMaintenance.AcredBMCauseID = BMWhy_1.BMWhyID LEFT OUTER JOIN
                         dbo.PREVMeasure ON dbo.DBBMMaintenance.AcredPREVMeasureID = dbo.PREVMeasure.PREVMeasureID LEFT OUTER JOIN
