                         dbo.BMCase AS BMCase_1 ON dbo.DBBMMaintenance.BMCaseID = BMCase_1.BMCaseID LEFT OUTER JOIN
                         dbo.BMMCUnit AS BMMCUnit_1 ON dbo.DBBMMaintenance.BMUnitID = BMMCUnit_1.BMMCUnitID LEFT OUTER JOIN
                         dbo.BMContent AS BMContent_1 ON dbo.DBBMMaintenance.BMContentID = BMContent_1.BMContentID LEFT OUTER JOIN
                         dbo.PMCategory AS PMCategory_1 ON dbo.DBBMMaintenance.PMCategoryID = PMCategory_1.PMCategoryID LEFT OUTER JOIN
                         dbo.BMContent ON dbo.DBBMMaintenance.AcredBMContentID = dbo.BMContent.BMContentID
