/****** Object:  Table [dbo].[MachineKarte_ReBM]    Script Date: 10/25/2026 4:57:09 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE TABLE [dbo].[MachineKarte_ReBM](
	[Seqno] [int] IDENTITY(1,1) NOT NULL,
	[BMID] [int] NULL,
	[Process] [varchar](20) NULL,
	[Mcno] [varchar](20) NULL,
	[BMCase] [varchar](255) NULL,
	[BMContent] [varchar](100) NULL,
	[ReoccurenceCount] [int] NULL,
	[isMCD] [varchar](10) NULL,
	[isSent] [bit] NULL,
	[isDone] [bit] NULL,
	[DeviceName] [varchar](50) NULL,
	[MCLocation] [varchar](50) NULL,
	[TimeOfRequest] [datetime] NULL,
 CONSTRAINT [PK_MachineKarte_ReBM] PRIMARY KEY CLUSTERED 
(
	[Seqno] ASC
)WITH (PAD_INDEX = OFF, STATISTICS_NORECOMPUTE = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON) ON [PRIMARY]
) ON [PRIMARY]
GO
/****** Object:  View [dbo].[viewKarteReBM]    Script Date: 10/25/2026 4:57:09 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[viewKarteReBM]
AS
SELECT a.Seqno, a.BMID, a.Process, c.ProcessID, a.Mcno, a.MCLocation AS Location, a.DeviceName, a.BMCase, a.BMContent, a.ReoccurenceCount, a.isMCD, a.isDone, b.Name, b.Position, b.CellNumber, b.Location AS ContactLocation
FROM     dbo.MachineKarte_ReBM AS a INNER JOIN
                  dbo.PMContacts AS b ON a.Process = b.Process AND (a.ReoccurenceCount = 3 AND b.Position = 'SM' AND a.MCLocation = b.Location OR
                  a.ReoccurenceCount = 4 AND b.Position = 'DM' OR
                  a.ReoccurenceCount = 5 AND b.Position = 'DIVISION') INNER JOIN
                  dbo.Process AS c ON a.Process = c.ProcessName
WHERE  (a.isDone = '0')
GO
