CREATE TABLE [dbo].[MachineKarte_ActionCard_TE](
	[Seqno] [int] IDENTITY(1,1) NOT NULL,
	[bmID] [int] NULL,
	[MachineNo] [varchar](50) NULL,
	[ProblemContent] [varchar](max) NULL,
	[InCharge] [varchar](50) NULL,
	[DateCard] [varchar](50) NULL,
	[InvestigationDone] [varchar](max) NULL,
	[Action] [varchar](max) NULL,
	[Comment] [varchar](max) NULL,
	[Date1] [varchar](50) NULL,
	[InCharge1] [varchar](50) NULL,
	[Comment2] [varchar](max) NULL,
	[Date2] [varchar](50) NULL,
	[InCharge2] [varchar](50) NULL,
	[Comment3] [varchar](max) NULL,
	[Date3] [varchar](50) NULL,
	[InCharge3] [varchar](50) NULL,
	[MCStatus] [varchar](50) NULL,
	[PMReply1] [varchar](max) NULL,
	[PMReply2] [varchar](max) NULL,
	[PMReply3] [varchar](max) NULL,
	[PMIncharge1] [varchar](50) NULL,
	[PMIncharge2] [varchar](50) NULL,
	[PMIncharge3] [varchar](50) NULL,
