/****** Object:  View [dbo].[viewMachineKarte_ActionCard_TE]    Script Date: 10/25/2026 4:57:09 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[viewMachineKarte_ActionCard_TE]
AS
SELECT TOP (1000) Seqno, bmID, MachineNo, ProblemContent, InCharge, DateCard, InvestigationDone, Action, Comment, Date1, InCharge1, Comment2, Date2, InCharge2, Comment3, Date3, InCharge3, MCStatus, PMReply1, PMReply2, PMReply3, 
                  PMIncharge1, PMIncharge2, PMIncharge3, PMDate1, PMDate2, PMDate3, CASE WHEN InCharge3 = '' THEN 'No' ELSE 'Yes' END AS HaveAction_DeptMan
FROM     dbo.MachineKarte_ActionCard_TE
GO
