	s.TPMSaved,
	bs.BMStatus,
	sp.SubProcess,
	pc.PMCategory, 
	s.PMConfirmGLOPReq,
	e.PMConfirmGLOPReqBy,
	e.PMConfirmGLOPReqDate,
	e.AccreditorPMReply,
	e.AccreditorRemarks,
	s.AccreditorI4MID,
	s.PMConfirmGLOPReason,
