CREATE VIEW [dbo].[SINGFinalBMRawData]
AS
SELECT        dbo.SINGBMMaintenance.MCNo AS [MC No], dbo.SINGBMMaintenance.MCType AS [MC Type], dbo.SINGBMMaintenance.PkgName AS Package, dbo.SINGBMMaintenance.KanagataNo AS [Kanagata Number], 
                         dbo.SINGBMMaintenance.LOTNo AS [Lot Number], dbo.SINGBMMaintenance.DeviceName AS [Device Name],
                             (SELECT        CASE WHEN dbo.SINGBMMaintenance.BMStatusID = 14 THEN PMCategory.PMCategory ELSE PMCategory_1.PMCategory END AS PMCategory) AS Classification, 
                         dbo.SINGBMMaintenance.NGDetectionCircumtances AS [NG Detection Circumstance], dbo.SINGBMMaintenance.RequestItem AS [Case Name], dbo.SINGBMMaintenance.RequestContent AS [Request Content], 
                         dbo.SINGBMMaintenance.Situation AS Condition, dbo.SINGBMMaintenance.OccurrenceFreq AS [Occurrence Rate Before Condition], dbo.SINGBMMaintenance.OccurrenceFreqQuantity AS Quantity1, 
                         dbo.SINGBMMaintenance.OccurrenceFreqLotFrame AS Quantity2, dbo.SINGBMMaintenance.AQI, dbo.SINGBMMaintenance.OccurrenceDate AS [Request Date and Time], dbo.SINGBMMaintenance.RequestedBy AS Issuer, 
                         dbo.SINGBMMaintenance.GLConfirmOPReqBy AS GL, dbo.SINGBMMaintenance.GLConfirmOPReqDate AS [GL Confirmed Date], dbo.SINGBMMaintenance.PMConfirmGLOPReqBy AS [PM Confirmed Request],
                             (SELECT        CASE WHEN dbo.SINGBMMaintenance.Turnover = 'PE' OR
                                                         dbo.SINGBMMaintenance.Turnover = 'CC' OR
                                                         dbo.SINGBMMaintenance.Turnover = 'VIS' THEN '' ELSE dbo.SINGBMMaintenance.RepairedByEnd END AS Expr1) AS [PM Done Request], 
                         dbo.SINGBMMaintenance.PMConfirmGLOPReqDate AS [START DATE AND TIME],
                             (SELECT        CASE WHEN dbo.SINGBMMaintenance.Turnover = 'PE' OR
                                                         dbo.SINGBMMaintenance.Turnover = 'CC' OR
                                                         dbo.SINGBMMaintenance.Turnover = 'VIS' THEN dbo.SINGBMMaintenance.PMTurnOvertoPEDate ELSE dbo.SINGBMMaintenance.EndOfRepair END AS Expr1) AS [END DATE AND TIME], 
                         dbo.SINGBMMaintenance.PEConfirmPMTurnoverBy AS [PE Confirmed Request],
                             (SELECT        CASE WHEN dbo.SINGBMMaintenance.Turnover = 'PE' OR
                                                         dbo.SINGBMMaintenance.Turnover = 'CC' OR
                                                         dbo.SINGBMMaintenance.Turnover = 'VIS' THEN dbo.SINGBMMaintenance.RepairedByEnd ELSE '' END AS Expr1) AS [PE Done Request], 
                         dbo.SINGBMMaintenance.PEConfirmPMTurnoverDate AS [PE START DATE AND TIME],
                             (SELECT        CASE WHEN dbo.SINGBMMaintenance.Turnover = 'PE' OR
                                                         dbo.SINGBMMaintenance.Turnover = 'CC' OR
                                                         dbo.SINGBMMaintenance.Turnover = 'VIS' THEN dbo.SINGBMMaintenance.EndOfRepair ELSE NULL END AS Expr1) AS [PE END DATE AND TIME], dbo.SINGBMMaintenance.Why1, 
                         dbo.SINGBMMaintenance.Why2, dbo.SINGBMMaintenance.Why3, dbo.BMWhy.BMWhy AS Why4, dbo.SINGBMMaintenance.Treatment1, dbo.SINGBMMaintenance.Treatment2, dbo.SINGBMMaintenance.Treatment3, 
                         dbo.SINGBMMaintenance.Treatment4, dbo.SINGBMMaintenance.Treatment5, dbo.SINGBMMaintenance.Treatment6, dbo.SINGBMMaintenance.Treatment7, dbo.SINGBMMaintenance.Treatment8, 
                         dbo.SINGBMMaintenance.Treatment9, dbo.SINGBMMaintenance.Treatment10, dbo.SINGBMMaintenance.Treatment11, dbo.SINGBMMaintenance.Treatment12, dbo.SINGBMMaintenance.Treatment13, 
                         dbo.SINGBMMaintenance.Treatment14, dbo.SINGBMMaintenance.MajorTreatment AS COUNTERMEASURE1, dbo.SINGBMMaintenance.ConditionAfterAdj AS [AFTER CONDITION], 
                         dbo.SINGBMMaintenance.ConditionAfterAdjMin AS [AFTER CONDITION QUANTITY1], dbo.SINGBMMaintenance.ConditionAfterAdjMax AS [AFTER CONDITION QUANTITY2], 
                         dbo.SINGBMMaintenance.UseDummyFrames AS [USING DUMMY PRODUCT], dbo.SINGBMMaintenance.DummyIn AS [DUMMY IN], dbo.SINGBMMaintenance.DummyOut AS [DUMMY OUT], 
                         dbo.SINGBMMaintenance.DroppedWork AS [CHECKING DROPPED WORK], dbo.SINGBMMaintenance.DroppedWorkBeforePM AS [DROPPED WORK BEFORE], 
                         dbo.SINGBMMaintenance.DroppeWorkAfterPM AS [DROPPED WORK AFTER], dbo.SINGBMMaintenance.ItemValueChecked AS [ITEM/VALUE CHECKED], 
                         dbo.SINGBMMaintenance.ChangedValueChecked AS [CHANGED/CHECKED VALUE], dbo.SINGBMMaintenance.ReqSATInsp AS [REQUEST FOR SAT INSPECTION], 
                         dbo.SINGBMMaintenance.SATInspResult AS [SAT INSPECTION RESULT], dbo.SINGBMMaintenance.SATInspResultStatus AS [SAT INSPECTION], 
                         dbo.SINGBMMaintenance.CheckSensorColorNo AS [CHECK SENSOR COLOR AND NO.], dbo.SINGBMMaintenance.CheckSensorReaction AS [CHECK SENSOR REACTION], 
                         dbo.SINGBMMaintenance.MotionSafetyCoverSwitch AS [MOTION OF SAFETY COVER SWITCH], dbo.SINGBMMaintenance.Check5SAfterPMWork AS [5S AFTER PM WORK], 
                         dbo.SINGBMMaintenance.SelconReg AS [SELCON REGISTRATION], dbo.SINGBMMaintenance.SelconRegValue AS [PREVIOUS ADJUSTMENT], dbo.SINGBMMaintenance.InspectionReq AS [INSPECTION REQUEST], 
                         dbo.SINGBMMaintenance.InspQtyNeeded AS [INSPECTION QTY NEEDED], dbo.SINGBMMaintenance.CheckItem AS [CHECK ITEM1], dbo.SINGBMMaintenance.CheckItem1 AS [CHECK ITEM2], 
                         dbo.SINGBMMaintenance.CheckItem2 AS [CHECK ITEM3], dbo.SINGBMMaintenance.CheckItem3 AS [CHECK ITEM4], dbo.SINGBMMaintenance.RequesttoPD AS [REQUEST TO], 
                         dbo.SINGBMMaintenance.PDConfirmation AS [PD CONFIRMATION], dbo.SINGBMMaintenance.InspectionResults AS [INSPECTION RESULTS], dbo.SINGBMMaintenance.PDTreatmentIncharge AS [PD TREATMENT/ INCHARGE], 
                         dbo.SINGBMMaintenance.ChangePartsName1 AS [PARTS NAME1], dbo.SINGBMMaintenance.ChangePartsType1 AS TYPE1, dbo.SINGBMMaintenance.ChangePartsQty1 AS QTY1, 
                         dbo.SINGBMMaintenance.ChangePartsNewReworked1 AS [PARTS REPLACED1], dbo.SINGBMMaintenance.ChangePartsDate1 AS [CHANGE PARTS DATE1], 
                         dbo.SINGBMMaintenance.ChangePartsMonthDay1 AS [REMARKS/LIFE1], dbo.SINGBMMaintenance.ChangePartsInsNewReworked1 AS [PARTS INSTALLED1], dbo.SINGBMMaintenance.ChangePartsName2 AS [PARTS NAME2], 
                         dbo.SINGBMMaintenance.ChangePartsType2 AS TYPE2, dbo.SINGBMMaintenance.ChangePartsQty2 AS QTY2, dbo.SINGBMMaintenance.ChangePartsNewReworked2 AS [PARTS REPLACED2], 
                         dbo.SINGBMMaintenance.ChangePartsDate2 AS [CHANGE PARTS DATE2], dbo.SINGBMMaintenance.ChangePartsMonthDay2 AS [REMARKS/LIFE2], 
                         dbo.SINGBMMaintenance.ChangePartsInsNewReworked2 AS [PARTS INSTALLED2], dbo.SINGBMMaintenance.ChangePartsName3 AS [PARTS NAME3], dbo.SINGBMMaintenance.ChangePartsType3 AS TYPE3, 
                         dbo.SINGBMMaintenance.ChangePartsQty3 AS QTY3, dbo.SINGBMMaintenance.ChangePartsNewReworked3 AS [PARTS REPLACED3], dbo.SINGBMMaintenance.ChangePartsDate3 AS [CHANGE PARTS DATE3], 
                         dbo.SINGBMMaintenance.ChangePartsMonthDay3 AS [REMARKS/LIFE3], dbo.SINGBMMaintenance.ChangePartsInsNewReworked3 AS [PARTS INSTALLED3], dbo.SINGBMMaintenance.ChangePartsName4 AS [PARTS NAME4], 
                         dbo.SINGBMMaintenance.ChangePartsType4 AS TYPE4, dbo.SINGBMMaintenance.ChangePartsQty4 AS QTY4, dbo.SINGBMMaintenance.ChangePartsNewReworked4 AS [PARTS REPLACED4], 
                         dbo.SINGBMMaintenance.ChangePartsDate4 AS [CHANGE PARTS DATE4], dbo.SINGBMMaintenance.ChangePartsMonthDay4 AS [REMARKS/LIFE4], 
                         dbo.SINGBMMaintenance.ChangePartsInsNewReworked4 AS [PARTS INSTALLED4], dbo.SINGBMMaintenance.ChangePartsName5 AS [PARTS NAME5], dbo.SINGBMMaintenance.ChangePartsType5 AS TYPE5, 
                         dbo.SINGBMMaintenance.ChangePartsQty5 AS QTY5, dbo.SINGBMMaintenance.ChangePartsNewReworked5 AS [PARTS REPLACED5], dbo.SINGBMMaintenance.ChangePartsDate5 AS [CHANGE PARTS DATE5], 
                         dbo.SINGBMMaintenance.ChangePartsMonthDay5 AS [REMARKS/LIFE5], dbo.SINGBMMaintenance.ChangePartsInsNewReworked5 AS [PARTS INSTALLED5], dbo.SINGBMMaintenance.TypeofRequest AS [TYPE OF REQUEST], 
                         dbo.SINGBMMaintenance.PMConfirmGLOPReason AS [INVALID REQUEST REASON], PMCategory_1.PMCategory AS [PM CATEGORY], BMContent_1.BMContent AS [BM CONTENT], BMCase_1.BMCase AS [CASE], 
                         BMMCUnit_1.BMMCUnit AS [MACHINE UNIT], BMPoint_1.BMPoint AS POSITION, BMWorkContent_1.BMWorkContent AS [WORK CONTENT], dbo.SINGBMMaintenance.RequestItem AS [BM CAUSE], 
                         dbo.PREVMeasure.PREVMeasure AS [PREVENTIVE MEASURE], dbo.SINGBMMaintenance.AccreditorRemarks AS [IN-CHARGE REMARKS], dbo.SINGBMMaintenance.AccreditorPMReply AS [PM REMARKS], 
                         BMWhy_1.BM4M AS [4M ANALYSIS TYPE], BMWhy_1.BMWhy AS [4M ANALYSIS], dbo.PMCategory.PMCategory AS [IN-CHARGE PM CATEGORY], dbo.BMContent.BMContent AS [IN-CHARGE-CONTENT], 
                         dbo.BMCase.BMCase AS [IN-CHARGE CASE], dbo.BMMCUnit.BMMCUnit AS [IN-CHARGE MACHINE UNIT], dbo.BMPoint.BMPoint AS [IN-CHARGE POSITION], 
                         dbo.BMWorkContent.BMWorkContent AS [IN-CHARGE WORK CONTENT], BMWhy_2.BMWhy AS [IN-CHARGE CAUSE], dbo.PREVMeasure.PREVMeasure AS [IN-CHARGE PREVENTIVE MEASURE], 
                         dbo.SINGBMMaintenance.AcredINSPN AS [PERIODIC RELATED BM], dbo.SINGBMMaintenance.bmID, dbo.SINGBMMaintenance.OccurrenceDate, dbo.SINGBMMaintenance.BMStatusID, dbo.SINGBMMaintenance.Process, 
                         dbo.SINGBMMaintenance.Location,
                             (SELECT        CASE WHEN dbo.SINGBMMaintenance.BMStatusID = '14' OR
                                                         dbo.SINGBMMaintenance.BMStatusID = '11' OR
                                                         dbo.SINGBMMaintenance.BMStatusID = '13' THEN CASE WHEN dbo.SINGBMMaintenance.isnotquality2 = 'No' AND 
                                                         dbo.SINGBMMaintenance.isnotquality3 = 'No' THEN 'Yes' ELSE 'No' END ELSE 'No' END AS IsQualityBM) AS IsQualityBM, dbo.SINGBMMaintenance.EndBM AS AccreditorTimeStamp
FROM            dbo.SINGBMMaintenance LEFT OUTER JOIN
                         dbo.BMWhy ON dbo.SINGBMMaintenance.Why4 = dbo.BMWhy.BMWhyID LEFT OUTER JOIN
                         dbo.BMWhy AS BMWhy_2 ON dbo.SINGBMMaintenance.AcredBMCauseID = BMWhy_2.BMWhyID LEFT OUTER JOIN
                         dbo.BMWorkContent ON dbo.SINGBMMaintenance.AcredBMWorkContentID = dbo.BMWorkContent.BMWorkContentID LEFT OUTER JOIN
                         dbo.BMPoint ON dbo.SINGBMMaintenance.AcredBMPointID = dbo.BMPoint.BMPointID LEFT OUTER JOIN
                         dbo.BMMCUnit ON dbo.SINGBMMaintenance.AcredBMMCUnitID = dbo.BMMCUnit.BMMCUnitID LEFT OUTER JOIN
                         dbo.BMCase ON dbo.SINGBMMaintenance.AcredBMCaseID = dbo.BMCase.BMCaseID LEFT OUTER JOIN
                         dbo.PMCategory ON dbo.SINGBMMaintenance.AcredPMCategoryID = dbo.PMCategory.PMCategoryID LEFT OUTER JOIN
                         dbo.BMWhy AS BMWhy_1 ON dbo.SINGBMMaintenance.AcredBMCauseID = BMWhy_1.BMWhyID LEFT OUTER JOIN
                         dbo.PREVMeasure ON dbo.SINGBMMaintenance.AcredPREVMeasureID = dbo.PREVMeasure.PREVMeasureID LEFT OUTER JOIN
                         dbo.BMWorkContent AS BMWorkContent_1 ON dbo.SINGBMMaintenance.BMWorkContentID = BMWorkContent_1.BMWorkContentID LEFT OUTER JOIN
                         dbo.BMPoint AS BMPoint_1 ON dbo.SINGBMMaintenance.BMPointID = BMPoint_1.BMPointID LEFT OUTER JOIN
                         dbo.BMCase AS BMCase_1 ON dbo.SINGBMMaintenance.BMCaseID = BMCase_1.BMCaseID LEFT OUTER JOIN
                         dbo.BMMCUnit AS BMMCUnit_1 ON dbo.SINGBMMaintenance.BMUnitID = BMMCUnit_1.BMMCUnitID LEFT OUTER JOIN
                         dbo.BMContent AS BMContent_1 ON dbo.SINGBMMaintenance.BMContentID = BMContent_1.BMContentID LEFT OUTER JOIN
                         dbo.PMCategory AS PMCategory_1 ON dbo.SINGBMMaintenance.PMCategoryID = PMCategory_1.PMCategoryID LEFT OUTER JOIN
                         dbo.BMContent ON dbo.SINGBMMaintenance.AcredBMContentID = dbo.BMContent.BMContentID
GO
/****** Object:  View [dbo].[viewDBWaitingForApproval]    Script Date: 10/25/2026 4:57:09 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO





CREATE VIEW [dbo].[viewDBWaitingForApproval]
AS
SELECT        COUNT(bmID) AS TotalBM, Location,
                             (SELECT        COUNT(BMStatusID) AS GLTotal
                               FROM            dbo.DBBMMaintenance AS b
                               WHERE        (BMStatusID = 1) AND (Location = a.Location)) AS WaitingForGLApprovalTotal,
                             (SELECT        COUNT(BMStatusID) AS PMTotal
                               FROM            dbo.DBBMMaintenance AS c
                               WHERE        (BMStatusID = 2) AND (Location = a.Location)) AS WaitingForPMApprovalTotal,
                             (SELECT        COUNT(BMStatusID) AS OnGoingPMTotal
                               FROM            dbo.DBBMMaintenance AS d
                               WHERE        (BMStatusID = 3) AND (Location = a.Location)) AS OnGoingPMTotal,
                             (SELECT        COUNT(BMStatusID) AS PMRepairDoneTotal
                               FROM            dbo.DBBMMaintenance AS e
                               WHERE        (BMStatusID = 4) AND (Location = a.Location)) AS PMRepairDoneTotal,
                             (SELECT        COUNT(BMStatusID) AS GLReturnedToPMTotal
                               FROM            dbo.DBBMMaintenance AS f
                               WHERE        (BMStatusID = 5) AND (Location = a.Location)) AS GLReturnedToPMTotal,
                             (SELECT        COUNT(BMStatusID) AS EETotal
                               FROM            dbo.DBBMMaintenance AS g
                               WHERE        (BMStatusID = 6) AND (Location = a.Location)) AS WaitingForEEApprovalTotal,
                             (SELECT        COUNT(BMStatusID) AS OngoingPERepairTotal
                               FROM            dbo.DBBMMaintenance AS h
                               WHERE        (BMStatusID = 7) AND (Location = a.Location)) AS OngoingPERepairTotal,
                             (SELECT        COUNT(BMStatusID) AS PERepairDoneTotal
                               FROM            dbo.DBBMMaintenance AS i
                               WHERE        (BMStatusID = 8) AND (Location = a.Location)) AS PERepairDoneTotal,
                             (SELECT        COUNT(BMStatusID) AS ReturnedToPETotal
                               FROM            dbo.DBBMMaintenance AS j
                               WHERE        (BMStatusID = 9) AND (Location = a.Location)) AS ReturnedToPETotal,
                             (SELECT        COUNT(BMStatusID) AS PMTurnoverApprovalTotal
                               FROM            dbo.DBBMMaintenance AS k
                               WHERE        (BMStatusID = 10) AND (Location = a.Location)) AS PMTurnoverApprovalTotal,
                             (SELECT        COUNT(BMStatusID) AS AccApprovalTotal
                               FROM            dbo.DBBMMaintenance AS l
                               WHERE        (BMStatusID = 11) AND (Location = a.Location)) AS AccApprovalTotal,
                             (SELECT        COUNT(BMStatusID) AS AccReturnedtoPM
                               FROM            dbo.DBBMMaintenance AS m
                               WHERE        (BMStatusID = 12) AND (Location = a.Location)) AS AccReturnedtoPM,
                             (SELECT        COUNT(BMStatusID) AS PMReturnedtoPM
                               FROM            dbo.DBBMMaintenance AS n
                               WHERE        (BMStatusID = 13) AND (Location = a.Location)) AS PMReturnedtoPM,
                             (SELECT        COUNT(BMStatusID) AS BMClosed
                               FROM            dbo.DBBMMaintenance AS o
                               WHERE        (BMStatusID = 14) AND (Location = a.Location)) AS BMClosed,
                             (SELECT        COUNT(BMStatusID) AS BMInvalid
                               FROM            dbo.DBBMMaintenance AS p
                               WHERE        (BMStatusID = 15) AND (Location = a.Location)) AS BMOcapResolved,
                             (SELECT        COUNT(BMStatusID) AS BMInvalid
                               FROM            dbo.DBBMMaintenance AS q
                               WHERE        (BMStatusID = 30) AND (Location = a.Location)) AS BMInvalid,
                             (SELECT        COUNT(BMStatusID) AS BMVoid
                               FROM            dbo.DBBMMaintenance AS r
                               WHERE        (BMStatusID = 31) AND (Location = a.Location)) AS BMVoid

FROM            dbo.DBBMMaintenance AS a
GROUP BY Location


GO
