        --a.PMConfirmGLOPReqDate,
        a.StartOfRepair,
        a.TotalStopTime,
        a.EEEWaitingStart,
        a.EEEWaitingEnd,
        a.PMCategoryID,
        a.SubProcessID,
        a.MCStatus,
