        a.NGDetectionCircumtances,
        a.RequestContent,
        a.OccurrenceFreq,
        a.OccurrenceFreqQuantity,
        a.OccurrenceFreqLotFrame,
        NULL AS OccurFreqUnit,
        NULL AS OccMode,
        a.LOTNo,
        a.DeviceName,
