		a.GLConfirmOPReqBy,
		a.PMConfirmGLOPReason,
        b.*,
        w.BMWhy AS BMWhy4,
        c.BMCase
    FROM TPBMMaintenance a
    LEFT JOIN EEEBMMaintenance b ON a.bmId = b.bm_ID AND b.Process = @Process
    LEFT JOIN dbo.BMWhy w ON a.Why4 = w.BMWhyID  
    LEFT JOIN dbo.BMCase c ON a.BMCaseID = c.BMCaseID  
    WHERE @Process = 'TP'

	UNION ALL

    SELECT 
        a.MCNo,
        a.Location,
        a.bmID,
        a.BMCaseID,
        a.Turnover,
        a.BMVersionNo,
        a.BMRouteNo,
        a.ConditionAfterAdj,
