        a.ConBeforeAfterAdjValue6,
        a.CPData,
        a.I4MID,
        a.PMRemarks,
        a.RequestedBy,
        --a.PMConfirmGLOPReqDate,
        a.StartOfRepair,
        a.TotalStopTime,
        a.EEEWaitingStart,
        a.EEEWaitingEnd,
        a.PMCategoryID,
        a.SubProcessID,
        a.MCStatus,
        a.MCType,
        a.RequestItem,
        a.OccurrenceDate,
        a.NGDetectionCircumtances,
        a.RequestContent,
        a.OccurrenceFreq,
        a.OccurrenceFreqQuantity,
        a.OccurrenceFreqLotFrame,
        NULL AS OccurFreqUnit,
