CREATE VIEW [dbo].[viewBMSummary]
AS
SELECT        TOP (100) PERCENT BMStatusID, BMStatus,
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.DBBMMaintenance AS DB
                               WHERE        (BMStatusID = L.BMStatusID) AND (Location LIKE 'LSI1%')) AS 'DBLSI1',
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.DBBMMaintenance AS DB
                               WHERE        (BMStatusID = L.BMStatusID) AND (Location LIKE 'LSI2-1F%')) AS 'DBLSI21F',
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.DBBMMaintenance AS DB
                               WHERE        (BMStatusID = L.BMStatusID) AND (Location LIKE 'LSI2-2F%')) AS 'DBLSI22F',
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.DBBMMaintenance AS DB
                               WHERE        (BMStatusID = L.BMStatusID) AND (Location LIKE 'LSI2-3F%')) AS 'DBLSI23F',
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.WBBMMaintenance AS DB
                               WHERE        (BMStatusID = L.BMStatusID) AND (Location LIKE 'LSI1%')) AS 'WBLSI1',
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.WBBMMaintenance AS DB
                               WHERE        (BMStatusID = L.BMStatusID) AND (Location LIKE 'LSI2-1F%')) AS 'WBLSI21F',
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.WBBMMaintenance AS DB
                               WHERE        (BMStatusID = L.BMStatusID) AND (Location LIKE 'LSI2-2F%')) AS 'WBLSI22F',
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.WBBMMaintenance AS DB
                               WHERE        (BMStatusID = L.BMStatusID) AND (Location LIKE 'LSI2-3F%')) AS 'WBLSI23F',
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.MPBMMaintenance AS DB
                               WHERE        (BMStatusID = L.BMStatusID) AND (Location LIKE 'LSI1%')) AS 'MPLSI1',
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.MPBMMaintenance AS DB
                               WHERE        (BMStatusID = L.BMStatusID) AND (Location LIKE 'LSI2-1F%')) AS 'MPLSI21F',
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.MPBMMaintenance AS DB
                               WHERE        (BMStatusID = L.BMStatusID) AND (Location LIKE 'LSI2-2F%')) AS 'MPLSI22F',
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.MPBMMaintenance AS DB
                               WHERE        (BMStatusID = L.BMStatusID) AND (Location LIKE 'LSI2-3F%')) AS 'MPLSI23F',
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.PLBMMaintenance AS DB
                               WHERE        (BMStatusID = L.BMStatusID) AND (Location LIKE 'LSI1%')) AS 'PLLSI1',
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.PLBMMaintenance AS DB
                               WHERE        (BMStatusID = L.BMStatusID) AND (Location LIKE 'LSI2-1F%')) AS 'PLLSI21F',
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.FLBMMaintenance AS DB
                               WHERE        (BMStatusID = L.BMStatusID) AND (Location LIKE 'LSI1%')) AS 'FLLSI1',
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.FLBMMaintenance AS DB
                               WHERE        (BMStatusID = L.BMStatusID) AND (Location LIKE 'LSI2-1F%')) AS 'FLLSI21F',
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.FLBMMaintenance AS DB
                               WHERE        (BMStatusID = L.BMStatusID) AND (Location LIKE 'LSI2-2F%')) AS 'FLLSI22F',
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.FLBMMaintenance AS DB
                               WHERE        (BMStatusID = L.BMStatusID) AND (Location LIKE 'LSI2-3F%')) AS 'FLLSI23F',
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.FLBMMaintenance AS DB
                               WHERE        (BMStatusID = L.BMStatusID) AND (Location LIKE 'LSI3%')) AS 'FLLSI3',
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.FTBMMaintenance AS DB
                               WHERE        (BMStatusID = L.BMStatusID) AND (Location LIKE 'LSI1%')) AS 'FTLSI1',
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.FTBMMaintenance AS DB
                               WHERE        (BMStatusID = L.BMStatusID) AND (Location LIKE 'LSI2-1F%')) AS 'FTLSI21F',
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.FTBMMaintenance AS DB
                               WHERE        (BMStatusID = L.BMStatusID) AND (Location LIKE 'LSI2-2F%')) AS 'FTLSI22F',
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.FTBMMaintenance AS DB
                               WHERE        (BMStatusID = L.BMStatusID) AND (Location LIKE 'LSI2-3F%')) AS 'FTLSI23F',
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.FTBMMaintenance AS DB
                               WHERE        (BMStatusID = L.BMStatusID) AND (Location LIKE 'LSI3%')) AS 'FTLSI3',
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.TPBMMaintenance AS DB
                               WHERE        (BMStatusID = L.BMStatusID) AND (Location LIKE 'LSI1%')) AS 'TPLSI1',
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.TPBMMaintenance AS DB
                               WHERE        (BMStatusID = L.BMStatusID) AND (Location LIKE 'LSI2-1F%')) AS 'TPLSI21F',
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.TPBMMaintenance AS DB
                               WHERE        (BMStatusID = L.BMStatusID) AND (Location LIKE 'LSI2-2F%')) AS 'TPLSI22F',
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.TPBMMaintenance AS DB
                               WHERE        (BMStatusID = L.BMStatusID) AND (Location LIKE 'LSI2-3F%')) AS 'TPLSI23F',
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.TPBMMaintenance AS DB
                               WHERE        (BMStatusID = L.BMStatusID) AND (Location LIKE 'LSI3%')) AS 'TPLSI3',
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.EDSBMMaintenance AS DB
                               WHERE        (BMStatusID = L.BMStatusID) AND (Location LIKE 'LSI3%')) AS 'EDSLSI3'
FROM            dbo.BMStatus AS L
WHERE        (BMStatusID < 9)
GO
