CREATE VIEW [dbo].[viewEDSTEPendingBM]
AS
SELECT        MCNo, BMStatusID AS Flag, StartOfRepair AS StartTime, EndOfRepair AS EndTime, GLConfirmOPReqDate AS DateTransct, bmID AS RepairID, TimeOfRequest AS ReqDate
FROM            dbo.TEBMMaintenance
WHERE        (Process = 'EDS') AND (BMStatusID IN ('1', '2', '3', '21', '5'))
