/****** Object:  View [dbo].[viewBMStatusWStats]    Script Date: 10/25/2026 4:57:09 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[viewBMStatusWStats]
AS
SELECT        BMStatus + ' (' + CONVERT(varchar,
                             (SELECT        COUNT(BMStatusID) AS iTotal
                               FROM            dbo.FLBMMaintenance AS b
                               WHERE        (a.BMStatusID = BMStatusID))) + ')' AS BMStatus, BMStatusEnabled, BMStatusID
FROM            dbo.BMStatus AS a
GO
/****** Object:  View [dbo].[view6HoursBM]    Script Date: 10/25/2026 4:57:09 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[view6HoursBM]
AS
SELECT        [BMId],
                             (SELECT        BMStatus
                               FROM            [eMaintenanceSystemDB].[dbo].[BMStatus] AS a
                               WHERE        a.BMStatusID = b.BMStatusID) AS BMStatus,
                             (SELECT        [PMCategory]
                               FROM            [eMaintenanceSystemDB].[dbo].[PMCategory] AS c
                               WHERE        c.PMCategoryID = b.PMCategoryID) AS PMCategory, [Process], [Location], [MCNo], [MCType], [LOTNo], [DeviceName], [PkgName], [RequestItem], [OccurrenceDate], [RequestContent], [RequestedBy], 
                         [StartOfRepair], [RepairedByStart], ISNULL([CurrentPM], '') AS CurrentPM, [TurnoverPM], [TimeTurnover], [Turnover], [Process] + [Location] AS [ProcessLocation]
FROM            [eMaintenanceSystemDB].[dbo].[DCBMMaintenance] AS b
WHERE        PMCategoryID = '1' AND BMStatusID IN (2, 3, 6, 7, 21) AND EndOfRepair IS NULL AND (DateDiff(MINUTE, OccurrenceDate, Getdate()) > 360)
UNION
SELECT        [BMId],
                             (SELECT        BMStatus
                               FROM            [eMaintenanceSystemDB].[dbo].[BMStatus] AS a
                               WHERE        a.BMStatusID = b.BMStatusID) AS BMStatus,
                             (SELECT        [PMCategory]
                               FROM            [eMaintenanceSystemDB].[dbo].[PMCategory] AS c
                               WHERE        c.PMCategoryID = b.PMCategoryID) AS PMCategory, [Process], [Location], [MCNo], [MCType], [LOTNo], [DeviceName], [PkgName], [RequestItem], [OccurrenceDate], [RequestContent], [RequestedBy], 
                         [StartOfRepair], [RepairedByStart], ISNULL([CurrentPM], '') AS CurrentPM, [TurnoverPM], [TimeTurnover], [Turnover], [Process] + [Location] AS [ProcessLocation]
FROM            [eMaintenanceSystemDB].[dbo].[DBBMMaintenance] AS b
WHERE        PMCategoryID = '1' AND BMStatusID IN (2, 3, 6, 7, 21) AND EndOfRepair IS NULL AND (DateDiff(MINUTE, OccurrenceDate, Getdate()) > 360)
UNION
SELECT        [BMId],
                             (SELECT        BMStatus
                               FROM            [eMaintenanceSystemDB].[dbo].[BMStatus] AS a
                               WHERE        a.BMStatusID = b.BMStatusID) AS BMStatus,
                             (SELECT        [PMCategory]
                               FROM            [eMaintenanceSystemDB].[dbo].[PMCategory] AS c
                               WHERE        c.PMCategoryID = b.PMCategoryID) AS PMCategory, [Process], [Location], [MCNo], [MCType], [LOTNo], [DeviceName], [PkgName], [RequestItem], [OccurrenceDate], [RequestContent], [RequestedBy], 
                         [StartOfRepair], [RepairedByStart], ISNULL([CurrentPM], '') AS CurrentPM, [TurnoverPM], [TimeTurnover], [Turnover], [Process] + [Location] AS [ProcessLocation]
FROM            [eMaintenanceSystemDB].[dbo].[WBBMMaintenance] AS b
WHERE        PMCategoryID = '1' AND BMStatusID IN (2, 3, 6, 7, 21) AND EndOfRepair IS NULL AND (DateDiff(MINUTE, OccurrenceDate, Getdate()) > 360)
UNION
SELECT        [BMId],
                             (SELECT        BMStatus
                               FROM            [eMaintenanceSystemDB].[dbo].[BMStatus] AS a
                               WHERE        a.BMStatusID = b.BMStatusID) AS BMStatus,
                             (SELECT        [PMCategory]
                               FROM            [eMaintenanceSystemDB].[dbo].[PMCategory] AS c
                               WHERE        c.PMCategoryID = b.PMCategoryID) AS PMCategory, [Process], [Location], [MCNo], [MCType], [LOTNo], [DeviceName], [PkgName], [RequestItem], [OccurrenceDate], [RequestContent], [RequestedBy], 
                         [StartOfRepair], [RepairedByStart], ISNULL([CurrentPM], '') AS CurrentPM, [TurnoverPM], [TimeTurnover], [Turnover], [Process] + [Location] AS [ProcessLocation]
FROM            [eMaintenanceSystemDB].[dbo].[MPBMMaintenance] AS b
WHERE        PMCategoryID = '1' AND BMStatusID IN (2, 3, 6, 7, 21) AND EndOfRepair IS NULL AND (DateDiff(MINUTE, OccurrenceDate, Getdate()) > 360)
UNION
SELECT        [BMId],
                             (SELECT        BMStatus
                               FROM            [eMaintenanceSystemDB].[dbo].[BMStatus] AS a
                               WHERE        a.BMStatusID = b.BMStatusID) AS BMStatus,
                             (SELECT        [PMCategory]
                               FROM            [eMaintenanceSystemDB].[dbo].[PMCategory] AS c
                               WHERE        c.PMCategoryID = b.PMCategoryID) AS PMCategory, [Process], [Location], [MCNo], [MCType], [LOTNo], [DeviceName], [PkgName], [RequestItem], [OccurrenceDate], [RequestContent], [RequestedBy], 
                         [StartOfRepair], [RepairedByStart], ISNULL([CurrentPM], '') AS CurrentPM, [TurnoverPM], [TimeTurnover], [Turnover], [Process] + [Location] AS [ProcessLocation]
FROM            [eMaintenanceSystemDB].[dbo].[PLBMMaintenance] AS b
WHERE        PMCategoryID = '1' AND BMStatusID IN (2, 3, 6, 7, 21) AND EndOfRepair IS NULL AND (DateDiff(MINUTE, OccurrenceDate, Getdate()) > 360)
UNION
