                         [StartOfRepair], [RepairedByStart], ISNULL([CurrentPM], '') AS CurrentPM, [TurnoverPM], [TimeTurnover], [Turnover], [Process] + [Location] AS [ProcessLocation]
FROM            [eMaintenanceSystemDB].[dbo].[FTBMMaintenance] AS b
WHERE        PMCategoryID = '1' AND BMStatusID IN (2, 3, 6, 7, 21) AND EndOfRepair IS NULL AND (DateDiff(MINUTE, OccurrenceDate, Getdate()) > 360)
UNION
SELECT        [BMId],
                             (SELECT        BMStatus
                               FROM            [eMaintenanceSystemDB].[dbo].[BMStatus] AS a
                               WHERE        a.BMStatusID = b.BMStatusID) AS BMStatus,
                             (SELECT        [PMCategory]
                               FROM            [eMaintenanceSystemDB].[dbo].[PMCategory] AS c
                               WHERE        c.PMCategoryID = b.PMCategoryID) AS PMCategory, [Process], [Location], [MCNo], [MCType], [LOTNo], [DeviceName], [PkgName], [RequestItem], [OccurrenceDate], [RequestContent], [RequestedBy], 
                         [StartOfRepair], [RepairedByStart], ISNULL([CurrentPM], '') AS CurrentPM, [TurnoverPM], [TimeTurnover], [Turnover], [Process] + [Location] AS [ProcessLocation]
FROM            [eMaintenanceSystemDB].[dbo].[TPBMMaintenance] AS b
WHERE        PMCategoryID = '1' AND BMStatusID IN (2, 3, 6, 7, 21) AND EndOfRepair IS NULL AND (DateDiff(MINUTE, OccurrenceDate, Getdate()) > 360)
UNION
SELECT        [BMId],
                             (SELECT        BMStatus
                               FROM            [eMaintenanceSystemDB].[dbo].[BMStatus] AS a
                               WHERE        a.BMStatusID = b.BMStatusID) AS BMStatus,
                             (SELECT        [PMCategory]
                               FROM            [eMaintenanceSystemDB].[dbo].[PMCategory] AS c
                               WHERE        c.PMCategoryID = b.PMCategoryID) AS PMCategory,
                             (SELECT        'TE' AS 'Process'), [Location], [MCNo], [MCType], [LOTNo], [DeviceName], [PkgName], [TestNoNG] AS 'RequestItem', [OccurrenceDate], [OPRemarks] AS 'RequestContent', [RequestedBy], [StartOfRepair], 
                         [RepairedByStart], ISNULL([CurrentPM], '') AS CurrentPM, [TurnoverPM], [TimeTurnover], [Turnover], 'TE' + [Location] AS [ProcessLocation]
FROM            [eMaintenanceSystemDB].[dbo].[TEBMMaintenance] AS b
WHERE        PMCategoryID = '1' AND BMStatusID IN (2, 3, 21) AND EndOfRepair IS NULL AND (DateDiff(MINUTE, OccurrenceDate, Getdate()) > 360)
GO
