SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[viewBMRate]
AS
SELECT DISTINCT TOP (100) PERCENT DAY(OccurrenceDate) AS DayRequested, FORMAT(OccurrenceDate, 'MMM d') AS MonthDay, FORMAT(OccurrenceDate, 'MMM') AS MonthRequested,
                             (SELECT        COUNT(Location) AS Expr1
                               FROM            dbo.FLBMMaintenance AS b
                               WHERE        (DAY(a.OccurrenceDate) = DAY(OccurrenceDate)) AND (BMStatusID > 10 OR
                                                         BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30)) AS NumberOfBM,
                             (SELECT        ISNULL(SUM(MachineCount) / 2, 0) AS Expr1
                               FROM            dbo.viewRunningMachine AS c
                               WHERE        (DAY(SendDate) = DAY(a.OccurrenceDate)) AND (ProcessMatch = 'FL') AND (Shift <> 'TET')) AS RunningMC, FORMAT(CAST
                             ((SELECT        COUNT(Location) AS Expr1
                                 FROM            dbo.FLBMMaintenance AS b
                                 WHERE        (Location = 'LSI2-1F') AND (DAY(a.OccurrenceDate) = DAY(OccurrenceDate)) AND (BMStatusID > 10 OR
                                                          BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30)) AS float) / CAST
                             ((SELECT        ISNULL(SUM(MachineCount) / 2, 0) AS Expr1
                                 FROM            dbo.viewRunningMachine AS c
                                 WHERE        (LocationMatch = 'LSI2-1F') AND (DAY(SendDate) = DAY(a.OccurrenceDate)) AND (ProcessMatch = 'FL') AND (Shift <> 'TET')) AS float), 'N2') AS LSI21F, FORMAT(CAST
                             ((SELECT        COUNT(Location) AS Expr1
                                 FROM            dbo.FLBMMaintenance AS b
                                 WHERE        (Location = 'LSI2-2F') AND (DAY(a.OccurrenceDate) = DAY(OccurrenceDate)) AND (BMStatusID > 10 OR
                                                          BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30)) AS float) / CAST
                             ((SELECT        ISNULL(SUM(MachineCount) / 2, 0) AS Expr1
                                 FROM            dbo.viewRunningMachine AS c
                                 WHERE        (LocationMatch = 'LSI2-2F') AND (DAY(SendDate) = DAY(a.OccurrenceDate)) AND (ProcessMatch = 'FL') AND (Shift <> 'TET')) AS float), 'N2') AS LSI22F, FORMAT(CAST
                             ((SELECT        COUNT(Location) AS Expr1
                                 FROM            dbo.FLBMMaintenance AS b
                                 WHERE        (Location = 'LSI2-3F') AND (DAY(a.OccurrenceDate) = DAY(OccurrenceDate)) AND (BMStatusID > 10 OR
                                                          BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30)) AS float) / CAST
                             ((SELECT        ISNULL(SUM(MachineCount) / 2, 0) AS Expr1
                                 FROM            dbo.viewRunningMachine AS c
                                 WHERE        (LocationMatch = 'LSI2-3F') AND (DAY(SendDate) = DAY(a.OccurrenceDate)) AND (ProcessMatch = 'FL') AND (Shift <> 'TET')) AS float), 'N2') AS LSI23F, FORMAT(CAST
                             ((SELECT        COUNT(Location) AS Expr1
                                 FROM            dbo.FLBMMaintenance AS b
                                 WHERE        (Location = 'LSI1-1F') AND (DAY(a.OccurrenceDate) = DAY(OccurrenceDate)) AND (BMStatusID > 10 OR
                                                          BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30)) AS float) / CAST
                             ((SELECT        ISNULL(SUM(MachineCount) / 2, 0) AS Expr1
                                 FROM            dbo.viewRunningMachine AS c
                                 WHERE        (LocationMatch = 'LSI1-1F') AND (DAY(SendDate) = DAY(a.OccurrenceDate)) AND (ProcessMatch = 'FL') AND (Shift <> 'TET')) AS float), 'N2') AS LSI11F, FORMAT(CAST
                             ((SELECT        COUNT(Location) AS Expr1
                                 FROM            dbo.FLBMMaintenance AS b
                                 WHERE        (Location = 'LSI1-2F') AND (DAY(a.OccurrenceDate) = DAY(OccurrenceDate)) AND (BMStatusID > 10 OR
                                                          BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30)) AS float) / CAST
                             ((SELECT        ISNULL(SUM(MachineCount) / 2, 0) AS Expr1
                                 FROM            dbo.viewRunningMachine AS c
                                 WHERE        (LocationMatch = 'LSI1-2F') AND (DAY(SendDate) = DAY(a.OccurrenceDate)) AND (ProcessMatch = 'FL') AND (Shift <> 'TET')) AS float), 'N2') AS LSI12F, FORMAT(CAST
                             ((SELECT        COUNT(Location) AS Expr1
                                 FROM            dbo.FLBMMaintenance AS b
                                 WHERE        (Location = 'LSI3-2F') AND (DAY(a.OccurrenceDate) = DAY(OccurrenceDate)) AND (BMStatusID > 10 OR
                                                          BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30)) AS float) / CAST
                             ((SELECT        ISNULL(SUM(MachineCount) / 2, 0) AS Expr1
                                 FROM            dbo.viewRunningMachine AS c
                                 WHERE        (LocationMatch = 'LSI3-2F') AND (DAY(SendDate) = DAY(a.OccurrenceDate)) AND (ProcessMatch = 'FL') AND (Shift <> 'TET')) AS float), 'N2') AS LSI32F, FORMAT(CAST
                             ((SELECT        COUNT(Location) AS Expr1
                                 FROM            dbo.FLBMMaintenance AS b
                                 WHERE        (DAY(a.OccurrenceDate) = DAY(OccurrenceDate)) AND (BMStatusID > 10 OR
                                                          BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30)) AS float) / CAST
                             ((SELECT        ISNULL(SUM(MachineCount) / 2, 0) AS Expr1
                                 FROM            dbo.viewRunningMachine AS c
                                 WHERE        (DAY(SendDate) = DAY(a.OccurrenceDate)) AND (ProcessMatch = 'FL') AND (Shift <> 'TET')) AS float), 'N2') AS TotalRate
FROM            dbo.FLBMMaintenance AS a
WHERE        (BMStatusID > 10 OR
                         BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30) AND (DAY(OccurrenceDate) <> DAY(GETDATE()))
GO
