SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[TEFinalRawData_1]
AS
SELECT        MONTH(dbo.TEBMMaintenance.EndOfRepair) AS MONTH, DAY(dbo.TEBMMaintenance.EndOfRepair) AS DAY, YEAR(dbo.TEBMMaintenance.EndOfRepair) AS YEAR, CONVERT(varchar(10), dbo.TEBMMaintenance.OccurrenceDate,
                          103) AS RequestDate, CONVERT(varchar(8), dbo.TEBMMaintenance.OccurrenceDate, 108) AS RequestTime, CONVERT(varchar(10), dbo.TEBMMaintenance.EndOfRepair, 103) AS EndDate, CONVERT(varchar(8), 
                         dbo.TEBMMaintenance.EndOfRepair, 108) AS EndTime, dbo.TEBMMaintenance.MCNo, dbo.TEBMMaintenance.MCType AS TesterType, dbo.TEBMMaintenance.TesterNo, dbo.TEBMMaintenance.DeviceName, 
                         dbo.TEBMMaintenance.TestFlow, dbo.TEBMMaintenance.Process, dbo.TEBMMaintenance.PkgName, dbo.TEBMMaintenance.LOTNo, dbo.TEBMMaintenance.BoxNo, dbo.TEBMMaintenance.DUT, 
                         dbo.TEBMMaintenance.BMCategoryID, dbo.TEContent.BMContentNumber, dbo.TECase.BMCaseCodeNo, dbo.BMTEUnit.BMTEUnitNumber, dbo.TEPoint.BMPointNo, dbo.TEWorkContent.BMWorkContentNumber, 
                         dbo.TECause.BMCauseNo, dbo.TEPREVMeasure.PREVMeasureNo, dbo.TEBMMaintenance.RequestedBy, dbo.TEBMMaintenance.RepairedByEnd, DATEDIFF(minute, dbo.TEBMMaintenance.StartOfRepair, 
                         dbo.TEBMMaintenance.EndOfRepair) - dbo.TEBMMaintenance.TotalStopTime - dbo.TEBMMaintenance.TotalSKCTPDtime AS RepairTime, DATEDIFF(minute, dbo.TEBMMaintenance.GLConfirmOPReqDate, 
                         dbo.TEBMMaintenance.PMConfirmGLOPReqDate) + dbo.TEBMMaintenance.TotalStopTime AS WaitingTime, DATEDIFF(minute, dbo.TEBMMaintenance.EndOfRepair, dbo.TEBMMaintenance.GLRepairConfirmation) 
                         AS MonitoringTime, dbo.TEBMMaintenance.ReqTestNoNG, dbo.TEBMMaintenance.OPRemarks, dbo.TEBMMaintenance.QAction, dbo.TEBMMaintenance.BMStatusID, dbo.TEBMMaintenance.OccurrenceDate, 
                         dbo.TEBMMaintenance.Location, dbo.TEBMMaintenance.SKCTPDOnHoldDate, dbo.TEBMMaintenance.SKCTPDReleaseDate, dbo.TEBMMaintenance.TotalSKCTPDtime
FROM            dbo.TEBMMaintenance LEFT OUTER JOIN
                         dbo.TEWorkContent ON dbo.TEBMMaintenance.BMWorkContentID = dbo.TEWorkContent.BMWorkContentID LEFT OUTER JOIN
                         dbo.TEPREVMeasure ON dbo.TEBMMaintenance.PrevMeasureID = dbo.TEPREVMeasure.PREVMeasureID LEFT OUTER JOIN
                         dbo.TEPoint ON dbo.TEBMMaintenance.BMPointID = dbo.TEPoint.BMPointID LEFT OUTER JOIN
                         dbo.TECause ON dbo.TEBMMaintenance.BMCauseID = dbo.TECause.BMCauseID LEFT OUTER JOIN
                         dbo.TECase ON dbo.TEBMMaintenance.BMCaseID = dbo.TECase.BMCaseID LEFT OUTER JOIN
                         dbo.BMTEUnit ON dbo.TEBMMaintenance.BMUnitID = dbo.BMTEUnit.BMTEUnitID LEFT OUTER JOIN
                         dbo.TEContent ON dbo.TEBMMaintenance.BMContentID = dbo.TEContent.BMContentID
GO
