/****** Object:  View [dbo].[viewBMPerMachine]    Script Date: 10/25/2026 4:57:09 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[viewBMPerMachine]
AS
SELECT DISTINCT TOP (100) PERCENT DAY(EndOfRepair) AS DayRequested, FORMAT(EndOfRepair, 'MMM d') AS MonthDay, FORMAT(EndOfRepair, 'MMM') AS MonthRequested,
                             (SELECT        COUNT(Location) AS Expr1
                               FROM            dbo.FLBMMaintenance AS b
                               WHERE        (DAY(a.EndOfRepair) = DAY(EndOfRepair)) AND (MONTH(a.EndOfRepair) = MONTH(EndOfRepair)) AND (YEAR(a.EndOfRepair) = YEAR(EndOfRepair)) AND (BMStatusID > 10 OR
                                                         BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30) AND (Location = 'LSI2-1F')) AS LSI21FBM,
                             (SELECT        ISNULL(SUM(MachineCount), 0) AS Expr1
                               FROM            dbo.viewRunningMachine AS c
                               WHERE        (DAY(SendDate) = DAY(a.EndOfRepair)) AND (MONTH(SendDate) = MONTH(a.EndOfRepair)) AND (YEAR(SendDate) = YEAR(a.EndOfRepair)) AND (ProcessMatch = 'FL') AND (Shift = '1ST') AND 
                                                         (LocationMatch = 'LSI2-1F')) AS LSI21FMC,
                             (SELECT        COUNT(Location) AS Expr1
                               FROM            dbo.FLBMMaintenance AS b
                               WHERE        (DAY(a.EndOfRepair) = DAY(EndOfRepair)) AND (MONTH(a.EndOfRepair) = MONTH(EndOfRepair)) AND (YEAR(a.EndOfRepair) = YEAR(EndOfRepair)) AND (BMStatusID > 10 OR
                                                         BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30) AND (Location = 'LSI2-2F')) AS LSI22FBM,
                             (SELECT        ISNULL(SUM(MachineCount), 0) AS Expr1
                               FROM            dbo.viewRunningMachine AS c
                               WHERE        (DAY(SendDate) = DAY(a.EndOfRepair)) AND (MONTH(SendDate) = MONTH(a.EndOfRepair)) AND (YEAR(SendDate) = YEAR(a.EndOfRepair)) AND (ProcessMatch = 'FL') AND (Shift = '1ST') AND 
                                                         (LocationMatch = 'LSI2-2F')) AS LSI22FMC,
                             (SELECT        COUNT(Location) AS Expr1
                               FROM            dbo.FLBMMaintenance AS b
                               WHERE        (DAY(a.EndOfRepair) = DAY(EndOfRepair)) AND (MONTH(a.EndOfRepair) = MONTH(EndOfRepair)) AND (YEAR(a.EndOfRepair) = YEAR(EndOfRepair)) AND (BMStatusID > 10 OR
                                                         BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30) AND (Location = 'LSI2-3F')) AS LSI23FBM,
                             (SELECT        ISNULL(SUM(MachineCount), 0) AS Expr1
                               FROM            dbo.viewRunningMachine AS c
                               WHERE        (DAY(SendDate) = DAY(a.EndOfRepair)) AND (MONTH(SendDate) = MONTH(a.EndOfRepair)) AND (YEAR(SendDate) = YEAR(a.EndOfRepair)) AND (ProcessMatch = 'FL') AND (Shift = '1ST') AND 
                                                         (LocationMatch = 'LSI2-3F')) AS LSI23FMC,
                             (SELECT        COUNT(Location) AS Expr1
                               FROM            dbo.FLBMMaintenance AS b
                               WHERE        (DAY(a.EndOfRepair) = DAY(EndOfRepair)) AND (MONTH(a.EndOfRepair) = MONTH(EndOfRepair)) AND (YEAR(a.EndOfRepair) = YEAR(EndOfRepair)) AND (BMStatusID > 10 OR
                                                         BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30) AND (Location = 'LSI1-1F')) AS LSI11FBM,
                             (SELECT        ISNULL(SUM(MachineCount), 0) AS Expr1
                               FROM            dbo.viewRunningMachine AS c
                               WHERE        (DAY(SendDate) = DAY(a.EndOfRepair)) AND (MONTH(SendDate) = MONTH(a.EndOfRepair)) AND (YEAR(SendDate) = YEAR(a.EndOfRepair)) AND (ProcessMatch = 'FL') AND (Shift = '1ST') AND 
                                                         (LocationMatch = 'LSI1-1F')) AS LSI11FMC,
                             (SELECT        COUNT(Location) AS Expr1
                               FROM            dbo.FLBMMaintenance AS b
                               WHERE        (DAY(a.EndOfRepair) = DAY(EndOfRepair)) AND (MONTH(a.EndOfRepair) = MONTH(EndOfRepair)) AND (YEAR(a.EndOfRepair) = YEAR(EndOfRepair)) AND (BMStatusID > 10 OR
                                                         BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30) AND (Location = 'LSI1-2F')) AS LSI12FBM,
                             (SELECT        ISNULL(SUM(MachineCount), 0) AS Expr1
                               FROM            dbo.viewRunningMachine AS c
                               WHERE        (DAY(SendDate) = DAY(a.EndOfRepair)) AND (MONTH(SendDate) = MONTH(a.EndOfRepair)) AND (YEAR(SendDate) = YEAR(a.EndOfRepair)) AND (ProcessMatch = 'FL') AND (Shift = '1ST') AND 
                                                         (LocationMatch = 'LSI1-2F')) AS LSI12FMC,
                             (SELECT        COUNT(Location) AS Expr1
                               FROM            dbo.FLBMMaintenance AS b
                               WHERE        (DAY(a.EndOfRepair) = DAY(EndOfRepair)) AND (MONTH(a.EndOfRepair) = MONTH(EndOfRepair)) AND (YEAR(a.EndOfRepair) = YEAR(EndOfRepair)) AND (BMStatusID > 10 OR
                                                         BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30) AND (Location = 'LSI3-2F')) AS LSI32FBM,
                             (SELECT        ISNULL(SUM(MachineCount), 0) AS Expr1
                               FROM            dbo.viewRunningMachine AS c
                               WHERE        (DAY(SendDate) = DAY(a.EndOfRepair)) AND (MONTH(SendDate) = MONTH(a.EndOfRepair)) AND (YEAR(SendDate) = YEAR(a.EndOfRepair)) AND (ProcessMatch = 'FL') AND (Shift = '1ST') AND 
                                                         (LocationMatch = 'LSI3-2F')) AS LSI32FMC
FROM            dbo.FLBMMaintenance AS a
WHERE        (BMStatusID > 10 OR
                         BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30)
GO
