SELECT bmID, [Process], [Location], PMCategoryID, MCNo, MCType, PkgName, DeviceName, LOTNo, RequestItem,RequestedBy,TimeOfRequest, BMStatusID, GLConfirmOPReqBy, GLConfirmOPReqDate, PMConfirmGLOPReqDate FROM dbo.gridTPData 
