/****** Object:  View [dbo].[TEFinalRawData_Test]    Script Date: 10/25/2026 4:57:09 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[TEFinalRawData_Test]
AS
SELECT        MONTH(te.OccurrenceDate) AS MONTH, DAY(te.OccurrenceDate) AS DAY, YEAR(te.OccurrenceDate) AS YEAR, CONVERT(varchar(10), te.OccurrenceDate, 103) AS RequestDate, CONVERT(varchar(8), te.OccurrenceDate, 108) 
                         AS RequestTime, CONVERT(varchar(10), te.EndOfRepair, 103) AS EndDate, CONVERT(varchar(8), te.EndOfRepair, 108) AS EndTime, te.MCNo, te.MCType AS TesterType, te.TesterNo, te.DeviceName, te.TestFlow, te.Process, 
                         te.PkgName, te.LOTNo, te.BoxNo, te.DUT, dbo.PMCategory.PMCategory, dbo.TEContent.BMContent, dbo.TECase.BMCase, dbo.BMTEUnit.BMTEUnit, dbo.TEPoint.BMPoint, dbo.TEWorkContent.BMWorkContent, 
                         dbo.TECause.BMCause, dbo.TEPREVMeasure.PREVMeasure, te.RequestedBy, te.RepairedByEnd, DATEDIFF(minute, te.StartOfRepair, te.EndOfRepair) - te.TotalSKCTPDtime - te.TotalStopTime AS RepairTime, DATEDIFF(minute, 
                         te.GLConfirmOPReqDate, te.PMConfirmGLOPReqDate) + te.TotalStopTime AS WaitingTime, DATEDIFF(minute, te.EndOfRepair, te.GLRepairConfirmation) AS MonitoringTime, te.ReqTestNoNG, te.OPRemarks, te.QAction, 
                         te.BMStatusID, te.OccurrenceDate, te.Location, te.GLConfirmOPReqDate AS OPGLApproveDate, te.GLConfirmOPReqBy AS OPGLApproveBy, DATEDIFF(minute, te.TimeOfRequest, te.GLConfirmOPReqDate) AS OPGLWaiting, 
                         te.GLRepairConfirmation AS TEGLConfirmDate, te.GLRepairConfirmationBy AS TEGLConfirmBy, DATEDIFF(minute, te.EndOfRepair, te.GLRepairConfirmation) AS TEGLWaiting, te.SubDUT, te.CurrentTE, te.ProbeRingBefore, 
                         te.ProbeRingAfter, te.IronPlateBefore, te.IronPlateAfter, te.ChangePartsName1, te.ChangePartsName2, te.ChangePartsName3, te.ChangePartsName4, te.ChangePartsName5, te.ChangePartsType1, te.ChangePartsType2, 
                         te.ChangePartsType3, te.ChangePartsType4, te.ChangePartsType5, te.ChangePartsQty1, te.ChangePartsQty2, te.ChangePartsQty3, te.ChangePartsQty4, te.ChangePartsQty5, te.SKCTPDOnHoldDate, te.SKCTPDReleaseDate, 
                         te.TotalSKCTPDtime, dbo.PMCategory.PMCategoryID, dbo.TEContent.BMContentNumber, dbo.TECase.BMCaseCodeNo, dbo.BMTEUnit.BMTEUnitNumber, dbo.TEPoint.BMPointNo, dbo.TEWorkContent.BMWorkContentNumber, 
                         dbo.TECause.BMCauseNo, dbo.TEPREVMeasure.PREVMeasureNo, te.EndBMBy
FROM            dbo.TEBMMaintenance AS te LEFT OUTER JOIN
                         dbo.TEWorkContent ON te.BMWorkContentID = dbo.TEWorkContent.BMWorkContentID LEFT OUTER JOIN
                         dbo.TEPREVMeasure ON te.PrevMeasureID = dbo.TEPREVMeasure.PREVMeasureID LEFT OUTER JOIN
                         dbo.TEPoint ON te.BMPointID = dbo.TEPoint.BMPointID LEFT OUTER JOIN
                         dbo.TECause ON te.BMCauseID = dbo.TECause.BMCauseID LEFT OUTER JOIN
                         dbo.TECase ON te.BMCaseID = dbo.TECase.BMCaseID LEFT OUTER JOIN
                         dbo.BMTEUnit ON te.BMUnitID = dbo.BMTEUnit.BMTEUnitID LEFT OUTER JOIN
                         dbo.TEContent ON te.BMContentID = dbo.TEContent.BMContentID LEFT OUTER JOIN
                         dbo.PMCategory ON dbo.PMCategory.PMCategoryID = te.PMCategoryID
GO
