GO
CREATE VIEW [dbo].[viewSkillMap]
AS
SELECT        dbo.BMSkillMap.acnt_no, dbo.MCType.MCType, dbo.BMSkillType.SkillType, dbo.BMSkillMap.SkillMapID, dbo.BMSkillMap.MCTypeID, dbo.BMSkillType.BMSkillID, dbo.Process.ProcessName, dbo.BMSkillMap.DateStart, 
                         dbo.BMSkillMap.DateEnd, dbo.PMCategory.PMCategory, dbo.Process.ProcessName AS 'acnt_process'
FROM            dbo.BMSkillMap INNER JOIN
                         dbo.BMSkillType ON dbo.BMSkillMap.BMSkillID = dbo.BMSkillType.BMSkillID INNER JOIN
                         dbo.MCType ON dbo.BMSkillMap.MCTypeID = dbo.MCType.MCTypeID INNER JOIN
                         dbo.Process ON dbo.MCType.ProcessID = dbo.Process.ProcessID INNER JOIN
                         dbo.PMCategory ON dbo.BMSkillMap.CategoryID = dbo.PMCategory.PMCategoryID
GO
