CREATE VIEW [dbo].[FTFinalBMRawData]
AS
SELECT        dbo.FTBMMaintenance.MCNo AS [MC No], dbo.FTBMMaintenance.MCType AS [MC Type], dbo.FTBMMaintenance.PkgName AS Package, dbo.FTBMMaintenance.KanagataNo AS [Kanagata Number], 
                         dbo.FTBMMaintenance.LOTNo AS [Lot Number], dbo.FTBMMaintenance.DeviceName AS [Device Name],
                             (SELECT        CASE WHEN dbo.FTBMMaintenance.BMStatusID = 14 THEN PMCategory.PMCategory ELSE PMCategory_1.PMCategory END AS PMCategory) AS Classification, 
                         dbo.FTBMMaintenance.NGDetectionCircumtances AS [NG Detection Circumstance], dbo.FTBMMaintenance.RequestItem AS [Case Name], dbo.FTBMMaintenance.RequestContent AS [Request Content], 
                         dbo.FTBMMaintenance.Situation AS Condition, dbo.FTBMMaintenance.OccurrenceFreq AS [Occurrence Rate Before Condition], dbo.FTBMMaintenance.OccurrenceFreqQuantity AS Quantity1, 
                         dbo.FTBMMaintenance.OccurrenceFreqLotFrame AS Quantity2, dbo.FTBMMaintenance.AQI, dbo.FTBMMaintenance.OccurrenceDate AS [Request Date and Time], dbo.FTBMMaintenance.RequestedBy AS Issuer, 
                         dbo.FTBMMaintenance.GLConfirmOPReqBy AS GL, dbo.FTBMMaintenance.GLConfirmOPReqDate AS [GL Confirmed Date], dbo.FTBMMaintenance.PMConfirmGLOPReqBy AS [PM Confirmed Request],
                             (SELECT        CASE WHEN dbo.FTBMMaintenance.Turnover = 'PE' OR
                                                         dbo.FTBMMaintenance.Turnover = 'CC' OR
                                                         dbo.FTBMMaintenance.Turnover = 'VIS' THEN '' ELSE dbo.FTBMMaintenance.RepairedByEnd END AS Expr1) AS [PM Done Request], dbo.FTBMMaintenance.PMConfirmGLOPReqDate AS [START DATE AND TIME],
                             (SELECT        CASE WHEN dbo.FTBMMaintenance.Turnover = 'PE' OR
                                                         dbo.FTBMMaintenance.Turnover = 'CC' OR
                                                         dbo.FTBMMaintenance.Turnover = 'VIS' THEN dbo.FTBMMaintenance.PMTurnOvertoPEDate ELSE dbo.FTBMMaintenance.EndOfRepair END AS Expr1) AS [END DATE AND TIME], 
                         dbo.FTBMMaintenance.PEConfirmPMTurnoverBy AS [PE Confirmed Request],
                             (SELECT        CASE WHEN dbo.FTBMMaintenance.Turnover = 'PE' OR
                                                         dbo.FTBMMaintenance.Turnover = 'CC' OR
                                                         dbo.FTBMMaintenance.Turnover = 'VIS' THEN dbo.FTBMMaintenance.RepairedByEnd ELSE '' END AS Expr1) AS [PE Done Request], 
                         dbo.FTBMMaintenance.PEConfirmPMTurnoverDate AS [PE START DATE AND TIME],
                             (SELECT        CASE WHEN dbo.FTBMMaintenance.Turnover = 'PE' OR
                                                         dbo.FTBMMaintenance.Turnover = 'CC' OR
                                                         dbo.FTBMMaintenance.Turnover = 'VIS' THEN dbo.FTBMMaintenance.EndOfRepair ELSE NULL END AS Expr1) AS [PE END DATE AND TIME], dbo.FTBMMaintenance.Why1, dbo.FTBMMaintenance.Why2, 
                         dbo.FTBMMaintenance.Why3, dbo.BMWhy.BMWhy AS Why4, dbo.FTBMMaintenance.Treatment1, dbo.FTBMMaintenance.Treatment2, dbo.FTBMMaintenance.Treatment3, dbo.FTBMMaintenance.Treatment4, 
                         dbo.FTBMMaintenance.Treatment5, dbo.FTBMMaintenance.Treatment6, dbo.FTBMMaintenance.Treatment7, dbo.FTBMMaintenance.Treatment8, dbo.FTBMMaintenance.Treatment9, dbo.FTBMMaintenance.Treatment10, 
                         dbo.FTBMMaintenance.Treatment11, dbo.FTBMMaintenance.Treatment12, dbo.FTBMMaintenance.Treatment13, dbo.FTBMMaintenance.Treatment14, dbo.FTBMMaintenance.MajorTreatment AS COUNTERMEASURE1, 
                         dbo.FTBMMaintenance.ConditionAfterAdj AS [AFTER CONDITION], dbo.FTBMMaintenance.ConditionAfterAdjMin AS [AFTER CONDITION QUANTITY1], 
                         dbo.FTBMMaintenance.ConditionAfterAdjMax AS [AFTER CONDITION QUANTITY2], dbo.FTBMMaintenance.UseDummyFrames AS [USING DUMMY PRODUCT], dbo.FTBMMaintenance.DummyIn AS [DUMMY IN], 
                         dbo.FTBMMaintenance.DummyOut AS [DUMMY OUT], dbo.FTBMMaintenance.DroppedWork AS [CHECKING DROPPED WORK], dbo.FTBMMaintenance.DroppedWorkBeforePM AS [DROPPED WORK BEFORE], 
                         dbo.FTBMMaintenance.DroppeWorkAfterPM AS [DROPPED WORK AFTER], dbo.FTBMMaintenance.ItemValueChecked AS [ITEM/VALUE CHECKED], dbo.FTBMMaintenance.ChangedValueChecked AS [CHANGED/CHECKED VALUE], 
                         dbo.FTBMMaintenance.ReqSATInsp AS [REQUEST FOR SAT INSPECTION], dbo.FTBMMaintenance.SATInspResult AS [SAT INSPECTION RESULT], dbo.FTBMMaintenance.SATInspResultStatus AS [SAT INSPECTION], 
                         dbo.FTBMMaintenance.CheckSensorColorNo AS [CHECK SENSOR COLOR AND NO.], dbo.FTBMMaintenance.CheckSensorReaction AS [CHECK SENSOR REACTION], 
                         dbo.FTBMMaintenance.MotionSafetyCoverSwitch AS [MOTION OF SAFETY COVER SWITCH], dbo.FTBMMaintenance.Check5SAfterPMWork AS [5S AFTER PM WORK], 
                         dbo.FTBMMaintenance.SelconReg AS [SELCON REGISTRATION], dbo.FTBMMaintenance.SelconRegValue AS [PREVIOUS ADJUSTMENT], dbo.FTBMMaintenance.InspectionReq AS [INSPECTION REQUEST], 
                         dbo.FTBMMaintenance.InspQtyNeeded AS [INSPECTION QTY NEEDED], dbo.FTBMMaintenance.CheckItem AS [CHECK ITEM1], dbo.FTBMMaintenance.CheckItem1 AS [CHECK ITEM2], 
                         dbo.FTBMMaintenance.CheckItem2 AS [CHECK ITEM3], dbo.FTBMMaintenance.CheckItem3 AS [CHECK ITEM4], dbo.FTBMMaintenance.RequesttoPD AS [REQUEST TO], 
                         dbo.FTBMMaintenance.PDConfirmation AS [PD CONFIRMATION], dbo.FTBMMaintenance.InspectionResults AS [INSPECTION RESULTS], dbo.FTBMMaintenance.PDTreatmentIncharge AS [PD TREATMENT/ INCHARGE], 
                         dbo.FTBMMaintenance.ChangePartsName1 AS [PARTS NAME1], dbo.FTBMMaintenance.ChangePartsType1 AS TYPE1, dbo.FTBMMaintenance.ChangePartsQty1 AS QTY1, 
                         dbo.FTBMMaintenance.ChangePartsNewReworked1 AS [PARTS REPLACED1], dbo.FTBMMaintenance.ChangePartsDate1 AS [CHANGE PARTS DATE1], dbo.FTBMMaintenance.ChangePartsMonthDay1 AS [REMARKS/LIFE1], 
                         dbo.FTBMMaintenance.ChangePartsInsNewReworked1 AS [PARTS INSTALLED1], dbo.FTBMMaintenance.ChangePartsName2 AS [PARTS NAME2], dbo.FTBMMaintenance.ChangePartsType2 AS TYPE2, 
                         dbo.FTBMMaintenance.ChangePartsQty2 AS QTY2, dbo.FTBMMaintenance.ChangePartsNewReworked2 AS [PARTS REPLACED2], dbo.FTBMMaintenance.ChangePartsDate2 AS [CHANGE PARTS DATE2], 
                         dbo.FTBMMaintenance.ChangePartsMonthDay2 AS [REMARKS/LIFE2], dbo.FTBMMaintenance.ChangePartsInsNewReworked2 AS [PARTS INSTALLED2], dbo.FTBMMaintenance.ChangePartsName3 AS [PARTS NAME3], 
                         dbo.FTBMMaintenance.ChangePartsType3 AS TYPE3, dbo.FTBMMaintenance.ChangePartsQty3 AS QTY3, dbo.FTBMMaintenance.ChangePartsNewReworked3 AS [PARTS REPLACED3], 
                         dbo.FTBMMaintenance.ChangePartsDate3 AS [CHANGE PARTS DATE3], dbo.FTBMMaintenance.ChangePartsMonthDay3 AS [REMARKS/LIFE3], dbo.FTBMMaintenance.ChangePartsInsNewReworked3 AS [PARTS INSTALLED3], 
                         dbo.FTBMMaintenance.ChangePartsName4 AS [PARTS NAME4], dbo.FTBMMaintenance.ChangePartsType4 AS TYPE4, dbo.FTBMMaintenance.ChangePartsQty4 AS QTY4, 
                         dbo.FTBMMaintenance.ChangePartsNewReworked4 AS [PARTS REPLACED4], dbo.FTBMMaintenance.ChangePartsDate4 AS [CHANGE PARTS DATE4], dbo.FTBMMaintenance.ChangePartsMonthDay4 AS [REMARKS/LIFE4], 
                         dbo.FTBMMaintenance.ChangePartsInsNewReworked4 AS [PARTS INSTALLED4], dbo.FTBMMaintenance.ChangePartsName5 AS [PARTS NAME5], dbo.FTBMMaintenance.ChangePartsType5 AS TYPE5, 
                         dbo.FTBMMaintenance.ChangePartsQty5 AS QTY5, dbo.FTBMMaintenance.ChangePartsNewReworked5 AS [PARTS REPLACED5], dbo.FTBMMaintenance.ChangePartsDate5 AS [CHANGE PARTS DATE5], 
                         dbo.FTBMMaintenance.ChangePartsMonthDay5 AS [REMARKS/LIFE5], dbo.FTBMMaintenance.ChangePartsInsNewReworked5 AS [PARTS INSTALLED5], dbo.FTBMMaintenance.TypeofRequest AS [TYPE OF REQUEST], 
                         dbo.FTBMMaintenance.PMConfirmGLOPReason AS [INVALID REQUEST REASON], PMCategory_1.PMCategory AS [PM CATEGORY], BMContent_1.BMContent AS [BM CONTENT], BMCase_1.BMCase AS [CASE], 
                         BMMCUnit_1.BMMCUnit AS [MACHINE UNIT], BMPoint_1.BMPoint AS POSITION, BMWorkContent_1.BMWorkContent AS [WORK CONTENT], dbo.FTBMMaintenance.RequestItem AS [BM CAUSE], 
                         dbo.PREVMeasure.PREVMeasure AS [PREVENTIVE MEASURE], dbo.FTBMMaintenance.AccreditorRemarks AS [IN-CHARGE REMARKS], dbo.FTBMMaintenance.AccreditorPMReply AS [PM REMARKS], 
                         BMWhy_1.BM4M AS [4M ANALYSIS TYPE], BMWhy_1.BMWhy AS [4M ANALYSIS], dbo.PMCategory.PMCategory AS [IN-CHARGE PM CATEGORY], dbo.BMContent.BMContent AS [IN-CHARGE-CONTENT], 
                         dbo.BMCase.BMCase AS [IN-CHARGE CASE], dbo.BMMCUnit.BMMCUnit AS [IN-CHARGE MACHINE UNIT], dbo.BMPoint.BMPoint AS [IN-CHARGE POSITION], 
                         dbo.BMWorkContent.BMWorkContent AS [IN-CHARGE WORK CONTENT], BMWhy_2.BMWhy AS [IN-CHARGE CAUSE], dbo.PREVMeasure.PREVMeasure AS [IN-CHARGE PREVENTIVE MEASURE], 
                         dbo.FTBMMaintenance.AcredINSPN AS [PERIODIC RELATED BM], dbo.FTBMMaintenance.OccurrenceDate, dbo.FTBMMaintenance.BMStatusID, dbo.FTBMMaintenance.Process, dbo.FTBMMaintenance.Location, 
                         dbo.FTBMMaintenance.bmID,
                             (SELECT        CASE WHEN dbo.FTBMMaintenance.BMStatusID = '14' OR
                                                         dbo.FTBMMaintenance.BMStatusID = '11' OR
                                                         dbo.FTBMMaintenance.BMStatusID = '13' THEN CASE WHEN dbo.FTBMMaintenance.isnotquality2 = 'No' AND dbo.FTBMMaintenance.isnotquality3 = 'No' THEN 'Yes' ELSE 'No' END ELSE 'No' END AS IsQualityBM)
                          AS IsQualityBM, dbo.FTBMMaintenance.EndBM AS AccreditorTimeStamp
FROM            dbo.FTBMMaintenance LEFT OUTER JOIN
                         dbo.BMWhy ON dbo.FTBMMaintenance.Why4 = dbo.BMWhy.BMWhyID LEFT OUTER JOIN
                         dbo.BMWhy AS BMWhy_2 ON dbo.FTBMMaintenance.AcredBMCauseID = BMWhy_2.BMWhyID LEFT OUTER JOIN
                         dbo.BMWorkContent ON dbo.FTBMMaintenance.AcredBMWorkContentID = dbo.BMWorkContent.BMWorkContentID LEFT OUTER JOIN
                         dbo.BMPoint ON dbo.FTBMMaintenance.AcredBMPointID = dbo.BMPoint.BMPointID LEFT OUTER JOIN
                         dbo.BMMCUnit ON dbo.FTBMMaintenance.AcredBMMCUnitID = dbo.BMMCUnit.BMMCUnitID LEFT OUTER JOIN
                         dbo.BMCase ON dbo.FTBMMaintenance.AcredBMCaseID = dbo.BMCase.BMCaseID LEFT OUTER JOIN
                         dbo.PMCategory ON dbo.FTBMMaintenance.AcredPMCategoryID = dbo.PMCategory.PMCategoryID LEFT OUTER JOIN
                         dbo.BMWhy AS BMWhy_1 ON dbo.FTBMMaintenance.AcredBMCauseID = BMWhy_1.BMWhyID LEFT OUTER JOIN
                         dbo.PREVMeasure ON dbo.FTBMMaintenance.AcredPREVMeasureID = dbo.PREVMeasure.PREVMeasureID LEFT OUTER JOIN
                         dbo.BMWorkContent AS BMWorkContent_1 ON dbo.FTBMMaintenance.BMWorkContentID = BMWorkContent_1.BMWorkContentID LEFT OUTER JOIN
                         dbo.BMPoint AS BMPoint_1 ON dbo.FTBMMaintenance.BMPointID = BMPoint_1.BMPointID LEFT OUTER JOIN
                         dbo.BMCase AS BMCase_1 ON dbo.FTBMMaintenance.BMCaseID = BMCase_1.BMCaseID LEFT OUTER JOIN
                         dbo.BMMCUnit AS BMMCUnit_1 ON dbo.FTBMMaintenance.BMUnitID = BMMCUnit_1.BMMCUnitID LEFT OUTER JOIN
                         dbo.BMContent AS BMContent_1 ON dbo.FTBMMaintenance.BMContentID = BMContent_1.BMContentID LEFT OUTER JOIN
                         dbo.PMCategory AS PMCategory_1 ON dbo.FTBMMaintenance.PMCategoryID = PMCategory_1.PMCategoryID LEFT OUTER JOIN
                         dbo.BMContent ON dbo.FTBMMaintenance.AcredBMContentID = dbo.BMContent.BMContentID
GO
/****** Object:  View [dbo].[View_KarteRawDataWB]    Script Date: 10/25/2026 4:57:09 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[View_KarteRawDataWB]
AS
SELECT   a.mcno, b.BMCase AS bmcase, OccurrenceDate, CASE WHEN mcno = LEAD(mcno) OVER (ORDER BY mcno DESC, OccurrenceDate ASC, bmcase DESC) 
THEN CASE WHEN bmcase = LEAD(bmcase) OVER (ORDER BY mcno DESC, OccurrenceDate ASC, bmcase DESC) THEN 'Same as next row' ELSE CASE WHEN bmcase = LAG(bmcase) 
OVER (ORDER BY mcno DESC, OccurrenceDate ASC, bmcase DESC) AND mcno = LAG(mcno) OVER (ORDER BY mcno DESC, OccurrenceDate ASC, bmcase DESC) 
THEN 'Same as next row' ELSE 'Different from next row' END END ELSE CASE WHEN bmcase = LAG(bmcase) OVER (ORDER BY mcno DESC, OccurrenceDate ASC, bmcase DESC) AND 
mcno = LAG(mcno) OVER (ORDER BY mcno DESC, OccurrenceDate ASC, bmcase DESC) THEN 'Same as next row' ELSE 'Different from next row' END END AS comparison_result
FROM         [eMaintenanceSystemDB].[dbo].[wbBMMaintenance] a INNER JOIN
                         [eMaintenanceSystemDB].[dbo].[BMCase] b ON a.BMCaseID = b.BMCaseID
WHERE     OccurrenceDate IS NOT NULL 
GO
