CREATE VIEW [dbo].[View_KarteRawDataDC]
AS
SELECT   a.mcno, b.BMCase AS bmcase, OccurrenceDate, CASE WHEN mcno = LEAD(mcno) OVER (ORDER BY mcno DESC, OccurrenceDate ASC, bmcase DESC) 
THEN CASE WHEN bmcase = LEAD(bmcase) OVER (ORDER BY mcno DESC, OccurrenceDate ASC, bmcase DESC) THEN 'Same as next row' ELSE CASE WHEN bmcase = LAG(bmcase) 
OVER (ORDER BY mcno DESC, OccurrenceDate ASC, bmcase DESC) AND mcno = LAG(mcno) OVER (ORDER BY mcno DESC, OccurrenceDate ASC, bmcase DESC) 
THEN 'Same as next row' ELSE 'Different from next row' END END ELSE CASE WHEN bmcase = LAG(bmcase) OVER (ORDER BY mcno DESC, OccurrenceDate ASC, bmcase DESC) AND 
mcno = LAG(mcno) OVER (ORDER BY mcno DESC, OccurrenceDate ASC, bmcase DESC) THEN 'Same as next row' ELSE 'Different from next row' END END AS comparison_result
FROM         [eMaintenanceSystemDB].[dbo].[DCBMMaintenance] a INNER JOIN
                         [eMaintenanceSystemDB].[dbo].[BMCase] b ON a.BMCaseID = b.BMCaseID
WHERE     OccurrenceDate IS NOT NULL
GO
