GO
CREATE VIEW [dbo].[viewOCAP]
AS
SELECT        dbo.BMCase.Process, dbo.MCType.MCTypeID, dbo.MCType.MCType, dbo.BMCase.BMCaseID, dbo.BMCase.BMCase, dbo.BMOCAP.BMOCAPName, dbo.BMOCAP.BMOCAPCheckingMethod, 
                         dbo.BMOCAP.BMOCAPTreatmentAction
FROM            dbo.MCType INNER JOIN
                         dbo.BMCase ON dbo.MCType.MCTypeID = dbo.BMCase.MCTypeID INNER JOIN
                         dbo.BMOCAP ON dbo.BMCase.BMCaseID = dbo.BMOCAP.BMCaseID
GO
/****** Object:  View [dbo].[ViewDCBM_OEE]    Script Date: 10/25/2026 4:57:09 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[ViewDCBM_OEE]
AS
SELECT DISTINCT MCNo, { fn IFNULL
                             ((SELECT        TOP (1) CellCon_MCNo
                                 FROM            dbo.MachineNameCompare_OEE
                                 WHERE        (Emaint_MCNo = dbo.DCBMMaintenance.MCNo)), MCNo) } AS MCNoCellCon, MCType, LOTNo, StartOfRepair, EndOfRepair, TimeOfRequest, PEConfirmPMTurnoverDate, GLConfirmOPReqDate, 
                         MONTH(StartOfRepair) AS Month1, DAY(StartOfRepair) AS Day1, YEAR(StartOfRepair) AS Year1, CAST(DATEPART(Hour, TimeOfRequest) AS varchar) + ':' + CAST(DATEPART(Minute, TimeOfRequest) AS varchar) AS timeofrequest1, 
                         MONTH(OccurrenceDate) AS MonthEnd_Emt, DAY(OccurrenceDate) AS DayEnd_Emt, YEAR(OccurrenceDate) AS YearEnd_Emt, CAST(DATEPART(Hour, EndOfRepair) AS varchar) + ':' + CAST(DATEPART(Minute, EndOfRepair) 
                         AS varchar) AS Endofrepair1, { fn WEEK(TimeOfRequest) } AS Week1, Location, { fn WEEK(OccurrenceDate) } AS WeekEnd_Emt, PkgName AS Package, Situation, OccurrenceFreq, OccurrenceFreqQuantity, 
                         OccurrenceFreqLotFrame, RequestedBy, OccurrenceDate, RepairedByEnd, GLConfirmOPReq, PMTurnOvertoPEDate,
                             (SELECT        BMCase
                               FROM            dbo.BMCase
                               WHERE        (BMCaseID = dbo.DCBMMaintenance.BMCaseID)) AS CaseName, RequestContent, GLConfirmOPReqDate AS GLConfirmDate, StartOfRepair AS StartTime, EndOfRepair AS EndTime, 
                         PEConfirmPMTurnoverDate AS PEStartTime, EndOfRepair AS PEEndTime,
                             (SELECT        PMCategory
                               FROM            dbo.PMCategory
                               WHERE        (PMCategoryID = dbo.DCBMMaintenance.PMCategoryID)) AS Classification, KanagataNo, DeviceName, NGDetectionCircumtances, AQI, RequestedBy AS Issuer, GLConfirmOPReq AS GL, PMConfirmGLOPReq, 
                         PEConfirmPMTurnoverBy, PEConfirmPMTurnoverDate AS Expr1, Why1
FROM            dbo.DCBMMaintenance
GO
