SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[viewTSC]
AS
SELECT        dbo.BMCase.Process, dbo.MCType.MCTypeID, dbo.MCType.MCType, dbo.BMCase.BMCaseID, dbo.BMCase.BMCase, dbo.BMTsc.BMTscName, dbo.BMTsc.BMTscStandard, dbo.BMTsc.BMTscAdjustment
FROM            dbo.MCType INNER JOIN
                         dbo.BMCase ON dbo.MCType.MCTypeID = dbo.BMCase.MCTypeID INNER JOIN
                         dbo.BMTsc ON dbo.BMCase.BMCaseID = dbo.BMTsc.BMCaseID
GO
