Create VIEW [dbo].[viewWBEMaking_Live]
AS
SELECT BMEvidenceID, bmID, BMEvidence_Title, BMEvidence_Desc, BMEvidence_Category, BMEvidence_ImgFile, BMEvidence_DateTime, BMEvidence_UploadedBy, BMEvidence_TCConfirm1, BMEvidence_TCConfirm2, BMEvidence_TCConfirm3, 
                  BMEvidence_TCConfirm4, BMEvidence_TCConfirm5, BMEvidence_TCConfirm6, BMEvidence_TCConfirm7, BMEvidence_TCConfirm8, BMEvidence_TCConfirm9, BMVersionNo, BMRouteNo, Process, SignalTowerKanban, SafetyTags, 
                  Bypass
FROM     dbo.BMEvidenceMaking
WHERE  (Process = 'WB')
GO
