CREATE VIEW [dbo].[ViewPLBM_OEE]
AS
SELECT DISTINCT MCNo, { fn IFNULL
                             ((SELECT        TOP (1) CellCon_MCNo
                                 FROM            dbo.MachineNameCompare_OEE
                                 WHERE        (Emaint_MCNo = dbo.PLBMMaintenance.MCNo)), MCNo) } AS MCNoCellCon, MCType, LOTNo, StartOfRepair, EndOfRepair, TimeOfRequest, PEConfirmPMTurnoverDate, GLConfirmOPReqDate, 
                         MONTH(StartOfRepair) AS Month1, DAY(StartOfRepair) AS Day1, YEAR(StartOfRepair) AS Year1, CAST(DATEPART(Hour, TimeOfRequest) AS varchar) + ':' + CAST(DATEPART(Minute, TimeOfRequest) AS varchar) AS timeofrequest1, 
                         MONTH(OccurrenceDate) AS Month2, DAY(OccurrenceDate) AS Day2, YEAR(OccurrenceDate) AS Year2, CAST(DATEPART(Hour, EndOfRepair) AS varchar) + ':' + CAST(DATEPART(Minute, EndOfRepair) AS varchar) AS Endofrepair1, 
                         { fn WEEK(TimeOfRequest) } AS Week1, Location, { fn WEEK(OccurrenceDate) } AS Week2, PkgName AS Package, Situation, OccurrenceFreq, OccurrenceFreqQuantity, OccurrenceFreqLotFrame, RequestedBy, OccurrenceDate, 
                         RepairedByEnd, GLConfirmOPReq,
                             (SELECT        BMCase
                               FROM            dbo.BMCase
                               WHERE        (BMCaseID = dbo.PLBMMaintenance.BMCaseID)) AS CaseName, RequestContent, GLConfirmOPReqDate AS GLConfirmDate, StartOfRepair AS StartTime, EndOfRepair AS EndTime, 
                         PEConfirmPMTurnoverDate AS PEStartTime, EndOfRepair AS PEEndTime,
                             (SELECT        PMCategory
                               FROM            dbo.PMCategory
                               WHERE        (PMCategoryID = dbo.PLBMMaintenance.PMCategoryID)) AS Classification, KanagataNo, DeviceName, NGDetectionCircumtances, AQI, RequestedBy AS Issuer, GLConfirmOPReq AS GL, PMConfirmGLOPReq, 
                         PEConfirmPMTurnoverBy, PEConfirmPMTurnoverDate AS Expr1, Why1,
                             (SELECT        CASE WHEN dbo.PLBMMaintenance.Turnover = 'PE' OR
                                                         dbo.PLBMMaintenance.Turnover = 'CC' OR
                                                         dbo.PLBMMaintenance.Turnover = 'VIS' THEN dbo.PLBMMaintenance.PMTurnOvertoPEDate ELSE dbo.PLBMMaintenance.EndOfRepair END AS PMTurnOvertoPEDate) AS PMTurnOvertoPEDate,
                             (SELECT        CASE WHEN dbo.PLBMMaintenance.Turnover = 'PE' OR
                                                         dbo.PLBMMaintenance.Turnover = 'CC' OR
                                                         dbo.PLBMMaintenance.Turnover = 'VIS' THEN dbo.PLBMMaintenance.EndOfRepair ELSE NULL END AS Expr1) AS Endofrepair3
FROM            dbo.PLBMMaintenance
GO
