CREATE VIEW [dbo].[EDSFinalBMRawData]
AS
SELECT        dbo.EDSBMMaintenance.MCNo AS [MC No], dbo.EDSBMMaintenance.MCType AS [MC Type], dbo.EDSBMMaintenance.PkgName AS Package, dbo.EDSBMMaintenance.KanagataNo AS [Kanagata Number], 
