                             (SELECT        CASE WHEN dbo.EDSBMMaintenance.BMStatusID = 14 THEN PMCategory.PMCategory ELSE PMCategory_1.PMCategory END AS PMCategory) AS Classification, 
                         dbo.EDSBMMaintenance.NGDetectionCircumtances AS [NG Detection Circumstance], dbo.EDSBMMaintenance.RequestItem AS [Case Name], dbo.EDSBMMaintenance.RequestContent AS [Request Content], 
                         dbo.EDSBMMaintenance.Situation AS Condition, dbo.EDSBMMaintenance.OccurrenceFreq AS [Occurrence Rate Before Condition], dbo.EDSBMMaintenance.OccurrenceFreqQuantity AS Quantity1, 
                         dbo.EDSBMMaintenance.OccurrenceFreqLotFrame AS Quantity2, dbo.EDSBMMaintenance.AQI, dbo.EDSBMMaintenance.OccurrenceDate AS [Request Date and Time], dbo.EDSBMMaintenance.RequestedBy AS Issuer, 
                         dbo.EDSBMMaintenance.GLConfirmOPReqBy AS GL, dbo.EDSBMMaintenance.GLConfirmOPReqDate AS [GL Confirmed Date], dbo.EDSBMMaintenance.PMConfirmGLOPReqBy AS [PM Confirmed Request],
                             (SELECT        CASE WHEN dbo.EDSBMMaintenance.Turnover = 'PE' OR
                                                         dbo.EDSBMMaintenance.Turnover = 'CC' OR
                                                         dbo.EDSBMMaintenance.Turnover = 'VIS' THEN '' ELSE dbo.EDSBMMaintenance.RepairedByEnd END AS Expr1) AS [PM Done Request], 
                         dbo.EDSBMMaintenance.PMConfirmGLOPReqDate AS [START DATE AND TIME],
                             (SELECT        CASE WHEN dbo.EDSBMMaintenance.Turnover = 'PE' OR
                                                         dbo.EDSBMMaintenance.Turnover = 'CC' OR
                                                         dbo.EDSBMMaintenance.Turnover = 'VIS' THEN dbo.EDSBMMaintenance.PMTurnOvertoPEDate ELSE dbo.EDSBMMaintenance.EndOfRepair END AS Expr1) AS [END DATE AND TIME], 
                         dbo.EDSBMMaintenance.PEConfirmPMTurnoverBy AS [PE Confirmed Request],
                             (SELECT        CASE WHEN dbo.EDSBMMaintenance.Turnover = 'PE' OR
                                                         dbo.EDSBMMaintenance.Turnover = 'CC' OR
                                                         dbo.EDSBMMaintenance.Turnover = 'VIS' THEN dbo.EDSBMMaintenance.RepairedByEnd ELSE '' END AS Expr1) AS [PE Done Request], 
                         dbo.EDSBMMaintenance.PEConfirmPMTurnoverDate AS [PE START DATE AND TIME],
                             (SELECT        CASE WHEN dbo.EDSBMMaintenance.Turnover = 'PE' OR
                                                         dbo.EDSBMMaintenance.Turnover = 'CC' OR
                                                         dbo.EDSBMMaintenance.Turnover = 'VIS' THEN dbo.EDSBMMaintenance.EndOfRepair ELSE NULL END AS Expr1) AS [PE END DATE AND TIME], dbo.EDSBMMaintenance.Why1, dbo.EDSBMMaintenance.Why2, 
                         dbo.EDSBMMaintenance.Why3, dbo.BMWhy.BMWhy AS Why4, dbo.EDSBMMaintenance.Treatment1, dbo.EDSBMMaintenance.Treatment2, dbo.EDSBMMaintenance.Treatment3, dbo.EDSBMMaintenance.Treatment4, 
                         dbo.EDSBMMaintenance.Treatment5, dbo.EDSBMMaintenance.Treatment6, dbo.EDSBMMaintenance.Treatment7, dbo.EDSBMMaintenance.Treatment8, dbo.EDSBMMaintenance.Treatment9, 
                         dbo.EDSBMMaintenance.Treatment10, dbo.EDSBMMaintenance.Treatment11, dbo.EDSBMMaintenance.Treatment12, dbo.EDSBMMaintenance.Treatment13, dbo.EDSBMMaintenance.Treatment14, 
                         dbo.EDSBMMaintenance.MajorTreatment AS COUNTERMEASURE1, dbo.EDSBMMaintenance.ConditionAfterAdj AS [AFTER CONDITION], dbo.EDSBMMaintenance.ConditionAfterAdjMin AS [AFTER CONDITION QUANTITY1], 
                         dbo.EDSBMMaintenance.ConditionAfterAdjMax AS [AFTER CONDITION QUANTITY2], dbo.EDSBMMaintenance.UseDummyFrames AS [USING DUMMY PRODUCT], dbo.EDSBMMaintenance.DummyIn AS [DUMMY IN], 
                         dbo.EDSBMMaintenance.DummyOut AS [DUMMY OUT], dbo.EDSBMMaintenance.DroppedWork AS [CHECKING DROPPED WORK], dbo.EDSBMMaintenance.DroppedWorkBeforePM AS [DROPPED WORK BEFORE], 
                         dbo.EDSBMMaintenance.DroppeWorkAfterPM AS [DROPPED WORK AFTER], dbo.EDSBMMaintenance.ItemValueChecked AS [ITEM/VALUE CHECKED], 
                         dbo.EDSBMMaintenance.ChangedValueChecked AS [CHANGED/CHECKED VALUE], dbo.EDSBMMaintenance.ReqSATInsp AS [REQUEST FOR SAT INSPECTION], 
                         dbo.EDSBMMaintenance.SATInspResult AS [SAT INSPECTION RESULT], dbo.EDSBMMaintenance.SATInspResultStatus AS [SAT INSPECTION], 
                         dbo.EDSBMMaintenance.CheckSensorColorNo AS [CHECK SENSOR COLOR AND NO.], dbo.EDSBMMaintenance.CheckSensorReaction AS [CHECK SENSOR REACTION], 
                         dbo.EDSBMMaintenance.MotionSafetyCoverSwitch AS [MOTION OF SAFETY COVER SWITCH], dbo.EDSBMMaintenance.Check5SAfterPMWork AS [5S AFTER PM WORK], 
                         dbo.EDSBMMaintenance.SelconReg AS [SELCON REGISTRATION], dbo.EDSBMMaintenance.SelconRegValue AS [PREVIOUS ADJUSTMENT], dbo.EDSBMMaintenance.InspectionReq AS [INSPECTION REQUEST], 
                         dbo.EDSBMMaintenance.InspQtyNeeded AS [INSPECTION QTY NEEDED], dbo.EDSBMMaintenance.CheckItem AS [CHECK ITEM1], dbo.EDSBMMaintenance.CheckItem1 AS [CHECK ITEM2], 
                         dbo.EDSBMMaintenance.CheckItem2 AS [CHECK ITEM3], dbo.EDSBMMaintenance.CheckItem3 AS [CHECK ITEM4], dbo.EDSBMMaintenance.RequesttoPD AS [REQUEST TO], 
                         dbo.EDSBMMaintenance.PDConfirmation AS [PD CONFIRMATION], dbo.EDSBMMaintenance.InspectionResults AS [INSPECTION RESULTS], dbo.EDSBMMaintenance.PDTreatmentIncharge AS [PD TREATMENT/ INCHARGE], 
                         dbo.EDSBMMaintenance.ChangePartsName1 AS [PARTS NAME1], dbo.EDSBMMaintenance.ChangePartsType1 AS TYPE1, dbo.EDSBMMaintenance.ChangePartsQty1 AS QTY1, 
                         dbo.EDSBMMaintenance.ChangePartsNewReworked1 AS [PARTS REPLACED1], dbo.EDSBMMaintenance.ChangePartsDate1 AS [CHANGE PARTS DATE1], dbo.EDSBMMaintenance.ChangePartsMonthDay1 AS [REMARKS/LIFE1], 
                         dbo.EDSBMMaintenance.ChangePartsInsNewReworked1 AS [PARTS INSTALLED1], dbo.EDSBMMaintenance.ChangePartsName2 AS [PARTS NAME2], dbo.EDSBMMaintenance.ChangePartsType2 AS TYPE2, 
                         dbo.EDSBMMaintenance.ChangePartsQty2 AS QTY2, dbo.EDSBMMaintenance.ChangePartsNewReworked2 AS [PARTS REPLACED2], dbo.EDSBMMaintenance.ChangePartsDate2 AS [CHANGE PARTS DATE2], 
                         dbo.EDSBMMaintenance.ChangePartsMonthDay2 AS [REMARKS/LIFE2], dbo.EDSBMMaintenance.ChangePartsInsNewReworked2 AS [PARTS INSTALLED2], dbo.EDSBMMaintenance.ChangePartsName3 AS [PARTS NAME3], 
                         dbo.EDSBMMaintenance.ChangePartsType3 AS TYPE3, dbo.EDSBMMaintenance.ChangePartsQty3 AS QTY3, dbo.EDSBMMaintenance.ChangePartsNewReworked3 AS [PARTS REPLACED3], 
                         dbo.EDSBMMaintenance.ChangePartsDate3 AS [CHANGE PARTS DATE3], dbo.EDSBMMaintenance.ChangePartsMonthDay3 AS [REMARKS/LIFE3], 
                         dbo.EDSBMMaintenance.ChangePartsInsNewReworked3 AS [PARTS INSTALLED3], dbo.EDSBMMaintenance.ChangePartsName4 AS [PARTS NAME4], dbo.EDSBMMaintenance.ChangePartsType4 AS TYPE4, 
                         dbo.EDSBMMaintenance.ChangePartsQty4 AS QTY4, dbo.EDSBMMaintenance.ChangePartsNewReworked4 AS [PARTS REPLACED4], dbo.EDSBMMaintenance.ChangePartsDate4 AS [CHANGE PARTS DATE4], 
                         dbo.EDSBMMaintenance.ChangePartsMonthDay4 AS [REMARKS/LIFE4], dbo.EDSBMMaintenance.ChangePartsInsNewReworked4 AS [PARTS INSTALLED4], dbo.EDSBMMaintenance.ChangePartsName5 AS [PARTS NAME5], 
                         dbo.EDSBMMaintenance.ChangePartsType5 AS TYPE5, dbo.EDSBMMaintenance.ChangePartsQty5 AS QTY5, dbo.EDSBMMaintenance.ChangePartsNewReworked5 AS [PARTS REPLACED5], 
                         dbo.EDSBMMaintenance.ChangePartsDate5 AS [CHANGE PARTS DATE5], dbo.EDSBMMaintenance.ChangePartsMonthDay5 AS [REMARKS/LIFE5], 
                         dbo.EDSBMMaintenance.ChangePartsInsNewReworked5 AS [PARTS INSTALLED5], dbo.EDSBMMaintenance.TypeofRequest AS [TYPE OF REQUEST], 
                         dbo.EDSBMMaintenance.PMConfirmGLOPReason AS [INVALID REQUEST REASON], PMCategory_1.PMCategory AS [PM CATEGORY], BMContent_1.BMContent AS [BM CONTENT], BMCase_1.BMCase AS [CASE], 
                         BMMCUnit_1.BMMCUnit AS [MACHINE UNIT], BMPoint_1.BMPoint AS POSITION, BMWorkContent_1.BMWorkContent AS [WORK CONTENT], dbo.EDSBMMaintenance.RequestItem AS [BM CAUSE], 
                         dbo.PREVMeasure.PREVMeasure AS [PREVENTIVE MEASURE], dbo.EDSBMMaintenance.AccreditorRemarks AS [IN-CHARGE REMARKS], dbo.EDSBMMaintenance.AccreditorPMReply AS [PM REMARKS], 
                         BMWhy_1.BM4M AS [4M ANALYSIS TYPE], BMWhy_1.BMWhy AS [4M ANALYSIS], dbo.PMCategory.PMCategory AS [IN-CHARGE PM CATEGORY], dbo.BMContent.BMContent AS [IN-CHARGE-CONTENT], 
                         dbo.BMCase.BMCase AS [IN-CHARGE CASE], dbo.BMMCUnit.BMMCUnit AS [IN-CHARGE MACHINE UNIT], dbo.BMPoint.BMPoint AS [IN-CHARGE POSITION], 
                         dbo.BMWorkContent.BMWorkContent AS [IN-CHARGE WORK CONTENT], BMWhy_2.BMWhy AS [IN-CHARGE CAUSE], dbo.PREVMeasure.PREVMeasure AS [IN-CHARGE PREVENTIVE MEASURE], 
                         dbo.EDSBMMaintenance.AcredINSPN AS [PERIODIC RELATED BM], dbo.EDSBMMaintenance.bmID, dbo.EDSBMMaintenance.OccurrenceDate, dbo.EDSBMMaintenance.BMStatusID, dbo.EDSBMMaintenance.Process, 
                         dbo.EDSBMMaintenance.Location,
                             (SELECT        CASE WHEN dbo.EDSBMMaintenance.BMStatusID = '14' OR
                                                         dbo.EDSBMMaintenance.BMStatusID = '11' OR
                                                         dbo.EDSBMMaintenance.BMStatusID = '13' THEN CASE WHEN dbo.EDSBMMaintenance.isnotquality2 = 'No' AND 
                                                         dbo.EDSBMMaintenance.isnotquality3 = 'No' THEN 'Yes' ELSE 'No' END ELSE 'No' END AS IsQualityBM) AS 'IsQualityBM'
FROM            dbo.EDSBMMaintenance LEFT OUTER JOIN
                         dbo.BMWhy ON dbo.EDSBMMaintenance.Why4 = dbo.BMWhy.BMWhyID LEFT OUTER JOIN
                         dbo.BMWhy AS BMWhy_2 ON dbo.EDSBMMaintenance.AcredBMCauseID = BMWhy_2.BMWhyID LEFT OUTER JOIN
                         dbo.BMWorkContent ON dbo.EDSBMMaintenance.AcredBMWorkContentID = dbo.BMWorkContent.BMWorkContentID LEFT OUTER JOIN
                         dbo.BMPoint ON dbo.EDSBMMaintenance.AcredBMPointID = dbo.BMPoint.BMPointID LEFT OUTER JOIN
                         dbo.BMMCUnit ON dbo.EDSBMMaintenance.AcredBMMCUnitID = dbo.BMMCUnit.BMMCUnitID LEFT OUTER JOIN
                         dbo.BMCase ON dbo.EDSBMMaintenance.AcredBMCaseID = dbo.BMCase.BMCaseID LEFT OUTER JOIN
                         dbo.PMCategory ON dbo.EDSBMMaintenance.AcredPMCategoryID = dbo.PMCategory.PMCategoryID LEFT OUTER JOIN
                         dbo.BMWhy AS BMWhy_1 ON dbo.EDSBMMaintenance.AcredBMCauseID = BMWhy_1.BMWhyID LEFT OUTER JOIN
                         dbo.PREVMeasure ON dbo.EDSBMMaintenance.AcredPREVMeasureID = dbo.PREVMeasure.PREVMeasureID LEFT OUTER JOIN
                         dbo.BMWorkContent AS BMWorkContent_1 ON dbo.EDSBMMaintenance.BMWorkContentID = BMWorkContent_1.BMWorkContentID LEFT OUTER JOIN
                         dbo.BMPoint AS BMPoint_1 ON dbo.EDSBMMaintenance.BMPointID = BMPoint_1.BMPointID LEFT OUTER JOIN
                         dbo.BMCase AS BMCase_1 ON dbo.EDSBMMaintenance.BMCaseID = BMCase_1.BMCaseID LEFT OUTER JOIN
                         dbo.BMMCUnit AS BMMCUnit_1 ON dbo.EDSBMMaintenance.BMUnitID = BMMCUnit_1.BMMCUnitID LEFT OUTER JOIN
                         dbo.BMContent AS BMContent_1 ON dbo.EDSBMMaintenance.BMContentID = BMContent_1.BMContentID LEFT OUTER JOIN
                         dbo.PMCategory AS PMCategory_1 ON dbo.EDSBMMaintenance.PMCategoryID = PMCategory_1.PMCategoryID LEFT OUTER JOIN
                         dbo.BMContent ON dbo.EDSBMMaintenance.AcredBMContentID = dbo.BMContent.BMContentID
GO
