                         dbo.pm_EquipInsData ON dbo.MPBMMaintenance.bmID = dbo.pm_EquipInsData.bmID LEFT OUTER JOIN
                         dbo.BMWhy ON dbo.BMWhy.BMWhyID = dbo.MPBMMaintenance.Why4
GO
