                         dbo.MPBMMaintenance.PmRelatedBM, dbo.MPBMMaintenance.ConfirmationOfSafeGuard, dbo.MPBMMaintenance.[4SCheck], dbo.MPBMMaintenance.AlarmNo, dbo.MPBMMaintenance.KatazureBefore, 
                         dbo.MPBMMaintenance.KatazureAfter, dbo.MPBMMaintenance.MoldCon, dbo.MPBMMaintenance.JudgementBefore, dbo.MPBMMaintenance.JudgementAfter, dbo.MPBMMaintenance.New4M, dbo.MPBMMaintenance.PMMiss, 
                         dbo.MPBMMaintenance.LastBMStop, dbo.MPBMMaintenance.LastBMContinue, dbo.MPBMMaintenance.DateWhen1, dbo.MPBMMaintenance.LotRetrieval, dbo.MPBMMaintenance.Remarks, dbo.MPBMMaintenance.TurnOverTo, 
                         dbo.MPBMMaintenance.BMVersionNo, dbo.MPBMMaintenance.BMRouteNo, dbo.MPBMMaintenance.LotRetrievalConfirm, dbo.MPBMMaintenance.LotRetrievalDate1, dbo.MPBMMaintenance.Akapen1, 
                         dbo.MPBMMaintenance.Akapen2, dbo.MPBMMaintenance.Aopen1, dbo.MPBMMaintenance.Aopen2, dbo.BMWhy.BMWhy AS BMWhy4, dbo.MPBMMaintenance.Akapen3, dbo.MPBMMaintenance.Aopen3, 
                         dbo.MPBMMaintenance.OccurFreqUnit, dbo.MPBMMaintenance.DataDevice, dbo.MPBMMaintenance.UploadtoEvidence, dbo.MPBMMaintenance.AssyUnit1, dbo.MPBMMaintenance.AssyUnit2, 
                         dbo.MPBMMaintenance.AssyUnit3, dbo.MPBMMaintenance.AssyUnit4, dbo.MPBMMaintenance.AssyUnit5, dbo.MPBMMaintenance.AssyUnit6, dbo.MPBMMaintenance.AssyUnit7, dbo.MPBMMaintenance.AssyUnit8, 
                         dbo.MPBMMaintenance.AssyUnit9, dbo.MPBMMaintenance.AssyUnit10, dbo.MPBMMaintenance.AssyUnit11, dbo.MPBMMaintenance.AssyUnit12, dbo.MPBMMaintenance.AssyUnit13, dbo.MPBMMaintenance.AssyUnit14,
                         dbo.MPBMMaintenance.why4others
FROM            dbo.MPBMMaintenance LEFT OUTER JOIN
                         dbo.SubProcess ON dbo.MPBMMaintenance.SubProcessID = dbo.SubProcess.SubProcessID LEFT OUTER JOIN
                         dbo.BMStatus ON dbo.MPBMMaintenance.BMStatusID = dbo.BMStatus.BMStatusID LEFT OUTER JOIN
                         dbo.PMCategory ON dbo.MPBMMaintenance.PMCategoryID = dbo.PMCategory.PMCategoryID LEFT OUTER JOIN
                         dbo.BMCase ON dbo.MPBMMaintenance.BMCaseID = dbo.BMCase.BMCaseID INNER JOIN
                         dbo.MCList ON dbo.MPBMMaintenance.MCNo = dbo.MCList.MCNo LEFT OUTER JOIN
                         dbo.I4M ON dbo.MPBMMaintenance.I4MID = dbo.I4M.I4MID LEFT OUTER JOIN
                         dbo.pm_EquipInsData ON dbo.MPBMMaintenance.bmID = dbo.pm_EquipInsData.bmID LEFT OUTER JOIN
                         dbo.BMWhy ON dbo.BMWhy.BMWhyID = dbo.MPBMMaintenance.Why4
