/****** Object:  View [dbo].[viewWBWaitingForApproval]    Script Date: 10/25/2026 4:57:09 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO






CREATE VIEW [dbo].[viewWBWaitingForApproval]
AS
SELECT        COUNT(bmID) AS TotalBM, Location,
                             (SELECT        COUNT(BMStatusID) AS GLTotal
                               FROM            dbo.WBBMMaintenance AS b
                               WHERE        (BMStatusID = 1) AND (Location = a.Location)) AS WaitingForGLApprovalTotal,
                             (SELECT        COUNT(BMStatusID) AS PMTotal
                               FROM            dbo.WBBMMaintenance AS c
                               WHERE        (BMStatusID = 2) AND (Location = a.Location)) AS WaitingForPMApprovalTotal,
                             (SELECT        COUNT(BMStatusID) AS OnGoingPMTotal
                               FROM            dbo.WBBMMaintenance AS d
                               WHERE        (BMStatusID = 3) AND (Location = a.Location)) AS OnGoingPMTotal,
                             (SELECT        COUNT(BMStatusID) AS PMRepairDoneTotal
                               FROM            dbo.WBBMMaintenance AS e
                               WHERE        (BMStatusID = 4) AND (Location = a.Location)) AS PMRepairDoneTotal,
                             (SELECT        COUNT(BMStatusID) AS GLReturnedToPMTotal
                               FROM            dbo.WBBMMaintenance AS f
                               WHERE        (BMStatusID = 5) AND (Location = a.Location)) AS GLReturnedToPMTotal,
                             (SELECT        COUNT(BMStatusID) AS EETotal
                               FROM            dbo.WBBMMaintenance AS g
                               WHERE        (BMStatusID = 6) AND (Location = a.Location)) AS WaitingForEEApprovalTotal,
                             (SELECT        COUNT(BMStatusID) AS OngoingPERepairTotal
                               FROM            dbo.WBBMMaintenance AS h
                               WHERE        (BMStatusID = 7) AND (Location = a.Location)) AS OngoingPERepairTotal,
                             (SELECT        COUNT(BMStatusID) AS PERepairDoneTotal
                               FROM            dbo.WBBMMaintenance AS i
                               WHERE        (BMStatusID = 8) AND (Location = a.Location)) AS PERepairDoneTotal,
                             (SELECT        COUNT(BMStatusID) AS ReturnedToPETotal
                               FROM            dbo.WBBMMaintenance AS j
                               WHERE        (BMStatusID = 9) AND (Location = a.Location)) AS ReturnedToPETotal,
                             (SELECT        COUNT(BMStatusID) AS PMTurnoverApprovalTotal
                               FROM            dbo.WBBMMaintenance AS k
                               WHERE        (BMStatusID = 10) AND (Location = a.Location)) AS PMTurnoverApprovalTotal,
                             (SELECT        COUNT(BMStatusID) AS AccApprovalTotal
                               FROM            dbo.WBBMMaintenance AS l
                               WHERE        (BMStatusID = 11) AND (Location = a.Location)) AS AccApprovalTotal,
                             (SELECT        COUNT(BMStatusID) AS AccReturnedtoPM
                               FROM            dbo.WBBMMaintenance AS m
                               WHERE        (BMStatusID = 12) AND (Location = a.Location)) AS AccReturnedtoPM,
                             (SELECT        COUNT(BMStatusID) AS PMReturnedtoPM
                               FROM            dbo.WBBMMaintenance AS n
                               WHERE        (BMStatusID = 13) AND (Location = a.Location)) AS PMReturnedtoPM,
                             (SELECT        COUNT(BMStatusID) AS BMClosed
                               FROM            dbo.WBBMMaintenance AS o
                               WHERE        (BMStatusID = 14) AND (Location = a.Location)) AS BMClosed,
                             (SELECT        COUNT(BMStatusID) AS BMInvalid
                               FROM            dbo.WBBMMaintenance AS p
                               WHERE        (BMStatusID = 15) AND (Location = a.Location)) AS BMOcapResolved,
                             (SELECT        COUNT(BMStatusID) AS BMInvalid
                               FROM            dbo.WBBMMaintenance AS q
                               WHERE        (BMStatusID = 30) AND (Location = a.Location)) AS BMInvalid,
                             (SELECT        COUNT(BMStatusID) AS BMVoid
                               FROM            dbo.WBBMMaintenance AS r
                               WHERE        (BMStatusID = 31) AND (Location = a.Location)) AS BMVoid

FROM            dbo.WBBMMaintenance AS a
GROUP BY Location



GO
/****** Object:  View [dbo].[TEFinalRawData_Ver2]    Script Date: 10/25/2026 4:57:09 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[TEFinalRawData_Ver2]
AS
SELECT MONTH(te.OccurrenceDate) AS MONTH, DAY(te.OccurrenceDate) AS DAY, YEAR(te.OccurrenceDate) AS YEAR, CONVERT(varchar(10), te.OccurrenceDate, 103) AS RequestDate, CONVERT(varchar(8), te.OccurrenceDate, 108) 
                  AS RequestTime, CONVERT(varchar(10), te.EndOfRepair, 103) AS EndDate, CONVERT(varchar(8), te.EndOfRepair, 108) AS EndTime, te.MCNo, te.MCType AS TesterType, te.TesterNo, te.DeviceName, te.TestFlow, te.Process, te.PkgName, 
                  te.LOTNo, te.BoxNo, te.DUT, dbo.PMCategory.PMCategory, dbo.TEContent.BMContent, dbo.TECase.BMCase, dbo.BMTEUnit.BMTEUnit, dbo.TEPoint.BMPoint, dbo.TEWorkContent.BMWorkContent, dbo.TECause.BMCause, 
                  dbo.TEPREVMeasure.PREVMeasure, te.RequestedBy, te.RepairedByEnd, DATEDIFF(minute, te.StartOfRepair, te.EndOfRepair) - ABS(ABS(te.TotalSKCTPDtime) - ABS(te.TotalStopTime)) AS RepairTime, DATEDIFF(minute, 
                  te.GLConfirmOPReqDate, te.PMConfirmGLOPReqDate) + te.TotalStopTime AS WaitingTime, DATEDIFF(minute, te.EndOfRepair, te.GLRepairConfirmation) AS MonitoringTime, te.ReqTestNoNG, te.OPRemarks, te.QAction, te.BMStatusID, 
                  te.OccurrenceDate, te.Location, te.GLConfirmOPReqDate AS OPGLApproveDate, te.GLConfirmOPReqBy AS OPGLApproveBy, DATEDIFF(minute, te.TimeOfRequest, te.GLConfirmOPReqDate) AS OPGLWaiting, 
                  te.GLRepairConfirmation AS TEGLConfirmDate, te.GLRepairConfirmationBy AS TEGLConfirmBy, DATEDIFF(minute, te.EndOfRepair, te.GLRepairConfirmation) AS TEGLWaiting, te.SubDUT, te.CurrentTE, te.ProbeRingBefore, 
                  te.ProbeRingAfter, te.IronPlateBefore, te.IronPlateAfter, te.ChangePartsName1, te.ChangePartsName2, te.ChangePartsName3, te.ChangePartsName4, te.ChangePartsName5, te.ChangePartsType1, te.ChangePartsType2, 
                  te.ChangePartsType3, te.ChangePartsType4, te.ChangePartsType5, te.ChangePartsQty1, te.ChangePartsQty2, te.ChangePartsQty3, te.ChangePartsQty4, te.ChangePartsQty5, te.SKCTPDOnHoldDate, te.SKCTPDReleaseDate, 
                  te.TotalSKCTPDtime, dbo.PMCategory.PMCategoryID, dbo.TEContent.BMContentNumber, dbo.TECase.BMCaseCodeNo, dbo.BMTEUnit.BMTEUnitNumber, dbo.TEPoint.BMPointNo, dbo.TEWorkContent.BMWorkContentNumber, 
                  dbo.TECause.BMCauseNo, dbo.TEPREVMeasure.PREVMeasureNo, te.EndBMBy, te.AccreditorRemarks_Max AS 'AccreditorRemarks', te.AccreditorPMReply, te.Designation, te.Priority, te.CellLine
FROM     dbo.TEBMMaintenance AS te LEFT OUTER JOIN
                  dbo.TEWorkContent ON te.BMWorkContentID = dbo.TEWorkContent.BMWorkContentID LEFT OUTER JOIN
                  dbo.TEPREVMeasure ON te.PrevMeasureID = dbo.TEPREVMeasure.PREVMeasureID LEFT OUTER JOIN
                  dbo.TEPoint ON te.BMPointID = dbo.TEPoint.BMPointID LEFT OUTER JOIN
                  dbo.TECause ON te.BMCauseID = dbo.TECause.BMCauseID LEFT OUTER JOIN
                  dbo.TECase ON te.BMCaseID = dbo.TECase.BMCaseID LEFT OUTER JOIN
                  dbo.BMTEUnit ON te.BMUnitID = dbo.BMTEUnit.BMTEUnitID LEFT OUTER JOIN
                  dbo.TEContent ON te.BMContentID = dbo.TEContent.BMContentID LEFT OUTER JOIN
                  dbo.PMCategory ON dbo.PMCategory.PMCategoryID = te.PMCategoryID
GO
