CREATE VIEW [dbo].[MEMSFinalBMRawData]
AS
SELECT        dbo.MEMSBMMaintenance.MCNo AS [MC No], dbo.MEMSBMMaintenance.MCType AS [MC Type], dbo.MEMSBMMaintenance.PkgName AS Package, dbo.MEMSBMMaintenance.KanagataNo AS [Kanagata Number], 
                         dbo.MEMSBMMaintenance.LOTNo AS [Lot Number], dbo.MEMSBMMaintenance.DeviceName AS [Device Name],
                             (SELECT        CASE WHEN dbo.MEMSBMMaintenance.BMStatusID = 14 THEN PMCategory.PMCategory ELSE PMCategory_1.PMCategory END AS PMCategory) AS Classification, 
                         dbo.MEMSBMMaintenance.NGDetectionCircumtances AS [NG Detection Circumstance], dbo.MEMSBMMaintenance.RequestItem AS [Case Name], dbo.MEMSBMMaintenance.RequestContent AS [Request Content], 
                         dbo.MEMSBMMaintenance.Situation AS Condition, dbo.MEMSBMMaintenance.OccurrenceFreq AS [Occurrence Rate Before Condition], dbo.MEMSBMMaintenance.OccurrenceFreqQuantity AS Quantity1, 
                         dbo.MEMSBMMaintenance.OccurrenceFreqLotFrame AS Quantity2, dbo.MEMSBMMaintenance.AQI, dbo.MEMSBMMaintenance.OccurrenceDate AS [Request Date and Time], dbo.MEMSBMMaintenance.RequestedBy AS Issuer, 
                         dbo.MEMSBMMaintenance.GLConfirmOPReqBy AS GL, dbo.MEMSBMMaintenance.GLConfirmOPReqDate AS [GL Confirmed Date], dbo.MEMSBMMaintenance.PMConfirmGLOPReqBy AS [PM Confirmed Request],
                             (SELECT        CASE WHEN dbo.MEMSBMMaintenance.Turnover = 'PE' OR
                                                         dbo.MEMSBMMaintenance.Turnover = 'CC' OR
                                                         dbo.MEMSBMMaintenance.Turnover = 'VIS' THEN '' ELSE dbo.MEMSBMMaintenance.RepairedByEnd END AS Expr1) AS [PM Done Request], 
                         dbo.MEMSBMMaintenance.PMConfirmGLOPReqDate AS [START DATE AND TIME],
                             (SELECT        CASE WHEN dbo.MEMSBMMaintenance.Turnover = 'PE' OR
                                                         dbo.MEMSBMMaintenance.Turnover = 'CC' OR
                                                         dbo.MEMSBMMaintenance.Turnover = 'VIS' THEN dbo.MEMSBMMaintenance.PMTurnOvertoPEDate ELSE dbo.MEMSBMMaintenance.EndOfRepair END AS Expr1) AS [END DATE AND TIME], 
                         dbo.MEMSBMMaintenance.PEConfirmPMTurnoverBy AS [PE Confirmed Request],
                             (SELECT        CASE WHEN dbo.MEMSBMMaintenance.Turnover = 'PE' OR
                                                         dbo.MEMSBMMaintenance.Turnover = 'CC' OR
                                                         dbo.MEMSBMMaintenance.Turnover = 'VIS' THEN dbo.MEMSBMMaintenance.RepairedByEnd ELSE '' END AS Expr1) AS [PE Done Request], 
                         dbo.MEMSBMMaintenance.PEConfirmPMTurnoverDate AS [PE START DATE AND TIME],
                             (SELECT        CASE WHEN dbo.MEMSBMMaintenance.Turnover = 'PE' OR
                                                         dbo.MEMSBMMaintenance.Turnover = 'CC' OR
                                                         dbo.MEMSBMMaintenance.Turnover = 'VIS' THEN dbo.MEMSBMMaintenance.EndOfRepair ELSE NULL END AS Expr1) AS [PE END DATE AND TIME], dbo.MEMSBMMaintenance.Why1, 
                         dbo.MEMSBMMaintenance.Why2, dbo.MEMSBMMaintenance.Why3, dbo.BMWhy.BMWhy AS Why4, dbo.MEMSBMMaintenance.Treatment1, dbo.MEMSBMMaintenance.Treatment2, dbo.MEMSBMMaintenance.Treatment3, 
                         dbo.MEMSBMMaintenance.Treatment4, dbo.MEMSBMMaintenance.Treatment5, dbo.MEMSBMMaintenance.Treatment6, dbo.MEMSBMMaintenance.Treatment7, dbo.MEMSBMMaintenance.Treatment8, 
                         dbo.MEMSBMMaintenance.Treatment9, dbo.MEMSBMMaintenance.Treatment10, dbo.MEMSBMMaintenance.Treatment11, dbo.MEMSBMMaintenance.Treatment12, dbo.MEMSBMMaintenance.Treatment13, 
                         dbo.MEMSBMMaintenance.Treatment14, dbo.MEMSBMMaintenance.MajorTreatment AS COUNTERMEASURE1, dbo.MEMSBMMaintenance.ConditionAfterAdj AS [AFTER CONDITION], 
                         dbo.MEMSBMMaintenance.ConditionAfterAdjMin AS [AFTER CONDITION QUANTITY1], dbo.MEMSBMMaintenance.ConditionAfterAdjMax AS [AFTER CONDITION QUANTITY2], 
                         dbo.MEMSBMMaintenance.UseDummyFrames AS [USING DUMMY PRODUCT], dbo.MEMSBMMaintenance.DummyIn AS [DUMMY IN], dbo.MEMSBMMaintenance.DummyOut AS [DUMMY OUT], 
                         dbo.MEMSBMMaintenance.DroppedWork AS [CHECKING DROPPED WORK], dbo.MEMSBMMaintenance.DroppedWorkBeforePM AS [DROPPED WORK BEFORE], 
                         dbo.MEMSBMMaintenance.DroppeWorkAfterPM AS [DROPPED WORK AFTER], dbo.MEMSBMMaintenance.ItemValueChecked AS [ITEM/VALUE CHECKED], 
                         dbo.MEMSBMMaintenance.ChangedValueChecked AS [CHANGED/CHECKED VALUE], dbo.MEMSBMMaintenance.ReqSATInsp AS [REQUEST FOR SAT INSPECTION], 
                         dbo.MEMSBMMaintenance.SATInspResult AS [SAT INSPECTION RESULT], dbo.MEMSBMMaintenance.SATInspResultStatus AS [SAT INSPECTION], 
                         dbo.MEMSBMMaintenance.CheckSensorColorNo AS [CHECK SENSOR COLOR AND NO.], dbo.MEMSBMMaintenance.CheckSensorReaction AS [CHECK SENSOR REACTION], 
                         dbo.MEMSBMMaintenance.MotionSafetyCoverSwitch AS [MOTION OF SAFETY COVER SWITCH], dbo.MEMSBMMaintenance.Check5SAfterPMWork AS [5S AFTER PM WORK], 
                         dbo.MEMSBMMaintenance.SelconReg AS [SELCON REGISTRATION], dbo.MEMSBMMaintenance.SelconRegValue AS [PREVIOUS ADJUSTMENT], dbo.MEMSBMMaintenance.InspectionReq AS [INSPECTION REQUEST], 
                         dbo.MEMSBMMaintenance.InspQtyNeeded AS [INSPECTION QTY NEEDED], dbo.MEMSBMMaintenance.CheckItem AS [CHECK ITEM1], dbo.MEMSBMMaintenance.CheckItem1 AS [CHECK ITEM2], 
                         dbo.MEMSBMMaintenance.CheckItem2 AS [CHECK ITEM3], dbo.MEMSBMMaintenance.CheckItem3 AS [CHECK ITEM4], dbo.MEMSBMMaintenance.RequesttoPD AS [REQUEST TO], 
                         dbo.MEMSBMMaintenance.PDConfirmation AS [PD CONFIRMATION], dbo.MEMSBMMaintenance.InspectionResults AS [INSPECTION RESULTS], dbo.MEMSBMMaintenance.PDTreatmentIncharge AS [PD TREATMENT/ INCHARGE],
                          dbo.MEMSBMMaintenance.ChangePartsName1 AS [PARTS NAME1], dbo.MEMSBMMaintenance.ChangePartsType1 AS TYPE1, dbo.MEMSBMMaintenance.ChangePartsQty1 AS QTY1, 
                         dbo.MEMSBMMaintenance.ChangePartsNewReworked1 AS [PARTS REPLACED1], dbo.MEMSBMMaintenance.ChangePartsDate1 AS [CHANGE PARTS DATE1], 
                         dbo.MEMSBMMaintenance.ChangePartsMonthDay1 AS [REMARKS/LIFE1], dbo.MEMSBMMaintenance.ChangePartsInsNewReworked1 AS [PARTS INSTALLED1], 
                         dbo.MEMSBMMaintenance.ChangePartsName2 AS [PARTS NAME2], dbo.MEMSBMMaintenance.ChangePartsType2 AS TYPE2, dbo.MEMSBMMaintenance.ChangePartsQty2 AS QTY2, 
                         dbo.MEMSBMMaintenance.ChangePartsNewReworked2 AS [PARTS REPLACED2], dbo.MEMSBMMaintenance.ChangePartsDate2 AS [CHANGE PARTS DATE2], 
                         dbo.MEMSBMMaintenance.ChangePartsMonthDay2 AS [REMARKS/LIFE2], dbo.MEMSBMMaintenance.ChangePartsInsNewReworked2 AS [PARTS INSTALLED2], 
                         dbo.MEMSBMMaintenance.ChangePartsName3 AS [PARTS NAME3], dbo.MEMSBMMaintenance.ChangePartsType3 AS TYPE3, dbo.MEMSBMMaintenance.ChangePartsQty3 AS QTY3, 
                         dbo.MEMSBMMaintenance.ChangePartsNewReworked3 AS [PARTS REPLACED3], dbo.MEMSBMMaintenance.ChangePartsDate3 AS [CHANGE PARTS DATE3], 
                         dbo.MEMSBMMaintenance.ChangePartsMonthDay3 AS [REMARKS/LIFE3], dbo.MEMSBMMaintenance.ChangePartsInsNewReworked3 AS [PARTS INSTALLED3], 
                         dbo.MEMSBMMaintenance.ChangePartsName4 AS [PARTS NAME4], dbo.MEMSBMMaintenance.ChangePartsType4 AS TYPE4, dbo.MEMSBMMaintenance.ChangePartsQty4 AS QTY4, 
                         dbo.MEMSBMMaintenance.ChangePartsNewReworked4 AS [PARTS REPLACED4], dbo.MEMSBMMaintenance.ChangePartsDate4 AS [CHANGE PARTS DATE4], 
                         dbo.MEMSBMMaintenance.ChangePartsMonthDay4 AS [REMARKS/LIFE4], dbo.MEMSBMMaintenance.ChangePartsInsNewReworked4 AS [PARTS INSTALLED4], 
                         dbo.MEMSBMMaintenance.ChangePartsName5 AS [PARTS NAME5], dbo.MEMSBMMaintenance.ChangePartsType5 AS TYPE5, dbo.MEMSBMMaintenance.ChangePartsQty5 AS QTY5, 
                         dbo.MEMSBMMaintenance.ChangePartsNewReworked5 AS [PARTS REPLACED5], dbo.MEMSBMMaintenance.ChangePartsDate5 AS [CHANGE PARTS DATE5], 
                         dbo.MEMSBMMaintenance.ChangePartsMonthDay5 AS [REMARKS/LIFE5], dbo.MEMSBMMaintenance.ChangePartsInsNewReworked5 AS [PARTS INSTALLED5], 
                         dbo.MEMSBMMaintenance.TypeofRequest AS [TYPE OF REQUEST], dbo.MEMSBMMaintenance.PMConfirmGLOPReason AS [INVALID REQUEST REASON], PMCategory_1.PMCategory AS [PM CATEGORY], 
                         BMContent_1.BMContent AS [BM CONTENT], BMCase_1.BMCase AS [CASE], BMMCUnit_1.BMMCUnit AS [MACHINE UNIT], BMPoint_1.BMPoint AS POSITION, BMWorkContent_1.BMWorkContent AS [WORK CONTENT], 
                         dbo.MEMSBMMaintenance.RequestItem AS [BM CAUSE], dbo.PREVMeasure.PREVMeasure AS [PREVENTIVE MEASURE], dbo.MEMSBMMaintenance.AccreditorRemarks AS [IN-CHARGE REMARKS], 
                         dbo.MEMSBMMaintenance.AccreditorPMReply AS [PM REMARKS], BMWhy_1.BM4M AS [4M ANALYSIS TYPE], BMWhy_1.BMWhy AS [4M ANALYSIS], dbo.PMCategory.PMCategory AS [IN-CHARGE PM CATEGORY], 
                         dbo.BMContent.BMContent AS [IN-CHARGE-CONTENT], dbo.BMCase.BMCase AS [IN-CHARGE CASE], dbo.BMMCUnit.BMMCUnit AS [IN-CHARGE MACHINE UNIT], dbo.BMPoint.BMPoint AS [IN-CHARGE POSITION], 
                         dbo.BMWorkContent.BMWorkContent AS [IN-CHARGE WORK CONTENT], BMWhy_2.BMWhy AS [IN-CHARGE CAUSE], dbo.PREVMeasure.PREVMeasure AS [IN-CHARGE PREVENTIVE MEASURE], 
                         dbo.MEMSBMMaintenance.AcredINSPN AS [PERIODIC RELATED BM], dbo.MEMSBMMaintenance.bmID, dbo.MEMSBMMaintenance.OccurrenceDate, dbo.MEMSBMMaintenance.BMStatusID, dbo.MEMSBMMaintenance.Process, 
                         dbo.MEMSBMMaintenance.Location,
                             (SELECT        CASE WHEN dbo.MEMSBMMaintenance.BMStatusID = '14' OR
                                                         dbo.MEMSBMMaintenance.BMStatusID = '11' OR
                                                         dbo.MEMSBMMaintenance.BMStatusID = '13' THEN CASE WHEN dbo.MEMSBMMaintenance.isnotquality2 = 'No' AND 
                                                         dbo.MEMSBMMaintenance.isnotquality3 = 'No' THEN 'Yes' ELSE 'No' END ELSE 'No' END AS IsQualityBM) AS 'IsQualityBM'
FROM            dbo.MEMSBMMaintenance LEFT OUTER JOIN
                         dbo.BMWhy ON dbo.MEMSBMMaintenance.Why4 = dbo.BMWhy.BMWhyID LEFT OUTER JOIN
                         dbo.BMWhy AS BMWhy_2 ON dbo.MEMSBMMaintenance.AcredBMCauseID = BMWhy_2.BMWhyID LEFT OUTER JOIN
                         dbo.BMWorkContent ON dbo.MEMSBMMaintenance.AcredBMWorkContentID = dbo.BMWorkContent.BMWorkContentID LEFT OUTER JOIN
                         dbo.BMPoint ON dbo.MEMSBMMaintenance.AcredBMPointID = dbo.BMPoint.BMPointID LEFT OUTER JOIN
                         dbo.BMMCUnit ON dbo.MEMSBMMaintenance.AcredBMMCUnitID = dbo.BMMCUnit.BMMCUnitID LEFT OUTER JOIN
                         dbo.BMCase ON dbo.MEMSBMMaintenance.AcredBMCaseID = dbo.BMCase.BMCaseID LEFT OUTER JOIN
                         dbo.PMCategory ON dbo.MEMSBMMaintenance.AcredPMCategoryID = dbo.PMCategory.PMCategoryID LEFT OUTER JOIN
                         dbo.BMWhy AS BMWhy_1 ON dbo.MEMSBMMaintenance.AcredBMCauseID = BMWhy_1.BMWhyID LEFT OUTER JOIN
                         dbo.PREVMeasure ON dbo.MEMSBMMaintenance.AcredPREVMeasureID = dbo.PREVMeasure.PREVMeasureID LEFT OUTER JOIN
                         dbo.BMWorkContent AS BMWorkContent_1 ON dbo.MEMSBMMaintenance.BMWorkContentID = BMWorkContent_1.BMWorkContentID LEFT OUTER JOIN
                         dbo.BMPoint AS BMPoint_1 ON dbo.MEMSBMMaintenance.BMPointID = BMPoint_1.BMPointID LEFT OUTER JOIN
                         dbo.BMCase AS BMCase_1 ON dbo.MEMSBMMaintenance.BMCaseID = BMCase_1.BMCaseID LEFT OUTER JOIN
                         dbo.BMMCUnit AS BMMCUnit_1 ON dbo.MEMSBMMaintenance.BMUnitID = BMMCUnit_1.BMMCUnitID LEFT OUTER JOIN
                         dbo.BMContent AS BMContent_1 ON dbo.MEMSBMMaintenance.BMContentID = BMContent_1.BMContentID LEFT OUTER JOIN
                         dbo.PMCategory AS PMCategory_1 ON dbo.MEMSBMMaintenance.PMCategoryID = PMCategory_1.PMCategoryID LEFT OUTER JOIN
                         dbo.BMContent ON dbo.MEMSBMMaintenance.AcredBMContentID = dbo.BMContent.BMContentID
GO
