CREATE VIEW [dbo].[WBFinalBMRawData]
AS
SELECT        dbo.WBBMMaintenance.MCNo AS [MC No], dbo.WBBMMaintenance.MCType AS [MC Type], dbo.WBBMMaintenance.PkgName AS Package, dbo.WBBMMaintenance.KanagataNo AS [Kanagata Number], 
