/****** Object:  View [dbo].[viewEDSPendingBM]    Script Date: 10/25/2026 4:57:09 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[viewEDSPendingBM]
AS
SELECT DISTINCT MCNo, BMStatusID
FROM            dbo.EDSBMMaintenance
WHERE        (BMStatusID IN ('1', '2', '3', '21', '5'))
GO
