/****** Object:  View [dbo].[viewDBBMPerMachine]    Script Date: 10/25/2026 4:57:09 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[viewDBBMPerMachine]
AS
SELECT DISTINCT FORMAT(EndOfRepair, 'MMM') AS MonthRequested, MONTH(EndOfRepair) AS myMOnth, YEAR(EndOfRepair) AS myYear,
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.DBBMMaintenance AS b
                               WHERE        (MONTH(EndOfRepair) = MONTH(a.EndOfRepair)) AND (YEAR(EndOfRepair) = YEAR(a.EndOfRepair)) AND (BMStatusID > 10 OR
                                                         BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30) AND (Location = 'LSI2-1F')) AS LSI21FBM,
                             (SELECT        ISNULL(macCount, 0) AS Expr1
                               FROM            dbo.viewBMRateCalc AS c
                               WHERE        (myMonth = MONTH(a.EndOfRepair)) AND (myYear = YEAR(a.EndOfRepair)) AND (ProcessMatch = 'DB') AND (Shift = '1ST') AND (LocationMatch = 'LSI2-1F')) AS LSI21FMC,
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.DBBMMaintenance AS b
                               WHERE        (MONTH(EndOfRepair) = MONTH(a.EndOfRepair)) AND (YEAR(EndOfRepair) = YEAR(a.EndOfRepair)) AND (BMStatusID > 10 OR
                                                         BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30) AND (Location = 'LSI2-2F')) AS LSI22FBM,
                             (SELECT        ISNULL(macCount, 0) AS Expr1
                               FROM            dbo.viewBMRateCalc AS c
                               WHERE        (myMonth = MONTH(a.EndOfRepair)) AND (myYear = YEAR(a.EndOfRepair)) AND (ProcessMatch = 'DB') AND (Shift = '1ST') AND (LocationMatch = 'LSI2-2F')) AS LSI22FMC,
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.DBBMMaintenance AS b
                               WHERE        (MONTH(EndOfRepair) = MONTH(a.EndOfRepair)) AND (YEAR(EndOfRepair) = YEAR(a.EndOfRepair)) AND (BMStatusID > 10 OR
                                                         BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30) AND (Location = 'LSI2-3F')) AS LSI23FBM,
                             (SELECT        ISNULL(macCount, 0) AS Expr1
                               FROM            dbo.viewBMRateCalc AS c
                               WHERE        (myMonth = MONTH(a.EndOfRepair)) AND (myYear = YEAR(a.EndOfRepair)) AND (ProcessMatch = 'DB') AND (Shift = '1ST') AND (LocationMatch = 'LSI2-3F')) AS LSI23FMC,
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.DBBMMaintenance AS b
                               WHERE        (MONTH(EndOfRepair) = MONTH(a.EndOfRepair)) AND (YEAR(EndOfRepair) = YEAR(a.EndOfRepair)) AND (BMStatusID > 10 OR
                                                         BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30) AND (Location = 'LSI1-1F')) AS LSI11FBM,
                             (SELECT        ISNULL(macCount, 0) AS Expr1
                               FROM            dbo.viewBMRateCalc AS c
                               WHERE        (myMonth = MONTH(a.EndOfRepair)) AND (myYear = YEAR(a.EndOfRepair)) AND (ProcessMatch = 'DB') AND (Shift = '1ST') AND (LocationMatch = 'LSI1-1F')) AS LSI11FMC,
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.DBBMMaintenance AS b
                               WHERE        (MONTH(EndOfRepair) = MONTH(a.EndOfRepair)) AND (YEAR(EndOfRepair) = YEAR(a.EndOfRepair)) AND (BMStatusID > 10 OR
                                                         BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30) AND (Location = 'LSI1-2F')) AS LSI12FBM,
                             (SELECT        ISNULL(macCount, 0) AS Expr1
                               FROM            dbo.viewBMRateCalc AS c
                               WHERE        (myMonth = MONTH(a.EndOfRepair)) AND (myYear = YEAR(a.EndOfRepair)) AND (ProcessMatch = 'DB') AND (Shift = '1ST') AND (LocationMatch = 'LSI1-2F')) AS LSI12FMC,
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.DBBMMaintenance AS b
                               WHERE        (MONTH(EndOfRepair) = MONTH(a.EndOfRepair)) AND (YEAR(EndOfRepair) = YEAR(a.EndOfRepair)) AND (BMStatusID > 10 OR
                                                         BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30) AND (Location = 'LSI3-2F')) AS LSI32FBM,
                             (SELECT        ISNULL(macCount, 0) AS Expr1
                               FROM            dbo.viewBMRateCalc AS c
                               WHERE        (myMonth = MONTH(a.EndOfRepair)) AND (myYear = YEAR(a.EndOfRepair)) AND (ProcessMatch = 'DB') AND (Shift = '1ST') AND (LocationMatch = 'LSI3-2F')) AS LSI32FMC
FROM            dbo.DBBMMaintenance AS a
WHERE        (BMStatusID > 10 OR
                         BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30) AND (EndOfRepair IS NOT NULL)
GROUP BY MONTH(EndOfRepair), EndOfRepair
GO
