       --                  dbo.DBBMMaintenance.CheckItem3, dbo.DBBMMaintenance.OPBMUnitID, dbo.DBBMMaintenance.Process, dbo.DBBMMaintenance.Location, dbo.DBBMMaintenance.ConBeforeAfterAdjValue6, 
       --                  dbo.DBBMMaintenance.ConBeforeAfterAdjValue5, dbo.DBBMMaintenance.ConBeforeAfterAdjValue4, dbo.DBBMMaintenance.ConBeforeAfterAdjValue3, dbo.DBBMMaintenance.ConBeforeAfterAdjValue2, 
       --                  dbo.DBBMMaintenance.ConBeforeAfterAdjValue1, dbo.DBBMMaintenance.ConBeforeAfterAdjItem6, dbo.DBBMMaintenance.ConBeforeAfterAdjItem5, dbo.DBBMMaintenance.ConBeforeAfterAdjItem4, 
       --                  dbo.DBBMMaintenance.ConBeforeAfterAdjItem3, dbo.DBBMMaintenance.ConBeforeAfterAdjItem2, dbo.DBBMMaintenance.ConBeforeAfterAdjItem1, dbo.DBBMMaintenance.RPMRelAdj, dbo.DBBMMaintenance.RPMStandard, 
       --                  dbo.DBBMMaintenance.RPMBefore, dbo.DBBMMaintenance.RPMAfter, dbo.DBBMMaintenance.CPData, dbo.DBBMMaintenance.QCData, dbo.DBBMMaintenance.BMINSPN, dbo.DBBMMaintenance.BMCategoryID, 
       --                  dbo.DBBMMaintenance.isNotQuality1, dbo.DBBMMaintenance.isNotQuality2, dbo.DBBMMaintenance.isNotQuality3, dbo.DBBMMaintenance.KanagataNo, dbo.DBBMMaintenance.TypeofRequest, 
       --                  dbo.DBBMMaintenance.SubChuckUsed, dbo.DBBMMaintenance.SubChuckReplaced, dbo.DBBMMaintenance.PincettePadUsed, dbo.DBBMMaintenance.PincettePadReplaced, dbo.DBBMMaintenance.ChuckTopUsed, 
       --                  dbo.DBBMMaintenance.ChuckTopReplaced, dbo.DBBMMaintenance.WaferNo, dbo.DBBMMaintenance.DefectiveUnit, dbo.DBBMMaintenance.DefectivePoint, dbo.DBBMMaintenance.LineLoc, dbo.DBBMMaintenance.CC1, 
       --                  dbo.DBBMMaintenance.CC2, dbo.DBBMMaintenance.CC3, dbo.DBBMMaintenance.CC4, dbo.DBBMMaintenance.CheckCondition, dbo.DBBMMaintenance.CC5, dbo.DBBMMaintenance.PrepofDummyFrames, 
       --                  dbo.DBBMMaintenance.PcsUsed, dbo.DBBMMaintenance.PcsScrapped, dbo.DBBMMaintenance.Freq1, dbo.DBBMMaintenance.Freq2, dbo.DBBMMaintenance.AbnormalityTreatment, dbo.DBBMMaintenance.BacksideAdj, 
       --                  dbo.DBBMMaintenance.MCInspRel, dbo.DBBMMaintenance.OccMode, dbo.DBBMMaintenance.ReqTo, dbo.DBBMMaintenance.GLConf, dbo.DBBMMaintenance.Result, dbo.DBBMMaintenance.Rate, 
       --                  dbo.DBBMMaintenance.FourSConfAfterPM, dbo.DBBMMaintenance.StartPM1, dbo.DBBMMaintenance.StartPM2, dbo.DBBMMaintenance.EndPM1, dbo.DBBMMaintenance.EndPM2, dbo.DBBMMaintenance.PMMiss, 
						 --dbo.DBBMMaintenance.LastBMStop, dbo.DBBMMaintenance.LastBMContinue, datediff(MINUTE, dbo.DBBMMaintenance.PEConfirmPMTurnoverDate,dbo.DBBMMaintenance.TimeTurnover ) as PEWaitingTime, datediff(MINUTE,dbo.DBBMMaintenance.timeturnover,dbo.DBBMMaintenance.EndofRepair) as PERepairTime, year(dbo.DBBMMaintenance.pmturnovertopedate) as BMYear, month(dbo.DBBMMaintenance.pmturnovertopedate) as BMMonth, day(dbo.DBBMMaintenance.pmturnovertopedate) as BMDay
FROM            dbo.DBBMMaintenance LEFT OUTER JOIN
                         dbo.SubProcess ON dbo.DBBMMaintenance.SubProcessID = dbo.SubProcess.SubProcessID LEFT OUTER JOIN
                         dbo.BMStatus ON dbo.DBBMMaintenance.BMStatusID = dbo.BMStatus.BMStatusID LEFT OUTER JOIN
                         dbo.PMCategory ON dbo.DBBMMaintenance.PMCategoryID = dbo.PMCategory.PMCategoryID LEFT OUTER JOIN
                         dbo.BMCase ON dbo.DBBMMaintenance.BMCaseID = dbo.BMCase.BMCaseID LEFT OUTER JOIN
                         dbo.MCList ON dbo.DBBMMaintenance.MCNo = dbo.MCList.MCNo 
	   --LEFT OUTER JOIN
       --                  dbo.I4M ON dbo.DBBMMaintenance.I4MID = dbo.I4M.I4MID LEFT OUTER JOIN
       --                  dbo.pm_EquipInsData ON dbo.DBBMMaintenance.bmID = dbo.pm_EquipInsData.bmID

WHERE dbo.DBBMMaintenance.bmsTATUSID<>30 AND dbo.DBBMMaintenance.Turnover= 'CC' AND dbo.DBBMMaintenance.PMCategoryID=1


