	LEFT OUTER JOIN dbo.SubProcess sp ON s.SubProcessID = sp.SubProcessID
    LEFT OUTER JOIN dbo.PMCategory pc ON e.BMCategoryID = pc.PMCategoryID
    LEFT OUTER JOIN dbo.PMCategory pc2 ON e.AcredPMCategoryID = pc2.PMCategoryID
    LEFT OUTER JOIN dbo.BMWhy w ON e.bm_id = w.BMWhyID
    LEFT OUTER JOIN dbo.BMCase c ON e.AcredBMCaseID = c.BMCaseID
    LEFT OUTER JOIN dbo.BMSpecialDevice sd ON s.DeviceName = sd.SpecialDevName
    LEFT OUTER JOIN dbo.BMCaseDefectMode cd ON s.RequestItem = cd.BMCaseDefectModeName
WHERE
    e.Process = 'DC' and (s.turnover = 'PE' or s.turnover = 'PES') 

