CREATE VIEW [dbo].[DCFinalBMRawData]
AS
SELECT        dbo.DCBMMaintenance.MCNo AS [MC No], dbo.DCBMMaintenance.MCType AS [MC Type], dbo.DCBMMaintenance.PkgName AS Package, dbo.DCBMMaintenance.KanagataNo AS [Kanagata Number], 
                         dbo.DCBMMaintenance.LOTNo AS [Lot Number], dbo.DCBMMaintenance.DeviceName AS [Device Name],
                             (SELECT        CASE WHEN dbo.DCBMMaintenance.BMStatusID = 14 THEN PMCategory.PMCategory ELSE PMCategory_1.PMCategory END AS PMCategory) AS Classification, 
                         dbo.DCBMMaintenance.NGDetectionCircumtances AS [NG Detection Circumstance], dbo.DCBMMaintenance.RequestItem AS [Case Name], dbo.DCBMMaintenance.RequestContent AS [Request Content], 
                         dbo.DCBMMaintenance.Situation AS Condition, dbo.DCBMMaintenance.OccurrenceFreq AS [Occurrence Rate Before Condition], dbo.DCBMMaintenance.OccurrenceFreqQuantity AS Quantity1, 
                         dbo.DCBMMaintenance.OccurrenceFreqLotFrame AS Quantity2, dbo.DCBMMaintenance.AQI, dbo.DCBMMaintenance.OccurrenceDate AS [Request Date and Time], dbo.DCBMMaintenance.RequestedBy AS Issuer, 
                         dbo.DCBMMaintenance.GLConfirmOPReqBy AS GL, dbo.DCBMMaintenance.GLConfirmOPReqDate AS [GL Confirmed Date], dbo.DCBMMaintenance.PMConfirmGLOPReqBy AS [PM Confirmed Request],
                             (SELECT        CASE WHEN dbo.DCBMMaintenance.Turnover = 'PE' OR
                                                         dbo.DCBMMaintenance.Turnover = 'CC' OR
                                                         dbo.DCBMMaintenance.Turnover = 'VIS' THEN '' ELSE dbo.DCBMMaintenance.RepairedByEnd END AS Expr1) AS [PM Done Request], 
                         dbo.DCBMMaintenance.PMConfirmGLOPReqDate AS [START DATE AND TIME],
                             (SELECT        CASE WHEN dbo.DCBMMaintenance.Turnover = 'PE' OR
                                                         dbo.DCBMMaintenance.Turnover = 'CC' OR
                                                         dbo.DCBMMaintenance.Turnover = 'VIS' THEN dbo.DCBMMaintenance.PMTurnOvertoPEDate ELSE dbo.DCBMMaintenance.EndOfRepair END AS Expr1) AS [END DATE AND TIME], 
                         dbo.DCBMMaintenance.PEConfirmPMTurnoverBy AS [PE Confirmed Request],
                             (SELECT        CASE WHEN dbo.DCBMMaintenance.Turnover = 'PE' OR
                                                         dbo.DCBMMaintenance.Turnover = 'CC' OR
                                                         dbo.DCBMMaintenance.Turnover = 'VIS' THEN dbo.DCBMMaintenance.RepairedByEnd ELSE '' END AS Expr1) AS [PE Done Request], 
                         dbo.DCBMMaintenance.PEConfirmPMTurnoverDate AS [PE START DATE AND TIME],
                             (SELECT        CASE WHEN dbo.DCBMMaintenance.Turnover = 'PE' OR
                                                         dbo.DCBMMaintenance.Turnover = 'CC' OR
                                                         dbo.DCBMMaintenance.Turnover = 'VIS' THEN dbo.DCBMMaintenance.EndOfRepair ELSE NULL END AS Expr1) AS [PE END DATE AND TIME], dbo.DCBMMaintenance.Why1, dbo.DCBMMaintenance.Why2, 
                         dbo.DCBMMaintenance.Why3, dbo.BMWhy.BMWhy AS Why4, dbo.DCBMMaintenance.Treatment1, dbo.DCBMMaintenance.Treatment2, dbo.DCBMMaintenance.Treatment3, dbo.DCBMMaintenance.Treatment4, 
                         dbo.DCBMMaintenance.Treatment5, dbo.DCBMMaintenance.Treatment6, dbo.DCBMMaintenance.Treatment7, dbo.DCBMMaintenance.Treatment8, dbo.DCBMMaintenance.Treatment9, dbo.DCBMMaintenance.Treatment10, 
                         dbo.DCBMMaintenance.Treatment11, dbo.DCBMMaintenance.Treatment12, dbo.DCBMMaintenance.Treatment13, dbo.DCBMMaintenance.Treatment14, dbo.DCBMMaintenance.MajorTreatment AS COUNTERMEASURE1, 
                         dbo.DCBMMaintenance.ConditionAfterAdj AS [AFTER CONDITION], dbo.DCBMMaintenance.ConditionAfterAdjMin AS [AFTER CONDITION QUANTITY1], 
                         dbo.DCBMMaintenance.ConditionAfterAdjMax AS [AFTER CONDITION QUANTITY2], dbo.DCBMMaintenance.UseDummyFrames AS [USING DUMMY PRODUCT], dbo.DCBMMaintenance.DummyIn AS [DUMMY IN], 
                         dbo.DCBMMaintenance.DummyOut AS [DUMMY OUT], dbo.DCBMMaintenance.DroppedWork AS [CHECKING DROPPED WORK], dbo.DCBMMaintenance.DroppedWorkBeforePM AS [DROPPED WORK BEFORE], 
                         dbo.DCBMMaintenance.DroppeWorkAfterPM AS [DROPPED WORK AFTER], dbo.DCBMMaintenance.ItemValueChecked AS [ITEM/VALUE CHECKED], 
                         dbo.DCBMMaintenance.ChangedValueChecked AS [CHANGED/CHECKED VALUE], dbo.DCBMMaintenance.ReqSATInsp AS [REQUEST FOR SAT INSPECTION], dbo.DCBMMaintenance.SATInspResult AS [SAT INSPECTION RESULT],
                          dbo.DCBMMaintenance.SATInspResultStatus AS [SAT INSPECTION], dbo.DCBMMaintenance.CheckSensorColorNo AS [CHECK SENSOR COLOR AND NO.], 
                         dbo.DCBMMaintenance.CheckSensorReaction AS [CHECK SENSOR REACTION], dbo.DCBMMaintenance.MotionSafetyCoverSwitch AS [MOTION OF SAFETY COVER SWITCH], 
                         dbo.DCBMMaintenance.Check5SAfterPMWork AS [5S AFTER PM WORK], dbo.DCBMMaintenance.SelconReg AS [SELCON REGISTRATION], dbo.DCBMMaintenance.SelconRegValue AS [PREVIOUS ADJUSTMENT], 
                         dbo.DCBMMaintenance.InspectionReq AS [INSPECTION REQUEST], dbo.DCBMMaintenance.InspQtyNeeded AS [INSPECTION QTY NEEDED], dbo.DCBMMaintenance.CheckItem AS [CHECK ITEM1], 
                         dbo.DCBMMaintenance.CheckItem1 AS [CHECK ITEM2], dbo.DCBMMaintenance.CheckItem2 AS [CHECK ITEM3], dbo.DCBMMaintenance.CheckItem3 AS [CHECK ITEM4], dbo.DCBMMaintenance.RequesttoPD AS [REQUEST TO], 
                         dbo.DCBMMaintenance.PDConfirmation AS [PD CONFIRMATION], dbo.DCBMMaintenance.InspectionResults AS [INSPECTION RESULTS], dbo.DCBMMaintenance.PDTreatmentIncharge AS [PD TREATMENT/ INCHARGE], 
                         dbo.DCBMMaintenance.ChangePartsName1 AS [PARTS NAME1], dbo.DCBMMaintenance.ChangePartsType1 AS TYPE1, dbo.DCBMMaintenance.ChangePartsQty1 AS QTY1, 
                         dbo.DCBMMaintenance.ChangePartsNewReworked1 AS [PARTS REPLACED1], dbo.DCBMMaintenance.ChangePartsDate1 AS [CHANGE PARTS DATE1], dbo.DCBMMaintenance.ChangePartsMonthDay1 AS [REMARKS/LIFE1], 
                         dbo.DCBMMaintenance.ChangePartsInsNewReworked1 AS [PARTS INSTALLED1], dbo.DCBMMaintenance.ChangePartsName2 AS [PARTS NAME2], dbo.DCBMMaintenance.ChangePartsType2 AS TYPE2, 
                         dbo.DCBMMaintenance.ChangePartsQty2 AS QTY2, dbo.DCBMMaintenance.ChangePartsNewReworked2 AS [PARTS REPLACED2], dbo.DCBMMaintenance.ChangePartsDate2 AS [CHANGE PARTS DATE2], 
                         dbo.DCBMMaintenance.ChangePartsMonthDay2 AS [REMARKS/LIFE2], dbo.DCBMMaintenance.ChangePartsInsNewReworked2 AS [PARTS INSTALLED2], dbo.DCBMMaintenance.ChangePartsName3 AS [PARTS NAME3], 
                         dbo.DCBMMaintenance.ChangePartsType3 AS TYPE3, dbo.DCBMMaintenance.ChangePartsQty3 AS QTY3, dbo.DCBMMaintenance.ChangePartsNewReworked3 AS [PARTS REPLACED3], 
                         dbo.DCBMMaintenance.ChangePartsDate3 AS [CHANGE PARTS DATE3], dbo.DCBMMaintenance.ChangePartsMonthDay3 AS [REMARKS/LIFE3], dbo.DCBMMaintenance.ChangePartsInsNewReworked3 AS [PARTS INSTALLED3], 
                         dbo.DCBMMaintenance.ChangePartsName4 AS [PARTS NAME4], dbo.DCBMMaintenance.ChangePartsType4 AS TYPE4, dbo.DCBMMaintenance.ChangePartsQty4 AS QTY4, 
                         dbo.DCBMMaintenance.ChangePartsNewReworked4 AS [PARTS REPLACED4], dbo.DCBMMaintenance.ChangePartsDate4 AS [CHANGE PARTS DATE4], dbo.DCBMMaintenance.ChangePartsMonthDay4 AS [REMARKS/LIFE4], 
                         dbo.DCBMMaintenance.ChangePartsInsNewReworked4 AS [PARTS INSTALLED4], dbo.DCBMMaintenance.ChangePartsName5 AS [PARTS NAME5], dbo.DCBMMaintenance.ChangePartsType5 AS TYPE5, 
                         dbo.DCBMMaintenance.ChangePartsQty5 AS QTY5, dbo.DCBMMaintenance.ChangePartsNewReworked5 AS [PARTS REPLACED5], dbo.DCBMMaintenance.ChangePartsDate5 AS [CHANGE PARTS DATE5], 
                         dbo.DCBMMaintenance.ChangePartsMonthDay5 AS [REMARKS/LIFE5], dbo.DCBMMaintenance.ChangePartsInsNewReworked5 AS [PARTS INSTALLED5], dbo.DCBMMaintenance.TypeofRequest AS [TYPE OF REQUEST], 
                         dbo.DCBMMaintenance.PMConfirmGLOPReason AS [INVALID REQUEST REASON], PMCategory_1.PMCategory AS [PM CATEGORY], BMContent_1.BMContent AS [BM CONTENT], BMCase_1.BMCase AS [CASE], 
                         BMMCUnit_1.BMMCUnit AS [MACHINE UNIT], BMPoint_1.BMPoint AS POSITION, BMWorkContent_1.BMWorkContent AS [WORK CONTENT], dbo.DCBMMaintenance.RequestItem AS [BM CAUSE], 
                         dbo.PREVMeasure.PREVMeasure AS [PREVENTIVE MEASURE], dbo.DCBMMaintenance.AccreditorRemarks AS [IN-CHARGE REMARKS], dbo.DCBMMaintenance.AccreditorPMReply AS [PM REMARKS], 
                         BMWhy_1.BM4M AS [4M ANALYSIS TYPE], BMWhy_1.BMWhy AS [4M ANALYSIS], dbo.PMCategory.PMCategory AS [IN-CHARGE PM CATEGORY], dbo.BMContent.BMContent AS [IN-CHARGE-CONTENT], 
                         dbo.BMCase.BMCase AS [IN-CHARGE CASE], dbo.BMMCUnit.BMMCUnit AS [IN-CHARGE MACHINE UNIT], dbo.BMPoint.BMPoint AS [IN-CHARGE POSITION], 
                         dbo.BMWorkContent.BMWorkContent AS [IN-CHARGE WORK CONTENT], BMWhy_2.BMWhy AS [IN-CHARGE CAUSE], dbo.PREVMeasure.PREVMeasure AS [IN-CHARGE PREVENTIVE MEASURE], 
                         dbo.DCBMMaintenance.AcredINSPN AS [PERIODIC RELATED BM], dbo.DCBMMaintenance.OccurrenceDate, dbo.DCBMMaintenance.BMStatusID, dbo.DCBMMaintenance.bmID, dbo.DCBMMaintenance.Process, 
                         dbo.DCBMMaintenance.Location,
                             (SELECT        CASE WHEN dbo.DCBMMaintenance.BMStatusID = '14' OR
                                                         dbo.DCBMMaintenance.BMStatusID = '11' OR
                                                         dbo.DCBMMaintenance.BMStatusID = '13' THEN CASE WHEN dbo.DCBMMaintenance.isnotquality2 = 'No' AND 
                                                         dbo.DCBMMaintenance.isnotquality3 = 'No' THEN 'Yes' ELSE 'No' END ELSE 'No' END AS IsQualityBM) AS IsQualityBM, dbo.DCBMMaintenance.EndBM AS AccreditorTimeStamp
FROM            dbo.DCBMMaintenance LEFT OUTER JOIN
                         dbo.BMWhy ON dbo.DCBMMaintenance.Why4 = dbo.BMWhy.BMWhyID LEFT OUTER JOIN
                         dbo.BMWhy AS BMWhy_2 ON dbo.DCBMMaintenance.AcredBMCauseID = BMWhy_2.BMWhyID LEFT OUTER JOIN
                         dbo.BMWorkContent ON dbo.DCBMMaintenance.AcredBMWorkContentID = dbo.BMWorkContent.BMWorkContentID LEFT OUTER JOIN
                         dbo.BMPoint ON dbo.DCBMMaintenance.AcredBMPointID = dbo.BMPoint.BMPointID LEFT OUTER JOIN
                         dbo.BMMCUnit ON dbo.DCBMMaintenance.AcredBMMCUnitID = dbo.BMMCUnit.BMMCUnitID LEFT OUTER JOIN
                         dbo.BMCase ON dbo.DCBMMaintenance.AcredBMCaseID = dbo.BMCase.BMCaseID LEFT OUTER JOIN
                         dbo.PMCategory ON dbo.DCBMMaintenance.AcredPMCategoryID = dbo.PMCategory.PMCategoryID LEFT OUTER JOIN
                         dbo.BMWhy AS BMWhy_1 ON dbo.DCBMMaintenance.AcredBMCauseID = BMWhy_1.BMWhyID LEFT OUTER JOIN
                         dbo.PREVMeasure ON dbo.DCBMMaintenance.AcredPREVMeasureID = dbo.PREVMeasure.PREVMeasureID LEFT OUTER JOIN
                         dbo.BMWorkContent AS BMWorkContent_1 ON dbo.DCBMMaintenance.BMWorkContentID = BMWorkContent_1.BMWorkContentID LEFT OUTER JOIN
                         dbo.BMPoint AS BMPoint_1 ON dbo.DCBMMaintenance.BMPointID = BMPoint_1.BMPointID LEFT OUTER JOIN
                         dbo.BMCase AS BMCase_1 ON dbo.DCBMMaintenance.BMCaseID = BMCase_1.BMCaseID LEFT OUTER JOIN
                         dbo.BMMCUnit AS BMMCUnit_1 ON dbo.DCBMMaintenance.BMUnitID = BMMCUnit_1.BMMCUnitID LEFT OUTER JOIN
                         dbo.BMContent AS BMContent_1 ON dbo.DCBMMaintenance.BMContentID = BMContent_1.BMContentID LEFT OUTER JOIN
                         dbo.PMCategory AS PMCategory_1 ON dbo.DCBMMaintenance.PMCategoryID = PMCategory_1.PMCategoryID LEFT OUTER JOIN
                         dbo.BMContent ON dbo.DCBMMaintenance.AcredBMContentID = dbo.BMContent.BMContentID
GO
/****** Object:  View [dbo].[viewFTBMPerMachine]    Script Date: 10/25/2026 4:57:09 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[viewFTBMPerMachine]
AS
SELECT DISTINCT FORMAT(EndOfRepair, 'MMM') AS MonthRequested, MONTH(EndOfRepair) AS myMOnth, YEAR(EndOfRepair) AS myYear,
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.FTBMMaintenance AS b
                               WHERE        (MONTH(EndOfRepair) = MONTH(a.EndOfRepair)) AND (YEAR(EndOfRepair) = YEAR(a.EndOfRepair)) AND (BMStatusID > 10 OR
                                                         BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30) AND (Location = 'LSI2-1F')) AS LSI21FBM,
                             (SELECT        ISNULL(macCount, 0) AS Expr1
                               FROM            dbo.viewBMRateCalc AS c
                               WHERE        (myMonth = MONTH(a.EndOfRepair)) AND (myYear = YEAR(a.EndOfRepair)) AND (ProcessMatch = 'FT') AND (Shift = '1ST') AND (LocationMatch = 'LSI2-1F')) AS LSI21FMC,
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.FTBMMaintenance AS b
                               WHERE        (MONTH(EndOfRepair) = MONTH(a.EndOfRepair)) AND (YEAR(EndOfRepair) = YEAR(a.EndOfRepair)) AND (BMStatusID > 10 OR
                                                         BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30) AND (Location = 'LSI2-2F')) AS LSI22FBM,
                             (SELECT        ISNULL(macCount, 0) AS Expr1
                               FROM            dbo.viewBMRateCalc AS c
                               WHERE        (myMonth = MONTH(a.EndOfRepair)) AND (myYear = YEAR(a.EndOfRepair)) AND (ProcessMatch = 'FT') AND (Shift = '1ST') AND (LocationMatch = 'LSI2-2F')) AS LSI22FMC,
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.FTBMMaintenance AS b
                               WHERE        (MONTH(EndOfRepair) = MONTH(a.EndOfRepair)) AND (YEAR(EndOfRepair) = YEAR(a.EndOfRepair)) AND (BMStatusID > 10 OR
                                                         BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30) AND (Location = 'LSI2-3F')) AS LSI23FBM,
                             (SELECT        ISNULL(macCount, 0) AS Expr1
                               FROM            dbo.viewBMRateCalc AS c
                               WHERE        (myMonth = MONTH(a.EndOfRepair)) AND (myYear = YEAR(a.EndOfRepair)) AND (ProcessMatch = 'FT') AND (Shift = '1ST') AND (LocationMatch = 'LSI2-3F')) AS LSI23FMC,
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.FTBMMaintenance AS b
                               WHERE        (MONTH(EndOfRepair) = MONTH(a.EndOfRepair)) AND (YEAR(EndOfRepair) = YEAR(a.EndOfRepair)) AND (BMStatusID > 10 OR
                                                         BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30) AND (Location = 'LSI1-1F')) AS LSI11FBM,
                             (SELECT        ISNULL(macCount, 0) AS Expr1
                               FROM            dbo.viewBMRateCalc AS c
                               WHERE        (myMonth = MONTH(a.EndOfRepair)) AND (myYear = YEAR(a.EndOfRepair)) AND (ProcessMatch = 'FT') AND (Shift = '1ST') AND (LocationMatch = 'LSI1-1F')) AS LSI11FMC,
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.FTBMMaintenance AS b
                               WHERE        (MONTH(EndOfRepair) = MONTH(a.EndOfRepair)) AND (YEAR(EndOfRepair) = YEAR(a.EndOfRepair)) AND (BMStatusID > 10 OR
                                                         BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30) AND (Location = 'LSI1-2F')) AS LSI12FBM,
                             (SELECT        ISNULL(macCount, 0) AS Expr1
                               FROM            dbo.viewBMRateCalc AS c
                               WHERE        (myMonth = MONTH(a.EndOfRepair)) AND (myYear = YEAR(a.EndOfRepair)) AND (ProcessMatch = 'FT') AND (Shift = '1ST') AND (LocationMatch = 'LSI1-2F')) AS LSI12FMC,
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.FTBMMaintenance AS b
                               WHERE        (MONTH(EndOfRepair) = MONTH(a.EndOfRepair)) AND (YEAR(EndOfRepair) = YEAR(a.EndOfRepair)) AND (BMStatusID > 10 OR
                                                         BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30) AND (Location = 'LSI3-2F')) AS LSI32FBM,
                             (SELECT        ISNULL(macCount, 0) AS Expr1
                               FROM            dbo.viewBMRateCalc AS c
                               WHERE        (myMonth = MONTH(a.EndOfRepair)) AND (myYear = YEAR(a.EndOfRepair)) AND (ProcessMatch = 'FT') AND (Shift = '1ST') AND (LocationMatch = 'LSI3-2F')) AS LSI32FMC
FROM            dbo.FTBMMaintenance AS a
WHERE        (BMStatusID > 10 OR
                         BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30) AND (EndOfRepair IS NOT NULL)
GROUP BY MONTH(EndOfRepair), EndOfRepair
GO
