	s.I4MID,
	e.PMAndon,
	e.Remarks AS PMRemarks,
	s.Void,
	s.GLWTime1,
	s.GLConfirmation,
	s.GLCheckedBy,
	s.RepairWTime,
	s. EEEWaitingEnd AS StartOfRepair,
	s.RepairedByStart,
	s.RepairTime,
	e.EndOfRepair,
    e.RepairedByEnd,
	s.MonitoringWTime,
	s.StartOfMonitoring,
	s.StartMonitoringBy,
	s.MonitoringTime,
	s.EndOfMonitoring,
	s.EndMonitoringBy,
	s.GLWTime2,
	s.GLRepairConfirmation,
	s.GLAndon2,
	s.GLRestartedBy,
	e.EndBM,
    e.EndBMBy,
	s.ApprovedDate,
	s.ApprovedBy,
	s.TotalPMTime,
	s.TotalStopTime,
	s.TurnoverPM,
	s.TimeTurnover,
	s.Turnover,
	s.CurrentPM,
	s.TPMSaved,
	bs.BMStatus,
	sp.SubProcess,
	pc.PMCategory, 
	s.PMConfirmGLOPReq,
	e.PMConfirmGLOPReqBy,
	e.PMConfirmGLOPReqDate,
	e.AccreditorPMReply,
	e.AccreditorRemarks,
	s.AccreditorI4MID,
	s.PMConfirmGLOPReason,
	s.AccreditorReturnToPMBy,
	s.AccreditorRetunToPMDate,
	s.PMTurnOvertoPEBy,
	s.PMTurnOvertoPEDate,
	s.PEConfirmPMTurnoverReq,
	s.PEConfirmPMTurnoverReason,
	s.PEConfirmPMTurnoverBy,
	s.PEConfirmPMTurnoverDate,
	s.PETurnOverPMBy,
	s.PETurnOverPMDate,
	 s.Process,
    s.Location, 
	e.OPBMUnitID,
	sd.SpecialDevName,
	cd.BMCaseDefectModeName,
	pc2.PMCategory AS AccPMCategory,
    
	s.isnotquality2, 
    s.isnotquality3, 
	s.EEEWaitingEnd, 
    e.Akapen1,
    e.Akapen2,
    e.Akapen3,
    e.Aopen1,
    e.Aopen2,
    e.Aopen3
   
    
    
     -- For Accredited PM Category
    --w.BMWhy AS BMWhy4,
    --c.BMCase,
    
    
FROM
    dbo.EEEBMMaintenance e
    LEFT OUTER JOIN dbo.EDSBMMaintenance s ON e.bm_id = s.bmID
    LEFT OUTER JOIN dbo.BMStatus bs ON e.BMStatusID = bs.BMStatusID
	LEFT OUTER JOIN dbo.SubProcess sp ON s.SubProcessID = sp.SubProcessID
    LEFT OUTER JOIN dbo.PMCategory pc ON e.BMCategoryID = pc.PMCategoryID
    LEFT OUTER JOIN dbo.PMCategory pc2 ON e.AcredPMCategoryID = pc2.PMCategoryID
    LEFT OUTER JOIN dbo.BMWhy w ON e.bm_id = w.BMWhyID
    LEFT OUTER JOIN dbo.BMCase c ON e.AcredBMCaseID = c.BMCaseID
    LEFT OUTER JOIN dbo.BMSpecialDevice sd ON s.DeviceName = sd.SpecialDevName
    LEFT OUTER JOIN dbo.BMCaseDefectMode cd ON s.RequestItem = cd.BMCaseDefectModeName
WHERE
    e.Process = 'EDS' and (s.turnover = 'PE' or s.turnover = 'PES') 

	
