                         dbo.DCBMMaintenance.PEConfirmPMTurnoverReq, dbo.DCBMMaintenance.PEConfirmPMTurnoverReason, dbo.DCBMMaintenance.PEConfirmPMTurnoverBy, dbo.DCBMMaintenance.PEConfirmPMTurnoverDate, 
                         dbo.DCBMMaintenance.PETurnOverPMBy, dbo.DCBMMaintenance.PETurnOverPMDate, dbo.DCBMMaintenance.Process, dbo.DCBMMaintenance.Location, dbo.DCBMMaintenance.OPBMUnitID, 
                         dbo.BMSpecialDevice.SpecialDevName, dbo.BMCaseDefectMode.BMCaseDefectModeName, dbo.PMCategory.PMCategory AS AccPMCategory, dbo.DCBMMaintenance.isNotQuality2, dbo.DCBMMaintenance.isNotQuality3, 
                         dbo.DCBMMaintenance.Akapen1, dbo.DCBMMaintenance.Akapen2, dbo.DCBMMaintenance.Akapen3, dbo.DCBMMaintenance.Aopen1, dbo.DCBMMaintenance.Aopen2, dbo.DCBMMaintenance.Aopen3
FROM            dbo.DCBMMaintenance LEFT OUTER JOIN
                         dbo.PMCategory ON dbo.DCBMMaintenance.AcredPMCategoryID = dbo.PMCategory.PMCategoryID LEFT OUTER JOIN
                         dbo.BMCaseDefectMode ON dbo.DCBMMaintenance.RequestItem = dbo.BMCaseDefectMode.BMCaseDefectModeName LEFT OUTER JOIN
                         dbo.BMSpecialDevice ON dbo.DCBMMaintenance.DeviceName = dbo.BMSpecialDevice.SpecialDevName LEFT OUTER JOIN
                         dbo.BMStatus ON dbo.BMStatus.BMStatusID = dbo.DCBMMaintenance.BMStatusID LEFT OUTER JOIN
                         dbo.SubProcess ON dbo.DCBMMaintenance.SubProcessID = dbo.SubProcess.SubProcessID LEFT OUTER JOIN
                         dbo.PMCategory AS PMCategory_1 ON dbo.DCBMMaintenance.PMCategoryID = PMCategory_1.PMCategoryID
