CREATE VIEW [dbo].[tbl_LongBMTextData]
AS
SELECT       [BMId], (SELECT        BMStatus
                          FROM            [eMaintenanceSystemDB].[dbo].[BMStatus] AS a
                          WHERE        a.BMStatusID = b.BMStatusID) AS BMStatus,
                             (SELECT        [PMCategory]
                               FROM            [eMaintenanceSystemDB].[dbo].[PMCategory] AS c
                               WHERE        c.PMCategoryID = b.PMCategoryID) AS PMCategory, [Process], [Location], [MCNo], [MCType], [LOTNo], [DeviceName], [PkgName], [RequestItem], [OccurrenceDate], [RequestContent], [RequestedBy], 
                         [StartOfRepair], [RepairedByStart], ISNULL([CurrentPM], '') AS CurrentPM
FROM            [eMaintenanceSystemDB].[dbo].[DCBMMaintenance] AS b
WHERE        PMCategoryID = '1' AND BMStatusID IN (2, 3, 6, 7) AND EndOfRepair IS NULL AND DateDiff(MINUTE, OccurrenceDate, Getdate()) > 180
UNION
SELECT        [BMId], (SELECT        BMStatus
                          FROM            [eMaintenanceSystemDB].[dbo].[BMStatus] AS a
                          WHERE        a.BMStatusID = b.BMStatusID) AS BMStatus,
                             (SELECT        [PMCategory]
                               FROM            [eMaintenanceSystemDB].[dbo].[PMCategory] AS c
                               WHERE        c.PMCategoryID = b.PMCategoryID) AS PMCategory, [Process], [Location], [MCNo], [MCType], [LOTNo], [DeviceName], [PkgName], [RequestItem], [OccurrenceDate], [RequestContent], [RequestedBy], 
                         [StartOfRepair], [RepairedByStart], ISNULL([CurrentPM], '') AS CurrentPM
FROM            [eMaintenanceSystemDB].[dbo].[DBBMMaintenance] AS b
WHERE        PMCategoryID = '1' AND BMStatusID IN (2, 3, 6, 7) AND EndOfRepair IS NULL AND DateDiff(MINUTE, OccurrenceDate, Getdate()) > 180
UNION
SELECT        [BMId], (SELECT        BMStatus
                          FROM            [eMaintenanceSystemDB].[dbo].[BMStatus] AS a
                          WHERE        a.BMStatusID = b.BMStatusID) AS BMStatus,
                             (SELECT        [PMCategory]
                               FROM            [eMaintenanceSystemDB].[dbo].[PMCategory] AS c
                               WHERE        c.PMCategoryID = b.PMCategoryID) AS PMCategory, [Process], [Location], [MCNo], [MCType], [LOTNo], [DeviceName], [PkgName], [RequestItem], [OccurrenceDate], [RequestContent], [RequestedBy], 
                         [StartOfRepair], [RepairedByStart], ISNULL([CurrentPM], '') AS CurrentPM
FROM            [eMaintenanceSystemDB].[dbo].[WBBMMaintenance] AS b
WHERE        PMCategoryID = '1' AND BMStatusID IN (2, 3, 6, 7) AND EndOfRepair IS NULL AND DateDiff(MINUTE, OccurrenceDate, Getdate()) > 180
UNION
SELECT        [BMId], (SELECT        BMStatus
                          FROM            [eMaintenanceSystemDB].[dbo].[BMStatus] AS a
                          WHERE        a.BMStatusID = b.BMStatusID) AS BMStatus,
                             (SELECT        [PMCategory]
                               FROM            [eMaintenanceSystemDB].[dbo].[PMCategory] AS c
                               WHERE        c.PMCategoryID = b.PMCategoryID) AS PMCategory, [Process], [Location], [MCNo], [MCType], [LOTNo], [DeviceName], [PkgName], [RequestItem], [OccurrenceDate], [RequestContent], [RequestedBy], 
                         [StartOfRepair], [RepairedByStart], ISNULL([CurrentPM], '') AS CurrentPM
FROM            [eMaintenanceSystemDB].[dbo].[MPBMMaintenance] AS b
WHERE        PMCategoryID = '1' AND BMStatusID IN (2, 3, 6, 7) AND EndOfRepair IS NULL AND DateDiff(MINUTE, OccurrenceDate, Getdate()) > 180
UNION
SELECT        [BMId], (SELECT        BMStatus
                          FROM            [eMaintenanceSystemDB].[dbo].[BMStatus] AS a
                          WHERE        a.BMStatusID = b.BMStatusID) AS BMStatus,
                             (SELECT        [PMCategory]
                               FROM            [eMaintenanceSystemDB].[dbo].[PMCategory] AS c
                               WHERE        c.PMCategoryID = b.PMCategoryID) AS PMCategory, [Process], [Location], [MCNo], [MCType], [LOTNo], [DeviceName], [PkgName], [RequestItem], [OccurrenceDate], [RequestContent], [RequestedBy], 
                         [StartOfRepair], [RepairedByStart], ISNULL([CurrentPM], '') AS CurrentPM
FROM            [eMaintenanceSystemDB].[dbo].[PLBMMaintenance] AS b
WHERE        PMCategoryID = '1' AND BMStatusID IN (2, 3, 6, 7) AND EndOfRepair IS NULL AND DateDiff(MINUTE, OccurrenceDate, Getdate()) > 180
UNION
SELECT        [BMId], (SELECT        BMStatus
                          FROM            [eMaintenanceSystemDB].[dbo].[BMStatus] AS a
                          WHERE        a.BMStatusID = b.BMStatusID) AS BMStatus,
                             (SELECT        [PMCategory]
                               FROM            [eMaintenanceSystemDB].[dbo].[PMCategory] AS c
                               WHERE        c.PMCategoryID = b.PMCategoryID) AS PMCategory, [Process], [Location], [MCNo], [MCType], [LOTNo], [DeviceName], [PkgName], [RequestItem], [OccurrenceDate], [RequestContent], [RequestedBy], 
                         [StartOfRepair], [RepairedByStart], ISNULL([CurrentPM], '') AS CurrentPM
FROM            [eMaintenanceSystemDB].[dbo].[FLBMMaintenance] AS b
WHERE        PMCategoryID = '1' AND BMStatusID IN (2, 3, 6, 7) AND EndOfRepair IS NULL AND DateDiff(MINUTE, OccurrenceDate, Getdate()) > 180
UNION
SELECT       [BMId], (SELECT        BMStatus
                          FROM            [eMaintenanceSystemDB].[dbo].[BMStatus] AS a
                          WHERE        a.BMStatusID = b.BMStatusID) AS BMStatus,
                             (SELECT        [PMCategory]
                               FROM            [eMaintenanceSystemDB].[dbo].[PMCategory] AS c
                               WHERE        c.PMCategoryID = b.PMCategoryID) AS PMCategory, [Process], [Location], [MCNo], [MCType], [LOTNo], [DeviceName], [PkgName], [RequestItem], [OccurrenceDate], [RequestContent], [RequestedBy], 
                         [StartOfRepair], [RepairedByStart], ISNULL([CurrentPM], '') AS CurrentPM
FROM            [eMaintenanceSystemDB].[dbo].[FTBMMaintenance] AS b
WHERE        PMCategoryID = '1' AND BMStatusID IN (2, 3, 6, 7) AND EndOfRepair IS NULL AND DateDiff(MINUTE, OccurrenceDate, Getdate()) > 180
UNION
SELECT        [BMId], (SELECT        BMStatus
                          FROM            [eMaintenanceSystemDB].[dbo].[BMStatus] AS a
                          WHERE        a.BMStatusID = b.BMStatusID) AS BMStatus,
                             (SELECT        [PMCategory]
                               FROM            [eMaintenanceSystemDB].[dbo].[PMCategory] AS c
                               WHERE        c.PMCategoryID = b.PMCategoryID) AS PMCategory, [Process], [Location], [MCNo], [MCType], [LOTNo], [DeviceName], [PkgName], [RequestItem], [OccurrenceDate], [RequestContent], [RequestedBy], 
                         [StartOfRepair], [RepairedByStart], ISNULL([CurrentPM], '') AS CurrentPM
FROM            [eMaintenanceSystemDB].[dbo].[TPBMMaintenance] AS b
WHERE        PMCategoryID = '1' AND BMStatusID IN (2, 3, 6, 7) AND EndOfRepair IS NULL AND DateDiff(MINUTE, OccurrenceDate, Getdate()) > 180
