/****** Object:  View [dbo].[viewDCWaitingForApproval]    Script Date: 10/25/2026 4:57:09 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO






CREATE VIEW [dbo].[viewDCWaitingForApproval]
AS
SELECT        COUNT(bmID) AS TotalBM, Location,
                             (SELECT        COUNT(BMStatusID) AS GLTotal
                               FROM            dbo.DCBMMaintenance AS b
                               WHERE        (BMStatusID = 1) AND (Location = a.Location)) AS WaitingForGLApprovalTotal,
                             (SELECT        COUNT(BMStatusID) AS PMTotal
                               FROM            dbo.DCBMMaintenance AS c
                               WHERE        (BMStatusID = 2) AND (Location = a.Location)) AS WaitingForPMApprovalTotal,
                             (SELECT        COUNT(BMStatusID) AS OnGoingPMTotal
                               FROM            dbo.DCBMMaintenance AS d
                               WHERE        (BMStatusID = 3) AND (Location = a.Location)) AS OnGoingPMTotal,
                             (SELECT        COUNT(BMStatusID) AS PMRepairDoneTotal
                               FROM            dbo.DCBMMaintenance AS e
                               WHERE        (BMStatusID = 4) AND (Location = a.Location)) AS PMRepairDoneTotal,
                             (SELECT        COUNT(BMStatusID) AS GLReturnedToPMTotal
                               FROM            dbo.DCBMMaintenance AS f
                               WHERE        (BMStatusID = 5) AND (Location = a.Location)) AS GLReturnedToPMTotal,
                             (SELECT        COUNT(BMStatusID) AS EETotal
                               FROM            dbo.DCBMMaintenance AS g
                               WHERE        (BMStatusID = 6) AND (Location = a.Location)) AS WaitingForEEApprovalTotal,
                             (SELECT        COUNT(BMStatusID) AS OngoingPERepairTotal
                               FROM            dbo.DCBMMaintenance AS h
                               WHERE        (BMStatusID = 7) AND (Location = a.Location)) AS OngoingPERepairTotal,
                             (SELECT        COUNT(BMStatusID) AS PERepairDoneTotal
                               FROM            dbo.DCBMMaintenance AS i
                               WHERE        (BMStatusID = 8) AND (Location = a.Location)) AS PERepairDoneTotal,
                             (SELECT        COUNT(BMStatusID) AS ReturnedToPETotal
                               FROM            dbo.DCBMMaintenance AS j
                               WHERE        (BMStatusID = 9) AND (Location = a.Location)) AS ReturnedToPETotal,
                             (SELECT        COUNT(BMStatusID) AS PMTurnoverApprovalTotal
                               FROM            dbo.DCBMMaintenance AS k
                               WHERE        (BMStatusID = 10) AND (Location = a.Location)) AS PMTurnoverApprovalTotal,
                             (SELECT        COUNT(BMStatusID) AS AccApprovalTotal
                               FROM            dbo.DCBMMaintenance AS l
                               WHERE        (BMStatusID = 11) AND (Location = a.Location)) AS AccApprovalTotal,
                             (SELECT        COUNT(BMStatusID) AS AccReturnedtoPM
                               FROM            dbo.DCBMMaintenance AS m
                               WHERE        (BMStatusID = 12) AND (Location = a.Location)) AS AccReturnedtoPM,
                             (SELECT        COUNT(BMStatusID) AS PMReturnedtoPM
                               FROM            dbo.DCBMMaintenance AS n
                               WHERE        (BMStatusID = 13) AND (Location = a.Location)) AS PMReturnedtoPM,
                             (SELECT        COUNT(BMStatusID) AS BMClosed
                               FROM            dbo.DCBMMaintenance AS o
                               WHERE        (BMStatusID = 14) AND (Location = a.Location)) AS BMClosed,
                             (SELECT        COUNT(BMStatusID) AS BMInvalid
                               FROM            dbo.DCBMMaintenance AS p
                               WHERE        (BMStatusID = 15) AND (Location = a.Location)) AS BMOcapResolved,
                             (SELECT        COUNT(BMStatusID) AS BMInvalid
                               FROM            dbo.DCBMMaintenance AS q
                               WHERE        (BMStatusID = 30) AND (Location = a.Location)) AS BMInvalid,
                             (SELECT        COUNT(BMStatusID) AS BMVoid
                               FROM            dbo.DCBMMaintenance AS r
                               WHERE        (BMStatusID = 31) AND (Location = a.Location)) AS BMVoid

FROM            dbo.DCBMMaintenance AS a
GROUP BY Location


GO
/****** Object:  View [dbo].[TEFinalRawData_2]    Script Date: 10/25/2026 4:57:09 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[TEFinalRawData_2]
AS
SELECT   MONTH(dbo.TEBMMaintenance.OccurrenceDate) AS MONTH, DAY(dbo.TEBMMaintenance.OccurrenceDate) AS DAY, YEAR(dbo.TEBMMaintenance.OccurrenceDate) AS YEAR, 
                         CONVERT(varchar(10), dbo.TEBMMaintenance.OccurrenceDate, 103) AS RequestDate, CONVERT(varchar(8), dbo.TEBMMaintenance.OccurrenceDate, 108) AS RequestTime, 
                         CONVERT(varchar(10), dbo.TEBMMaintenance.EndOfRepair, 103) AS EndDate, CONVERT(varchar(8), dbo.TEBMMaintenance.EndOfRepair, 108) AS EndTime, 
                         dbo.TEBMMaintenance.MCNo, dbo.TEBMMaintenance.MCType AS TesterType, dbo.TEBMMaintenance.TesterNo, dbo.TEBMMaintenance.DeviceName, dbo.TEBMMaintenance.TestFlow, 
                         dbo.TEBMMaintenance.Process, dbo.TEBMMaintenance.PkgName, dbo.TEBMMaintenance.LOTNo, dbo.TEBMMaintenance.BoxNo, dbo.TEBMMaintenance.DUT, 
                         dbo.TEBMMaintenance.PMCategoryID, dbo.TEContent.BMContentNumber, dbo.TECase.BMCaseCodeNo, dbo.BMTEUnit.BMTEUnitNumber, dbo.TEPoint.BMPointNo, 
                         dbo.TEWorkContent.BMWorkContentNumber, dbo.TECause.BMCauseNo, dbo.TEPREVMeasure.PREVMeasureNo, dbo.TEBMMaintenance.RequestedBy, 
                         dbo.TEBMMaintenance.RepairedByEnd, DATEDIFF(minute, dbo.TEBMMaintenance.StartOfRepair, dbo.TEBMMaintenance.EndOfRepair) 
                         - dbo.TEBMMaintenance.TotalSKCTPDtime - dbo.TEBMMaintenance.TotalStopTime AS RepairTime, DATEDIFF(minute, dbo.TEBMMaintenance.GLConfirmOPReqDate, 
                         dbo.TEBMMaintenance.PMConfirmGLOPReqDate) + dbo.TEBMMaintenance.TotalStopTime AS WaitingTime, DATEDIFF(minute, dbo.TEBMMaintenance.EndOfRepair, 
                         dbo.TEBMMaintenance.GLRepairConfirmation) AS MonitoringTime, dbo.TEBMMaintenance.ReqTestNoNG, dbo.TEBMMaintenance.OPRemarks, dbo.TEBMMaintenance.QAction, 
                         dbo.TEBMMaintenance.BMStatusID, dbo.TEBMMaintenance.OccurrenceDate, dbo.TEBMMaintenance.Location, dbo.TEBMMaintenance.SubDUT, dbo.TEBMMaintenance.CurrentTE, 
                         dbo.TEBMMaintenance.ProbeRingBefore, dbo.TEBMMaintenance.ProbeRingAfter, dbo.TEBMMaintenance.IronPlateBefore, dbo.TEBMMaintenance.IronPlateAfter, 
                         dbo.TEBMMaintenance.ChangePartsName1, dbo.TEBMMaintenance.ChangePartsName2, dbo.TEBMMaintenance.ChangePartsName3, dbo.TEBMMaintenance.ChangePartsName4, 
                         dbo.TEBMMaintenance.ChangePartsName5, dbo.TEBMMaintenance.ChangePartsType1, dbo.TEBMMaintenance.ChangePartsType2, dbo.TEBMMaintenance.ChangePartsType3, 
                         dbo.TEBMMaintenance.ChangePartsType4, dbo.TEBMMaintenance.ChangePartsType5, dbo.TEBMMaintenance.ChangePartsQty1, dbo.TEBMMaintenance.ChangePartsQty2, 
                         dbo.TEBMMaintenance.ChangePartsQty3, dbo.TEBMMaintenance.ChangePartsQty4, dbo.TEBMMaintenance.ChangePartsQty5, dbo.TEBMMaintenance.SKCTPDOnHoldDate, 
                         dbo.TEBMMaintenance.SKCTPDReleaseDate, dbo.TEBMMaintenance.TotalSKCTPDtime
FROM         dbo.TEBMMaintenance LEFT OUTER JOIN
                         dbo.TEWorkContent ON dbo.TEBMMaintenance.BMWorkContentID = dbo.TEWorkContent.BMWorkContentID LEFT OUTER JOIN
                         dbo.TEPREVMeasure ON dbo.TEBMMaintenance.PrevMeasureID = dbo.TEPREVMeasure.PREVMeasureID LEFT OUTER JOIN
                         dbo.TEPoint ON dbo.TEBMMaintenance.BMPointID = dbo.TEPoint.BMPointID LEFT OUTER JOIN
                         dbo.TECause ON dbo.TEBMMaintenance.BMCauseID = dbo.TECause.BMCauseID LEFT OUTER JOIN
                         dbo.TECase ON dbo.TEBMMaintenance.BMCaseID = dbo.TECase.BMCaseID LEFT OUTER JOIN
                         dbo.BMTEUnit ON dbo.TEBMMaintenance.BMUnitID = dbo.BMTEUnit.BMTEUnitID LEFT OUTER JOIN
                         dbo.TEContent ON dbo.TEBMMaintenance.BMContentID = dbo.TEContent.BMContentID
GO
/****** Object:  View [dbo].[viewTPBMPerMachine]    Script Date: 10/25/2026 4:57:09 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[viewTPBMPerMachine]
AS
SELECT DISTINCT FORMAT(EndOfRepair, 'MMM') AS MonthRequested, MONTH(EndOfRepair) AS myMOnth, YEAR(EndOfRepair) AS myYear,
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.TPBMMaintenance AS b
                               WHERE        (MONTH(EndOfRepair) = MONTH(a.EndOfRepair)) AND (YEAR(EndOfRepair) = YEAR(a.EndOfRepair)) AND (BMStatusID > 10 OR
                                                         BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30) AND (Location = 'LSI2-1F')) AS LSI21FBM,
                             (SELECT        ISNULL(macCount, 0) AS Expr1
                               FROM            dbo.viewBMRateCalc AS c
                               WHERE        (myMonth = MONTH(a.EndOfRepair)) AND (myYear = YEAR(a.EndOfRepair)) AND (ProcessMatch = 'TP') AND (Shift = '1ST') AND (LocationMatch = 'LSI2-1F')) AS LSI21FMC,
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.TPBMMaintenance AS b
                               WHERE        (MONTH(EndOfRepair) = MONTH(a.EndOfRepair)) AND (YEAR(EndOfRepair) = YEAR(a.EndOfRepair)) AND (BMStatusID > 10 OR
                                                         BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30) AND (Location = 'LSI2-2F')) AS LSI22FBM,
                             (SELECT        ISNULL(macCount, 0) AS Expr1
                               FROM            dbo.viewBMRateCalc AS c
                               WHERE        (myMonth = MONTH(a.EndOfRepair)) AND (myYear = YEAR(a.EndOfRepair)) AND (ProcessMatch = 'TP') AND (Shift = '1ST') AND (LocationMatch = 'LSI2-2F')) AS LSI22FMC,
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.TPBMMaintenance AS b
                               WHERE        (MONTH(EndOfRepair) = MONTH(a.EndOfRepair)) AND (YEAR(EndOfRepair) = YEAR(a.EndOfRepair)) AND (BMStatusID > 10 OR
                                                         BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30) AND (Location = 'LSI2-3F')) AS LSI23FBM,
                             (SELECT        ISNULL(macCount, 0) AS Expr1
                               FROM            dbo.viewBMRateCalc AS c
                               WHERE        (myMonth = MONTH(a.EndOfRepair)) AND (myYear = YEAR(a.EndOfRepair)) AND (ProcessMatch = 'TP') AND (Shift = '1ST') AND (LocationMatch = 'LSI2-3F')) AS LSI23FMC,
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.TPBMMaintenance AS b
                               WHERE        (MONTH(EndOfRepair) = MONTH(a.EndOfRepair)) AND (YEAR(EndOfRepair) = YEAR(a.EndOfRepair)) AND (BMStatusID > 10 OR
                                                         BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30) AND (Location = 'LSI1-1F')) AS LSI11FBM,
                             (SELECT        ISNULL(macCount, 0) AS Expr1
                               FROM            dbo.viewBMRateCalc AS c
                               WHERE        (myMonth = MONTH(a.EndOfRepair)) AND (myYear = YEAR(a.EndOfRepair)) AND (ProcessMatch = 'TP') AND (Shift = '1ST') AND (LocationMatch = 'LSI1-1F')) AS LSI11FMC,
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.TPBMMaintenance AS b
                               WHERE        (MONTH(EndOfRepair) = MONTH(a.EndOfRepair)) AND (YEAR(EndOfRepair) = YEAR(a.EndOfRepair)) AND (BMStatusID > 10 OR
                                                         BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30) AND (Location = 'LSI1-2F')) AS LSI12FBM,
                             (SELECT        ISNULL(SUM(macCount), 0) AS Expr1
                               FROM            dbo.viewBMRateCalc AS c
                               WHERE        (myMonth = MONTH(a.EndOfRepair)) AND (myYear = YEAR(a.EndOfRepair)) AND (ProcessMatch = 'TP') AND (Shift = '1ST') AND (LocationMatch = 'LSI1-2F')) AS LSI12FMC,
                             (SELECT        COUNT(bmID) AS Expr1
                               FROM            dbo.TPBMMaintenance AS b
                               WHERE        (MONTH(EndOfRepair) = MONTH(a.EndOfRepair)) AND (YEAR(EndOfRepair) = YEAR(a.EndOfRepair)) AND (BMStatusID > 10 OR
                                                         BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30) AND (Location = 'LSI3-2F')) AS LSI32FBM,
                             (SELECT        ISNULL(macCount, 0) AS Expr1
                               FROM            dbo.viewBMRateCalc AS c
                               WHERE        (myMonth = MONTH(a.EndOfRepair)) AND (myYear = YEAR(a.EndOfRepair)) AND (ProcessMatch = 'TP') AND (Shift = '1ST') AND (LocationMatch = 'LSI3-2F')) AS LSI32FMC
FROM            dbo.TPBMMaintenance AS a
WHERE        (BMStatusID > 10 OR
                         BMStatusID = 4) AND (BMStatusID <> 15) AND (BMStatusID <> 30) AND (EndOfRepair IS NOT NULL)
GROUP BY MONTH(EndOfRepair), EndOfRepair
GO
