    LEFT OUTER JOIN dbo.BMWhy w ON e.bm_id = w.BMWhyID
    LEFT OUTER JOIN dbo.BMCase c ON e.AcredBMCaseID = c.BMCaseID
    LEFT OUTER JOIN dbo.BMSpecialDevice sd ON s.DeviceName = sd.SpecialDevName
    LEFT OUTER JOIN dbo.BMCaseDefectMode cd ON s.RequestItem = cd.BMCaseDefectModeName
