CREATE VIEW [dbo].[viewDCEMaking]
AS
SELECT        BMEvidenceID, bmID, BMEvidence_Title, BMEvidence_Desc, BMEvidence_Category, BMEvidence_ImgFile, BMEvidence_DateTime, BMEvidence_UploadedBy, BMEvidence_TCConfirm1, BMEvidence_TCConfirm2, 
                         BMEvidence_TCConfirm3, Process
FROM            dbo.BMEvidenceMaking
WHERE        (Process = 'DC')
