                         dbo.FTBMMaintenance.IQN, dbo.FTBMMaintenance.why4others, dbo.FTBMMaintenance.UploadtoEvidence, dbo.FTBMMaintenance.DataDevice
FROM            dbo.FTBMMaintenance LEFT OUTER JOIN
                         dbo.SubProcess ON dbo.FTBMMaintenance.SubProcessID = dbo.SubProcess.SubProcessID LEFT OUTER JOIN
                         dbo.BMStatus ON dbo.FTBMMaintenance.BMStatusID = dbo.BMStatus.BMStatusID LEFT OUTER JOIN
                         dbo.PMCategory ON dbo.FTBMMaintenance.PMCategoryID = dbo.PMCategory.PMCategoryID LEFT OUTER JOIN
                         dbo.BMCase ON dbo.FTBMMaintenance.BMCaseID = dbo.BMCase.BMCaseID INNER JOIN
                         dbo.MCList ON dbo.FTBMMaintenance.MCNo = dbo.MCList.MCNo LEFT OUTER JOIN
                         dbo.I4M ON dbo.FTBMMaintenance.I4MID = dbo.I4M.I4MID LEFT OUTER JOIN
                         dbo.pm_EquipInsData ON dbo.FTBMMaintenance.bmID = dbo.pm_EquipInsData.bmID LEFT OUTER JOIN
                         dbo.BMWhy ON dbo.BMWhy.BMWhyID = dbo.FTBMMaintenance.Why4
GO
/****** Object:  View [dbo].[LSI_OEE_eMaintenance]    Script Date: 10/25/2026 4:57:09 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO




CREATE VIEW [dbo].[LSI_OEE_eMaintenance]
AS
SELECT  DISTINCT
		OEE.MCNo, 
		OEE.MCType, 
		OEE.PkgName, 
		OEE.LOTNo, 
		PMC.PMCategory, 
		OEE.TimeOfRequest, 
		OEE.RequestedBy, 
		OEE.GLConfirmOPReqDate, 
		CASE
		WHEN OEE.PEConfirmPMTurnoverBy IS NULL THEN	OEE.RepairedByEnd
		ELSE NULL
		END AS RepairedByEnd,
	    CASE
		WHEN OEE.PEConfirmPMTurnoverBy IS NULL THEN OEE.StartOfRepair
		ELSE NULL
		END AS StartOfRepair,
		CASE
		WHEN OEE.PEConfirmPMTurnoverBy IS NULL THEN OEE.EndOfRepair
		ELSE NULL
		END AS PMRepairEndDate, 
		OEE.PEConfirmPMTurnoverBy, 
		OEE.PEConfirmPMTurnoverDate,
		CASE
		WHEN OEE.PEConfirmPMTurnoverBy IS NULL THEN NULL
		ELSE OEE.EndOfRepair 
		END AS PERepairEndDate
FROM (
    SELECT  MCNo, MCType, PkgName, LOTNo, TimeOfRequest, RequestedBy, GLConfirmOPReqDate, RepairedByEnd, StartOfRepair, EndOfRepair, PEConfirmPMTurnoverBy, PEConfirmPMTurnoverDate, PMCategoryID        
	FROM dbo.DBBMMaintenance EBM
	    UNION ALL
    SELECT  MCNo, MCType, PkgName, LOTNo, TimeOfRequest, RequestedBy, GLConfirmOPReqDate, RepairedByEnd, StartOfRepair, EndOfRepair, PEConfirmPMTurnoverBy, PEConfirmPMTurnoverDate, PMCategoryID
	FROM dbo.DCBMMaintenance
	 UNION ALL
    SELECT  MCNo, MCType, PkgName, LOTNo, TimeOfRequest, RequestedBy, GLConfirmOPReqDate, RepairedByEnd, StartOfRepair, EndOfRepair, PEConfirmPMTurnoverBy, PEConfirmPMTurnoverDate, PMCategoryID
	FROM dbo.WBBMMaintenance
	 UNION ALL
	SELECT  MCNo, MCType, PkgName, LOTNo, TimeOfRequest, RequestedBy, GLConfirmOPReqDate, RepairedByEnd, StartOfRepair, EndOfRepair, PEConfirmPMTurnoverBy, PEConfirmPMTurnoverDate, PMCategoryID
	FROM dbo.MPBMMaintenance
	 UNION ALL
	SELECT  MCNo, MCType, PkgName, LOTNo, TimeOfRequest, RequestedBy, GLConfirmOPReqDate, RepairedByEnd, StartOfRepair, EndOfRepair, PEConfirmPMTurnoverBy, PEConfirmPMTurnoverDate, PMCategoryID
	FROM dbo.PLBMMaintenance
	 UNION ALL
	SELECT  MCNo, MCType, PkgName, LOTNo, TimeOfRequest, RequestedBy, GLConfirmOPReqDate, RepairedByEnd, StartOfRepair, EndOfRepair, PEConfirmPMTurnoverBy, PEConfirmPMTurnoverDate, PMCategoryID
	FROM dbo.FLBMMaintenance
	 UNION ALL
	SELECT  MCNo, MCType, PkgName, LOTNo, TimeOfRequest, RequestedBy, GLConfirmOPReqDate, RepairedByEnd, StartOfRepair, EndOfRepair, PEConfirmPMTurnoverBy, PEConfirmPMTurnoverDate, PMCategoryID
	FROM dbo.FTBMMaintenance
	 UNION ALL
	SELECT MCNo, MCType, PkgName, LOTNo, TimeOfRequest, RequestedBy, GLConfirmOPReqDate, RepairedByEnd, StartOfRepair, EndOfRepair, PEConfirmPMTurnoverBy, PEConfirmPMTurnoverDate, PMCategoryID
	FROM dbo.TPBMMaintenance
	 UNION ALL
	SELECT  MCNo, MCType, PkgName, LOTNo, TimeOfRequest, RequestedBy, GLConfirmOPReqDate, RepairedByEnd, StartOfRepair, EndOfRepair, PEConfirmPMTurnoverBy, PEConfirmPMTurnoverDate, PMCategoryID
	FROM dbo.EDSBMMaintenance EBM

) AS OEE
	INNER JOIN PMCategory PMC
	ON  OEE.PMCategoryID = PMC.PMCategoryID 

	WHERE OEE.RepairedByEnd <> ''
GO
