CREATE VIEW [dbo].[TEFinalRawData]
AS
SELECT        (CASE WHEN dbo.TEBMMaintenance.bmstatusID = '4' THEN MONTH(dbo.TEBMMaintenance.EndOfRepair) ELSE MONTH(dbo.TEBMMaintenance.OccurrenceDate) END) AS MONTH, 
                         (CASE WHEN dbo.TEBMMaintenance.bmstatusID = '4' THEN DAY(dbo.TEBMMaintenance.EndOfRepair) ELSE DAY(dbo.TEBMMaintenance.OccurrenceDate) END) AS DAY, 
                         (CASE WHEN dbo.TEBMMaintenance.bmstatusID = '4' THEN YEAR(dbo.TEBMMaintenance.EndOfRepair) ELSE YEAR(dbo.TEBMMaintenance.OccurrenceDate) END) AS YEAR, CONVERT(varchar(10), 
                         dbo.TEBMMaintenance.OccurrenceDate, 103) AS RequestDate, CONVERT(varchar(8), dbo.TEBMMaintenance.OccurrenceDate, 108) AS RequestTime, CONVERT(varchar(10), dbo.TEBMMaintenance.EndOfRepair, 103) AS EndDate, 
                         CONVERT(varchar(8), dbo.TEBMMaintenance.EndOfRepair, 108) AS EndTime, dbo.TEBMMaintenance.MCNo, dbo.TEBMMaintenance.MCType AS TesterType, dbo.TEBMMaintenance.TesterNo, 
                         dbo.TEBMMaintenance.DeviceName, dbo.TEBMMaintenance.TestFlow, dbo.TEBMMaintenance.Process, dbo.TEBMMaintenance.PkgName, dbo.TEBMMaintenance.LOTNo, dbo.TEBMMaintenance.BoxNo, 
                         dbo.TEBMMaintenance.DUT, dbo.TEBMMaintenance.PMCategoryID, dbo.TEContent.BMContentNumber, dbo.TECase.BMCaseCodeNo, dbo.BMTEUnit.BMTEUnitNumber, dbo.TEPoint.BMPointNo, 
                         dbo.TEWorkContent.BMWorkContentNumber, dbo.TECause.BMCauseNo, dbo.TEPREVMeasure.PREVMeasureNo, dbo.TEBMMaintenance.RequestedBy, dbo.TEBMMaintenance.RepairedByEnd, DATEDIFF(minute, 
                         dbo.TEBMMaintenance.StartOfRepair, dbo.TEBMMaintenance.EndOfRepair) - dbo.TEBMMaintenance.TotalSKCTPDtime - dbo.TEBMMaintenance.TotalStopTime AS RepairTime, DATEDIFF(minute, 
                         dbo.TEBMMaintenance.GLConfirmOPReqDate, dbo.TEBMMaintenance.PMConfirmGLOPReqDate) + dbo.TEBMMaintenance.TotalStopTime AS WaitingTime, DATEDIFF(minute, dbo.TEBMMaintenance.EndOfRepair, 
                         dbo.TEBMMaintenance.GLRepairConfirmation) AS MonitoringTime, dbo.TEBMMaintenance.ReqTestNoNG, dbo.TEBMMaintenance.OPRemarks, dbo.TEBMMaintenance.QAction, dbo.TEBMMaintenance.BMStatusID, 
                         dbo.TEBMMaintenance.OccurrenceDate, dbo.TEBMMaintenance.Location, dbo.TEBMMaintenance.SubDUT, dbo.TEBMMaintenance.CurrentTE, dbo.TEBMMaintenance.ProbeRingBefore, dbo.TEBMMaintenance.ProbeRingAfter, 
                         dbo.TEBMMaintenance.IronPlateBefore, dbo.TEBMMaintenance.IronPlateAfter, dbo.TEBMMaintenance.ChangePartsName1, dbo.TEBMMaintenance.ChangePartsName2, dbo.TEBMMaintenance.ChangePartsName3, 
                         dbo.TEBMMaintenance.ChangePartsName4, dbo.TEBMMaintenance.ChangePartsName5, dbo.TEBMMaintenance.ChangePartsType1, dbo.TEBMMaintenance.ChangePartsType2, dbo.TEBMMaintenance.ChangePartsType3, 
                         dbo.TEBMMaintenance.ChangePartsType4, dbo.TEBMMaintenance.ChangePartsType5, dbo.TEBMMaintenance.ChangePartsQty1, dbo.TEBMMaintenance.ChangePartsQty2, dbo.TEBMMaintenance.ChangePartsQty3, 
                         dbo.TEBMMaintenance.ChangePartsQty4, dbo.TEBMMaintenance.ChangePartsQty5, dbo.TEBMMaintenance.SKCTPDOnHoldDate, dbo.TEBMMaintenance.SKCTPDReleaseDate, dbo.TEBMMaintenance.TotalSKCTPDtime
FROM            dbo.TEBMMaintenance LEFT OUTER JOIN
                         dbo.TEWorkContent ON dbo.TEBMMaintenance.BMWorkContentID = dbo.TEWorkContent.BMWorkContentID LEFT OUTER JOIN
                         dbo.TEPREVMeasure ON dbo.TEBMMaintenance.PrevMeasureID = dbo.TEPREVMeasure.PREVMeasureID LEFT OUTER JOIN
                         dbo.TEPoint ON dbo.TEBMMaintenance.BMPointID = dbo.TEPoint.BMPointID LEFT OUTER JOIN
                         dbo.TECause ON dbo.TEBMMaintenance.BMCauseID = dbo.TECause.BMCauseID LEFT OUTER JOIN
                         dbo.TECase ON dbo.TEBMMaintenance.BMCaseID = dbo.TECase.BMCaseID LEFT OUTER JOIN
                         dbo.BMTEUnit ON dbo.TEBMMaintenance.BMUnitID = dbo.BMTEUnit.BMTEUnitID LEFT OUTER JOIN
                         dbo.TEContent ON dbo.TEBMMaintenance.BMContentID = dbo.TEContent.BMContentID
GO
