CREATE VIEW [dbo].[MPFinalBMRawData]
AS
SELECT        dbo.MPBMMaintenance.MCNo AS [MC No], dbo.MPBMMaintenance.MCType AS [MC Type], dbo.MPBMMaintenance.Location, dbo.MPBMMaintenance.PkgName AS Package, dbo.MPBMMaintenance.LOTNo AS [Lot Number], 
                         dbo.MPBMMaintenance.DeviceName AS [Device Name],
                             (SELECT        CASE WHEN dbo.MPBMMaintenance.BMStatusID = 14 THEN PMCategory.PMCategory ELSE PMCategory_1.PMCategory END AS PMCategory) AS Classification, 
                         dbo.MPBMMaintenance.RequestItem AS [Request Content], dbo.MPBMMaintenance.RequestContent AS Phenomenon, dbo.MPBMMaintenance.OccurrenceFreq AS [Occurrence Rate Before Condition], dbo.MPBMMaintenance.AQI, 
                         dbo.MPBMMaintenance.MCStatus AS [MC STATUS], dbo.MPBMMaintenance.OccurrenceDate AS [Request Date and Time], dbo.MPBMMaintenance.RequestedBy AS OP, dbo.MPBMMaintenance.GLConfirmOPReqBy AS GL, 
                         dbo.MPBMMaintenance.GLConfirmOPReqDate AS [GL Confirmed Date], dbo.MPBMMaintenance.PMConfirmGLOPReqBy AS [PM Confirmed Request],
                             (SELECT        CASE WHEN dbo.MPBMMaintenance.Turnover = 'PE' OR
                                                         dbo.MPBMMaintenance.Turnover = 'CC' OR
                                                         dbo.MPBMMaintenance.Turnover = 'VIS' THEN '' ELSE dbo.MPBMMaintenance.RepairedByEnd END AS Expr1) AS [PM Done Request], 
                         dbo.MPBMMaintenance.PMConfirmGLOPReqDate AS [START DATE AND TIME],
                             (SELECT        CASE WHEN dbo.MPBMMaintenance.Turnover = 'PE' OR
                                                         dbo.MPBMMaintenance.Turnover = 'CC' OR
                                                         dbo.MPBMMaintenance.Turnover = 'VIS' THEN dbo.MPBMMaintenance.PMTurnOvertoPEDate ELSE dbo.MPBMMaintenance.EndOfRepair END AS Expr1) AS [END DATE AND TIME], 
                         dbo.MPBMMaintenance.PEConfirmPMTurnoverBy AS [PE Confirmed Request],
                             (SELECT        CASE WHEN dbo.MPBMMaintenance.Turnover = 'PE' OR
                                                         dbo.MPBMMaintenance.Turnover = 'CC' OR
                                                         dbo.MPBMMaintenance.Turnover = 'VIS' THEN dbo.MPBMMaintenance.RepairedByEnd ELSE '' END AS Expr1) AS [PE Done Request],
                             (SELECT        CASE WHEN dbo.MPBMMaintenance.Turnover = 'PE' OR
                                                         dbo.MPBMMaintenance.Turnover = 'CC' OR
                                                         dbo.MPBMMaintenance.Turnover = 'VIS' THEN dbo.MPBMMaintenance.EndOfRepair ELSE NULL END AS Expr1) AS [PE END DATE AND TIME], 
                         dbo.MPBMMaintenance.PEConfirmPMTurnoverDate AS [PE START DATE AND TIME], dbo.MPBMMaintenance.Situation AS Condition, dbo.MPBMMaintenance.Why1, dbo.MPBMMaintenance.Why2, dbo.MPBMMaintenance.Why3, 
                         dbo.BMWhy.BMWhy AS Why4, dbo.MPBMMaintenance.Treatment1, dbo.MPBMMaintenance.Treatment2, dbo.MPBMMaintenance.Treatment3, dbo.MPBMMaintenance.Treatment4, dbo.MPBMMaintenance.Treatment5, 
                         dbo.MPBMMaintenance.Treatment6, dbo.MPBMMaintenance.Treatment7, dbo.MPBMMaintenance.Treatment8, dbo.MPBMMaintenance.Treatment9, dbo.MPBMMaintenance.Treatment10, dbo.MPBMMaintenance.Treatment11, 
                         dbo.MPBMMaintenance.Treatment12, dbo.MPBMMaintenance.Treatment13, dbo.MPBMMaintenance.Treatment14, dbo.MPBMMaintenance.KanagataNo AS [Kanagata Number], 
                         dbo.MPBMMaintenance.NGDetectionCircumtances AS [NG Detection Circumstance], dbo.MPBMMaintenance.OccurrenceFreqQuantity AS Quantity1, dbo.MPBMMaintenance.OccurrenceFreqLotFrame AS Quantity2, 
                         dbo.MPBMMaintenance.MajorTreatment AS COUNTERMEASURE1, dbo.MPBMMaintenance.ConditionAfterAdj AS [AFTER CONDITION], dbo.MPBMMaintenance.ConditionAfterAdjMin AS [AFTER CONDITION QUANTITY1], 
                         dbo.MPBMMaintenance.ConditionAfterAdjMax AS [AFTER CONDITION QUANTITY2], dbo.MPBMMaintenance.UseDummyFrames AS [USING DUMMY PRODUCT], dbo.MPBMMaintenance.DummyIn AS [DUMMY IN], 
                         dbo.MPBMMaintenance.DummyOut AS [DUMMY OUT], dbo.MPBMMaintenance.DroppedWork AS [CHECKING DROPPED WORK], dbo.MPBMMaintenance.DroppedWorkBeforePM AS [DROPPED WORK BEFORE], 
                         dbo.MPBMMaintenance.DroppeWorkAfterPM AS [DROPPED WORK AFTER], dbo.MPBMMaintenance.ItemValueChecked AS [ITEM/VALUE CHECKED], 
                         dbo.MPBMMaintenance.ChangedValueChecked AS [CHANGED/CHECKED VALUE], dbo.MPBMMaintenance.ReqSATInsp AS [REQUEST FOR SAT INSPECTION], 
                         dbo.MPBMMaintenance.SATInspResult AS [SAT INSPECTION RESULT], dbo.MPBMMaintenance.SATInspResultStatus AS [SAT INSPECTION], dbo.MPBMMaintenance.CheckSensorColorNo AS [CHECK SENSOR COLOR AND NO.], 
                         dbo.MPBMMaintenance.CheckSensorReaction AS [CHECK SENSOR REACTION], dbo.MPBMMaintenance.MotionSafetyCoverSwitch AS [MOTION OF SAFETY COVER SWITCH], 
                         dbo.MPBMMaintenance.Check5SAfterPMWork AS [5S AFTER PM WORK], dbo.MPBMMaintenance.SelconReg AS [SELCON REGISTRATION], dbo.MPBMMaintenance.SelconRegValue AS [PREVIOUS ADJUSTMENT], 
                         dbo.MPBMMaintenance.InspectionReq AS [INSPECTION REQUEST], dbo.MPBMMaintenance.InspQtyNeeded AS [INSPECTION QTY NEEDED], dbo.MPBMMaintenance.CheckItem AS [CHECK ITEM1], 
                         dbo.MPBMMaintenance.CheckItem1 AS [CHECK ITEM2], dbo.MPBMMaintenance.CheckItem2 AS [CHECK ITEM3], dbo.MPBMMaintenance.CheckItem3 AS [CHECK ITEM4], dbo.MPBMMaintenance.RequesttoPD AS [REQUEST TO], 
                         dbo.MPBMMaintenance.PDConfirmation AS [PD CONFIRMATION], dbo.MPBMMaintenance.InspectionResults AS [INSPECTION RESULTS], dbo.MPBMMaintenance.PDTreatmentIncharge AS [PD TREATMENT/ INCHARGE], 
                         dbo.MPBMMaintenance.ChangePartsName1 AS [PARTS NAME1], dbo.MPBMMaintenance.ChangePartsType1 AS TYPE1, dbo.MPBMMaintenance.ChangePartsQty1 AS QTY1, 
                         dbo.MPBMMaintenance.ChangePartsNewReworked1 AS [PARTS REPLACED1], dbo.MPBMMaintenance.ChangePartsDate1 AS [CHANGE PARTS DATE1], dbo.MPBMMaintenance.ChangePartsMonthDay1 AS [REMARKS/LIFE1], 
                         dbo.MPBMMaintenance.ChangePartsInsNewReworked1 AS [PARTS INSTALLED1], dbo.MPBMMaintenance.ChangePartsName2 AS [PARTS NAME2], dbo.MPBMMaintenance.ChangePartsType2 AS TYPE2, 
                         dbo.MPBMMaintenance.ChangePartsQty2 AS QTY2, dbo.MPBMMaintenance.ChangePartsNewReworked2 AS [PARTS REPLACED2], dbo.MPBMMaintenance.ChangePartsDate2 AS [CHANGE PARTS DATE2], 
                         dbo.MPBMMaintenance.ChangePartsMonthDay2 AS [REMARKS/LIFE2], dbo.MPBMMaintenance.ChangePartsInsNewReworked2 AS [PARTS INSTALLED2], dbo.MPBMMaintenance.ChangePartsName3 AS [PARTS NAME3], 
                         dbo.MPBMMaintenance.ChangePartsType3 AS TYPE3, dbo.MPBMMaintenance.ChangePartsQty3 AS QTY3, dbo.MPBMMaintenance.ChangePartsNewReworked3 AS [PARTS REPLACED3], 
                         dbo.MPBMMaintenance.ChangePartsDate3 AS [CHANGE PARTS DATE3], dbo.MPBMMaintenance.ChangePartsMonthDay3 AS [REMARKS/LIFE3], dbo.MPBMMaintenance.ChangePartsInsNewReworked3 AS [PARTS INSTALLED3], 
                         dbo.MPBMMaintenance.ChangePartsName4 AS [PARTS NAME4], dbo.MPBMMaintenance.ChangePartsType4 AS TYPE4, dbo.MPBMMaintenance.ChangePartsQty4 AS QTY4, 
                         dbo.MPBMMaintenance.ChangePartsNewReworked4 AS [PARTS REPLACED4], dbo.MPBMMaintenance.ChangePartsDate4 AS [CHANGE PARTS DATE4], dbo.MPBMMaintenance.ChangePartsMonthDay4 AS [REMARKS/LIFE4], 
                         dbo.MPBMMaintenance.ChangePartsInsNewReworked4 AS [PARTS INSTALLED4], dbo.MPBMMaintenance.ChangePartsName5 AS [PARTS NAME5], dbo.MPBMMaintenance.ChangePartsType5 AS TYPE5, 
                         dbo.MPBMMaintenance.ChangePartsQty5 AS QTY5, dbo.MPBMMaintenance.ChangePartsNewReworked5 AS [PARTS REPLACED5], dbo.MPBMMaintenance.ChangePartsDate5 AS [CHANGE PARTS DATE5], 
                         dbo.MPBMMaintenance.ChangePartsMonthDay5 AS [REMARKS/LIFE5], dbo.MPBMMaintenance.ChangePartsInsNewReworked5 AS [PARTS INSTALLED5], dbo.MPBMMaintenance.TypeofRequest AS [TYPE OF REQUEST], 
                         dbo.MPBMMaintenance.PMConfirmGLOPReason AS [INVALID REQUEST REASON], PMCategory_1.PMCategory AS [PM CATEGORY], BMContent_1.BMContent AS [BM CONTENT], BMCase_1.BMCase AS [CASE], 
                         BMMCUnit_1.BMMCUnit AS [MACHINE UNIT], BMPoint_1.BMPoint AS POSITION, BMWorkContent_1.BMWorkContent AS [WORK CONTENT], dbo.MPBMMaintenance.RequestItem AS [BM CAUSE], 
                         dbo.PREVMeasure.PREVMeasure AS [PREVENTIVE MEASURE], dbo.MPBMMaintenance.AccreditorRemarks AS [IN-CHARGE REMARKS], dbo.MPBMMaintenance.AccreditorPMReply AS [PM REMARKS], 
                         BMWhy_1.BM4M AS [4M ANALYSIS TYPE], BMWhy_1.BMWhy AS [4M ANALYSIS], dbo.PMCategory.PMCategory AS [IN-CHARGE PM CATEGORY], dbo.BMContent.BMContent AS [IN-CHARGE-CONTENT], 
                         dbo.BMCase.BMCase AS [IN-CHARGE CASE], dbo.BMMCUnit.BMMCUnit AS [IN-CHARGE MACHINE UNIT], dbo.BMPoint.BMPoint AS [IN-CHARGE POSITION], 
                         dbo.BMWorkContent.BMWorkContent AS [IN-CHARGE WORK CONTENT], BMWhy_2.BMWhy AS [IN-CHARGE CAUSE], dbo.PREVMeasure.PREVMeasure AS [IN-CHARGE PREVENTIVE MEASURE], 
                         dbo.MPBMMaintenance.AcredINSPN AS [PERIODIC RELATED BM], dbo.MPBMMaintenance.bmID, dbo.MPBMMaintenance.OccurrenceDate, dbo.MPBMMaintenance.BMStatusID, dbo.MPBMMaintenance.Process, 
                         dbo.MPBMMaintenance.RequestItem AS [Case Name], dbo.MPBMMaintenance.RequestedBy AS Issuer,
                             (SELECT        CASE WHEN dbo.MPBMMaintenance.BMStatusID = '14' OR
                                                         dbo.MPBMMaintenance.BMStatusID = '11' OR
                                                         dbo.MPBMMaintenance.BMStatusID = '13' THEN CASE WHEN dbo.MPBMMaintenance.isnotquality2 = 'No' AND 
                                                         dbo.MPBMMaintenance.isnotquality3 = 'No' THEN 'Yes' ELSE 'No' END ELSE 'No' END AS IsQualityBM) AS IsQualityBM, dbo.MPBMMaintenance.EndBM AS AccreditorTimeStamp
FROM            dbo.MPBMMaintenance LEFT OUTER JOIN
                         dbo.BMWhy ON dbo.MPBMMaintenance.Why4 = dbo.BMWhy.BMWhyID LEFT OUTER JOIN
                         dbo.BMWhy AS BMWhy_2 ON dbo.MPBMMaintenance.AcredBMCauseID = BMWhy_2.BMWhyID LEFT OUTER JOIN
                         dbo.BMWorkContent ON dbo.MPBMMaintenance.AcredBMWorkContentID = dbo.BMWorkContent.BMWorkContentID LEFT OUTER JOIN
                         dbo.BMPoint ON dbo.MPBMMaintenance.AcredBMPointID = dbo.BMPoint.BMPointID LEFT OUTER JOIN
                         dbo.BMMCUnit ON dbo.MPBMMaintenance.AcredBMMCUnitID = dbo.BMMCUnit.BMMCUnitID LEFT OUTER JOIN
                         dbo.BMCase ON dbo.MPBMMaintenance.AcredBMCaseID = dbo.BMCase.BMCaseID LEFT OUTER JOIN
                         dbo.PMCategory ON dbo.MPBMMaintenance.AcredPMCategoryID = dbo.PMCategory.PMCategoryID LEFT OUTER JOIN
                         dbo.BMWhy AS BMWhy_1 ON dbo.MPBMMaintenance.AcredBMCauseID = BMWhy_1.BMWhyID LEFT OUTER JOIN
                         dbo.PREVMeasure ON dbo.MPBMMaintenance.AcredPREVMeasureID = dbo.PREVMeasure.PREVMeasureID LEFT OUTER JOIN
                         dbo.BMWorkContent AS BMWorkContent_1 ON dbo.MPBMMaintenance.BMWorkContentID = BMWorkContent_1.BMWorkContentID LEFT OUTER JOIN
                         dbo.BMPoint AS BMPoint_1 ON dbo.MPBMMaintenance.BMPointID = BMPoint_1.BMPointID LEFT OUTER JOIN
                         dbo.BMCase AS BMCase_1 ON dbo.MPBMMaintenance.BMCaseID = BMCase_1.BMCaseID LEFT OUTER JOIN
                         dbo.BMMCUnit AS BMMCUnit_1 ON dbo.MPBMMaintenance.BMUnitID = BMMCUnit_1.BMMCUnitID LEFT OUTER JOIN
                         dbo.BMContent AS BMContent_1 ON dbo.MPBMMaintenance.BMContentID = BMContent_1.BMContentID LEFT OUTER JOIN
                         dbo.PMCategory AS PMCategory_1 ON dbo.MPBMMaintenance.PMCategoryID = PMCategory_1.PMCategoryID LEFT OUTER JOIN
                         dbo.BMContent ON dbo.MPBMMaintenance.AcredBMContentID = dbo.BMContent.BMContentID
GO
