/****** Object:  View [dbo].[view3HoursLBM]    Script Date: 10/25/2026 4:57:09 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[view3HoursLBM]
AS
SELECT        [BMId],
                             (SELECT        FirstName
                               FROM            dbo.tbl_SMSContacts AS d
                               WHERE        d .Process = b.Process AND d .Position = 'DM') AS FirstName,
                             (SELECT        LastName
                               FROM            dbo.tbl_SMSContacts AS d
                               WHERE        d .Process = b.Process AND d .Position = 'DM') AS LastName,
                             (SELECT        CellNumber
                               FROM            dbo.tbl_SMSContacts AS d
                               WHERE        d .Process = b.Process AND d .Position = 'DM') AS CellNumber,
