CREATE VIEW [dbo].[view24HoursLBM]
AS
SELECT        [BMId],
                             (SELECT        FirstName
                               FROM            dbo.tbl_SMSContacts AS d
                               WHERE        d .Position = 'DIV') AS FirstName,
                             (SELECT        LastName
                               FROM            dbo.tbl_SMSContacts AS d
                               WHERE        d .Position = 'DIV') AS LastName,
                             (SELECT        CellNumber
                               FROM            dbo.tbl_SMSContacts AS d
                               WHERE        d .Position = 'DIV') AS CellNumber,
                             (SELECT        BMStatus
                               FROM            [eMaintenanceSystemDB].[dbo].[BMStatus] AS a
                               WHERE        a.BMStatusID = b.BMStatusID) AS BMStatus,
                             (SELECT        [PMCategory]
                               FROM            [eMaintenanceSystemDB].[dbo].[PMCategory] AS c
                               WHERE        c.PMCategoryID = b.PMCategoryID) AS PMCategory, [Process], [Location], [MCNo], [MCType], [LOTNo], [DeviceName], [PkgName], [RequestItem], [OccurrenceDate], [RequestContent], [RequestedBy], 
                         [StartOfRepair], [RepairedByStart], ISNULL([CurrentPM], '') AS CurrentPM,[TurnoverPM]
      ,[TimeTurnover]
      ,[Turnover]
FROM            [eMaintenanceSystemDB].[dbo].[DCBMMaintenance] AS b
WHERE        PMCategoryID = '1' AND BMStatusID IN (2, 3, 6, 7) AND EndOfRepair IS NULL AND DateDiff(MINUTE, OccurrenceDate, Getdate()) >= 1440
UNION
SELECT        [BMId],
                             (SELECT        FirstName
                               FROM            dbo.tbl_SMSContacts AS d
                               WHERE        d .Position = 'DIV') AS FirstName,
