/****** Object:  View [dbo].[viewMPWaitingForApproval]    Script Date: 10/25/2026 4:57:09 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO





CREATE VIEW [dbo].[viewMPWaitingForApproval]
AS
SELECT        COUNT(bmID) AS TotalBM, Location,
                             (SELECT        COUNT(BMStatusID) AS GLTotal
                               FROM            dbo.MPBMMaintenance AS b
                               WHERE        (BMStatusID = 1) AND (Location = a.Location)) AS WaitingForGLApprovalTotal,
                             (SELECT        COUNT(BMStatusID) AS PMTotal
                               FROM            dbo.MPBMMaintenance AS c
                               WHERE        (BMStatusID = 2) AND (Location = a.Location)) AS WaitingForPMApprovalTotal,
                             (SELECT        COUNT(BMStatusID) AS OnGoingPMTotal
                               FROM            dbo.MPBMMaintenance AS d
                               WHERE        (BMStatusID = 3) AND (Location = a.Location)) AS OnGoingPMTotal,
                             (SELECT        COUNT(BMStatusID) AS PMRepairDoneTotal
                               FROM            dbo.MPBMMaintenance AS e
                               WHERE        (BMStatusID = 4) AND (Location = a.Location)) AS PMRepairDoneTotal,
                             (SELECT        COUNT(BMStatusID) AS GLReturnedToPMTotal
                               FROM            dbo.MPBMMaintenance AS f
                               WHERE        (BMStatusID = 5) AND (Location = a.Location)) AS GLReturnedToPMTotal,
                             (SELECT        COUNT(BMStatusID) AS EETotal
                               FROM            dbo.MPBMMaintenance AS g
                               WHERE        (BMStatusID = 6) AND (Location = a.Location)) AS WaitingForEEApprovalTotal,
                             (SELECT        COUNT(BMStatusID) AS OngoingPERepairTotal
                               FROM            dbo.MPBMMaintenance AS h
                               WHERE        (BMStatusID = 7) AND (Location = a.Location)) AS OngoingPERepairTotal,
                             (SELECT        COUNT(BMStatusID) AS PERepairDoneTotal
                               FROM            dbo.MPBMMaintenance AS i
                               WHERE        (BMStatusID = 8) AND (Location = a.Location)) AS PERepairDoneTotal,
                             (SELECT        COUNT(BMStatusID) AS ReturnedToPETotal
                               FROM            dbo.MPBMMaintenance AS j
                               WHERE        (BMStatusID = 9) AND (Location = a.Location)) AS ReturnedToPETotal,
                             (SELECT        COUNT(BMStatusID) AS PMTurnoverApprovalTotal
                               FROM            dbo.MPBMMaintenance AS k
                               WHERE        (BMStatusID = 10) AND (Location = a.Location)) AS PMTurnoverApprovalTotal,
                             (SELECT        COUNT(BMStatusID) AS AccApprovalTotal
                               FROM            dbo.MPBMMaintenance AS l
                               WHERE        (BMStatusID = 11) AND (Location = a.Location)) AS AccApprovalTotal,
                             (SELECT        COUNT(BMStatusID) AS AccReturnedtoPM
                               FROM            dbo.MPBMMaintenance AS m
                               WHERE        (BMStatusID = 12) AND (Location = a.Location)) AS AccReturnedtoPM,
                             (SELECT        COUNT(BMStatusID) AS PMReturnedtoPM
                               FROM            dbo.MPBMMaintenance AS n
                               WHERE        (BMStatusID = 13) AND (Location = a.Location)) AS PMReturnedtoPM,
                             (SELECT        COUNT(BMStatusID) AS BMClosed
                               FROM            dbo.MPBMMaintenance AS o
                               WHERE        (BMStatusID = 14) AND (Location = a.Location)) AS BMClosed,
                             (SELECT        COUNT(BMStatusID) AS BMInvalid
                               FROM            dbo.MPBMMaintenance AS p
                               WHERE        (BMStatusID = 15) AND (Location = a.Location)) AS BMOcapResolved,
                             (SELECT        COUNT(BMStatusID) AS BMInvalid
                               FROM            dbo.MPBMMaintenance AS q
                               WHERE        (BMStatusID = 30) AND (Location = a.Location)) AS BMInvalid,
                             (SELECT        COUNT(BMStatusID) AS BMVoid
                               FROM            dbo.MPBMMaintenance AS r
                               WHERE        (BMStatusID = 31) AND (Location = a.Location)) AS BMVoid

FROM            dbo.MPBMMaintenance AS a
GROUP BY Location


GO
