CREATE VIEW [dbo].[viewProcBMTotal]
AS
SELECT   (SELECT   COUNT(BMStatusID) AS FLTotal
                          FROM         dbo.FLBMMaintenance AS b
                          WHERE     (BMStatusID = a.BMStatusID)) AS FLTotal,
                             (SELECT   COUNT(BMStatusID) AS TPTotal
                                FROM         dbo.TPBMMaintenance AS c
                                WHERE     (BMStatusID = a.BMStatusID)) AS TPTotal,
                             (SELECT   COUNT(BMStatusID) AS DCTotal
                                FROM         dbo.DCBMMaintenance AS d
                                WHERE     (BMStatusID = a.BMStatusID)) AS DCTotal,
                             (SELECT   COUNT(BMStatusID) AS DBTotal
                                FROM         dbo.DBBMMaintenance AS d
                                WHERE     (BMStatusID = a.BMStatusID)) AS DBTotal,
                             (SELECT   COUNT(BMStatusID) AS WBTotal
                                FROM         dbo.WBBMMaintenance AS d
                                WHERE     (BMStatusID = a.BMStatusID)) AS WBTotal,
                             (SELECT   COUNT(BMStatusID) AS MPTotal
                                FROM         dbo.MPBMMaintenance AS d
                                WHERE     (BMStatusID = a.BMStatusID)) AS MPTotal,
                             (SELECT   COUNT(BMStatusID) AS PLTotal
                                FROM         dbo.PLBMMaintenance AS d
                                WHERE     (BMStatusID = a.BMStatusID)) AS PLTotal,
                             (SELECT   COUNT(BMStatusID) AS MEMSTotal
                                FROM         dbo.MEMSBMMaintenance AS d
                                WHERE     (BMStatusID = a.BMStatusID)) AS MEMSTotal,
                             (SELECT   COUNT(BMStatusID) AS EDSTotal
                                FROM         dbo.EDSBMMaintenance AS d
                                WHERE     (BMStatusID = a.BMStatusID)) AS EDSTotal,
                             (SELECT   COUNT(BMStatusID) AS FTTotal
                                FROM         dbo.FTBMMaintenance AS d
                                WHERE     (BMStatusID = a.BMStatusID)) AS FTTotal,
						-- Add 2 process 07/03/2025
							(SELECT   COUNT(BMStatusID) AS ATCTotal
                                FROM         dbo.ATCBMMaintenance AS d
                                WHERE     (BMStatusID = a.BMStatusID)) AS ATCTotal,
							(SELECT   COUNT(BMStatusID) AS SINGTotal
                                FROM         dbo.SINGBMMaintenance AS d
                                WHERE     (BMStatusID = a.BMStatusID)) AS SINGTotal
FROM         dbo.BMStatus AS a
WHERE     (BMStatusID = 6)
GO
