SELECT        [BMId],
                             (SELECT        FirstName
                               FROM            dbo.tbl_SMSContacts AS d
                               WHERE        d .Process = b.Process AND d .Position = 'GDM') AS FirstName,
                             (SELECT        LastName
                               FROM            dbo.tbl_SMSContacts AS d
                               WHERE        d .Process = b.Process AND d .Position = 'GDM') AS LastName,
                             (SELECT        CellNumber
                               FROM            dbo.tbl_SMSContacts AS d
                               WHERE        d .Process = b.Process AND d .Position = 'GDM') AS CellNumber,
                             (SELECT        BMStatus
                               FROM            [eMaintenanceSystemDB].[dbo].[BMStatus] AS a
                               WHERE        a.BMStatusID = b.BMStatusID) AS BMStatus,
                             (SELECT        [PMCategory]
                               FROM            [eMaintenanceSystemDB].[dbo].[PMCategory] AS c
