/****** Object:  View [dbo].[gridPLMachineHistory]    Script Date: 10/25/2026 4:57:09 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[gridPLMachineHistory]
AS
SELECT        dbo.PLBMMaintenance.bmID, dbo.PLBMMaintenance.BMStatusID, dbo.PLBMMaintenance.SubProcessID, dbo.PLBMMaintenance.PMCategoryID, dbo.PLBMMaintenance.MCNo, dbo.PLBMMaintenance.MCStatus, 
                         dbo.PLBMMaintenance.MCType, dbo.PLBMMaintenance.LOTNo, dbo.PLBMMaintenance.DeviceName, dbo.PLBMMaintenance.PkgName, dbo.PLBMMaintenance.RequestItem, dbo.BMMCUnit.BMMCUnit, 
                         dbo.PLBMMaintenance.OccurrenceDate, dbo.PLBMMaintenance.Why1, dbo.PLBMMaintenance.Why2, dbo.PLBMMaintenance.Why3, dbo.BMWhy.BMWhy, dbo.PLBMMaintenance.Treatment1, 
                         dbo.PLBMMaintenance.Treatment2, dbo.PLBMMaintenance.Treatment3, dbo.PLBMMaintenance.Treatment4, dbo.PLBMMaintenance.Treatment5, dbo.PLBMMaintenance.Treatment6, dbo.PLBMMaintenance.Treatment7, 
                         dbo.PLBMMaintenance.Treatment8, dbo.PLBMMaintenance.Treatment9, dbo.PLBMMaintenance.Treatment10, dbo.PLBMMaintenance.Treatment11, dbo.PLBMMaintenance.Treatment12, dbo.PLBMMaintenance.Treatment13, 
                         dbo.PLBMMaintenance.Treatment14, dbo.PLBMMaintenance.TimeOfRequest, dbo.PMCategory.PMCategory, dbo.PLBMMaintenance.RequestedBy, dbo.SubProcess.SubProcess
FROM            dbo.BMStatus INNER JOIN
                         dbo.PLBMMaintenance ON dbo.BMStatus.BMStatusID = dbo.PLBMMaintenance.BMStatusID INNER JOIN
                         dbo.PMCategory ON dbo.PLBMMaintenance.PMCategoryID = dbo.PMCategory.PMCategoryID LEFT OUTER JOIN
                         dbo.BMMCUnit ON dbo.PLBMMaintenance.OPBMUnitID = dbo.BMMCUnit.BMMCUnitID LEFT OUTER JOIN
                         dbo.BMWhy ON dbo.PLBMMaintenance.Why4 = dbo.BMWhy.BMWhyID LEFT OUTER JOIN
                         dbo.SubProcess ON dbo.PLBMMaintenance.SubProcessID = dbo.SubProcess.SubProcessID
GO
