                         dbo.FLBMMaintenance.LOTNo AS [Lot Number], dbo.FLBMMaintenance.DeviceName AS [Device Name],
                             (SELECT        CASE WHEN dbo.FLBMMaintenance.BMStatusID = 14 THEN PMCategory.PMCategory ELSE PMCategory_1.PMCategory END AS PMCategory) AS Classification, 
                         dbo.FLBMMaintenance.NGDetectionCircumtances AS [NG Detection Circumstance], dbo.FLBMMaintenance.RequestItem AS [Case Name], dbo.FLBMMaintenance.RequestContent AS [Request Content], 
                         dbo.FLBMMaintenance.Situation AS Condition, dbo.FLBMMaintenance.OccurrenceFreq AS [Occurrence Rate Before Condition], dbo.FLBMMaintenance.OccurrenceFreqQuantity AS Quantity1, 
                         dbo.FLBMMaintenance.OccurrenceFreqLotFrame AS Quantity2, dbo.FLBMMaintenance.AQI, dbo.FLBMMaintenance.OccurrenceDate AS [Request Date and Time], dbo.FLBMMaintenance.RequestedBy AS Issuer, 
                         dbo.FLBMMaintenance.GLConfirmOPReqBy AS GL, dbo.FLBMMaintenance.GLConfirmOPReqDate AS [GL Confirmed Date], dbo.FLBMMaintenance.PMConfirmGLOPReqBy AS [PM Confirmed Request],
                             (SELECT        CASE WHEN dbo.FLBMMaintenance.Turnover = 'PE' OR
                                                         dbo.FLBMMaintenance.Turnover = 'CC' OR
                                                         dbo.FLBMMaintenance.Turnover = 'VIS' THEN '' ELSE dbo.FLBMMaintenance.RepairedByEnd END AS Expr1) AS [PM Done Request], dbo.FLBMMaintenance.PMConfirmGLOPReqDate AS [START DATE AND TIME],
                             (SELECT        CASE WHEN dbo.FLBMMaintenance.Turnover = 'PE' OR
                                                         dbo.FLBMMaintenance.Turnover = 'CC' OR
                                                         dbo.FLBMMaintenance.Turnover = 'VIS' THEN dbo.FLBMMaintenance.PMTurnOvertoPEDate ELSE dbo.FLBMMaintenance.EndOfRepair END AS Expr1) AS [END DATE AND TIME], 
                         dbo.FLBMMaintenance.PEConfirmPMTurnoverBy AS [PE Confirmed Request],
                             (SELECT        CASE WHEN dbo.FLBMMaintenance.Turnover = 'PE' OR
                                                         dbo.FLBMMaintenance.Turnover = 'CC' OR
                                                         dbo.FLBMMaintenance.Turnover = 'VIS' THEN dbo.FLBMMaintenance.RepairedByEnd ELSE '' END AS Expr1) AS [PE Done Request], 
