                             (SELECT        CASE WHEN dbo.FLBMMaintenance.Turnover = 'PE' OR
                                                         dbo.FLBMMaintenance.Turnover = 'CC' OR
                                                         dbo.FLBMMaintenance.Turnover = 'VIS' THEN dbo.FLBMMaintenance.EndOfRepair ELSE NULL END AS Expr1) AS [PE END DATE AND TIME], dbo.FLBMMaintenance.Why1, dbo.FLBMMaintenance.Why2, 
