                                                         dbo.PLBMMaintenance.BMStatusID = '11' OR
                                                         dbo.PLBMMaintenance.BMStatusID = '13' THEN CASE WHEN dbo.PLBMMaintenance.isnotquality2 = 'No' AND 
                                                         dbo.PLBMMaintenance.isnotquality3 = 'No' THEN 'Yes' ELSE 'No' END ELSE 'No' END AS IsQualityBM) AS IsQualityBM, dbo.PLBMMaintenance.EndBM AS AccreditorTimeStamp
FROM            dbo.PLBMMaintenance LEFT OUTER JOIN
                         dbo.BMWhy ON dbo.PLBMMaintenance.Why4 = dbo.BMWhy.BMWhyID LEFT OUTER JOIN
                         dbo.BMWhy AS BMWhy_2 ON dbo.PLBMMaintenance.AcredBMCauseID = BMWhy_2.BMWhyID LEFT OUTER JOIN
                         dbo.BMWorkContent ON dbo.PLBMMaintenance.AcredBMWorkContentID = dbo.BMWorkContent.BMWorkContentID LEFT OUTER JOIN
                         dbo.BMPoint ON dbo.PLBMMaintenance.AcredBMPointID = dbo.BMPoint.BMPointID LEFT OUTER JOIN
                         dbo.BMMCUnit ON dbo.PLBMMaintenance.AcredBMMCUnitID = dbo.BMMCUnit.BMMCUnitID LEFT OUTER JOIN
                         dbo.BMCase ON dbo.PLBMMaintenance.AcredBMCaseID = dbo.BMCase.BMCaseID LEFT OUTER JOIN
                         dbo.PMCategory ON dbo.PLBMMaintenance.AcredPMCategoryID = dbo.PMCategory.PMCategoryID LEFT OUTER JOIN
                         dbo.BMWhy AS BMWhy_1 ON dbo.PLBMMaintenance.AcredBMCauseID = BMWhy_1.BMWhyID LEFT OUTER JOIN
                         dbo.PREVMeasure ON dbo.PLBMMaintenance.AcredPREVMeasureID = dbo.PREVMeasure.PREVMeasureID LEFT OUTER JOIN
                         dbo.BMWorkContent AS BMWorkContent_1 ON dbo.PLBMMaintenance.BMWorkContentID = BMWorkContent_1.BMWorkContentID LEFT OUTER JOIN
                         dbo.BMPoint AS BMPoint_1 ON dbo.PLBMMaintenance.BMPointID = BMPoint_1.BMPointID LEFT OUTER JOIN
                         dbo.BMCase AS BMCase_1 ON dbo.PLBMMaintenance.BMCaseID = BMCase_1.BMCaseID LEFT OUTER JOIN
                         dbo.BMMCUnit AS BMMCUnit_1 ON dbo.PLBMMaintenance.BMUnitID = BMMCUnit_1.BMMCUnitID LEFT OUTER JOIN
                         dbo.BMContent AS BMContent_1 ON dbo.PLBMMaintenance.BMContentID = BMContent_1.BMContentID LEFT OUTER JOIN
                         dbo.PMCategory AS PMCategory_1 ON dbo.PLBMMaintenance.PMCategoryID = PMCategory_1.PMCategoryID LEFT OUTER JOIN
                         dbo.BMContent ON dbo.PLBMMaintenance.AcredBMContentID = dbo.BMContent.BMContentID
GO
