        --a.PMConfirmGLOPReqDate,
        a.StartOfRepair,
        a.TotalStopTime,
        a.EEEWaitingStart,
        a.EEEWaitingEnd,
        a.PMCategoryID,
        a.SubProcessID,
        a.MCStatus,
        a.MCType,
        a.RequestItem,
        a.OccurrenceDate,
        a.NGDetectionCircumtances,
        a.RequestContent,
        a.OccurrenceFreq,
        a.OccurrenceFreqQuantity,
        a.OccurrenceFreqLotFrame,
        a.OccurFreqUnit,
        a.OccMode,
        a.LOTNo,
        a.DeviceName,
        a.PkgName,
        a.LineLoc,
        a.AQI,
        a.Andon,
        a.GLAndon,
        a.GLAndon2,
		a.GLConfirmOPReqDate,
		a.TimeOfRequest,
		a.GLConfirmOPReqReason,
		a.GLConfirmOPReqBy,
		a.PMConfirmGLOPReason,
        b.*,
        w.BMWhy AS BMWhy4,
        c.BMCase
    FROM WBBMMaintenance a
    LEFT JOIN EEEBMMaintenance b ON a.bmId = b.bm_ID
    LEFT JOIN dbo.BMWhy w ON a.Why4 = w.BMWhyID  
    LEFT JOIN dbo.BMCase c ON a.BMCaseID = c.BMCaseID  
    WHERE @Process = 'WB'

	UNION ALL

    SELECT 
        a.MCNo,
        a.Location,
        a.bmID,
        a.BMCaseID,
        a.Turnover,
        a.BMVersionNo,
        a.BMRouteNo,
        a.ConditionAfterAdj,
