CREATE VIEW [dbo].[viewDCBMAnalysis]
AS
SELECT *,
    CASE WHEN RepairingTime > 359 AND RepairingTime < 720
	THEN 1 ELSE 0 END AS '6hrs above',
	CASE WHEN RepairingTime > 719 AND RepairingTime < 1440 
	THEN 1 ELSE 0 END AS '12hrs above',
	CASE WHEN RepairingTime > 1439
	THEN 1 ELSE 0 END AS '24hrs above',
	CASE WHEN 'MC No' IS NOT NULL
	THEN 1 ELSE 0 END AS 'BM Count'
FROM(SELECT
		MCNo as 'MC No', MCType as 'MC Type', PkgName as 'Package' , KanagataNo as 'Kanagata Number', LOTNo as 'Lot Number', DeviceName as 'Device Name', c.PMCategory as 'Classification', NGDetectionCircumtances as 'NG Detection Circumstance', RequestItem as 'Case Name', RequestContent as 'Request Content', Situation as 'Condition', OccurrenceFreq as 'Occurrence Rate Before Condition', OccurrenceFreqQuantity as 'Quantity 1', OccurrenceFreqLotFrame as 'Quantity 2', a.AQI, a.OccurrenceDate as 'Request Date and Time', RequestedBy as 'Issuer', GLConfirmOPReqBy as 'GL', GLConfirmOPReqDate as 'GL Confirmed Date', RepairedByStart as 'PM Confirmed Request', RepairedByEnd as 'PM Done Request', StartOfRepair as 'START DATE AND TIME', EndOfRepair as 'END DATE AND TIME', PEConfirmPMTurnoverBy as 'PE Confirmed Request', RepairedByEnd as 'PE Done Request', null as 'PE START DATE AND TIME', null as 'PE END DATE AND TIME', a.Why1, a.Why2, a.Why3, a.Why4, a.Treatment1, a.Treatment2, a.Treatment3, a.Treatment4, a.Treatment5, a.Treatment6, a.Treatment7, a.Treatment8, a.Treatment9, a.Treatment10, a.Treatment11, a.Treatment12, a.Treatment13, a.Treatment14, MajorTreatment as 'COUNTERMEASURE1', ConditionAfterAdj as 'AFTER CONDITION', ConditionAfterAdjMin as 'AFTER CONDITION QUANTITY1', ConditionAfterAdjMax as 'AFTER CONDITION QUANTITY2', UseDummyFrames as 'USING DUMMY PRODUCT', DummyIn as 'DUMMY IN', DummyOut as 'DUMMY OUT', DroppedWork as 'CHECKING DROPPED WORK', DroppedWorkBeforePM as 'DROPPED WORK BEFORE', DroppeWorkAfterPM as 'DROPPED WORK AFTER', ItemValueChecked as 'ITEM/VALUE CHECKED', ChangedValueChecked as 'CHANGED/CHECKED VALUE', ReqSATInsp as 'REQUEST FOR SAT INSPECTION', SATInspResult as 'SAT INSPECTION RESULT', SATInspResultStatus as 'SAT INSPECTION', CheckSensorColorNo as 'CHECK SENSOR COLOR AND NO.', CheckSensorReaction as 'CHECK SENSOR REACTION', MotionSafetyCoverSwitch as 'MOTION OF SAFETY COVER SWITCH', Check5SAfterPMWork as '5S AFTER PM WORK', SelconReg as 'SELCON REGISTRATION', PrevAdjValue as 'PREVIOUS ADJUSTMENT', InspectionReq as 'INSPECTION REQUEST', InspQtyNeeded as 'INSPECTION QTY NEEDED', CheckItem as 'CHECK ITEM1', CheckItem1 as 'CHECK ITEM2', CheckItem2 as 'CHECK ITEM3', CheckItem3 as 'CHECK ITEM4', RequestToPD as 'REQUEST TO', PDConfirmation as 'PD CONFIRMATION', InspectionResults as 'INSPECTION RESULTS', PDTreatmentInCharge as 'PD TREATMENT/ INCHARGE', ChangePartsName1 as 'PARTS 1', ChangePartsType1 as 'TYPE1', ChangePartsQty1 as 'QTY1', ChangePartsNewReworked1 as 'PARTS REPLACED1', ChangePartsDate1 as 'CHANGE PARTS DATE1', ChangePartsMonthDay1 as 'REMARKS/LIFE1', ChangePartsInsNewReworked1 as 'PARTS INSTALLED1', ChangePartsName2 as 'PARTS 2', ChangePartsType2 as 'TYPE2', ChangePartsQty2 as 'QTY2', ChangePartsNewReworked2 as 'PARTS REPLACED2', ChangePartsDate2 as 'CHANGE PARTS DATE2', ChangePartsMonthDay2 as 'REMARKS/LIFE2', ChangePartsInsNewReworked2 as 'PARTS INSTALLED2', ChangePartsName3 as 'PARTS 3', ChangePartsType3 as 'TYPE3', ChangePartsQty3 as 'QTY3', ChangePartsNewReworked3 as 'PARTS REPLACED3', ChangePartsDate3 as 'CHANGE PARTS DATE3', ChangePartsMonthDay3 as 'REMARKS/LIFE3', ChangePartsInsNewReworked3 as 'PARTS INSTALLED3', ChangePartsName4 as 'PARTS 4', ChangePartsType4 as 'TYPE4', ChangePartsQty4 as 'QTY4', ChangePartsNewReworked4 as 'PARTS REPLACED4', ChangePartsDate4 as 'CHANGE PARTS DATE4', ChangePartsMonthDay4 as 'REMARKS/LIFE4', ChangePartsInsNewReworked4 as 'PARTS INSTALLED4', ChangePartsName5 as 'PARTS 5', ChangePartsType5 as 'TYPE5', ChangePartsQty5 as 'QTY5', ChangePartsNewReworked5 as 'PARTS REPLACED5', ChangePartsDate5 as 'CHANGE PARTS DATE5', ChangePartsMonthDay5 as 'REMARKS/LIFE5', ChangePartsInsNewReworked5 as 'PARTS INSTALLED5', TypeofRequest as 'TYPE OF REQUEST', PMConfirmGLOPReason as 'INVALID REQUEST REASON', c.PMCategory as 'PM CATEGORY', b.BMContent as 'BM CONTENT', RequestItem as 'CASE', Situation as 'MACHINE UNIT', f.BMPoint as 'POSITION', RequestItem as 'WORK CONTENT', d.BMCase as 'BM CAUSE', j.PREVMeasure as 'PREVENTIVE MEASURE', AccreditorRemarks as 'IN-CHARGE REMARKS', AccreditorPMReply as 'PM REMARKS', i.BM4M as '4M ANALYSIS TYPE', i.BMWhy as '4M ANALYSIS', c.PMCategory as 'IN-CHARGE PM CATEGORY', b.BMContent as 'IN-CHARGE-CONTENT', d.BMCase as 'IN-CHARGE CASE', g.BMMCUnit as 'IN-CHARGE MACHINE UNIT', f.BMPoint as 'IN-CHARGE POSITION', h.BMWorkContent as 'IN-CHARGE WORK CONTENT', i.BMWhy as 'IN-CHARGE CAUSE', j.PREVMeasure as 'IN-CHARGE PREVENTIVE MEASURE', AcredINSPN as 'PERIODIC RELATED BM', a.Process as 'PROCESS', a.Location as 'LOCATION',

		CASE WHEN PMTurnOvertoPEDate IS NULL
		THEN CAST(DATEDIFF(SECOND, StartOfRepair, EndOfRepair) AS decimal(10, 2)) / 60.0
		ELSE CAST(DATEDIFF(SECOND, StartOfRepair, PMTurnOvertoPEDate) AS decimal(10, 2)) / 60.0 END AS RepairingTime,

		CASE WHEN bmStatusID IN (11, 14, 13) AND a.isNotQuality2 = 'No' AND a.isNotQuality3 = 'No' 
		THEN 'Yes' ELSE 'No' END AS isQualityBM

    FROM DCBMMaintenance as a
	INNER JOIN dbo.BMContent AS b ON a.BMContentID = b.BMContentID
	INNER JOIN dbo.PMCategory AS c ON a.PMCategoryID = c.PMCategoryID
	INNER JOIN dbo.BMCase AS d ON a.BMCaseID = d.BMCaseID	
	LEFT JOIN dbo.BMPoint AS f ON a.BMPointID = f.BMPointID
	INNER JOIN dbo.BMMCUnit AS g ON a.BMUnitID = g.BMMCUnitID
	INNER JOIN dbo.BMWorkContent AS h ON a.BMWorkContentID = h.BMWorkContentID
	INNER JOIN dbo.BMWhy AS i ON a.AcredBMCauseID = i.BMWhyID
	LEFT JOIN dbo.PREVMeasure j ON a.AcredPREVMeasureID = j.PREVMeasureID) AS Query

	WHERE [Request Date and Time] > '2024-01-01' 

GO
