GO
CREATE VIEW [dbo].[view3HoursSM]
AS
SELECT        dbo.PMContacts.Name, dbo.PMContacts.CellNumber, dbo.view3HoursBM.BMId, dbo.view3HoursBM.BMStatus, dbo.view3HoursBM.PMCategory, dbo.view3HoursBM.Process, dbo.view3HoursBM.Location, 
                         dbo.view3HoursBM.MCNo, dbo.view3HoursBM.MCType, dbo.view3HoursBM.LOTNo, dbo.view3HoursBM.DeviceName, dbo.view3HoursBM.PkgName, dbo.view3HoursBM.RequestItem, dbo.view3HoursBM.OccurrenceDate, 
                         dbo.view3HoursBM.RequestContent, dbo.view3HoursBM.RequestedBy, dbo.view3HoursBM.StartOfRepair, dbo.view3HoursBM.RepairedByStart, dbo.view3HoursBM.CurrentPM, dbo.view3HoursBM.TurnoverPM, 
                         dbo.view3HoursBM.TimeTurnover, dbo.view3HoursBM.Turnover, DATEDIFF(HOUR, dbo.view3HoursBM.OccurrenceDate, GETDATE()) AS 'BMHours'
FROM            dbo.PMContacts INNER JOIN
                         dbo.view3HoursBM ON dbo.PMContacts.ProcessLocation = dbo.view3HoursBM.ProcessLocation
WHERE        (dbo.PMContacts.Position = 'SM')
GO
