    gdf.Treatment11, 
    gdf.Treatment12, 
    gdf.Treatment13, 
    gdf.Treatment14, 
    dbo.BMWhy.BMWhy, 
    gdf.TimeOfRequest, 
    dbo.PMCategory.PMCategory, 
    gdf.RequestedBy, 
    gdf.Why1, 
    gdf.Why2, 
    gdf.Why3,
    'TP' AS Process
FROM 
    dbo.GetDataFunction('TP') AS gdf
    INNER JOIN dbo.BMStatus 
        ON dbo.BMStatus.BMStatusID = gdf.BMStatusID
    INNER JOIN dbo.PMCategory 
        ON gdf.PMCategoryID = dbo.PMCategory.PMCategoryID
    LEFT OUTER JOIN dbo.BMWhy 
        ON gdf.Why4 = dbo.BMWhy.BMWhyID
    LEFT OUTER JOIN dbo.SubProcess 
        ON gdf.SubProcessID = dbo.SubProcess.SubProcessID

UNION ALL

SELECT 
    gdf.bmID, 
    gdf.BMStatusID, 
    gdf.SubProcessID, 
    gdf.PMCategoryID, 
    gdf.MCNo, 
    gdf.MCStatus, 
    gdf.MCType, 
    gdf.LOTNo, 
    gdf.DeviceName, 
    gdf.PkgName, 
    gdf.RequestItem, 
    gdf.OccurrenceDate, 
    dbo.BMStatus.BMStatus, 
    dbo.SubProcess.SubProcess, 
    gdf.Treatment1, 
    gdf.Treatment2, 
    gdf.Treatment3, 
    gdf.Treatment4, 
    gdf.Treatment5, 
    gdf.Treatment6, 
    gdf.Treatment7, 
    gdf.Treatment8, 
    gdf.Treatment9, 
    gdf.Treatment10, 
    gdf.Treatment11, 
    gdf.Treatment12, 
    gdf.Treatment13, 
    gdf.Treatment14, 
    dbo.BMWhy.BMWhy, 
    gdf.TimeOfRequest, 
    dbo.PMCategory.PMCategory, 
    gdf.RequestedBy, 
    gdf.Why1, 
    gdf.Why2, 
    gdf.Why3,
    'MEMS' AS Process
FROM 
    dbo.GetDataFunction('MEMS') AS gdf
    INNER JOIN dbo.BMStatus 
        ON dbo.BMStatus.BMStatusID = gdf.BMStatusID
    INNER JOIN dbo.PMCategory 
        ON gdf.PMCategoryID = dbo.PMCategory.PMCategoryID
    LEFT OUTER JOIN dbo.BMWhy 
        ON gdf.Why4 = dbo.BMWhy.BMWhyID
    LEFT OUTER JOIN dbo.SubProcess 
        ON gdf.SubProcessID = dbo.SubProcess.SubProcessID
GO
