                         dbo.SubProcess ON dbo.SINGBMMaintenance.SubProcessID = dbo.SubProcess.SubProcessID LEFT OUTER JOIN
                         dbo.BMStatus ON dbo.SINGBMMaintenance.BMStatusID = dbo.BMStatus.BMStatusID LEFT OUTER JOIN
                         dbo.PMCategory ON dbo.SINGBMMaintenance.PMCategoryID = dbo.PMCategory.PMCategoryID LEFT OUTER JOIN
