    FROM [10.20.10.253].[SELCONDB].[dbo].[ViewMachineRequest]
    WHERE MachineName = @Mcno
      AND Signal <> 'SC'
      AND TimeReceived BETWEEN @date1 AND @date2

    UNION

    SELECT 
        'SC' AS Status, Machinename AS Machine, AlarmTimeOccur AS Timestamp, 
        alarmno AS Column1, alarmdescription AS Column2, '' AS Column3
    FROM [10.20.10.253].[SELCONDB].[dbo].[ViewDBAlarm]
