) AS Combined
ORDER BY 
    Timestamp ASC,
    CASE Status
        WHEN 'WT'      THEN 1
        WHEN 'GT'      THEN 2
        WHEN 'MT'      THEN 3
        WHEN 'Unknown' THEN 4
        ELSE 5
    END ASC;

WITH InputRowNum AS (
