    FROM InputRowNum a
    JOIN MTRanges r 
      ON a.RowNum > r.MinRowNum AND a.RowNum <= r.MaxRowNum
),
UpdateTargetsCTE AS (
    SELECT 
        source.Status,
        source.Machine,
        target.Timestamp,
        source.Column1,
