        source.Column3,
        source.RowNum
    FROM DeleteTargets AS target
    JOIN DeleteTargets AS source
      ON target.Machine = source.Machine
    JOIN MTRanges AS r
      ON target.Machine = r.Machine
    WHERE target.RowNum = r.MaxRowNum
      AND source.RowNum = r.MaxRowNum - 1
)

SELECT Status, Machine, Timestamp, Column1, Column2, Column3
INTO #UpdateTargetsDB
