MTSignals_MT AS (
    SELECT TOP 1 RowNum, Column3, Machine
    FROM InputRowNum
    WHERE Status = 'MT' 
    ORDER BY RowNum ASC 
),
MTRanges_GT AS (
    SELECT a.Column3, a.Machine,
           a.RowNum AS MinRowNum,
           b.RowNum AS MaxRowNum
    FROM MTSignals_GT a
    CROSS JOIN MTSignals_MT b
),
DeleteTargets_GT AS (
    SELECT a.*
    FROM InputRowNum a
    JOIN MTRanges_GT r 
      ON a.RowNum > r.MinRowNum AND a.RowNum <= r.MaxRowNum - 1
)

DELETE cs
FROM #CombinedStatusTP cs
JOIN DeleteTargets_GT dt 
  ON cs.Timestamp = dt.Timestamp 
  AND cs.Status = dt.Status;

SELECT * 
FROM #CombinedStatusTP 
ORDER BY 
    Timestamp ASC,
    CASE Status
        WHEN 'WT'      THEN 1
        WHEN 'GT'      THEN 2
        WHEN 'MT'      THEN 3
        WHEN 'Unknown' THEN 4
        ELSE 5
    END ASC;
	-------------------------------------------------------------------------------------------------------------------------------------------------------
      END
	  ------------------------------------------------------------------------------------------------------------------------------------------
      
END
