CREATE PROCEDURE [dbo].[24hrsMachinePerformance_GetDataOutputs]
      @Process VARCHAR(50),
      @Mcno VARCHAR(50),
	  @date1 varchar(50),
	  @date2 varchar(50)
AS
BEGIN
      SET NOCOUNT ON;
	 
      IF @Process = 'MP'
		BEGIN
					SELECT 
						--CAST(ROUND(AVG(MTTR), 2) AS FLOAT) AS MTTR,
						CAST(ROUND(AVG(alarmtime / (AlarmCount + 1)), 2) AS FLOAT) AS MTTR,
						CAST(ROUND(AVG(runtime / (AlarmCount + 1)), 2) AS FLOAT) AS MTBA,
						SUM(good + totalng) AS OutputQty,
						CAST(ROUND(AVG(good / runtime), 2) AS FLOAT) AS RPM,
						SUM(AlarmCount) AS AlarmQty
						FROM [10.20.10.253].[SELCONDB].[dbo].[MPData]
						WHERE machinename = @Mcno and runtime <> 0.00
						AND starttime BETWEEN @date1 AND @date2
      END        
      ELSE IF @process = 'DB'
	  	BEGIN
						SELECT 
							--CAST(ROUND(AVG(MTTR), 2) AS FLOAT) AS MTTR,
							CAST(ROUND(AVG(alarmtime / (alarmqty + 1)), 2) AS FLOAT) AS MTTR,
							CAST(ROUND(AVG(runtime / (alarmqty + 1)), 2) AS FLOAT) AS MTBA,
							SUM(good + ng) AS OutputQty,
							CAST(ROUND(AVG(good / runtime), 2) AS FLOAT) AS RPM,
							SUM(alarmqty) AS AlarmQty
						FROM [10.20.10.253].[SELCONDB].[dbo].[DBData]
						WHERE machinename = @Mcno and runtime <> 0.00
						AND starttime BETWEEN @date1 AND @date2
						  END
	   ELSE IF @process = 'DC'
	   	BEGIN
			select '' as MTTR,'' as MTBA,'' as OutputQty,'' as RPM
			  END
	   ELSE IF @process = 'PL'
	   	BEGIN
			select '' as MTTR,'' as MTBA,'' as OutputQty,'' as RPM
			  END
	   ELSE IF @process = 'WB'
	   	BEGIN
						SELECT 
							--CAST(ROUND(AVG(MTTR), 2) AS FLOAT) AS MTTR,
								CAST(ROUND(AVG(alarmtime / (AlarmQty + 1)), 2) AS FLOAT) AS MTTR,
							CAST(ROUND(AVG(runtime / (AlarmQty + 1)), 2) AS FLOAT) AS MTBA,
							SUM(good + ng) AS OutputQty,
							CAST(ROUND(AVG(good / runtime), 2) AS FLOAT) AS RPM,
							SUM(alarmqty) AS AlarmQty
						FROM [10.20.10.253].[SELCONDB].[dbo].[DBData]
						WHERE machinename = @Mcno and runtime <> 0.00
						AND starttime BETWEEN @date1 AND @date2
						  END
	   ELSE IF @process = 'FL'
	   	BEGIN
						SELECT 
							--CAST(ROUND(AVG(MTTR), 2) AS FLOAT) AS MTTR,
							CAST(ROUND(AVG(alarmtime / (AlarmCount + 1)), 2) AS FLOAT) AS MTTR,
							CAST(ROUND(AVG(runtime / (AlarmCount + 1)), 2) AS FLOAT) AS MTBA,
							SUM(TotalGood + totalng) AS OutputQty,
							CAST(ROUND(AVG(TotalGood / runtime), 2) AS FLOAT) AS RPM,
							SUM(AlarmCount) AS AlarmQty
						FROM [10.20.10.253].[SELCONDB].[dbo].[FLData]
						WHERE machinename = @Mcno and runtime <> 0.00
						AND starttime BETWEEN @date1 AND @date2
						  END
	   ELSE IF @process = 'FT'
	   	BEGIN
						SELECT 
							--CAST(ROUND(AVG(MTTR), 2) AS FLOAT) AS MTTR,
							CAST(ROUND(AVG(alarmtime / (AlarmCount + 1)), 2) AS FLOAT) AS MTTR,
							CAST(ROUND(AVG(runtime / (AlarmCount + 1)), 2) AS FLOAT) AS MTBA,
							SUM(Good + totalng) AS OutputQty,
							CAST(ROUND(AVG(Good / runtime), 2) AS FLOAT) AS RPM,
							SUM(AlarmCount) AS AlarmQty
						FROM [10.20.10.253].[SELCONDB].[dbo].[FTData]
						WHERE machinename = @Mcno and runtime <> 0.00
						AND starttime BETWEEN @date1 AND @date2
						  END
	   ELSE IF @process = 'TP'
	 	BEGIN
		SELECT 
							--CAST(ROUND(AVG(MTTR), 2) AS FLOAT) AS MTTR,
							CAST(ROUND(AVG(alarmtime / (AlarmCount + 1)), 2) AS FLOAT) AS MTTR,
							CAST(ROUND(AVG(runtime / (AlarmCount + 1)), 2) AS FLOAT) AS MTBA,
							SUM(Good + ng) AS OutputQty,
							CAST(ROUND(AVG(Good / runtime), 2) AS FLOAT) AS RPM,
							SUM(AlarmCount) AS AlarmQty
						FROM [10.20.10.253].[SELCONDB].[dbo].[TPData]
						WHERE machineno = @Mcno and runtime <> 0.00
						AND starttime BETWEEN @date1 AND @date2
        END
END
GO
