CREATE PROCEDURE [dbo].[AndonValidate]
      @acnt_username VARCHAR(50),
      @acnt_Password VARCHAR(50)
AS
BEGIN
      SET NOCOUNT ON;
      DECLARE @acnt_id INT
     
      SELECT @acnt_id = acnt_id
      FROM acnt_info_tbl WHERE acnt_username = @acnt_username AND acnt_Password = @acnt_Password
     
      IF @acnt_id IS NOT NULL
      BEGIN
            
                 
                  SELECT @acnt_id [acnt_id],  (SELECT acnt_position FROM acnt_info_tbl 
                              WHERE acnt_id = @acnt_id) [acnt_position]-- User Valid
            END
           
      ELSE
      BEGIN
            SELECT -1 [acnt_id], '' [acnt_position] -- User invalid.
      END
END
GO
