UNION ALL

SELECT Process, bmID, BMStatusID ,StartOfRepair, EndOfRepair FROM [eMaintenanceSystemDB].[dbo].[TPBMMaintenance]
WHERE BMStatusID IN ('4','8','9','14','15','18','19') AND (DATEPART(YEAR,EndOfRepair) IS NOT NULL) AND (DATEPART(YEAR,EndOfRepair)) =  @YEAR AND (DATEPART(MONTH,EndOfRepair)) = @MONTH

