-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[GetAllCellCon_Akapen]
	-- Add the parameters for the stored procedure here
	 @DateFrom VARCHAR(50),
	 @DateTo VARCHAR(50)
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
						Select  BMID,[Process],[Location],[MCNo],[MCType],ISNULL([LOTNo],'') as LOTNo,ISNULL([DeviceName],'') as DeviceName,ISNULL([PkgName],'') as PkgName
                                ,[RequestItem],[OccurrenceDate],ISNULL([RequestContent],'') as RequestContent
                                ,ISNULL([PEConfirmPMTurnoverBy],'') as PENumber,ISNULL([PEConfirmPMTurnoverDate],'') as PEConfirmPMTurnoverDate
