                                , Datediff(minute,TimeTurnover,EndOfRepair) as 'PESRepairtime' FROM [eMaintenanceSystemDB].[dbo].[FTBMMaintenance] where (BMCategoryID = 1 and  turnover = 'CC' and BMStatusID not in ('30','31')) and (occurrencedate between @DateFrom and @DateTo)
                         Union
