                                , Datediff(minute,TimeTurnover,EndOfRepair) as 'PESRepairtime' FROM [eMaintenanceSystemDB].[dbo].[TPBMMaintenance] where (BMCategoryID = 1 and  turnover = 'CC' and BMStatusID not in ('30','31')) and (occurrencedate between @DateFrom and @DateTo) 
                         Union
                         Select BMID,[Process],[Location],[MCNo],[MCType],ISNULL([LOTNo],'') as LOTNo,ISNULL([DeviceName],'') as DeviceName,ISNULL([PkgName],'') as PkgName
                                ,[RequestItem],[OccurrenceDate],ISNULL([RequestContent],'') as RequestContent
                                ,ISNULL([PEConfirmPMTurnoverBy],'') as PENumber,ISNULL([PEConfirmPMTurnoverDate],'') as PEConfirmPMTurnoverDate
                                ,[RequestedBy],ISNULL([Why1],'') as Why1,ISNULL([Why2],'') as Why2,ISNULL([Why3],'') as Why3,[StartOfRepair] as 'PMStartofRepair',ISNULL([RepairedByStart],'') as RepairedByStart
                               ,ISNULL([PMTurnOvertoPEBy],'') as PMTurnOvertoPEBy,[PMTurnOvertoPEDate],ISNULL([TurnoverPM],'') as 'TurnoverEEE',TimeTurnover as 'TimeTurnoverToPES' ,[EndOfRepair],ISNULL([RepairedByEnd],'') as RepairedByEnd
                                , Datediff(minute,TimeTurnover,EndOfRepair) as 'PESRepairtime' FROM [eMaintenanceSystemDB].[dbo].[EDSBMMaintenance] where (BMCategoryID = 1 and  turnover = 'CC' and BMStatusID not in ('30','31')) and (occurrencedate between @DateFrom and @DateTo)
