/****** Object:  StoredProcedure [dbo].[sp_GetTEStats]    Script Date: 10/25/2026 4:57:10 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[sp_GetTEStats]
	-- Add the parameters for the stored procedure here
	@date1_fs varchar(50),
	@date2_fs varchar(50),
	@date3_ss varchar(50),
	@date4_ss varchar(50),
	@location varchar(20)
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	 WITH firstShiftIn AS (
    SELECT COUNT(bmid) AS [IN]
    FROM [eMaintenanceSystemDB].[dbo].[TEBMMaintenance]
    WHERE OccurrenceDate BETWEEN @date1_fs AND @date2_fs
      AND Location like @location
       AND BMStatusID IN ('2','3','21')
),
firstShiftOut AS (
    SELECT COUNT(bmid) AS [OUT]
    FROM [eMaintenanceSystemDB].[dbo].[TEBMMaintenance]
    WHERE OccurrenceDate BETWEEN @date1_fs AND @date2_fs
      AND Location like @location
      AND BMStatusID = '4'
),
secondShiftIn AS (
    SELECT COUNT(bmid) AS [IN]
    FROM [eMaintenanceSystemDB].[dbo].[TEBMMaintenance]
    WHERE OccurrenceDate BETWEEN @date3_ss AND @date4_ss
      AND Location like @location
      AND BMStatusID IN ('2','3','21')
),
secondShiftOut AS (
    SELECT COUNT(bmid) AS [OUT]
    FROM [eMaintenanceSystemDB].[dbo].[TEBMMaintenance]
    WHERE OccurrenceDate BETWEEN @date3_ss AND @date4_ss
      AND Location like @location
      AND BMStatusID = '4'
),
turnOver AS (
    SELECT COUNT(bmid) AS [TO]
    FROM [eMaintenanceSystemDB].[dbo].[TEBMMaintenance]
    WHERE OccurrenceDate <  @date1_fs 
      AND Location like @location
     AND BMStatusID IN ('2','3','21')
),
 reMain AS (
    SELECT COUNT(bmid) AS [Remain]
    FROM [eMaintenanceSystemDB].[dbo].[TEBMMaintenance]
    WHERE OccurrenceDate BETWEEN @date1_fs AND @date4_ss
      AND Location like @location
      AND BMStatusID IN ('2','3','21')
), sixHours AS (
    SELECT COUNT(bmid) AS [6hrs]
    FROM [eMaintenanceSystemDB].[dbo].[TEBMMaintenance]
    WHERE DateDiff(MINUTE,OccurrenceDate,Getdate()) >=  360 
      AND Location like @location
      AND BMStatusID IN ('2','3','21')
), twelveHours AS (
    SELECT COUNT(bmid) AS [12hrs]
    FROM [eMaintenanceSystemDB].[dbo].[TEBMMaintenance]
    WHERE DateDiff(MINUTE,OccurrenceDate,Getdate()) >=  720 
      AND Location like @location
      AND BMStatusID IN ('2','3','21')
), twentyFourHours AS (
    SELECT COUNT(bmid) AS [24hrs]
    FROM [eMaintenanceSystemDB].[dbo].[TEBMMaintenance]
    WHERE DateDiff(MINUTE,OccurrenceDate,Getdate()) >=  1440 
      AND Location like @location
      AND BMStatusID IN ('2','3','21')
), fortyEightHours AS (
    SELECT COUNT(bmid) AS [48hrs]
    FROM [eMaintenanceSystemDB].[dbo].[TEBMMaintenance]
    WHERE DateDiff(MINUTE,OccurrenceDate,Getdate()) >=  2880 
      AND Location like @location
      AND BMStatusID IN ('2','3','21')
)



SELECT 
	tov.[TO] as 'T.O',
    fi.[IN] as 'F_in',
    fo.[OUT] as 'F_out',
	 CASE 
        WHEN FORMAT(GETDATE(), 'HH:mm') > '16:59' 
		THEN si.[IN] + fi.[IN] + tov.[TO]
        ELSE 0
    END AS [S_in],
	 CASE 
        WHEN FORMAT(GETDATE(), 'HH:mm') > '16:59' 
		THEN  so.[OUT]
        ELSE 0
    END AS [S_Out],
	rem.[Remain],sh.[6hrs],twh.[12hrs],tfh.[24hrs],feh.[48hrs] 
FROM firstShiftIn fi
CROSS JOIN firstShiftOut fo
CROSS JOIN secondShiftIn si
CROSS JOIN secondShiftOut so
CROSS JOIN turnOver tov
CROSS JOIN reMain rem
cross join sixHours sh
cross join twelveHours twh
cross join twentyFourHours tfh
cross join fortyEightHours feh;
END
GO
/****** Object:  StoredProcedure [dbo].[sp_PCemaintenaceRecord]    Script Date: 10/25/2026 4:57:10 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[sp_PCemaintenaceRecord]
    @Process VARCHAR(50),
    @Location VARCHAR(50),
    @Date1 VARCHAR(50),
    @Date2 VARCHAR(50),
	@classification varchar(50)
AS
BEGIN
    SET NOCOUNT ON;

    IF @Process = 'All'
    BEGIN
	 DECLARE @SQL123 NVARCHAR(MAX);
	 SET @SQL123 = '
        SELECT
            a.BMID,
            f.PMCategory,
            a.Process,
            a.Location,
            a.MCNo,
            a.PkgName AS PackageName,
            c.PackageFamily,
            COALESCE(e.RobinName, a.DeviceName) AS DeviceName,
            a.LotNo,
            a.RepairedByEnd,
            a.StartOfRepair,
            a.EndOfRepair,
            CAST(DATEDIFF(SECOND, a.StartOfRepair, a.EndOfRepair) / 60.0 AS DECIMAL(10,2)) AS RepairDurationInMinutes,
            d.BMStatus
        FROM
        (
            SELECT BMID, Process, Location, MCNo, PkgName, DeviceName,
                   LotNo, RepairedByEnd, StartOfRepair, EndOfRepair,
                   BMStatusID, PMCategoryID
            FROM DCBMMaintenance
            WHERE (OccurrenceDate BETWEEN @Date1 AND @Date2)'

			IF @classification <> 'All'
				BEGIN
				SET @SQL123 += ' AND PMCategoryID = @classification ';
				END

           SET @SQL123 += '  UNION ALL

            SELECT BMID, Process, Location, MCNo, PkgName, DeviceName,
                   LotNo, RepairedByEnd, StartOfRepair, EndOfRepair,
                   BMStatusID, PMCategoryID
            FROM DBBMMaintenance
            WHERE (OccurrenceDate BETWEEN @Date1 AND @Date2) '

			IF @classification <> 'All'
				BEGIN
				SET @SQL123 += ' AND PMCategoryID = @classification ';
				END

           SET @SQL123 += '  UNION ALL

            SELECT BMID, Process, Location, MCNo, PkgName, DeviceName,
                   LotNo, RepairedByEnd, StartOfRepair, EndOfRepair,
                   BMStatusID, PMCategoryID
            FROM WBBMMaintenance
            WHERE (OccurrenceDate BETWEEN @Date1 AND @Date2)'  

            	IF @classification <> 'All'
				BEGIN
				SET @SQL123 += ' AND PMCategoryID = @classification ';
				END

           SET @SQL123 += '  UNION ALL

            SELECT BMID, Process, Location, MCNo, PkgName, DeviceName,
                   LotNo, RepairedByEnd, StartOfRepair, EndOfRepair,
                   BMStatusID, PMCategoryID
            FROM MPBMMaintenance
            WHERE (OccurrenceDate BETWEEN @Date1 AND @Date2) '

            	IF @classification <> 'All'
				BEGIN
				SET @SQL123 += ' AND PMCategoryID = @classification ';
				END

           SET @SQL123 += '  UNION ALL

            SELECT BMID, Process, Location, MCNo, PkgName, DeviceName,
                   LotNo, RepairedByEnd, StartOfRepair, EndOfRepair,
                   BMStatusID, PMCategoryID
            FROM PLBMMaintenance
            WHERE (OccurrenceDate BETWEEN @Date1 AND @Date2)  '

           	IF @classification <> 'All'
				BEGIN
				SET @SQL123 += ' AND PMCategoryID = @classification ';
				END

           SET @SQL123 += '  UNION ALL

            SELECT BMID, Process, Location, MCNo, PkgName, DeviceName,
                   LotNo, RepairedByEnd, StartOfRepair, EndOfRepair,
                   BMStatusID, PMCategoryID
            FROM FLBMMaintenance
            WHERE (OccurrenceDate BETWEEN @Date1 AND @Date2) '

          	IF @classification <> 'All'
				BEGIN
				SET @SQL123 += ' AND PMCategoryID = @classification ';
				END

           SET @SQL123 += '  UNION ALL

            SELECT BMID, Process, Location, MCNo, PkgName, DeviceName,
                   LotNo, RepairedByEnd, StartOfRepair, EndOfRepair,
                   BMStatusID, PMCategoryID
            FROM FTBMMaintenance
            WHERE (OccurrenceDate BETWEEN @Date1 AND @Date2) '

            	IF @classification <> 'All'
				BEGIN
				SET @SQL123 += ' AND PMCategoryID = @classification ';
				END

           SET @SQL123 += '  UNION ALL

            SELECT BMID, Process, Location, MCNo, PkgName, DeviceName,
                   LotNo, RepairedByEnd, StartOfRepair, EndOfRepair,
                   BMStatusID, PMCategoryID
            FROM TPBMMaintenance
            WHERE (OccurrenceDate BETWEEN @Date1 AND @Date2) '

            	IF @classification <> 'All'
				BEGIN
				SET @SQL123 += ' AND PMCategoryID = @classification ';
				END

           SET @SQL123 += '  UNION ALL

            SELECT BMID, Process, Location, MCNo, PkgName, DeviceName,
                   LotNo, RepairedByEnd, StartOfRepair, EndOfRepair,
                   BMStatusID, PMCategoryID
            FROM EDSBMMaintenance
            WHERE (OccurrenceDate BETWEEN @Date1 AND @Date2)  '


				IF @classification <> 'All'
				BEGIN
				SET @SQL123 += ' AND PMCategoryID = @classification ';
				END

         SET @SQL123 += ' ) a
        LEFT JOIN PackagesName b
            ON a.PkgName = b.PackageName
        LEFT JOIN PackageFamily c
            ON b.GroupID = c.GroupID
        LEFT JOIN BMStatus d
            ON a.BMStatusID = d.BMStatusID
        OUTER APPLY
        (
            SELECT TOP 1 *
            FROM DeviceName dn
            WHERE dn.DeviceName = a.DeviceName
            ORDER BY dn.SeqID DESC
        ) e
        LEFT JOIN PMCategory f
            ON a.PMCategoryID = f.PMCategoryID
        ORDER BY
            a.Process,
            a.Location,
            a.MCNo,
            a.StartOfRepair DESC;'

			 EXEC sp_executesql
            @SQL123,
            N'@Location VARCHAR(50), @Date1 VARCHAR(50), @Date2 VARCHAR(50), @Process VARCHAR(50), @classification VARCHAR(50)',
            @Location,
            @Date1,
            @Date2,
            @Process,
			@classification;

    END
    ELSE
    BEGIN

        DECLARE @TableName VARCHAR(50);

        SET @TableName =
            CASE @Process
                WHEN 'DC'  THEN 'DCBMMaintenance'
                WHEN 'DB'  THEN 'DBBMMaintenance'
                WHEN 'WB'  THEN 'WBBMMaintenance'
                WHEN 'MP'  THEN 'MPBMMaintenance'
                WHEN 'PL'  THEN 'PLBMMaintenance'
                WHEN 'FL'  THEN 'FLBMMaintenance'
                WHEN 'FT'  THEN 'FTBMMaintenance'
                WHEN 'TP'  THEN 'TPBMMaintenance'
                WHEN 'EDS' THEN 'EDSBMMaintenance'
            END;

        DECLARE @SQL NVARCHAR(MAX);

        SET @SQL = '
        SELECT
            a.BMID,
            f.PMCategory,
            a.Process,
            a.Location,
            a.MCNo,
            a.PkgName AS PackageName,
            CASE
                WHEN @Process = ''EDS'' THEN a.PkgName
                ELSE c.PackageFamily
            END AS PackageFamily,
            COALESCE(e.RobinName, a.DeviceName) AS DeviceName,
            a.LotNo,
            a.RepairedByEnd,
            a.StartOfRepair,
            a.EndOfRepair,
            CAST(DATEDIFF(SECOND, a.StartOfRepair, a.EndOfRepair) / 60.0 AS DECIMAL(10,2)) AS RepairDurationInMinutes,
            d.BMStatus
        FROM ' + QUOTENAME(@TableName) + ' a
        LEFT JOIN PackagesName b
            ON a.PkgName = b.PackageName
        LEFT JOIN PackageFamily c
            ON b.GroupID = c.GroupID
        LEFT JOIN BMStatus d
            ON a.BMStatusID = d.BMStatusID
        OUTER APPLY
        (
            SELECT TOP 1 *
            FROM DeviceName dn
            WHERE dn.DeviceName = a.DeviceName
            ORDER BY dn.SeqID DESC
        ) e
        LEFT JOIN PMCategory f
            ON a.PMCategoryID = f.PMCategoryID
        WHERE a.Location = @Location
        AND (a.OccurrenceDate BETWEEN @Date1 AND @Date2) '

			IF @classification <> 'All'
				BEGIN
				SET @SQL += ' AND a.PMCategoryID = @classification ';
				END

           SET @SQL += ' ORDER BY a.BMID DESC;';

         EXEC sp_executesql
            @SQL,
            N'@Location VARCHAR(50), @Date1 VARCHAR(50), @Date2 VARCHAR(50), @Process VARCHAR(50), @classification VARCHAR(50)',
            @Location,
            @Date1,
            @Date2,
            @Process,
			@classification;
    END
END
GO
/****** Object:  StoredProcedure [dbo].[sp_PCemaintenaceRecord_bkup]    Script Date: 10/25/2026 4:57:10 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
Create PROCEDURE [dbo].[sp_PCemaintenaceRecord_bkup]
    @Process VARCHAR(50),
    @Location VARCHAR(50),
	 @Date1 VARCHAR(50),
	@Date2 VARCHAR(50)
AS
BEGIN
    SET NOCOUNT ON;

    IF @Process = 'All'
		BEGIN
				 SELECT
						a.Process,
						a.Location,
						a.MCNo,
						a.pkgname AS PackageName,
						c.PackageFamily,
						e.RobinName as 'DeviceName',
						a.LotNo,
						a.RepairedByEnd,
						a.StartOfRepair,
						a.EndOfRepair,
						CONVERT(DECIMAL(10,2), DATEDIFF(SECOND, a.StartOfRepair, a.EndOfRepair) / 60.0) AS RepairDurationInMinutes,
						d.BMStatus 
					FROM 
					(
						SELECT 
								Process,
								Location,
								MCNo,
								PkgName,
								DeviceName,
								LotNo,
								RepairedByEnd,
								StartOfRepair,
								EndOfRepair,
								BMStatusID
					    FROM [eMaintenanceSystemDB].[dbo].[DCBMMaintenance] where OccurrenceDate between @Date1 and @Date2 
						UNION ALL
						SELECT 
								Process,
								Location,
								MCNo,
								PkgName,
								DeviceName,
								LotNo,
								RepairedByEnd,
								StartOfRepair,
								EndOfRepair,
								BMStatusID
					 FROM [eMaintenanceSystemDB].[dbo].[DBBMMaintenance]  where OccurrenceDate between @Date1 and @Date2 
					 UNION ALL
						SELECT 
								Process,
								Location,
								MCNo,
								PkgName,
								DeviceName,
								LotNo,
								RepairedByEnd,
								StartOfRepair,
								EndOfRepair,
								BMStatusID
					 FROM [eMaintenanceSystemDB].[dbo].[WBBMMaintenance]  where OccurrenceDate between @Date1 and @Date2 
					 UNION ALL
						SELECT 
								Process,
								Location,
								MCNo,
								PkgName,
								DeviceName,
								LotNo,
								RepairedByEnd,
								StartOfRepair,
								EndOfRepair,
								BMStatusID
					 FROM [eMaintenanceSystemDB].[dbo].[MPBMMaintenance]  where OccurrenceDate between @Date1 and @Date2 
					 UNION ALL
						SELECT 
								Process,
								Location,
								MCNo,
								PkgName,
								DeviceName,
								LotNo,
								RepairedByEnd,
								StartOfRepair,
								EndOfRepair,
								BMStatusID
					 FROM [eMaintenanceSystemDB].[dbo].[PLBMMaintenance]  where OccurrenceDate between @Date1 and @Date2 
					 UNION ALL
						SELECT 
								Process,
								Location,
								MCNo,
								PkgName,
								DeviceName,
								LotNo,
								RepairedByEnd,
								StartOfRepair,
								EndOfRepair,
								BMStatusID
					 FROM [eMaintenanceSystemDB].[dbo].[FLBMMaintenance]  where OccurrenceDate between @Date1 and @Date2 
					 UNION ALL
						SELECT 
								Process,
								Location,
								MCNo,
								PkgName,
								DeviceName,
								LotNo,
								RepairedByEnd,
								StartOfRepair,
								EndOfRepair,
								BMStatusID
					 FROM [eMaintenanceSystemDB].[dbo].[FTBMMaintenance]  where OccurrenceDate between @Date1 and @Date2 
					 UNION ALL
						SELECT 
								Process,
								Location,
								MCNo,
								PkgName,
								DeviceName,
								LotNo,
								RepairedByEnd,
								StartOfRepair,
								EndOfRepair,
								BMStatusID
					 FROM [eMaintenanceSystemDB].[dbo].[TPBMMaintenance]  where OccurrenceDate between @Date1 and @Date2 
					 UNION ALL
						SELECT 
								Process,
								Location,
								MCNo,
								PkgName,
								DeviceName,
								LotNo,
								RepairedByEnd,
								StartOfRepair,
								EndOfRepair,
								BMStatusID
					 FROM [eMaintenanceSystemDB].[dbo].[EDSBMMaintenance]  where OccurrenceDate between @Date1 and @Date2 
					 ) AS a
					INNER JOIN [eMaintenanceSystemDB].[dbo].[PackagesName] AS b 
						ON a.PkgName = b.PackageName
					INNER JOIN [eMaintenanceSystemDB].[dbo].[PackageFamily] AS c 
						ON b.groupid = c.groupid
					INNER JOIN [eMaintenanceSystemDB].[dbo].[BMStatus] AS d 
						ON a.BMStatusID = d.BMStatusID
						INNER JOIN [eMaintenanceSystemDB].[dbo].[DeviceName] e
						on a.DeviceName = e.Devicename
							 order by a.process,a.location,a.mcno,a.startofrepair desc
		END
    ELSE
		BEGIN
				IF @Process = 'MP'
						Begin
							SELECT
								a.Process,
								a.Location,
								a.MCNo,
								a.pkgname AS PackageName,
								c.PackageFamily,
								e.RobinName as 'DeviceName',
								a.LotNo,
								a.RepairedByEnd,
								a.StartOfRepair,
								a.EndOfRepair,
								CAST(DATEDIFF(SECOND, a.StartOfRepair, a.EndOfRepair) / 60.0 AS DECIMAL(10,2)) AS RepairDurationInMinutes,
								d.BMStatus 
							FROM 
								[eMaintenanceSystemDB].[dbo].[MPBMMaintenance] AS a
