/****** Object:  StoredProcedure [dbo].[spCheckIFAlreadyStartedByCC]    Script Date: 10/25/2026 4:57:10 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[spCheckIFAlreadyStartedByCC]
    @BMID INT,
    @Process VARCHAR(10)
AS
BEGIN
    DECLARE @CCStartOfRepair DATETIME
    DECLARE @Message Bit
    DECLARE @DynamicSQL NVARCHAR(MAX)

    SET @DynamicSQL = N'SELECT @CCStartOfRepair = CCStartOfRepair FROM ' + @Process + 'BMMaintenance WHERE BMid = @BMID'

    EXEC sp_executesql @DynamicSQL, N'@CCStartOfRepair DATETIME OUTPUT, @BMID INT', @CCStartOfRepair OUTPUT, @BMID

    IF @CCStartOfRepair IS NULL
    BEGIN
        SET @Message = 0
    END
    ELSE
    BEGIN
        SET @Message = 1
    END

    SELECT @Message AS ResultMessage
END;
GO
