    @searchCriteria NVARCHAR(MAX),
    @timeframe INT,
    @MCNo NVARCHAR(50) ,
    @RequestItem NVARCHAR(100) ,
    @inRole NVARCHAR(20),
    @inLoc NVARCHAR(50),
    @inProc NVARCHAR(50),
   

@FromDate DATE,
    @ToDate DATE
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @strReoccurence NVARCHAR(MAX),
            @strDeviceRankQuery NVARCHAR(MAX),
            @sqlFields NVARCHAR(MAX),
            @strRTime NVARCHAR(MAX),
            @strRTimeA NVARCHAR(MAX),
            @strRTimeB NVARCHAR(MAX),
            @sqlWhereLoc NVARCHAR(MAX),
            @sqlWhereProc NVARCHAR(MAX),
            @strwhereMCNo NVARCHAR(MAX) = '',
            @strwhereRequestItem NVARCHAR(MAX) = '',
--@dateRangeCrit NVARCHAR(MAX) = '',
@SpecialCritDev NVARCHAR(MAX),
@ddlReoccurrence INT = 0,
@ddlLocID INT = 0,
@userData_Location NVARCHAR(50) = NULL,
@SqlCommand NVARCHAR(MAX);
    -- Default values for dynamic components
    --SET @strReoccurence = '(SELECT 0) AS Reoccurrence';
   
		SET @strDeviceRankQuery =
		'CASE 
			WHEN [Process] = ''DB'' THEN
				CASE
					WHEN TRIM(PkgName) IN (
						SELECT TRIM(PkgName1) 
						FROM PackagePriority 
						WHERE [level] = 3 AND isactive = 1
					) THEN 3
					WHEN TRIM(PkgName) IN (
						SELECT TRIM(PkgName1) 
						FROM PackagePriority 
						WHERE [level] = 2 AND isactive = 1
					) THEN 2
					WHEN TRIM(PkgName) IN (
						SELECT TRIM(PkgName1) 
						FROM PackagePriority 
						WHERE [level] = 1 AND isactive = 1
					) THEN 1
					ELSE 0
				END
			ELSE 
				CASE
					WHEN TRIM(DeviceName) IN (
						SELECT TRIM(DeviceName) 
						FROM MachineKarte_MCD where isactive = 1
					) THEN 3
					WHEN TRIM(DeviceName) IN (
						SELECT TRIM(DeviceName) 
						FROM MachineKarte_MCD where isactive = 1
					) THEN 3
					ELSE 0
				END
		END AS Priority';

    -- Adjust for reoccurrence condition
--    IF @ddlReoccurrence <> 0
--    BEGIN
--        SET @strReoccurence =
--           'COUNT(CASE WHEN TimeOfRequest >= (DATEADD(DAY, -@timeframe, GETDATE())) THEN 1 END)
--           OVER (PARTITION BY MCNo, RequestItem) - 1 AS Reoccurrence';


--    END
--ELSE
--    BEGIN
--        SET @strReoccurence = '0 AS Reoccurrence';  -- Default case if timeframe is 0
--    END
IF @timeframe <> '0'  
    BEGIN
        SET @strReoccurence = 'COUNT(CASE WHEN TimeOfRequest >= (DATEADD(DAY, -' + CAST(@timeframe AS VARCHAR) + ', GETDATE())) THEN 1 END) OVER (PARTITION BY [MCNo], [RequestItem]) - 1 AS Reoccurrence';
    END
    ELSE
    BEGIN
        SET @strReoccurence = '0 AS Reoccurrence';  -- Default case if timeframe is 0
    END
    -- Apply MCNo and RequestItem filters
    IF LEN(@MCNo) > 0
        SET @strWhereMCNo = ' AND MCNo = ''' + REPLACE(@MCNo, '''', '''''') + '''';

    IF LEN(@RequestItem) > 0
        SET @strWhereRequestItem = ' AND RequestItem = ''' + REPLACE(@RequestItem, '''', '''''') + '''';

    -- Define SQL fields
	--EEE set into BM Closed
    --SET @sqlFields = 'DISTINCT bmID,
    --    IIF(BMStatusID IN (14, 11, 13), IIF(isnotquality2 = ''No'' AND isnotquality3 = ''No'', ''Yes'', ''No''), ''No'') AS IsQualityBM,
    --   IIF(BMStatusID = 14, IIF(akapen1 <> ''0'' OR akapen2 <> ''0'' OR akapen3 <> ''0'', ''YES'', ''NO''),
    --     IIF(akapen1 = ''0'' AND akapen2 = ''0'' AND akapen3 = ''0'', ''NO'', ''NO'')) AS IsAkapen,
    --   IIF(BMStatusID IN (14, 11), IIF(aopen1 <> ''0'' OR aopen2 <> ''0'' OR aopen3 <> ''0'', ''YES'', ''NO''),
    --        IIF(aopen1 = ''0'' AND aopen2 = ''0'' AND aopen3 = ''0'', ''NO'', ''NO'')) AS IsAopen,
    --   [Process], ' + @strReoccurence + ', ' + @strDeviceRankQuery + ',
    --  [Location], IIF(BMStatusID = 14, AccPMCategory, PMCategory) AS PMCategory, MCNo, MCType,
    --   PkgName, DeviceName, LOTNo, RequestItem, RequestedBy, TimeOfRequest, BMStatusID,
    -- GLConfirmOPReqBy, GLConfirmOPReqDate, PMConfirmGLOPReqDate, 
    --   CASE 
    --       WHEN ''' + @inRole + ''' = ''EEE'' AND BMStatusID NOT IN (6, 7, 19) THEN ''BM CLOSED''
    --        ELSE BMStatus 
    --    END AS BMStatus,
    --    PMConfirmGLOPReqBy, StartOfRepair, EndOfRepair, RepairedByEnd, SpecialDevName, BMCaseDefectModeName';
	--For EEE data
	--SET @sqlFields = 'DISTINCT bmID,
 --       IIF(
 --       EXISTS (
 --           SELECT 1 
 --           FROM EEEBMMaintenance E
 --           WHERE E.bm_ID = bmID AND (
 --               E.SoftwareChange = ''YES'' OR
 --               E.BeforeSoftwareChange = ''YES'' OR
 --               E.AfterSoftwareChange = ''YES'' OR
 --               E.CPURelated = ''YES'' OR
 --               E.BeforeCPURelated = ''YES'' OR
 --               E.AfterCPURelated = ''YES'' OR
 --               E.CameraDriverSoft = ''YES'' OR
 --               E.BeforeCameraDriverSoft = ''YES'' OR
 --               E.AfterCameraDriverSoft = ''YES'' OR
 --               E.HalconInstaller = ''YES'' OR
 --               E.BeforeHalconInstaller = ''YES'' OR
 --               E.AfterHalconInstaller = ''YES'' OR
 --               E.ImageAcqFiles = ''YES'' OR
 --               E.BeforeImageAcqFiles = ''YES'' OR
 --               E.AfterImageAcqFiles = ''YES'' OR
 --               E.StandardParameter = ''YES'' OR
 --               E.BeforeStandardParameter = ''YES'' OR
 --               E.AfterStandardParameter = ''YES''
 --           )
 --       ),
 --       ''Yes'',
 --       IIF(
 --           BMStatusID IN (14, 11, 13) AND 
 --           isnotquality2 = ''No'' AND 
 --           isnotquality3 = ''No'',
 --           ''Yes'',
 --           ''No''
 --       )
 --   ) AS IsQualityBM,
 --      IIF(BMStatusID IN (14, 33), IIF(akapen1 <> ''0'' OR akapen2 <> ''0'' OR akapen3 <> ''0'', ''YES'', ''NO''),
 --           IIF(akapen1 = ''0'' AND akapen2 = ''0'' AND akapen3 = ''0'', ''NO'', ''NO'')) AS IsAkapen,
 --      IIF(BMStatusID IN (14, 11, 33), IIF(aopen1 <> ''0'' OR aopen2 <> ''0'' OR aopen3 <> ''0'', ''YES'', ''NO''),
 --           IIF(aopen1 = ''0'' AND aopen2 = ''0'' AND aopen3 = ''0'', ''NO'', ''NO'')) AS IsAopen,
 --      [Process], ' + @strReoccurence + ', ' + @strDeviceRankQuery + ',
 --      [Location], IIF(BMStatusID = 14, AccPMCategory, PMCategory) AS PMCategory, MCNo, MCType,
 --       PkgName, DeviceName, LOTNo, RequestItem, RequestedBy, TimeOfRequest, BMStatusID,
 --      GLConfirmOPReqBy, GLConfirmOPReqDate, PMConfirmGLOPReqDate, BMStatus,
 --      PMConfirmGLOPReqBy, StartOfRepair, EndOfRepair, RepairedByEnd, SpecialDevName, BMCaseDefectModeName';

 IF @inRole IN ('PE', 'PES')
    BEGIN
        SET @sqlFields = 'DISTINCT bmID,
            IIF(
                EXISTS (
                    SELECT 1 
                    FROM EEEBMMaintenance E
                    WHERE E.bm_ID = bmID AND (
                        E.SoftwareChange = ''YES'' OR
                        E.BeforeSoftwareChange = ''YES'' OR
                        E.AfterSoftwareChange = ''YES'' OR
                        E.CPURelated = ''YES'' OR
                        E.BeforeCPURelated = ''YES'' OR
                        E.AfterCPURelated = ''YES'' OR
                        E.CameraDriverSoft = ''YES'' OR
                        E.BeforeCameraDriverSoft = ''YES'' OR
                        E.AfterCameraDriverSoft = ''YES'' OR
                        E.HalconInstaller = ''YES'' OR
                        E.BeforeHalconInstaller = ''YES'' OR
                        E.AfterHalconInstaller = ''YES'' OR
                        E.ImageAcqFiles = ''YES'' OR
                        E.BeforeImageAcqFiles = ''YES'' OR
                        E.AfterImageAcqFiles = ''YES'' OR
                        E.StandardParameter = ''YES'' OR
                        E.BeforeStandardParameter = ''YES'' OR
                        E.AfterStandardParameter = ''YES''
                    )
                ),
                ''Yes'',
                IIF(
                    BMStatusID IN (14, 11, 13) AND 
                    isnotquality2 = ''No'' AND 
                    isnotquality3 = ''No'',
                    ''Yes'',
                    ''No''
                )
            ) AS IsQualityBM,
            IIF(BMStatusID IN (14, 33), IIF(akapen1 <> ''0'' OR akapen2 <> ''0'' OR akapen3 <> ''0'', ''YES'', ''NO''),
                IIF(akapen1 = ''0'' AND akapen2 = ''0'' AND akapen3 = ''0'', ''NO'', ''NO'')) AS IsAkapen,
            IIF(BMStatusID IN (14, 11, 33), IIF(aopen1 <> ''0'' OR aopen2 <> ''0'' OR aopen3 <> ''0'', ''YES'', ''NO''),
                IIF(aopen1 = ''0'' AND aopen2 = ''0'' AND aopen3 = ''0'', ''NO'', ''NO'')) AS IsAopen,
            [Process], ' + @strReoccurence + ', ' + @strDeviceRankQuery + ',
            [Location], IIF(BMStatusID = 14, AccPMCategory, PMCategory) AS PMCategory, MCNo, MCType,
            PkgName, DeviceName, LOTNo, RequestItem, RequestedBy, TimeOfRequest, BMStatusID,
            GLConfirmOPReqBy, GLConfirmOPReqDate, PMConfirmGLOPReqDate, BMStatus,
            PMConfirmGLOPReqBy, StartOfRepair, EndOfRepair, RepairedByEnd, SpecialDevName, BMCaseDefectModeName';
    END
    ELSE
    BEGIN
        SET @sqlFields = 'DISTINCT bmID,
            IIF(BMStatusID IN (14, 11, 13), IIF(isnotquality2 = ''No'' AND isnotquality3 = ''No'', ''Yes'', ''No''), ''No'') AS IsQualityBM,
            IIF(BMStatusID IN (14, 33), IIF(akapen1 <> ''0'' OR akapen2 <> ''0'' OR akapen3 <> ''0'', ''YES'', ''NO''),
                IIF(akapen1 = ''0'' AND akapen2 = ''0'' AND akapen3 = ''0'', ''NO'', ''NO'')) AS IsAkapen,
            IIF(BMStatusID IN (14, 11, 33), IIF(aopen1 <> ''0'' OR aopen2 <> ''0'' OR aopen3 <> ''0'', ''YES'', ''NO''),
                IIF(aopen1 = ''0'' AND aopen2 = ''0'' AND aopen3 = ''0'', ''NO'', ''NO'')) AS IsAopen,
            [Process], ' + @strReoccurence + ', ' + @strDeviceRankQuery + ',
            [Location], IIF(BMStatusID = 14, AccPMCategory, PMCategory) AS PMCategory, MCNo, MCType,
            PkgName, DeviceName, LOTNo, RequestItem, RequestedBy, TimeOfRequest, BMStatusID,
            GLConfirmOPReqBy, GLConfirmOPReqDate, PMConfirmGLOPReqDate, BMStatus,
            PMConfirmGLOPReqBy, StartOfRepair, EndOfRepair, RepairedByEnd, SpecialDevName, BMCaseDefectModeName';
    END

	--SET @sqlFields = 'DISTINCT bmID,
 --       CASE 
 --           WHEN ''' + @inRole + ''' = ''EEE'' AND BMStatusID NOT IN (6, 7, 19) THEN 
 --               IIF(isnotquality2 = ''No'' AND isnotquality3 = ''No'', ''Yes'', ''No'')
 --           ELSE 
 --               IIF(BMStatusID IN (14, 11, 13), IIF(isnotquality2 = ''No'' AND isnotquality3 = ''No'', ''Yes'', ''No''), ''No'')
 --       END AS IsQualityBM,
        
 --       CASE 
 --           WHEN ''' + @inRole + ''' = ''EEE'' AND BMStatusID NOT IN (6, 7, 19) THEN 
 --               IIF(akapen1 <> ''0'' OR akapen2 <> ''0'' OR akapen3 <> ''0'', ''YES'', ''NO'')
 --           ELSE 
 --               IIF(BMStatusID = 14, 
 --                   IIF(akapen1 <> ''0'' OR akapen2 <> ''0'' OR akapen3 <> ''0'', ''YES'', ''NO''),
 --                   IIF(akapen1 = ''0'' AND akapen2 = ''0'' AND akapen3 = ''0'', ''NO'', ''NO''))
 --       END AS IsAkapen,
        
 --       CASE 
 --           WHEN ''' + @inRole + ''' = ''EEE'' AND BMStatusID NOT IN (6, 7, 19) THEN 
 --               IIF(aopen1 <> ''0'' OR aopen2 <> ''0'' OR aopen3 <> ''0'', ''YES'', ''NO'')
 --           ELSE 
 --               IIF(BMStatusID IN (14, 11), 
 --                   IIF(aopen1 <> ''0'' OR aopen2 <> ''0'' OR aopen3 <> ''0'', ''YES'', ''NO''),
 --                   IIF(aopen1 = ''0'' AND aopen2 = ''0'' AND aopen3 = ''0'', ''NO'', ''NO''))
 --       END AS IsAopen,
        
 --       [Process], ' + @strReoccurence + ', ' + @strDeviceRankQuery + ',
 --       [Location], IIF(BMStatusID = 14, AccPMCategory, PMCategory) AS PMCategory, MCNo, MCType,
 --       PkgName, DeviceName, LOTNo, RequestItem, RequestedBy, TimeOfRequest, BMStatusID,
 --       GLConfirmOPReqBy, GLConfirmOPReqDate, PMConfirmGLOPReqDate, 
 --       CASE 
 --           WHEN ''' + @inRole + ''' = ''EEE'' AND BMStatusID NOT IN (6, 7, 19) THEN ''BM CLOSED''
 --           ELSE BMStatus 
 --       END AS BMStatus,
 --       PMConfirmGLOPReqBy, StartOfRepair, EndOfRepair, RepairedByEnd, SpecialDevName, BMCaseDefectModeName';

    -- Define RequestElapsed calculations
    SET @strRTime = 'FORMAT((DATEDIFF(MINUTE, TimeOfRequest, IIF(GLConfirmOPReqBy IS NULL, SYSDATETIME(), GLConfirmOPReqDate))), ''###.##'') AS RequestElapsed,
        FORMAT((DATEDIFF(MINUTE, GLConfirmOPReqDate, IIF(PMConfirmGLOPReqBy IS NULL, SYSDATETIME(), PMConfirmGLOPReqDate))), ''###.##'') AS RequestElapsed2,
        FORMAT((DATEDIFF(MINUTE, StartOfRepair, IIF(RepairedByEnd IS NULL, SYSDATETIME(), EndOfRepair))), ''###.##'') AS RequestElapsed3';

		

--SET @SqlCommand = 'SELECT ' + @SqlFields + ', ' + @StrRTime + '
--                  FROM grid' + @inProc + 'Data
--                  WHERE CONVERT(DATE, OccurrenceDate) BETWEEN ''' + CONVERT(VARCHAR, @FromDate, 120) + '''
--                  AND ''' + CONVERT(VARCHAR, @ToDate, 120) + ''' ' +
--                  @SqlWhereLoc + ' ' + @SqlWhereProc + ' ' +
--                  @SearchCriteria + ' ' + @SpecialCritDev + ' ' +
--                  @StrWhereMCNo + ' ' + @StrWhereRequestItem + '
--                  ORDER BY TimeofRequest DESC';




    -- Adjust for roles
    IF @inRole IN ('EE', 'PE', 'PEI', 'CC', 'VIS', 'PKG', 'EEE', 'PES')
    BEGIN
       

 SET @strRTimeA = 'FORMAT((DATEDIFF(MINUTE, a.TimeOfRequest, IIF(a.GLConfirmOPReqBy IS NULL, SYSDATETIME(), a.GLConfirmOPReqDate))), ''###.##'') AS RequestElapsed,
            FORMAT((DATEDIFF(MINUTE, a.GLConfirmOPReqDate, IIF(a.PMConfirmGLOPReqBy IS NULL, SYSDATETIME(), a.PMConfirmGLOPReqDate))), ''###.##'') AS RequestElapsed2,
            FORMAT((DATEDIFF(MINUTE, a.StartOfRepair, IIF(a.RepairedByEnd IS NULL, SYSDATETIME(), a.EndOfRepair))), ''###.##'') AS RequestElapsed3';
			

        SET @strRTimeB = 'FORMAT((DATEDIFF(MINUTE, b.TimeOfRequest, IIF(b.GLConfirmOPReqBy IS NULL, SYSDATETIME(), b.GLConfirmOPReqDate))), ''###.##'') AS RequestElapsed,
            FORMAT((DATEDIFF(MINUTE, b.GLConfirmOPReqDate, IIF(b.PMConfirmGLOPReqBy IS NULL, SYSDATETIME(), b.PMConfirmGLOPReqDate))), ''###.##'') AS RequestElapsed2,
            FORMAT((DATEDIFF(MINUTE, b.StartOfRepair, IIF(b.RepairedByEnd IS NULL, SYSDATETIME(), b.EndOfRepair))), ''###.##'') AS RequestElapsed3';
			
    END

    -- Adjust location filter
    IF @inRole IN ('OP', 'GL')
    BEGIN
        SET @sqlWhereLoc = ' AND Location = ''' + @inLoc + '''';
    END
    ELSE IF @ddlLocID = 0
    BEGIN
        IF @userData_Location IS NULL OR @userData_Location = '<    >'
            SET @sqlWhereLoc = '';
        ELSE
            SET @sqlWhereLoc = ' AND Location = ''' + @inLoc + '''';
    END

    -- Adjust process filter
    IF @ddlLocID <> 0 AND @inProc IS NOT NULL
        SET @sqlWhereProc = ' AND Process = ''' + @inProc + '''';


SET @SqlWhereProc = ISNULL(@SqlWhereProc, '');
SET @SearchCriteria = ISNULL(@SearchCriteria, '');
SET @SpecialCritDev = ISNULL(@SpecialCritDev, '');
SET @SqlWhereLoc = ISNULL(@SqlWhereLoc, '');
SET @StrWhereMCNo = ISNULL(@StrWhereMCNo, '');
SET @StrWhereRequestItem = ISNULL(@StrWhereRequestItem, '');


    IF @inRole = 'OP'
    BEGIN
        SET @SqlCommand = 'SELECT ' + @SqlFields + ', ' + @StrRTime + '
                          FROM grid' + @inProc + 'Data WHERE CONVERT(DATE, OccurrenceDate) BETWEEN ''' + CONVERT(VARCHAR, @fromDate, 120) + ''' AND ''' + CONVERT(VARCHAR, @toDate, 120) + ''' ' +
                          @SqlWhereLoc + ' ' + @SqlWhereProc + ' ' +
                          @SearchCriteria + ' ' + @SpecialCritDev + ' ' +
                          @StrWhereMCNo + ' ' + @StrWhereRequestItem + '
                          ORDER BY TimeofRequest DESC';
    END

    ELSE IF @inRole = 'GL'
    BEGIN
        SET @SqlCommand = 'SELECT ' + @SqlFields + ', ' + @StrRTime + '
                          FROM grid' + @inProc + 'Data WHERE CONVERT(DATE, OccurrenceDate) BETWEEN ''' + CONVERT(VARCHAR, @fromDate, 120) + ''' AND ''' + CONVERT(VARCHAR, @toDate, 120) + ''' ' +
                          @SqlWhereLoc + ' ' + @SqlWhereProc + ' ' +
                          @SearchCriteria + ' ' + @SpecialCritDev + ' ' +
                          @StrWhereMCNo + ' ' + @StrWhereRequestItem + '
                          ORDER BY TimeofRequest DESC';

    END

ELSE IF @inRole = 'PM'
BEGIN


SET @SqlCommand = 'SELECT ' + @SqlFields + ', ' + @StrRTime + '
							FROM grid' + @inProc + 'Data WHERE CONVERT(DATE, OccurrenceDate) BETWEEN ''' + CONVERT(VARCHAR, @fromDate, 120) + ''' AND ''' + CONVERT(VARCHAR, @toDate, 120) + ''' ' +
							@SqlWhereLoc + ' ' + @SqlWhereProc + ' ' +
							@SearchCriteria + ' ' + @SpecialCritDev + ' ' +
							@StrWhereMCNo + ' ' + @StrWhereRequestItem + '										ORDER BY TimeofRequest DESC';

END
ELSE IF @inRole IN ( 'EEE','PE')
    BEGIN
			SET @SqlCommand = '
						(SELECT ' + @sqlFields + ', ' + @strRTimeA + '
						 FROM gridFLData AS a
						 WHERE Turnover IN ( ''PE'', ''EE'')
						 AND CONVERT(DATE, OccurrenceDate) BETWEEN ''' + CONVERT(NVARCHAR, @FromDate, 23) + ''' AND ''' + CONVERT(NVARCHAR, @ToDate, 23) + '''
						 ' + @searchCriteria + ' ' + @strWhereMCNo + ' ' + @strWhereRequestItem + ' ' + @SpecialCritDev + ')
						UNION ALL
						(SELECT ' + @sqlFields + ', ' + @strRTimeB + '
						 FROM gridTPData AS b
						 WHERE Turnover IN ( ''PE'', ''EE'')
						 AND CONVERT(DATE, OccurrenceDate) BETWEEN ''' + CONVERT(NVARCHAR, @FromDate, 23) + ''' AND ''' + CONVERT(NVARCHAR, @ToDate, 23) + '''
						 ' + @searchCriteria + ' ' + @strWhereMCNo + ' ' + @strWhereRequestItem + ' ' + @SpecialCritDev + ')
						UNION ALL
						(SELECT ' + @sqlFields + ', ' + @strRTimeA + '
						 FROM gridEDSData AS a
						 WHERE Turnover IN ( ''PE'', ''EE'')
						 AND CONVERT(DATE, OccurrenceDate) BETWEEN ''' + CONVERT(NVARCHAR, @FromDate, 23) + ''' AND ''' + CONVERT(NVARCHAR, @ToDate, 23) + '''
						 ' + @searchCriteria + ' ' + @strWhereMCNo + ' ' + @strWhereRequestItem + ' ' + @SpecialCritDev + ')
						UNION ALL
						(SELECT ' + @sqlFields + ', ' + @strRTimeB + '
						 FROM gridFTData AS b
						 WHERE Turnover IN ( ''PE'', ''EE'')
						 AND CONVERT(DATE, OccurrenceDate) BETWEEN ''' + CONVERT(NVARCHAR, @FromDate, 23) + ''' AND ''' + CONVERT(NVARCHAR, @ToDate, 23) + '''
						 ' + @searchCriteria + ' ' + @strWhereMCNo + ' ' + @strWhereRequestItem + ' ' + @SpecialCritDev + ')
						UNION ALL
						(SELECT ' + @sqlFields + ', ' + @strRTimeA + '
						 FROM gridDBData AS a
						 WHERE Turnover IN ( ''PE'', ''EE'')
						 AND CONVERT(DATE, OccurrenceDate) BETWEEN ''' + CONVERT(NVARCHAR, @FromDate, 23) + ''' AND ''' + CONVERT(NVARCHAR, @ToDate, 23) + '''
						 ' + @searchCriteria + ' ' + @strWhereMCNo + ' ' + @strWhereRequestItem + ' ' + @SpecialCritDev + ')
						UNION ALL
						(SELECT ' + @sqlFields + ', ' + @strRTimeB + '
						 FROM gridMPData AS b
						 WHERE Turnover IN ( ''PE'', ''EE'')
						 AND CONVERT(DATE, OccurrenceDate) BETWEEN ''' + CONVERT(NVARCHAR, @FromDate, 23) + ''' AND ''' + CONVERT(NVARCHAR, @ToDate, 23) + '''
						 ' + @searchCriteria + ' ' + @strWhereMCNo + ' ' + @strWhereRequestItem + ' ' + @SpecialCritDev + ')
						UNION ALL
						(SELECT ' + @sqlFields + ', ' + @strRTimeA + '
						 FROM gridPLData AS a
						 WHERE Turnover IN ( ''PE'', ''EE'')
						 AND CONVERT(DATE, OccurrenceDate) BETWEEN ''' + CONVERT(NVARCHAR, @FromDate, 23) + ''' AND ''' + CONVERT(NVARCHAR, @ToDate, 23) + '''
						 ' + @searchCriteria + ' ' + @strWhereMCNo + ' ' + @strWhereRequestItem + ' ' + @SpecialCritDev + ')
						UNION ALL
						(SELECT ' + @sqlFields + ', ' + @strRTimeB + '
						 FROM gridWBData AS b
						 WHERE Turnover IN ( ''PE'', ''EE'')
						 AND CONVERT(DATE, OccurrenceDate) BETWEEN ''' + CONVERT(NVARCHAR, @FromDate, 23) + ''' AND ''' + CONVERT(NVARCHAR, @ToDate, 23) + '''
						 ' + @searchCriteria + ' ' + @strWhereMCNo + ' ' + @strWhereRequestItem + ' ' + @SpecialCritDev + ')
						UNION ALL
						(SELECT ' + @sqlFields + ', ' + @strRTimeA + '
						 FROM gridDCData AS a
						 WHERE Turnover IN ( ''PE'', ''EE'')
						 AND CONVERT(DATE, OccurrenceDate) BETWEEN ''' + CONVERT(NVARCHAR, @FromDate, 23) + ''' AND ''' + CONVERT(NVARCHAR, @ToDate, 23) + '''
						 ' + @searchCriteria + ' ' + @strWhereMCNo + ' ' + @strWhereRequestItem + ' ' + @SpecialCritDev + ')
						UNION ALL
						(SELECT ' + @sqlFields + ', ' + @strRTimeB + '
						 FROM gridMEMSData AS b
						 WHERE Turnover IN ( ''PE'', ''EE'')
						 AND CONVERT(DATE, OccurrenceDate) BETWEEN ''' + CONVERT(NVARCHAR, @FromDate, 23) + ''' AND ''' + CONVERT(NVARCHAR, @ToDate, 23) + '''
						 ' + @searchCriteria + ' ' + @strWhereMCNo + ' ' + @strWhereRequestItem + ' ' + @SpecialCritDev + ')
						UNION ALL
						(SELECT ' + @sqlFields + ', ' + @strRTimeA + '
						 FROM gridSINGData AS a
						 WHERE Turnover IN ( ''PE'', ''EE'')
						 AND CONVERT(DATE, OccurrenceDate) BETWEEN ''' + CONVERT(NVARCHAR, @FromDate, 23) + ''' AND ''' + CONVERT(NVARCHAR, @ToDate, 23) + '''
						 ' + @searchCriteria + ' ' + @strWhereMCNo + ' ' + @strWhereRequestItem + ' ' + @SpecialCritDev + ')
						UNION ALL
						(SELECT ' + @sqlFields + ', ' + @strRTimeB + '
						 FROM gridATCData AS b
						 WHERE Turnover IN ( ''PE'', ''EE'')
						 AND CONVERT(DATE, OccurrenceDate) BETWEEN ''' + CONVERT(NVARCHAR, @FromDate, 23) + ''' AND ''' + CONVERT(NVARCHAR, @ToDate, 23) + '''
						 ' + @searchCriteria + ' ' + @strWhereMCNo + ' ' + @strWhereRequestItem + ' ' + @SpecialCritDev + ')
						';
  		 
    END

ELSE IF @inRole IN ( 'PEI')
    BEGIN


			SET @SqlCommand = '
						(SELECT ' + @sqlFields + ', ' + @strRTimeA + '
						 FROM gridFLData AS a
						 WHERE Turnover IN (''VIS'', ''CC'', ''PE'', ''EE'')
						 AND CONVERT(DATE, OccurrenceDate) BETWEEN ''' + CONVERT(NVARCHAR, @FromDate, 23) + ''' AND ''' + CONVERT(NVARCHAR, @ToDate, 23) + '''
						 ' + @searchCriteria + ' ' + @strWhereMCNo + ' ' + @strWhereRequestItem + ' ' + @SpecialCritDev + ')
						UNION ALL
						(SELECT ' + @sqlFields + ', ' + @strRTimeB + '
						 FROM gridTPData AS b
						 WHERE Turnover IN (''VIS'', ''CC'', ''PE'', ''EE'')
						 AND CONVERT(DATE, OccurrenceDate) BETWEEN ''' + CONVERT(NVARCHAR, @FromDate, 23) + ''' AND ''' + CONVERT(NVARCHAR, @ToDate, 23) + '''
						 ' + @searchCriteria + ' ' + @strWhereMCNo + ' ' + @strWhereRequestItem + ' ' + @SpecialCritDev + ')
						UNION ALL
						(SELECT ' + @sqlFields + ', ' + @strRTimeA + '
						 FROM gridEDSData AS a
						 WHERE Turnover IN (''VIS'', ''CC'', ''PE'', ''EE'')
						 AND CONVERT(DATE, OccurrenceDate) BETWEEN ''' + CONVERT(NVARCHAR, @FromDate, 23) + ''' AND ''' + CONVERT(NVARCHAR, @ToDate, 23) + '''
						 ' + @searchCriteria + ' ' + @strWhereMCNo + ' ' + @strWhereRequestItem + ' ' + @SpecialCritDev + ')
						UNION ALL
						(SELECT ' + @sqlFields + ', ' + @strRTimeB + '
