                          FROM grid' + @inProc + 'Data WHERE CONVERT(DATE, OccurrenceDate) BETWEEN ''' + CONVERT(VARCHAR, @fromDate, 120) + ''' AND ''' + CONVERT(VARCHAR, @toDate, 120) + ''' ' +
                          @searchCriteria +''+@SqlWhereLoc + ' ' + @SqlWhereProc + ' ' +
                            @SpecialCritDev + ' ' +
                          @StrWhereMCNo + ' ' + @StrWhereRequestItem + '
                          ORDER BY TimeofRequest DESC';
   
END
ELSE
BEGIN
SET @SqlCommand = 'SELECT ' + @SqlFields + ', ' + @StrRTime + '
                  FROM grid' + @inProc + 'Data
                  WHERE CONVERT(DATE, OccurrenceDate) BETWEEN ''' + CONVERT(VARCHAR, @FromDate, 120) + '''
                  AND ''' + CONVERT(VARCHAR, @ToDate, 120) + ''' ' +
                  @SqlWhereLoc + ' ' + @SqlWhereProc + ' ' +
                  @SearchCriteria + ' ' + @SpecialCritDev + ' ' +
                  @StrWhereMCNo + ' ' + @StrWhereRequestItem + '
                  ORDER BY TimeofRequest DESC';
END


--PRINT @SqlCommand;

   
PRINT 'SqlFields: ' + @SqlFields;
PRINT 'StrRTime: ' + @StrRTime;
PRINT 'SqlWhereProc: ' + ISNULL(@SqlWhereProc, 'NULL');
PRINT 'SearchCriteria: ' + ISNULL(@SearchCriteria, 'NULL');
PRINT 'SpecialCritDev: ' + ISNULL(@SpecialCritDev, 'NULL');
PRINT 'SqlWhereLoc: ' + ISNULL(@SqlWhereLoc, 'NULL');

EXEC sp_executesql @SqlCommand,
     N'@MCNo VARCHAR(50), @RequestItem VARCHAR(100), @inLoc VARCHAR(50), @FromDate DATE, @ToDate DATE',
       @MCNo = @MCNo,
       @RequestItem = @RequestItem,
      @inLoc = @inLoc,
       @FromDate = @FromDate,
      @ToDate = @ToDate;


   
END;
