    -- Insert statements for procedure here
	INSERT INTO [DBBMMaintenance]

		(SubProcessID,
		PMCategoryID,
		MCNo, 
		MCStatus,
		MCType,
		OPBMUnitID,
		LOTNo,
		DeviceName,
		PkgName,
		RequestItem,
		OccurrenceDate,
		NGDetectionCircumtances,
		RequestContent,
		OccurrenceFreq,
		OccurrenceFreqQuantity,
		OccurrenceFreqLotFrame,
		AQI,
		Andon,
		GLAndon,
		GLAndon2,
		TimeOfRequest,
		RequestedBy,
		BMStatusID,
		BMCaseID,		
		QCData,
		OCAPData,
		Process,
		Location,
		isNotQuality1,
		KanagataNo,
		LineLoc,
		WaferNo,
		GLConfirmOPReq,
		GLConfirmOPReqReason,
		GLConfirmOPReqBy,
		GLConfirmOPReqDate,
		PMConfirmGLOPReq,
		PMConfirmGLOPReason,
		PMConfirmGLOPReqBy,
		PMConfirmGLOPReqDate,
		StartOfRepair,
		RepairedByStart,
		CurrentPM,
		FrequencyOP )
		
	VALUES  
	
	    (@SubProcessID,
		@PMCategoryID,
		@MCNo, 
		@MCStatus,
		@MCType,
		@OPBMUnitID,
		@LOTNo,
		@DeviceName,
		@PkgName,
		@RequestItem,
		@OccurrenceDate,
		@NGDetectionCircumtances,
		@RequestContent,
		@OccurrenceFreq,
		@OccurrenceFreqQuantity,
		@OccurrenceFreqLotFrame,
		@AQI,
		@Andon,
		@GLAndon,
		@GLAndon2,
		@TimeOfRequest,
		@RequestedBy,
		@BMStatusID,
		@BMCaseID,
		@QCData,
		@OCAPData,
		@Process,
		@Location,
		@isNotQuality1,
		@KanagataNo,
		@LineLoc,
		@WaferNo,
		@GLConfirmOPReq,
		@GLConfirmOPReqReason,
		@GLConfirmOPReqBy,
		@GLConfirmOPReqDate,
		@PMConfirmGLOPReq,
		@PMConfirmGLOPReason,
		@PMConfirmGLOPReqBy,
		@PMConfirmGLOPReqDate,
		@StartOfRepair,
		@RepairedByStart,
		@PMConfirmGLOPReqBy,
		@FrequencyOP )
        
        SELECT 0 [ID]
		
END
	ELSE
	SELECT -1 [ID]
END







