    Process, BMID, a.BMStatusID,Location, StartOfRepair, EndOfRepair,[SubProcessID],[PMCategoryID],[MCNo] ,[MCStatus] ,[MCType],[OPBMUnitID],[LOTNo],[DeviceName] ,[PkgName] ,[RequestItem] ,[OccurrenceDate] ,[NGDetectionCircumtances] ,[RequestContent],[OccurrenceFreq]  
HAVING 
    SUM(CASE WHEN DATEDIFF(HOUR, StartOfRepair, GETDATE())    BETWEEN 6.00 AND 11.99  THEN 1 ELSE 0 END) > 0
    OR SUM(CASE WHEN DATEDIFF(HOUR, StartOfRepair, GETDATE()) BETWEEN 12.00 AND 23.99 THEN 1 ELSE 0 END) > 0
    OR SUM(CASE WHEN DATEDIFF(HOUR, StartOfRepair, GETDATE()) >= 24 THEN 1 ELSE 0 END) > 0

	UNION ALL

SELECT 
    Process,
    BMID,
    (SELECT BMStatus FROM BMStatus WHERE BMStatusID = a.BMStatusID) AS BMStatusName,
	Location,
    StartOfRepair,
    EndOfRepair,
	[SubProcessID],[PMCategoryID],[MCNo] ,[MCStatus] ,[MCType],[OPBMUnitID],[LOTNo],[DeviceName] ,[PkgName] ,[RequestItem] ,[OccurrenceDate] ,[NGDetectionCircumtances] ,[RequestContent],[OccurrenceFreq],
    ISNULL(SUM(CASE WHEN DATEDIFF(HOUR, StartOfRepair, GETDATE()) BETWEEN 6.00 AND 11.99 THEN 1 ELSE 0 END), 0) AS '6 Hours',
    ISNULL(SUM(CASE WHEN DATEDIFF(HOUR, StartOfRepair, GETDATE()) BETWEEN 12.00 AND 23.99 THEN 1 ELSE 0 END), 0) AS '12 Hours',
    ISNULL(SUM(CASE WHEN DATEDIFF(HOUR, StartOfRepair, GETDATE()) >= 24 THEN 1 ELSE 0 END), 0) AS '24 Hours'
FROM 
    [eMaintenanceSystemDB].[dbo].[WBBMMaintenance] a
WHERE 
    BMStatusID IN ('1','2','3','5','6','7','10','11','12', '13','16','17','20','21')
    AND (EndOfRepair IS NULL AND RepairedByEnd IS NULL) 
    AND (StartOfRepair IS NOT NULL AND RepairedByStart IS NOT NULL)

	

GROUP BY 
    Process, BMID, a.BMStatusID,Location, StartOfRepair, EndOfRepair,[SubProcessID],[PMCategoryID],[MCNo] ,[MCStatus] ,[MCType],[OPBMUnitID],[LOTNo],[DeviceName] ,[PkgName] ,[RequestItem] ,[OccurrenceDate] ,[NGDetectionCircumtances] ,[RequestContent],[OccurrenceFreq]  
HAVING 
    SUM(CASE WHEN DATEDIFF(HOUR, StartOfRepair, GETDATE())    BETWEEN 6.00 AND 11.99 THEN 1 ELSE 0 END) > 0
    OR SUM(CASE WHEN DATEDIFF(HOUR, StartOfRepair, GETDATE()) BETWEEN 12.00 AND 23.99 THEN 1 ELSE 0 END) > 0
    OR SUM(CASE WHEN DATEDIFF(HOUR, StartOfRepair, GETDATE()) >= 24 THEN 1 ELSE 0 END) > 0


END
