/****** Object:  StoredProcedure [dbo].[spGetBMCountPerMonth_DB]    Script Date: 10/25/2026 4:57:10 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Vincent
-- Create date: 10 -4 -2023
-- Description:	get bm count per year 
-- =============================================
CREATE PROCEDURE [dbo].[spGetBMCountPerMonth_DB] 
	-- Add the parameters for the stored procedure here
	@Year AS INTEGER,
	@Month AS INTEGER
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

   SELECT 
     ISNULL(SUM(CASE WHEN DATEDIFF(HOUR, StartOfRepair, EndOfRepair)BETWEEN 6.00 AND 11.99  THEN 1 ELSE 0 END), 0) AS '6 Hours',
    ISNULL(SUM(CASE WHEN DATEDIFF(HOUR, StartOfRepair, EndOfRepair) BETWEEN 12.00 AND 23.99 THEN 1 ELSE 0 END), 0) AS '12 Hours',
    ISNULL(SUM(CASE WHEN DATEDIFF(HOUR, StartOfRepair, EndOfRepair) >= 24 THEN 1 ELSE 0 END), 0) AS '24 Hours'
  FROM [eMaintenanceSystemDB].[dbo].[DBBMMaintenance]
  WHERE 
  (MONTH(StartOfRepair) =@Month AND YEAR(StartOfRepair) = @Year) AND (MONTH(EndOfRepair) =@Month AND YEAR(EndOfRepair ) =@Year)
  AND BMStatusID IN ('4','8','9','14','15','18','19')
END
GO
