/****** Object:  StoredProcedure [dbo].[spGetDaysInMonth]    Script Date: 10/25/2026 4:57:10 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[spGetDaysInMonth]
	-- Add the parameters for the stored procedure here
	@Month As VARCHAR(10)
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	DECLARE @mydate DATETIME
	SELECT @mydate = Convert(varchar(10),YEAR(getdate())) + '/01/' + @Month

	Declare @Days Table (DateField datetime, DayField varchar(50))
	Declare @CurrentDate datetime
	Declare @EndDate datetime

	SELECT @CurrentDate = DATEADD(dd,-(DAY(@mydate)-1),@mydate)
	SELECT @EndDate =DATEADD(dd,-(DAY(DATEADD(mm,1,@mydate))),DATEADD(mm,1,@mydate))

	While @CurrentDate <= @EndDate
	Begin
	Insert Into @Days Values(@CurrentDate, DATENAME(dw , @CurrentDate))
	Set @CurrentDate = DateAdd(d,1,@CurrentDate)
	End 

	SELECT DAY(DateField) FROM @Days ORDER BY DateField

END
GO
