-- =============================================
-- Author:		vincent capistrano
-- Create date: 1/8/2024
-- Description: getting chart categories
-- =============================================
CREATE PROCEDURE [dbo].[spGetGRAPH_Categories_EMPLOYEE]
@Month_from AS INTEGER,
@Year_from AS INTEGER,
@Month_to AS INTEGER,
@YEar_to AS INTEGER,
@Empno AS VARCHAR(10)

AS
BEGIN
WITH AKAPENAOPEN_TBL AS (


    SELECT DISTINCT DATEPART(MONTH, EndOfRepair) AS MONTH, DATEPART(WEEK, EndOfRepair) AS WK 
	FROM DBBMMaintenance 
	WHERE BMStatusID = '14' AND 
	RepairedByEnd = @Empno AND
	EndOfRepair IS NOT NULL AND
	   (DATEPART(YEAR, EndOfRepair) > @Year_from  OR 
        (DATEPART(YEAR, EndOfRepair) = @Year_from  AND DATEPART(MONTH, EndOfRepair) >= @Month_from ))
    AND
    (DATEPART(YEAR, EndOfRepair) < @Year_to OR 
        (DATEPART(YEAR, EndOfRepair) = @Year_to  AND DATEPART(MONTH, EndOfRepair) <= @Month_to ))
		
	UNION ALL 

   SELECT DISTINCT DATEPART(MONTH, EndOfRepair) AS MONTH, DATEPART(WEEK, EndOfRepair) AS WK 
	FROM DCBMMaintenance
	WHERE BMStatusID = '14' AND
		RepairedByEnd = @Empno AND
    EndOfRepair IS NOT NULL AND
	   (DATEPART(YEAR, EndOfRepair) > @Year_from  OR 
        (DATEPART(YEAR, EndOfRepair) = @Year_from  AND DATEPART(MONTH, EndOfRepair) >= @Month_from ))
    AND
    (DATEPART(YEAR, EndOfRepair) < @Year_to OR 
        (DATEPART(YEAR, EndOfRepair) = @Year_to  AND DATEPART(MONTH, EndOfRepair) <= @Month_to ))

		UNION ALL 

  SELECT DISTINCT DATEPART(MONTH, EndOfRepair) AS MONTH, DATEPART(WEEK, EndOfRepair) AS WK 
	FROM EDSBMMaintenance
	WHERE BMStatusID = '14' AND
		RepairedByEnd = @Empno AND
    EndOfRepair IS NOT NULL AND
	   (DATEPART(YEAR, EndOfRepair) > @Year_from  OR 
        (DATEPART(YEAR, EndOfRepair) = @Year_from  AND DATEPART(MONTH, EndOfRepair) >= @Month_from ))
    AND
    (DATEPART(YEAR, EndOfRepair) < @Year_to OR 
        (DATEPART(YEAR, EndOfRepair) = @Year_to  AND DATEPART(MONTH, EndOfRepair) <= @Month_to ))

		UNION ALL 

    SELECT DISTINCT DATEPART(MONTH, EndOfRepair) AS MONTH, DATEPART(WEEK, EndOfRepair) AS WK 
	FROM FLBMMaintenance
	WHERE BMStatusID = '14' AND
		RepairedByEnd = @Empno AND
    EndOfRepair IS NOT NULL AND
   (DATEPART(YEAR, EndOfRepair) > @Year_from  OR 
        (DATEPART(YEAR, EndOfRepair) = @Year_from  AND DATEPART(MONTH, EndOfRepair) >= @Month_from ))
    AND
    (DATEPART(YEAR, EndOfRepair) < @Year_to OR 
        (DATEPART(YEAR, EndOfRepair) = @Year_to  AND DATEPART(MONTH, EndOfRepair) <= @Month_to ))

		UNION ALL 

SELECT DISTINCT DATEPART(MONTH, EndOfRepair) AS MONTH, DATEPART(WEEK, EndOfRepair) AS WK 
	FROM FTBMMaintenance
	WHERE BMStatusID = '14' AND
		RepairedByEnd = @Empno AND
    EndOfRepair IS NOT NULL AND
   (DATEPART(YEAR, EndOfRepair) > @Year_from  OR 
        (DATEPART(YEAR, EndOfRepair) = @Year_from  AND DATEPART(MONTH, EndOfRepair) >= @Month_from ))
    AND
    (DATEPART(YEAR, EndOfRepair) < @Year_to OR 
        (DATEPART(YEAR, EndOfRepair) = @Year_to  AND DATEPART(MONTH, EndOfRepair) <= @Month_to ))

		UNION ALL 

SELECT DISTINCT DATEPART(MONTH, EndOfRepair) AS MONTH, DATEPART(WEEK, EndOfRepair) AS WK 
	FROM MEMSBMMaintenance
	WHERE BMStatusID = '14' AND
		RepairedByEnd = @Empno AND
    EndOfRepair IS NOT NULL AND
   (DATEPART(YEAR, EndOfRepair) > @Year_from  OR 
        (DATEPART(YEAR, EndOfRepair) = @Year_from  AND DATEPART(MONTH, EndOfRepair) >= @Month_from ))
    AND
    (DATEPART(YEAR, EndOfRepair) < @Year_to OR 
        (DATEPART(YEAR, EndOfRepair) = @Year_to  AND DATEPART(MONTH, EndOfRepair) <= @Month_to ))

		UNION ALL 

SELECT DISTINCT DATEPART(MONTH, EndOfRepair) AS MONTH, DATEPART(WEEK, EndOfRepair) AS WK 
	FROM MPBMMaintenance
	WHERE BMStatusID = '14' AND
		RepairedByEnd = @Empno AND
    EndOfRepair IS NOT NULL AND
   (DATEPART(YEAR, EndOfRepair) > @Year_from  OR 
        (DATEPART(YEAR, EndOfRepair) = @Year_from  AND DATEPART(MONTH, EndOfRepair) >= @Month_from ))
    AND
    (DATEPART(YEAR, EndOfRepair) < @Year_to OR 
        (DATEPART(YEAR, EndOfRepair) = @Year_to  AND DATEPART(MONTH, EndOfRepair) <= @Month_to ))

		UNION ALL 

SELECT DISTINCT DATEPART(MONTH, EndOfRepair) AS MONTH, DATEPART(WEEK, EndOfRepair) AS WK 
	FROM PLBMMaintenance
	WHERE BMStatusID = '14' AND
		RepairedByEnd = @Empno AND
    EndOfRepair IS NOT NULL AND
	   (DATEPART(YEAR, EndOfRepair) > @Year_from  OR 
        (DATEPART(YEAR, EndOfRepair) = @Year_from  AND DATEPART(MONTH, EndOfRepair) >= @Month_from ))
    AND
    (DATEPART(YEAR, EndOfRepair) < @Year_to OR 
        (DATEPART(YEAR, EndOfRepair) = @Year_to  AND DATEPART(MONTH, EndOfRepair) <= @Month_to ))

	--	UNION ALL 

 --   SELECT bmID, Process , Location, Akapen1, AKAPEN2, AKAPEN3, AOPEN1, Aopen2, Aopen3, DATEPART(MONTH, EndOfRepair) AS MONTH,DATEPART(WEEK, EndOfRepair) AS WK , RepairedByEnd AS ACCREDITOR  
	--FROM TEBMMaintenance
