Create PROCEDURE [dbo].[spGetLoadDataMonthly_OEE_Compute]
(
@DateFrom datetime,
@DateTo datetime,
@McName varchar(20),
@Process varchar(20)
)
AS
if @Process = 'TP'
BEGIN				
					select  sum(convert(decimal(12,2),convert(decimal(12,2),convert(decimal(12,2),datediff(second,TimeOfRequest,endofrepair))/86400)*1440)) as PMLossTime,isnull(sum(convert(decimal(12,2),convert(decimal(12,2),convert(decimal(12,2),datediff(second,PEConfirmPMTurnoverDate,endofrepair))/86400)*1440)),0.00) as PELossTime
					from
