/****** Object:  StoredProcedure [dbo].[spGetLoadDataMonthly_OEE_Compute_New_RawData]    Script Date: 10/25/2026 4:57:10 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[spGetLoadDataMonthly_OEE_Compute_New_RawData]
(
@DateFrom datetime,
@DateTo datetime,
@McName varchar(20),
@McName2 varchar(20),
@Package varchar(50),
@Process varchar(20),
@Location varchar(20),
@Location2 varchar(20),
@McType varchar(50),
@RepOne varchar(20),
@RepTwo varchar(20),
@RepThree varchar(20),
@RepFour varchar(20)
)
AS
begin
 SET NOCOUNT ON;
declare @query nvarchar(MAX);
				SET @query= 
																		'Select OK.*
																		from
																		(
																		Select Machineno,Month11,Week1,Day1,year1,convert(datetime, starttime, 103) as starttime1,convert(datetime, endtime, 103) as endtime1, lead(starttime,1,endtime) over (order by month11,week1,day1,convert(datetime, starttime, 103) ) as nexttime 
																		from selcondb.dbo.View'+ @Process +'Data_OEE
																		where  (StartTime BETWEEN @DateFrom AND @DateTo) ' +

																		(case
																		 when ((@McName2 = 'N/A') and (@Location2 = 'N/A') and (@Package = 'N/A') and (@McType) = 'N/A')
																		then ''
																		else
																			' AND '
																			+
																			(case when @McName2 <> 'N/A' then ' Machineno = '''+ @McName2 +'''' +(case when @McType <> 'N/A' then ' AND ' else '' end) else '' end) 							
																			+
																			(case when @McType <> 'N/A' then ' MachineType = '''+ @McType +'''' +(case when @Location2 <> 'N/A' then ' AND ' else '' end) else ''  end)
																			+
											  							   (case when @Location2 <> 'N/A' then ' Location = '''+ @Location2 +'''' + (case when @Package <> 'N/A' then ' AND ' else '' end) else '' end)
																			+
																			(case when @Package <> 'N/A' then ' Package = '''+ @Package +'''' + '' else '' end)
																		 end)
																		+ ')

																		as gg

																		right join
																		(
																		Select replace(replace(REPLACE(MCNO,'+ @RepOne +','+ @RepTwo +'),'+ @RepTwo +','+ @RepThree +'),'+ @RepThree +','+ @RepFour +') as Machineno,Month1 as Month,Week1 as Week,Day1 as Day,year1 as Year,convert(datetime, timeofrequest, 103) as TimeofRequest ,sum(convert(decimal(12,4),convert(decimal(12,4),convert(decimal(12,4),datediff(second,TimeOfRequest,endofrepair))/86400)*1440)) as PMLossTime,isnull(sum(convert(decimal(12,4),convert(decimal(12,4),convert(decimal(12,4),datediff(second,PEConfirmPMTurnoverDate,endofrepair))/86400)*1440)),0.00) as PELossTime,isnull(sum(convert(decimal(12,4),convert(decimal(12,4),convert(decimal(12,4),datediff(second,StartofRepair,Endofrepair))/86400)*1440)),0.00) as PMRepairTime,isnull(sum(convert(decimal(12,4),convert(decimal(12,4),convert(decimal(12,4),datediff(second,GLConfirmOPReqDate,startofrepair))/86400)*1440)),0.00) as PDWaitingTime,isnull(sum(convert(decimal(12,4),convert(decimal(12,4),convert(decimal(12,4),datediff(second,timeofrequest,GLConfirmOPReqDate))/86400)*1440)),0.00) as PMWaitingTime
																		from emaintenancesystemdb.dbo.View'+ @Process +'BM_OEE  
																		where  (TimeOfRequest BETWEEN @DateFrom AND @DateTo)  ' +

																		(case
																		 when ((@McName = 'N/A') and (@Location = 'N/A'))
																		then ''
																		else
																			' AND '
																			+
																			(case when @Location <> 'N/A' then ' Location = '''+ @Location +'''' +( case when @McName <> 'N/A' then ' AND ' else '' end) else '' end) 							
																			+								
																			(case when @McName <> 'N/A' then ' mcno = '''+ @McName +'''' + '' else '' end)
																		 end)



																		+ 'group by mcno,month1,week1,day1,year1,timeofrequest1,TimeOfRequest
																		)

																		as ok

																		on
																		 gg.Month11  = ok.month
																		and gg.week1 = ok.week
																		and gg.Day1 = ok.day
																		and gg.Year1 = ok.Year
																		and ok.timeofrequest  between gg.ENDTIME1 and gg.nexttime
																		order by ok.machineno,ok.Month,ok.week,ok.day,ok.year desc'
								
		
							
						 EXECUTE sp_executesql @query,
						 N'@DateFrom datetime,
						@DateTo datetime,
						@McName varchar(20),
						@McName2 varchar(20),
						@Package varchar(50),
						@Process varchar(20),
						@Location varchar(20),
						@Location2 varchar(20),
						@McType varchar(50),
						@RepOne varchar(20),
						@RepTwo varchar(20),
						@RepThree varchar(20),
						@RepFour varchar(20)',
						 @DateFrom,
						@DateTo,
						@McName,
						@McName2,
						@Package,
						@Process,
						@Location ,
						@Location2 ,
						@McType,
						@RepOne ,
						@RepTwo ,
						@RepThree ,
						@RepFour  		
							


end
GO
/****** Object:  StoredProcedure [dbo].[spGetMachineKarte_viewer]    Script Date: 10/25/2026 4:57:10 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[spGetMachineKarte_viewer]
(

 @MONTHTEMP VARCHAR(20),
 @YEARTEMP VARCHAR(20),
 @MCType VARCHAR(20),
 @Process VARCHAR(20),
 @Tablename varchar(100),
 @MCname varchar(20)
)
AS
Create Table #TempTable (
    BMcase  varchar(100),
	BMCount int,
	WeekID int
);



DECLARE @DAYTEMP VARCHAR(20) = '01'
DECLARE @MyDate1 varchar(20)
DECLARE @MyDate2 varchar(20)
DECLARE @Result1 varchar(100)
DECLARE @Result2 varchar(100)
DECLARE @GetDate  DATETIME
DECLARE @Sql NVARCHAR(MAX)

set @GetDate = @MONTHTEMP + '/' + @DAYTEMP + '/' + @YEARTEMP 

SET @MyDate1 = (SELECT format(  DATEADD(month, -2, @GetDate),'MM/01/yyyy') AS FirstDate );
SET @MyDate2 = (SELECT format(DATEADD(DD,-(DAY(@GetDate)), DATEADD(MM, 1, @GetDate)),'MM/dd/yyy') AS LastDate);


set @Result1 = 	(SELECT top 1 datepart(WEEK,(DATEADD(WEEK,x.number, @MyDate1))) AS WeekID
		FROM    master.dbo.spt_values x WHERE   x.type = 'P'
		AND     x.number <= DATEDIFF(WEEK, @MyDate1, 
		@MyDate2) order by weekid asc )

set @Result2 = 	(SELECT top 1 datepart(WEEK,(DATEADD(WEEK,x.number, @MyDate1))) AS WeekID
		FROM    master.dbo.spt_values x WHERE   x.type = 'P'
		AND     x.number <= DATEDIFF(WEEK, @MyDate1, 
		@MyDate2) order by weekid desc )
		
DECLARE @i int = @result1
WHILE @i <= @result2
BEGIN
PRINT @i
     

	 if @MCname = ''
	 begin
				 SET @Sql =  'Insert Into #TempTable 
			  Select top(10) b.BMCase as BMCase,count(b.BMCase) as Count,datepart(week,EndOfRepair) as WeekID FROM '+ @Tablename +' a
				inner join [eMaintenanceSystemDB].[dbo].[BMCase] b
					on a.BMCaseID = b.BMCaseID 
				inner join [eMaintenanceSystemDB].[dbo].[Process] c
					on b.process = c.ProcessName 
				inner join  [eMaintenanceSystemDB].[dbo].[MCType] d
					on c.ProcessID = d.ProcessID 
						where (c.ProcessName =  '''+ @Process +'''    and d.MCType =  '''+ @MCType +'''  and a.PMCategoryID = 1 and b.BMCase <> ''-'') and ((EndOfRepair between   '''+ @MyDate1 +'''    and   '''+ @MyDate2 +''')   and datepart(week,EndOfRepair) =  '''+ cast(@i as varchar(20)) +''') 

				group by b.BMCase,datepart(week,EndOfRepair)
				order by weekid desc,count desc'
	 end
	 else
	 begin

			  SET @Sql =  'Insert Into #TempTable 
			  Select top(10) b.BMCase as BMCase,count(b.BMCase) as Count,datepart(week,EndOfRepair) as WeekID FROM '+ @Tablename +' a
				inner join [eMaintenanceSystemDB].[dbo].[BMCase] b
					on a.BMCaseID = b.BMCaseID 
				inner join [eMaintenanceSystemDB].[dbo].[Process] c
					on b.process = c.ProcessName 
				inner join  [eMaintenanceSystemDB].[dbo].[MCType] d
					on c.ProcessID = d.ProcessID 
						where (c.ProcessName =  '''+ @Process +'''    and d.MCType =  '''+ @MCType +''' and a.MCno =  '''+ @MCname +'''  and a.PMCategoryID = 1 and b.BMCase <> ''-'') and ((EndOfRepair between   '''+ @MyDate1 +'''    and   '''+ @MyDate2 +''')   and datepart(week,EndOfRepair) =  '''+ cast(@i as varchar(20)) +''') 

				group by b.BMCase,datepart(week,EndOfRepair)
				order by weekid desc,count desc'
	 end

	PRINT @Sql
	 EXECUTE sp_executesql @Sql

	 SET @i = @i + 1



END

		select test1.WeekID,coalesce(test2.BMCount,0) as BMCount , coalesce(test2.BMcase,'') as BMCase
		from
		(
		SELECT  datepart(WEEK,(DATEADD(WEEK,x.number, @MyDate1))) AS WeekID
		FROM    master.dbo.spt_values x WHERE   x.type = 'P'
		AND     x.number <= DATEDIFF(WEEK, @MyDate1, @MyDate2)
		) 
		as test1


		left join 

		(
		Select * 
		FROM    #TempTable
		
		) 
		as test2

		on  test1.WeekID = test2.WeekID 
		order by test1.WeekID

Drop Table #TempTable
GO
