CREATE PROCEDURE [dbo].[spGetMachineKarteRawData_viewer]
(

 @MONTHTEMP VARCHAR(20),
 @YEARTEMP VARCHAR(20),
 @MCType VARCHAR(20),
 @Process VARCHAR(20),
  @Tablename varchar(100),
 @MCname varchar(20)

)
AS
BEGIN

DECLARE @DAYTEMP VARCHAR(20) = '01'
DECLARE @MyDate1 varchar(20)
DECLARE @MyDate2 varchar(20)
DECLARE @Result1 varchar(100)
DECLARE @Result2 varchar(100)
DECLARE @GetDate  DATETIME
set @GetDate = @MONTHTEMP + '/' + @DAYTEMP + '/' + @YEARTEMP 

SET @MyDate1 = (SELECT format(  DATEADD(month, -2, @GetDate),'MM/01/yyyy') AS FirstDate );
SET @MyDate2 = (SELECT format(DATEADD(DD,-(DAY(@GetDate)), DATEADD(MM, 1, @GetDate)),'MM/dd/yyy') AS LastDate);
DECLARE @Sql NVARCHAR(MAX)

 if @MCname = ''
	 begin
	 SET @Sql =  'select a.MCNo as MCNo,a.pkgname as Package,a.LOTNo as LotNo,a.DeviceName as DeviceName,e.PMCategory as Classification,b.BMCase as CaseName,a.TimeOfRequest as RequestDateandTime,a.RequestedBy as Issuer,a.PMConfirmGLOPReqBy as PMConfirmedRequest,a.StartOfRepair as StartDateAndTime,a.EndOfRepair as EndDateAndTime,f.BMWhy as Why4  FROM '+ @Tablename +'  a
			inner join [eMaintenanceSystemDB].[dbo].[BMCase] b
				on a.BMCaseID = b.BMCaseID 
			inner join [eMaintenanceSystemDB].[dbo].[Process] c
				on b.process = c.ProcessName 
			inner join  [eMaintenanceSystemDB].[dbo].[MCType] d
				on c.ProcessID = d.ProcessID 
			inner join  [eMaintenanceSystemDB].[dbo].[PMCategory] e
				on a.PMCategoryID  = e.PMCategoryID 
					inner join  [eMaintenanceSystemDB].[dbo].[BMWhy] f
				on a.why4  = f.BMWhyID
					
					where (c.Processname = '''+ @Process +''' and d.MCType = '''+ @MCType +''' and a.PMCategoryID = 1) and (EndOfRepair between   '''+ @MyDate1 +'''    and   '''+ @MyDate2 +''' )
					order by mcno,TimeOfRequest asc'
	 end
	 else
	 begin
	 SET @Sql =  'select a.MCNo as MCNo,a.pkgname as Package,a.LOTNo as LotNo,a.DeviceName as DeviceName,e.PMCategory as Classification,b.BMCase as CaseName,a.TimeOfRequest as RequestDateandTime,a.RequestedBy as Issuer,a.PMConfirmGLOPReqBy as PMConfirmedRequest,a.StartOfRepair as StartDateAndTime,a.EndOfRepair as EndDateAndTime,f.BMWhy as Why4  FROM '+ @Tablename +'  a
			inner join [eMaintenanceSystemDB].[dbo].[BMCase] b
				on a.BMCaseID = b.BMCaseID 
			inner join [eMaintenanceSystemDB].[dbo].[Process] c
				on b.process = c.ProcessName 
			inner join  [eMaintenanceSystemDB].[dbo].[MCType] d
				on c.ProcessID = d.ProcessID 
			inner join  [eMaintenanceSystemDB].[dbo].[PMCategory] e
				on a.PMCategoryID  = e.PMCategoryID 
					inner join  [eMaintenanceSystemDB].[dbo].[BMWhy] f
				on a.why4  = f.BMWhyID
					
					where (c.Processname = '''+ @Process +''' and d.MCType = '''+ @MCType +''' and a.MCno =  '''+ @MCname +''' and a.PMCategoryID = 1) and (EndOfRepair between   '''+ @MyDate1 +'''    and   '''+ @MyDate2 +''' )
					order by mcno,TimeOfRequest asc'
	 end
	 







execute sp_executesql @sql
END


GO
