CREATE PROCEDURE [dbo].[spGetMCLicense]
  	@acnt_no int,
	@ProcessName varchar(50),
	@MCtype varchar(50)
AS
BEGIN
DECLARE @Connection As Int
SET @Connection = (select  1  from sys.servers where name = '10.27.1.163') 
IF @Connection = 1
				BEGIN
					SELECT
                      [BMSkillID]                     
                       ,coalesce([DateStart],GETDATE()) as 'DateStart'
                      ,coalesce([DateEnd],GETDATE()) as 'DateEnd'
                      ,[SkillDesc],'QLMS' as 'Server'
                  FROM [10.27.1.163].[QLMSMK].[dbo].[V_NewMCLicense] WHERE acnt_no = @acnt_no AND ProcessName = @ProcessName AND MCtype = @MCtype				 			
				END
ELSE 
				BEGIN
				 SELECT [BMSkillID]                     
                      ,coalesce([DateStart],GETDATE()) as 'DateStart'
                      ,coalesce([DateEnd],GETDATE()) as 'DateEnd'
                      ,[PMCategory] as SkillDesc,'EMAINT' as 'Server'
					  FROM dbo.viewSkillMap WHERE acnt_no = @acnt_no AND ProcessName = @ProcessName AND MCtype = @MCtype					
				END	
END


