/****** Object:  StoredProcedure [dbo].[spGetPESBMCount]    Script Date: 10/25/2026 4:57:10 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[spGetPESBMCount]
    @Month_from AS INTEGER,
    @Year_from AS INTEGER,
    @Month_to AS INTEGER,
    @Year_to AS INTEGER
AS
BEGIN
    SELECT 
        'DB' AS Process,
        AVG(PERepairtime) AS PERepairTimeAVG, 
        AVG(PEWaitingTime) AS PEWaitingtime, 
        BMMonth AS MONTHLYBM,
        COUNT (bmID) AS BMCOUNT
    FROM [eMaintenanceSystemDB].[dbo].[ViewDBDataPE]
    WHERE
        (BMYear > @Year_from OR (BMYear = @Year_from AND BMMonth >= @Month_from))
        AND
        (BMYear < @Year_to OR (BMYear = @Year_to AND BMMonth <= @Month_to))
    GROUP BY BMMonth
    
    UNION ALL
    
    SELECT 
        'FL' AS Process,
        AVG(PERepairtime) AS PERepairTimeAVG, 
        AVG(PEWaitingTime) AS PEWaitingtime, 
        BMMonth AS MONTHLYBM,
        COUNT (bmID) AS BMCOUNT  
    FROM [eMaintenanceSystemDB].[dbo].[ViewFLDataPE]
    WHERE
        (BMYear > @Year_from OR (BMYear = @Year_from AND BMMonth >= @Month_from))
        AND
        (BMYear < @Year_to OR (BMYear = @Year_to AND BMMonth <= @Month_to))
    GROUP BY BMMonth
    
    UNION ALL
    
    SELECT 
        'FT' AS Process,
        AVG(PERepairtime) AS PERepairTimeAVG, 
        AVG(PEWaitingTime) AS PEWaitingtime, 
        BMMonth AS MONTHLYBM,
        COUNT (bmID) AS BMCOUNT
    FROM [eMaintenanceSystemDB].[dbo].[ViewFTDataPE]
    WHERE
        (BMYear > @Year_from OR (BMYear = @Year_from AND BMMonth >= @Month_from))
        AND
        (BMYear < @Year_to OR (BMYear = @Year_to AND BMMonth <= @Month_to))
    GROUP BY BMMonth
    
    UNION ALL
    
    SELECT 
        'MP' AS Process,
        AVG(PERepairtime) AS PERepairTimeAVG, 
        AVG(PEWaitingTime) AS PEWaitingtime, 
        BMMonth AS MONTHLYBM,
        COUNT (bmID) AS BMCOUNT  
    FROM [eMaintenanceSystemDB].[dbo].[ViewMPDataPE]
    WHERE
        (BMYear > @Year_from OR (BMYear = @Year_from AND BMMonth >= @Month_from))
        AND
        (BMYear < @Year_to OR (BMYear = @Year_to AND BMMonth <= @Month_to))
    GROUP BY BMMonth
    
    UNION ALL
    
    SELECT 
        'PL' AS Process,
        AVG(PERepairtime) AS PERepairTimeAVG, 
        AVG(PEWaitingTime) AS PEWaitingtime, 
        BMMonth AS MONTHLYBM,
        COUNT (bmID) AS BMCOUNT  
    FROM [eMaintenanceSystemDB].[dbo].[ViewPLDataPE]
    WHERE
        (BMYear > @Year_from OR (BMYear = @Year_from AND BMMonth >= @Month_from))
        AND
        (BMYear < @Year_to OR (BMYear = @Year_to AND BMMonth <= @Month_to))
    GROUP BY BMMonth
    
    UNION ALL
    
    SELECT 
        'TP' AS Process,
        AVG(PERepairtime) AS PERepairTimeAVG, 
        AVG(PEWaitingTime) AS PEWaitingtime, 
        BMMonth AS MONTHLYBM,
        COUNT (bmID) AS BMCOUNT  
    FROM [eMaintenanceSystemDB].[dbo].[ViewTPDataPE]
    WHERE
        (BMYear > @Year_from OR (BMYear = @Year_from AND BMMonth >= @Month_from))
        AND
        (BMYear < @Year_to OR (BMYear = @Year_to AND BMMonth <= @Month_to))
    GROUP BY BMMonth
    
    UNION ALL
    
    SELECT 
        'WB' AS Process,
        AVG(PERepairtime) AS PERepairTimeAVG, 
        AVG(PEWaitingTime) AS PEWaitingtime, 
        BMMonth AS MONTHLYBM,
        COUNT (bmID) AS BMCOUNT  
    FROM [eMaintenanceSystemDB].[dbo].[ViewWBDataPE]
    WHERE
        (BMYear > @Year_from OR (BMYear = @Year_from AND BMMonth >= @Month_from))
        AND
        (BMYear < @Year_to OR (BMYear = @Year_to AND BMMonth <= @Month_to))
    GROUP BY BMMonth
    
    ORDER BY Process, BMMonth;
END
GO
/****** Object:  StoredProcedure [dbo].[spGetPESBMCountTest]    Script Date: 10/25/2026 4:57:10 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:      KYRONDALE GERVACIO
-- Create date: 01.16.2024
-- Description: GET PES BM COUNT
-- =============================================
CREATE PROCEDURE [dbo].[spGetPESBMCountTest]
    -- Add the parameters for the stored procedure here
   
	@Month_from AS INTEGER,
	@Year_from AS INTEGER,
	@Month_to AS INTEGER,
	@Year_to AS INTEGER,
	@PROCESS AS VARCHAR(5)
AS
BEGIN
SET NOCOUNT ON;

SELECT 
'DB' AS PROCESS,
OccurRenceDate,
DATEPART(WEEK, OccurRenceDate) AS VALUE,
COUNT (*) AS VALUE_COUNT,
AVG (PERepairtime) AS REPAIRTIME,
AVG (PEWaitingTime) AS WAITINGTIME,
SUM (PMCategoryID) AS BMQUANTITY
FROM dbo.ViewDBDataPE
WHERE
	(BMMonth > @Month_from OR 
        (BMMonth = @Month_from AND OccurRencedate>= @Month_from))
        AND
      (BMMonth > @Month_to OR 
        (BMMonth = @Month_to AND OccurRencedate >= @Month_to))

		AND
		(BMYear > @Year_from OR 
        (BMYear = @Year_from AND BMMonth >= @Month_from))
        AND
        (BMYear < @Year_to OR 
        (BMYear = @Year_to AND BMMonth <= @Month_to))
		AND
		 (PROCESS = @PROCESS)
GROUP BY 
    PROCESS,BMMonth,OccurRenceDate
	UNION ALL
SELECT 
'FL' AS PROCESS,
OccurRenceDate,
DATEPART(WEEK, OccurRenceDate) AS VALUE,
COUNT (*) AS VALUE_COUNT,
AVG (PERepairtime) AS REPAIRTIME,
AVG (PEWaitingTime) AS WAITINGTIME,
SUM (PMCategoryID) AS BMQUANTITY

FROM dbo.ViewFLDataPE
WHERE
	(BMMonth > @Month_from OR 
