-- =============================================
-- Author:		vincent
-- Create date: 10-17-2023
-- Description:	getting top 20 machince with pending bm based on downtime
-- =============================================
CREATE PROCEDURE [dbo].[spGetTop20Machine]
	-- Add the parameters for the stored procedure here
	
AS
BEGIN
	WITH FilteredRepairs AS (
  SELECT Location,Process , MCNo, StartOfRepair ,PkgName,RequestItem
    FROM DCBMMaintenance
    WHERE        
(BMStatusID IN ('1','2','3','5','6','7','9','10','12', '13','16','17','20','21'))
  AND (EndOfRepair  IS NULL AND RepairedByEnd IS NULL) AND (StartOfRepair IS NOT NULL AND RepairedByStart IS NOT NULL) AND MCNo<>'Select' AND (location <>'' OR location IS NULL)
  AND DATEDIFF(HOUR, startofrepair, GETDATE()) >= 24

 UNION ALL

 SELECT Location,Process , MCNo, StartOfRepair ,PkgName,RequestItem
    FROM DBBMMaintenance
    WHERE        
(BMStatusID IN ('1','2','3','5','6','7','9','10','12', '13','16','17','20','21'))
  AND (EndOfRepair  IS NULL AND RepairedByEnd IS NULL) AND (StartOfRepair IS NOT NULL AND RepairedByStart IS NOT NULL) AND MCNo<>'Select'AND (location <>'' OR location IS NULL)
  AND DATEDIFF(HOUR, startofrepair, GETDATE()) >= 24

  UNION ALL

 SELECT Location,Process , MCNo, StartOfRepair ,PkgName,RequestItem
    FROM WBBMMaintenance
    WHERE        
(BMStatusID IN ('1','2','3','5','6','7','9','10','12', '13','16','17','20','21'))
  AND (EndOfRepair  IS NULL AND RepairedByEnd IS NULL) AND (StartOfRepair IS NOT NULL AND RepairedByStart IS NOT NULL) AND MCNo<>'Select'AND (location <>'' OR location IS NULL)
  AND DATEDIFF(HOUR, startofrepair, GETDATE()) >= 24

  UNION ALL

 SELECT Location,Process , MCNo, StartOfRepair ,PkgName,RequestItem
    FROM MPBMMaintenance
    WHERE        
(BMStatusID IN ('1','2','3','5','6','7','9','10','12', '13','16','17','20','21'))
  AND (EndOfRepair  IS NULL AND RepairedByEnd IS NULL) AND (StartOfRepair IS NOT NULL AND RepairedByStart IS NOT NULL) AND MCNo<>'Select'AND (location <>'' OR location IS NULL)
  AND DATEDIFF(HOUR, startofrepair, GETDATE()) >= 24

  UNION ALL

 SELECT Location,Process , MCNo, StartOfRepair ,PkgName,RequestItem
    FROM PLBMMaintenance
    WHERE        
(BMStatusID IN ('1','2','3','5','6','7','9','10','12', '13','16','17','20','21'))
  AND (EndOfRepair  IS NULL AND RepairedByEnd IS NULL) AND (StartOfRepair IS NOT NULL AND RepairedByStart IS NOT NULL) AND MCNo<>'Select'AND (location <>'' OR location IS NULL)
  AND DATEDIFF(HOUR, startofrepair, GETDATE()) >= 24


  UNION ALL

 SELECT Location,Process , MCNo, StartOfRepair ,PkgName,RequestItem
    FROM FLBMMaintenance
    WHERE        
(BMStatusID IN ('1','2','3','5','6','7','9','10','12', '13','16','17','20','21'))
  AND (EndOfRepair  IS NULL AND RepairedByEnd IS NULL) AND (StartOfRepair IS NOT NULL AND RepairedByStart IS NOT NULL) AND MCNo<>'Select'AND (location <>'' OR location IS NULL)
  AND DATEDIFF(HOUR, startofrepair, GETDATE()) >= 24

  UNION ALL

 SELECT Location,Process , MCNo, StartOfRepair ,PkgName,RequestItem
    FROM FTBMMaintenance
    WHERE        
  (BMStatusID IN ('1','2','3','5','6','7','9','10','12', '13','16','17','20','21'))
  AND (EndOfRepair  IS NULL AND RepairedByEnd IS NULL) AND (StartOfRepair IS NOT NULL AND RepairedByStart IS NOT NULL) AND MCNo<>'Select'AND (location <>'' OR location IS NULL)
  AND DATEDIFF(HOUR, startofrepair, GETDATE()) >= 24

  UNION ALL

 SELECT Location,Process , MCNo, StartOfRepair ,PkgName,RequestItem
    FROM TPBMMaintenance
    WHERE        
  (BMStatusID IN ('1','2','3','5','6','7','9','10','12', '13','16','17','20','21'))
  AND (EndOfRepair  IS NULL AND RepairedByEnd IS NULL) AND (StartOfRepair IS NOT NULL AND RepairedByStart IS NOT NULL) AND MCNo<>'Select' AND (location <>'' OR location IS NULL)
  AND DATEDIFF(HOUR, startofrepair, GETDATE()) >= 24

  UNION ALL

 SELECT Location,Process , MCNo, StartOfRepair ,PkgName,RequestItem
    FROM EDSBMMaintenance
    WHERE        
 (BMStatusID IN ('1','2','3','5','6','7','9','10','12', '13','16','17','20','21'))
  AND (EndOfRepair  IS NULL AND RepairedByEnd IS NULL) AND (StartOfRepair IS NOT NULL AND RepairedByStart IS NOT NULL) AND MCNo<>'Select'AND (location <>'' OR location IS NULL)
  AND DATEDIFF(HOUR, startofrepair, GETDATE()) >= 24

  UNION ALL

 SELECT Location,Process , MCNo, StartOfRepair ,PkgName,RequestItem
    FROM MEMSBMMaintenance
    WHERE        
(BMStatusID IN ('1','2','3','5','6','7','9','10','12', '13','16','17','20','21'))
  AND (EndOfRepair  IS NULL AND RepairedByEnd IS NULL) AND (StartOfRepair IS NOT NULL AND RepairedByStart IS NOT NULL) AND MCNo<>'Select'AND (location <>'' OR location IS NULL)
  AND DATEDIFF(HOUR, startofrepair, GETDATE()) >= 24

  UNION ALL

 SELECT Location,Process , MCNo, StartOfRepair ,PkgName,RequestItem
    FROM TEBMMaintenance
    WHERE        
(BMStatusID IN ('1','2','3','5','6','7','9','10','12', '13','16','17','20','21'))
  AND (EndOfRepair  IS NULL AND RepairedByEnd IS NULL) AND (StartOfRepair IS NOT NULL AND RepairedByStart IS NOT NULL) AND MCNo<>'Select' AND (location <>'' OR location IS NULL)
  AND DATEDIFF(HOUR, startofrepair, GETDATE()) >= 24

)
, DowntimeCalculation AS (
    SELECT 
        Location,Process , MCNo ,PkgName, StartOfRepair,RequestItem,
        DATEDIFF(DAY, startofrepair, GETDATE()) AS downtime_days,
        DATEDIFF(HOUR, startofrepair, GETDATE()) % 24 AS downtime_hours
    FROM FilteredRepairs
)
SELECT TOP 20 
    Location AS Area,Process , MCNo ,PkgName AS Package ,RequestItem AS BMName, StartOfRepair,
    CONCAT(downtime_days, ' Day/s ', downtime_hours, ' Hour/s') AS Downtime
FROM DowntimeCalculation
WHERE RequestItem <> 'Select' AND Location <> '' AND PkgName IS NOT NULL 
ORDER BY downtime_days DESC, downtime_hours DESC;
END
GO
