-- =============================================
CREATE PROCEDURE [dbo].[spINSERT_SKILLMAP]
@empno AS varchar(max),
@mctype as varchar(max),
@skilltype AS varchar(max),
@datestart as datetime,
@dateend as datetime,
@uploadedby as varchar(20)

AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	
DECLARE @dateuploaded as datetime;
	SET @dateuploaded = GETDATE()

   INSERT INTO  [eMaintenanceSystemDB].[dbo].[BMSkillMap] 
   (acnt_no,
   MCTypeID,
   BMSkillID,
   DateStart,
   DateEnd,
   UpdatedBy,
   DateUpdated) 
   
   VALUES (
   @empno,
   (SELECT DISTINCT MCTypeID FROM [eMaintenanceSystemDB].[dbo].[MCType] WHERE MCType= @mctype),
   (SELECT DISTINCT BMSkillID  FROM [eMaintenanceSystemDB].[dbo].[BMSkillType] WHERE SkillType = @skilltype ),
  @datestart,
   @dateend,
   @uploadedby,
   @dateuploaded)


END
