CREATE PROCEDURE [dbo].[spInsertEEEData]  
	@bmID INT,
	@Why1 varchar(200),
	@Treatment1 varchar (200),
	@TreatmentBefore1 varchar (20),
	@TreatmentAfter1 varchar (20),
	@TreatmentBy1 varchar (20),
	@TreatmentDate1 datetime,
	@BMStatusID int,
	--@TimeOfRequest datetime,
	--@GLConfirmOPReqDate datetime,
	@PMConfirmGLOPReqDate datetime,
	@Process varchar(10) 
AS
BEGIN
	SET NOCOUNT ON;

	IF EXISTS (SELECT 1 FROM EEEBMMaintenance WHERE bm_ID = @bmID AND Process = @Process)
	BEGIN
		UPDATE EEEBMMaintenance
		SET 
			Why1 = @Why1,
			Treatment1 = @Treatment1,
			TreatmentBefore1 = @TreatmentBefore1,	
			TreatmentAfter1 = @TreatmentAfter1,
			TreatmentBy1 = @TreatmentBy1,
			TreatmentDate1 = @TreatmentDate1,
			BMStatusID = @BMStatusID,
			--TimeOfRequest = @TimeOfRequest,
			--GLConfirmOPReqDate = @GLConfirmOPReqDate,
			PMConfirmGLOPReqDate = @PMConfirmGLOPReqDate,
			Process = @Process
		WHERE bm_ID = @bmID
	END
	ELSE
	BEGIN
		INSERT INTO EEEBMMaintenance
			(bm_ID, Why1, Treatment1, TreatmentBefore1, TreatmentAfter1, TreatmentBy1, TreatmentDate1, BMStatusID,  PMConfirmGLOPReqDate, Process )
		VALUES
			(@bmID, @Why1, @Treatment1, @TreatmentBefore1, @TreatmentAfter1, @TreatmentBy1, @TreatmentDate1, @BMStatusID,   @PMConfirmGLOPReqDate, @Process )
	END
END
GO
