		@DeviceName,
		@PkgName,
		@RequestItem,
		@LeaderChk,
		@LineLoc,
		@OccurrenceDate,
		@NGDetectionCircumtances,
		@RequestContent,
		@OccurrenceFreq,
		@OccurrenceFreqQuantity,
		@OccurrenceFreqLotFrame,
		@ProdQtyData,
		@LastActBeforeProb,
		@Situation,
		@AQI,
		@Andon,
		@TimeOfRequest,
		@RequestedBy,
		@BMStatusID,
		@BMCaseID,
		@QCData,
		@OCAPData,
		@Process,
		@Location,
		@ddlAfterAR,
		@ddlAfterFA, 
		@ddlAfterTC, 
		@ddlAfterRJ, 
		@ddlAfterCRM,
		@Abnormality,
		@AlarmNo,
		@isNotQuality1)
        
        SELECT 0 [ID]
		
END
	ELSE
