		GLConfirmOPReqReason,
		GLConfirmOPReqBy,
		GLConfirmOPReqDate,
		PMConfirmGLOPReq,
		PMConfirmGLOPReason,
		PMConfirmGLOPReqBy,
		PMConfirmGLOPReqDate,
		StartOfRepair,
		RepairedByStart,
		CurrentPM,PMTurnOvertoPEBy,
		PMTurnOvertoPEDate,
		Turnover,
		PEConfirmPMTurnoverReq,
		PEConfirmPMTurnoverReason,
		PEConfirmPMTurnoverBy,
		PEConfirmPMTurnoverDate)
		
	VALUES  
	
	    (@SubProcessID,
		@PMCategoryID,
		@MCNo, 
		@MCStatus,
		@MCType,
		@OPBMUnitID,
		@LOTNo,
		@DeviceName,
		@PkgName,
		@RequestItem,
		@OccurrenceDate,
		@NGDetectionCircumtances,
		@RequestContent,
		@OccurrenceFreq,
		@OccurrenceFreqQuantity,
		@OccurrenceFreqLotFrame,
		@AQI,
		@Andon,
		@GLAndon,
		@GLAndon2,
		@TimeOfRequest,
		@RequestedBy,
		@BMStatusID,
		@BMCaseID,
		@QCData,
		@OCAPData,
		@Process,
		@Location,
		@isNotQuality1,
		@KanagataNo,
		@LineLoc,
		@WaferNo,
		@CaseTitle,
		@Prioritization,
		@AlarmNo,
		@GLConfirmOPReq,
		@GLConfirmOPReqReason,
		@GLConfirmOPReqBy,
		@GLConfirmOPReqDate,
		@PMConfirmGLOPReq,
		@PMConfirmGLOPReason,
		@PMConfirmGLOPReqBy,
		@PMConfirmGLOPReqDate,
		@StartOfRepair,
		@RepairedByStart,
		@PMConfirmGLOPReqBy,
