/****** Object:  StoredProcedure [dbo].[sprHoldLotTable_EMaintenance_TEST]    Script Date: 10/25/2026 4:57:10 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Kino Rongavilla
-- Create date: 04-08-2024
-- Description:	Integration of eMaintenance and RAIS Lot Hold
-- =============================================
CREATE PROCEDURE [dbo].[sprHoldLotTable_EMaintenance_TEST]
	-- Add the parameters for the stored procedure here
	@action As varchar(20),
	@machineNo varchar(15),
	@processCode varchar(4),
	@assyLotNo as varchar(11),
	@lotTreatment as varchar(100)
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	DECLARE @StartDate as date = DATEADD(day, -70, GETDATE())

	BEGIN -- Declaration of Temporary Table Variable here
		DECLARE @tempHoldLotTable as TABLE (
			InputDate datetime, 
			AssyLotNo nvarchar(50), 
			ProgressBranch nvarchar(50), 
			NGProgFlag int, 
			InputOperator nvarchar(50), 
			Andon nvarchar(5), 
			AQI nvarchar(5), 
			PMrequest nvarchar(5), 
			TargetProcess nvarchar(50), 
			DefectMode nvarchar(50), 
			NGMode nvarchar(50), 
			Details nvarchar(200), 
			OccurrenceCause nvarchar(200), 
			LotTreatment nvarchar(200), 
			LotJudgement nvarchar(200), 
			TreatmentDate datetime, 
			TreatmentCharge nvarchar(200), 
			HoldFlow nvarchar(50)
		)
	END

	Declare @ERRORSUM as INT
	
	IF @action = 'HOLD'
		BEGIN -- HOLD FUNCTIONS HERE!
			
			-- 1st step
			-- INSERT INTO Temporary Table

			INSERT INTO @tempHoldLotTable

			(
					[InputDate]
					,[AssyLotNo]
					,[ProgressBranch]
					,[NGProgFlag]
					,[InputOperator]
					,[Andon]
					,[AQI]
					,[PMrequest]
					,[TargetProcess]
					,[DefectMode]
					,[NGMode]
					,[Details]
					,[OccurrenceCause]
					,[LotTreatment]
					,[LotJudgement]
					,[TreatmentDate]
					,[TreatmentCharge]
					,[HoldFlow]
				)

			SELECT 
				GETDATE()															As InputDate
				,AssyLotNo															
				,'0000'																As ProcessCode
				,0																	As NGProgFlag
				,'RAIS E-Maintenance LOT HOLD DLL'									As InputOperator
				,@machineno																As Andon
				,'-'																As AQI
				,'-'																As PMRequest
				,'OG1'																As TargetProcess
				,'Critical'															As DefectMode
				,'RAIS E-Maintenance LOT HOLD'										As NGMode
				,'Prevent to be shipped out in OG1/SHIPPING'						As Details
				,'From E-Maintenance Transaction Machine No: ' + @machineno			As OccurenceCause
				,'-'																As LotTreatment
				,'-'																As LotJudgement
				,NULL																As TreatmentDate
				,'-'																As TreatmentCharge
				,'OG1'																As HoldFlow

			FROM
				(

					SELECT DISTINCT(ls.AssyLotNo), ls.ProgressProcess, ls.LastUpdate, wo.OptionValue
			
					FROM RWIT_LotStockTable_TEST ls 

					INNER JOIN RWIT_WorkOptionTable_TEST wo On ls.ProgressProcess = wo.ProgressProcess and ls.LastUpdate = wo.InputDate and wo.OptionType = 'Machine No1' and wo.OptionValue = @machineNo

					WHERE ls.ProgressProcess = '203'
					AND ls.LastUpdate  >= @StartDate

			) As x -- Itago natin sa alyas na X! Kase wala nang maisip na variable!

			-- 2nd step
			-- Populate affected ROWS affected

			DECLARE @NoOfLots As INT
			SET @NoOfLots = (SELECT COUNT(AssyLotNo) FROM @tempHoldLotTable)

			DECLARE @NoOfExistingLots AS INT
			SET @NoOfExistingLots = (SELECT COUNT(AssyLotNo) FROM @tempHoldLotTable WHERE AssyLotNo IN(SELECT AssyLotNo FROM [dbo].[RWIT_HoldLotTable_TEST]))

			DECLARE @AffectedLots As INT
			SET @AffectedLots = @NoOfLots - @NoOfExistingLots

			-- 3rd step
			-- Insert to Table

			INSERT INTO
			
			[dbo].[RWIT_HoldLotTable_TEST]
			--[dbo].[RWIT_HoldLotTable_QC_Release_20220128]

				(
					[InputDate]
					,[AssyLotNo]
					,[ProgressBranch]
					,[NGProgFlag]
					,[InputOperator]
					,[Andon]
					,[AQI]
					,[PMrequest]
					,[TargetProcess]
					,[DefectMode]
					,[NGMode]
					,[Details]
					,[OccurrenceCause]
					,[LotTreatment]
					,[LotJudgement]
					,[TreatmentDate]
					,[TreatmentCharge]
					,[HoldFlow]
				)
				
			SELECT

				[InputDate]
				,[AssyLotNo]
				,[ProgressBranch]
				,[NGProgFlag]
				,[InputOperator]
				,[Andon]
				,[AQI]
				,[PMrequest]
				,[TargetProcess]
				,[DefectMode]
				,[NGMode]
				,[Details]
				,[OccurrenceCause]
				,[LotTreatment]
				,[LotJudgement]
				,[TreatmentDate]
				,[TreatmentCharge]
				,[HoldFlow]

			FROM @tempHoldLotTable

			WHERE AssyLotNo NOT IN
				(
					SELECT AssyLotNo FROM [dbo].[RWIT_HoldLotTable_TEST]
					--SELECT AssyLotNo FROM [dbo].[RWIT_HoldLotTable_QC_Release_20220128]
				)

			---- 4th step
			---- Insert to log table on how many LOTS were affected

			--INSERT INTO [dbo].[Logs_LotHoldDLL_Table] VALUES (@machineNo, @NoOfLots, @NoOfExistingLots, @AffectedLots, 'EMaintenanceLOTHold', GETDATE())

			SET @ERRORSUM = @@ERROR

			IF @ERRORSUM > 0
				BEGIN
					SELECT 'NG' As message
				END

			ELSE IF @ERRORSUM = 0

				BEGIN

					SELECT CAST(@AffectedLots As varchar(3)) + ' LOTNOs has been set to be ON HOLD in SHIPPING Process for Machine Number: ' + @machineNo As message

				END


		END -- HOLD FUNCTIONS HERE! </END TAG>

	ELSE IF @action = 'RELEASE'

		BEGIN -- RELEASE FUNCTIONS HERE!
			
			IF @assyLotNo <> ''

				BEGIN

					-- Check if LOTNO is existing in HOLD LOT Table

					IF EXISTS(SELECT AssyLotNo FROM [dbo].[RWIT_HoldLotTable_TEST] WHERE AssyLotNo = @AssyLotNo AND InputOperator = 'RAIS E-Maintenance LOT HOLD DLL')
						BEGIN

							-- 1st step
							-- Update NG ProgFlag to 1 to identify as "released"

							UPDATE [dbo].[RWIT_HoldLotTable_TEST]
							--UPDATE [dbo].[RWIT_HoldLotTable_QC_Release_20220128] -- Dummy
								SET
									[NGProgFlag] = '1'
									,[LotTreatment] = @LotTreatment
					
							WHERE
									AssyLotNo = @AssyLotNo
								AND InputOperator = 'RAIS E-Maintenance LOT HOLD DLL'

							-- 2nd step
							-- Then INSERT from ONLINE to ARCHIVE

							INSERT INTO [dbo].[RWIT_HoldLotTable_old_TEST]
									(
										[InputDate]
										,[AssyLotNo]
										,[ProgressBranch]
										,[NGProgFlag]
										,[InputOperator]
										,[Andon]
										,[AQI]
										,[PMrequest]
										,[TargetProcess]
										,[DefectMode]
										,[NGMode]
										,[Details]
										,[OccurrenceCause]
										,[LotTreatment]
										,[LotJudgement]
										,[TreatmentDate]
										,[TreatmentCharge]
										,[HoldFlow]
									)
			
								SELECT

									[InputDate]
									,[AssyLotNo]
									,[ProgressBranch]
									,[NGProgFlag]
									,[InputOperator]
									,[Andon]
									,[AQI]
									,[PMrequest]
									,[TargetProcess]
									,[DefectMode]
									,[NGMode]
									,[Details]
									,[OccurrenceCause]
									,[LotTreatment]
									,[LotJudgement]
									,[TreatmentDate]
									,[TreatmentCharge]
									,[HoldFlow]

								FROM [dbo].[RWIT_HoldLotTable_TEST]
								--FROM [dbo].[RWIT_HoldLotTable_QC_Release_20220128] -- Dummy
								WHERE
										AssyLotNo = @AssyLotNo
									AND InputOperator = 'RAIS E-Maintenance LOT HOLD DLL'
									AND NGProgFlag = '1'
									AND LotTreatment = @lotTreatment

								-- 3rd step
								-- DELETE FROM LIVE and INSERT to archive

								DELETE
								FROM [dbo].[RWIT_HoldLotTable_TEST]
								--FROM [dbo].[RWIT_HoldLotTable_QC_Release_20220128] -- Dummy
								WHERE
										AssyLotNo = @AssyLotNo
									AND InputOperator = 'RAIS E-Maintenance LOT HOLD DLL'
									AND NGProgFlag = '1'
									AND LotTreatment = @lotTreatment
								

								SET @ERRORSUM = @@ERROR

								IF @ERRORSUM > 0
									BEGIN
										SELECT 'NG' As message
									END

								ELSE IF @ERRORSUM = 0
									BEGIN
										SELECT 'LOT release executed' As message
									END

								END

							ELSE IF NOT EXISTS(SELECT AssyLotNo FROM [dbo].[RWIT_HoldLotTable_TEST] WHERE AssyLotNo = @AssyLotNo AND InputOperator = 'RAIS E-Maintenance LOT HOLD DLL')
								BEGIN
									SELECT 'Affected LOT cannot be found in RAIS Lot Hold Table. LOT must be non-existent or already undergone LOT release' As message
								END

						END

			ELSE IF @assyLotNo = ''

				BEGIN
					SELECT 'LOT Number is empty, this is required.' As message
				END



		END
	ELSE IF @action = 'HOLDLIST'

		BEGIN
			SELECT * FROM [dbo].[RWIT_HoldLotTable_TEST]
			WHERE InputOperator = 'RAIS E-Maintenance LOT HOLD DLL'
		END

	ELSE IF @action = 'AFFECTEDLOTS'

		BEGIN
			
			SELECT DISTINCT(ls.AssyLotNo), ls.ProgressProcess, ls.LastUpdate, wo.OptionValue
			
			FROM RWIT_LotStockTable_TEST ls 

			INNER JOIN RWIT_WorkOptionTable_TEST wo On ls.ProgressProcess = wo.ProgressProcess and ls.LastUpdate = wo.InputDate and wo.OptionType = 'Machine No1' and wo.OptionValue = @machineNo

			WHERE ls.ProgressProcess = '203'
			AND ls.LastUpdate  >= @StartDate

		END

END
GO
