	@bmID INT,
	@GLResolvedOPReq varchar(15),
	@GLResolvedOPReqBy varchar(20),
	@GLResolvedOPReqDate datetime
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

