CREATE PROCEDURE [dbo].[spTPPMSaveEvidence] 
	-- Add the parameters for the stored procedure here
	@bmID INT,
	@BMEvidence_Title varchar(50), 
	@BMEvidence_Desc varchar(100),
	@BMEvidence_Category varchar(50),
	@BMEvidence_ImgFile varchar(100),
	@BMEvidence_DateTime datetime,
	@BMEvidence_UploadedBy varchar(20),
	@BMEvidence_TCConfirm1 varchar(5),
	@BMEvidence_TCConfirm2 varchar(5),
	@BMEvidence_TCConfirm3 varchar(5)
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	INSERT INTO [BMTPEvidenceMaking]

		(bmID,
		BMEvidence_Title,
		BMEvidence_Desc, 
		BMEvidence_Category, 
		BMEvidence_ImgFile,
		BMEvidence_DateTime,
		BMEvidence_UploadedBy,
		BMEvidence_TCConfirm1,
		BMEvidence_TCConfirm2,
		BMEvidence_TCConfirm3)
		
	VALUES  
	
	    (@bmID,
		@BMEvidence_Title,
		@BMEvidence_Desc, 
		@BMEvidence_Category,
		@BMEvidence_ImgFile,
		@BMEvidence_DateTime,
		@BMEvidence_UploadedBy,
		@BMEvidence_TCConfirm1,
		@BMEvidence_TCConfirm2,
		@BMEvidence_TCConfirm3)

	UPDATE [BMTPEvidenceMaking]	
	SET 
		BMEvidence_TCConfirm1=@BMEvidence_TCConfirm1,
		BMEvidence_TCConfirm2=@BMEvidence_TCConfirm2,
		BMEvidence_TCConfirm3=@BMEvidence_TCConfirm3		
	WHERE bmID=@bmID
        
END
