-- =============================================
CREATE PROCEDURE [dbo].[spUPDATE_SKILLMAP]
@empno AS varchar(20),
@mctype as varchar(max),
@skilltype AS varchar(max),
@datestart as datetime,
@dateend as datetime,
@uploadedby as varchar(20)

AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	DECLARE @dateuploaded as datetime;
	SET @dateuploaded = GETDATE()
    -- Insert statements for procedure here
 UPDATE  [eMaintenanceSystemDB].[dbo].[BMSkillMap] SET BMSkillID =(SELECT DISTINCT BMSkillID  FROM [eMaintenanceSystemDB].[dbo].[BMSkillType] WHERE SkillType = @skilltype ), DateStart = @datestart , DateEnd = @dateend  , UpdatedBy = @uploadedby , DateUpdated = @dateuploaded
  WHERE acnt_no = @empno
  AND MCTypeID = (SELECT DISTINCT MCTypeID FROM [eMaintenanceSystemDB].[dbo].[MCType] WHERE MCType= @mctype) 

END
