-- =============================================
Create PROCEDURE [dbo].[spUpdateCCStartOfRepair] 
	-- Add the parameters for the stored procedure here
	@bmID INT,
	@StartOfRepair datetime,
	@StartBy varchar(10),
	@Process varchar(5)
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
 	 SET NOCOUNT ON;
	 DECLARE @DynamicSQL NVARCHAR(MAX);

	 set @DynamicSQL =  N'UPDATE ['+ @Process +'BMMaintenance]	
						SET 
							CCStartOfRepair=@StartOfRepair,
							CCStartBy=@StartBy	
						WHERE bmID=@bmID'


	EXECUTE sp_executesql @DynamicSQL,N' @bmID INT,
										 @StartOfRepair datetime,
										 @StartBy varchar(10),
										 @Process varchar(5)',
										 @bmid,
										 @StartOfRepair,
										 @StartBy,
										 @Process 

END
