-- Description:	<Update Status of BM and Update End Time Info>
-- =============================================
CREATE PROCEDURE [dbo].[spWBPMEndBMRepair]  
	-- Add the parameters for the stored procedure here
	@BMStatusID	int,
	@bmID INT,
	@EndOfRepair datetime,
	@RepairedByEnd varchar(10)

AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	UPDATE [WBBMMaintenance]	
	SET 
		BMStatusID=@BMStatusID,
		EndOfRepair=@EndOfRepair,
		RepairedByEnd=@RepairedByEnd
				
	WHERE bmID=@bmID

END



