	@BMEvidence_TCConfirm3 varchar(5)
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	UPDATE [BMEvidenceMaking]	
	SET 
		BMEvidence_Title=@BMEvidence_Title,
		BMEvidence_Desc=@BMEvidence_Desc,
		BMEvidence_Category=@BMEvidence_Category,
		BMEvidence_ImgFile=@BMEvidence_ImgFile,
		BMEvidence_DateTime=@BMEvidence_DateTime,
		BMEvidence_UploadedBy=@BMEvidence_UploadedBy,
		BMEvidence_TCConfirm1=@BMEvidence_TCConfirm1,
		BMEvidence_TCConfirm2=@BMEvidence_TCConfirm2,
		BMEvidence_TCConfirm3=@BMEvidence_TCConfirm3		
	WHERE BMEvidenceID=@BMEvidenceID

	UPDATE [BMEvidenceMaking]	
	SET 
		BMEvidence_TCConfirm1=@BMEvidence_TCConfirm1,
		BMEvidence_TCConfirm2=@BMEvidence_TCConfirm2,
		BMEvidence_TCConfirm3=@BMEvidence_TCConfirm3		
	WHERE bmID=@bmID
END
GO
/****** Object:  StoredProcedure [dbo].[Test_spLoginMVC]    Script Date: 10/25/2026 4:57:10 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[Test_spLoginMVC]
	-- Add the parameters for the stored procedure here
	 @Username varchar(20),
	 @Password varchar(20)
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

   IF EXISTS (SELECT * FROM [eMaintenanceSystemDB].[dbo].[acnt_info_tbl] WHERE acnt_username = @Username AND acnt_password = @Password )
		BEGIN
			SELECT 'PASS' as [status]
		END
   ELSE
		BEGIN
			SELECT 'FAIL' as [status]
		END
END
GO
/****** Object:  StoredProcedure [dbo].[validate]    Script Date: 10/25/2026 4:57:10 PM ******/
SET ANSI_NULLS ON
GO
