GO

-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[validate](@EmpNo varchar(20),@Password varchar(20))
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	SELECT a.acnt_id as UserID, a.acnt_position as UserType, a.acnt_position as Position, a.acnt_location as Location, a.acnt_process as Process, a.acnt_isactive as IsActive, a.acnt_no as AccountNo From acnt_info_tbl as a where  CAST(a.acnt_username as varbinary)=CAST(@EmpNo as varbinary) and CAST(a.acnt_password as varbinary)=CAST(@Password as varbinary)
END
GO
